-- ============================ tiny self-contained helpers ============================
local function singleton(name)
    local ok, s = pcall(function() return sdk.get_managed_singleton(name) end)
    return ok and s or nil
end

local function get_player()
    local cm = singleton("app.CharacterManager")
    if not cm then return nil end
    local ok, p = pcall(function() return cm:call("get_ManualPlayer") end)
    return ok and p or nil
end

local function char_go(ch)
    local ok, go = pcall(function() return ch:call("get_GameObject") end)
    return ok and go or nil
end

local function go_name(go)
    local ok, n = pcall(function() return go and go:call("get_Name") end)
    return ok and tostring(n) or "?"
end

local function upos(go)
    local ok, p = pcall(function() return go:call("get_Transform"):call("get_UniversalPosition") end)
    return ok and p or nil
end

local function set_upos(go, pos)
    pcall(function() go:call("get_Transform"):call("set_UniversalPosition", pos) end)
end

local function dist(a, b)
    if not (a and b) then return 1e9 end
    local dx, dy, dz = a.x - b.x, a.y - b.y, a.z - b.z
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end

local function comp(go, tn)
    local ok, c = pcall(function() return go:call("getComponent(System.Type)", sdk.typeof(tn)) end)
    return ok and c or nil
end

local function notify(text)
    -- soft feedback: surfaces in the STATUS line (no modal boxes); kept for future in-world tells
    if C.notify_lines ~= true then return end
    S.last_notify = tostring(text)
end

-- HP read/write (the proven multi-getter/setter cascade from the griffin work)
local function hit_controller(ch)
    local go = char_go(ch)
    return go and comp(go, "app.HitController") or nil
end

local function read_hp(hc)
    if not hc then return nil, nil end
    local hp, max = nil, nil
    for _, m in ipairs({ "get_Hp", "get_CurrentHitPoint" }) do
        local ok, v = pcall(function() return hc:call(m) end)
        if ok and tonumber(v) then hp = tonumber(v); break end
    end
    for _, m in ipairs({ "get_MaxHitPoint", "get_MaxHp", "get_HpMax" }) do
        local ok, v = pcall(function() return hc:call(m) end)
        if ok and tonumber(v) then max = tonumber(v); break end
    end
    return hp, max
end

local function write_hp(hc, v)
    if not hc then return end
    for _, sig in ipairs({
        "setHp(System.Single, System.Boolean, System.Int32)",
        "setHp(System.Single, System.Boolean)",
        "setHp(System.Single)",
        "set_Hp(System.Single)",
    }) do
        pcall(function() hc:call(sig, v, true, 0) end)
    end
end

local function set_immunity(ch, on)
    -- the ritual shield: while approached/yielded/tamed the creature CANNOT be hurt (pawn-proof).
    -- NOT applied during the combat "context" phase -- the weakening fight must still work.
    local hc = hit_controller(ch)
    if not hc then return end
    for _, sig in ipairs({ "set_IsDamageZero", "set_IsIgnoreDamageHit", "set_DamageCollisionOff" }) do
        pcall(function() hc:call(sig, on == true) end)
    end
end

local function set_immunity_soft(ch, on)
    -- SOFT shield: protect HP with ONLY IsDamageZero (damage value forced to 0), and DELIBERATELY
    -- leave IsIgnoreDamageHit + DamageCollisionOff OFF so the hit pipeline runs to completion and the
    -- damageProc hook FIRES -- that hook is how we detect "the player struck the wolf". (IsDamageZero
    -- alone zeroes the HP loss; the HP floor in the shield backstops any leak.) The full 3-flag
    -- set_immunity is only used where NOBODY -- not even the player -- may hit it (the yield window).
    local hc = hit_controller(ch)
    if not hc then return end
    pcall(function() hc:call("set_IsDamageZero", on == true) end)
    if on then
        pcall(function() hc:call("set_IsIgnoreDamageHit", false) end)
        pcall(function() hc:call("set_DamageCollisionOff", false) end)
    end
end

-- THE REAL PACIFY SUITE (ported from the griffin ride + PetDogProbe -- correct signatures):
-- clearAllHate on the beast, clear its TARGET lists, zero its hate RATE toward the party (so
-- peace can't re-accrue), and clear the party's hate back at it.
local function hate_system(ch)
    local hs = nil
    pcall(function() hs = ch:call("get_HateSystem") end)
    if not hs then hs = comp(char_go(ch), "app.HateSystem") end
    return hs
end

local function strip_hate(ch)
    local hs = hate_system(ch)
    if hs then pcall(function() hs:call("clearAllHate") end) end
end

local function clear_targets(ch)
    local go = char_go(ch)
    if not go then return end
    local lock_on = comp(go, "app.LockOnTarget")
    if lock_on then pcall(function() lock_on:set_field("TargetData", nil) end) end
    local bb = comp(go, "app.AIBlackBoardController")
    if bb then
        pcall(function() bb:call("clearEnemyTargetList") end)
        pcall(function() bb:call("updateEnemyTargetList") end)
    end
end

local function party_characters()
    local out = {}
    local pl = get_player()
    if pl then out[#out + 1] = pl end
    local pm = singleton("app.PawnManager")
    if pm then
        for _, getter in ipairs({ "get_PawnCharacterList", "get_AlivePawnCharacterList" }) do
            local list = nil
            pcall(function() list = pm:call(getter) end)
            local n = 0
            pcall(function() n = list and list:call("get_Count") or 0 end)
            for i = 0, (tonumber(n) or 0) - 1 do
                local pawn = nil
                pcall(function() pawn = list:call("get_Item", i) end)
                if pawn then out[#out + 1] = pawn end
            end
            if n and tonumber(n) and tonumber(n) > 0 then break end
        end
    end
    return out
end

local function pacify_toward_party(ch)
    -- zero the hate RATE toward each party member + clear existing hate on them (griffin recipe:
    -- passive distance-hate otherwise refills the list just from standing near friends)
    local hs = hate_system(ch)
    if not hs then return end
    for _, member in ipairs(party_characters()) do
        local mgo = char_go(member)
        if mgo then
            pcall(function() hs:call("setCustomRate(via.GameObject, System.Single)", mgo, 0.0) end)
            pcall(function() hs:call("clear(via.GameObject)", mgo) end)
        end
    end
end

local function clear_party_hate_toward(ch)
    -- the party stops hating the beast (pawns, stand down)
    for _, member in ipairs(party_characters()) do
        local mhs = hate_system(member)
        if mhs then
            pcall(function() mhs:call("clearAllHate") end)
        end
    end
end

local function full_pacify(ch)
    strip_hate(ch)
    clear_targets(ch)
    pacify_toward_party(ch)
end

-- NATIVE PET COMMANDS (PetDogProbe's crown find: app.Ch223001CommandCtrl on the ch223 family --
-- Capcom's own companion-dog system: 1=ATTACK 2=KEEP_OBSERVE 3=FOLLOW)
local function command_ctrl(ch)
    local go = char_go(ch)
    if not go then return nil end
    for _, tn in ipairs({ "app.Ch223001CommandCtrl", "app.Ch223000CommandCtrl" }) do
        local c = comp(go, tn)
        if c then return c end
    end
    return nil
end

local function native_command(ch, cmd)
    local ctrl = command_ctrl(ch)
    if not ctrl then return false end
    local ok = pcall(function() ctrl:call("requestCommand(app.Ch223001CommandCtrl.CommandType)", cmd) end)
    if not ok then ok = pcall(function() ctrl:call("requestCommand", cmd) end) end
    return ok
end

local function set_nav_stop(ch, stop)
    -- hold-ground (dog probe): the wary animal STOPS and watches instead of wandering/chasing
    local nav = nil
    pcall(function() nav = ch:get_field("<NavigationAI>k__BackingField") end)
    if not nav then pcall(function() nav = ch:call("get_NavigationAI") end) end
    if not nav then nav = comp(char_go(ch), "app.NavigationAI") end
    if not nav then return false end
    return pcall(function() nav:call("set_IsStopCalled", stop == true) end)
        or pcall(function() nav:set_field("IsStopCalled", stop == true) end)
end

local function set_think_stop(ch, stop)
    -- method setter FIRST + short-circuit (other-session Iris's fix: set_field on a missing
    -- field logs a red error even inside pcall -- the field write is last resort only)
    if pcall(function() ch:call("set_IsThinkStop(System.Boolean)", stop == true) end) then return true end
    if pcall(function() ch:call("set_IsThinkStop", stop == true) end) then return true end
    pcall(function() ch:set_field("_IsThinkStop", stop == true) end)
    return true
end

local function set_ground_glue(go2, enabled)
    -- kill/restore the ground-snap + push components (GroundFixer + CharacterController). A flying
    -- or perched critter is otherwise RE-PLANTED on the terrain every frame and its live capsule
    -- SHOVES the player - collision-off alone is not enough (the talon-carry's hard-won lesson).
    -- Returns how many components it actually touched (0 = the disable silently failed: diagnose).
    if not go2 then return 0 end
    local hits = 0
    pcall(function()
        local comps = go2:call("get_Components")
        local n = 0
        pcall(function() n = comps:get_size() end)
        if n == 0 then pcall(function() n = tonumber(comps:call("get_Length")) or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local c2 = nil
                pcall(function() c2 = comps:get_element(i) end)
                if c2 == nil then c2 = comps:call("get_Item", i) end
                local full = c2:get_type_definition():get_full_name()
                if full:find("GroundFixer", 1, true) or full:find("CharacterController", 1, true)
                    or full:find("PressDetector", 1, true) or full:find("CharacterPress", 1, true)
                    or full:find("physics.Colliders", 1, true) or full:find("RequestSetCollider", 1, true) then
                    c2:call("set_Enabled", enabled == true)
                    hits = hits + 1
                end
            end)
        end
    end)
    -- belt + suspenders: the known types straight by name (covers an array-iteration failure)
    for _, tn2 in ipairs({ "app.GroundFixer", "via.physics.CharacterController", "app.CharacterController" }) do
        pcall(function()
            local t2 = sdk.typeof(tn2)
            local c2 = t2 and go2:call("getComponent(System.Type)", t2)
            if c2 then c2:call("set_Enabled", enabled == true); hits = hits + 1 end
        end)
    end
    S.glue_dbg = string.format("glue %s: %d comps", enabled and "ON" or "OFF", hits)
    return hits
end

local function unparent_critter(ch)
    -- release a hand-parented critter -- ONLY one we parented (detaching an ordinary character
    -- from its scene hierarchy is not a risk worth taking, hence the address guard)
    if not (ch and S.parented_addr) then return end
    local addr = nil
    pcall(function() addr = ch:get_address() end)
    if addr ~= S.parented_addr then return end
    pcall(function()
        local go2 = nil
        pcall(function() go2 = ch:call("get_GameObject") end)
        local ctf = go2 and go2:call("get_Transform")
        if not ctf then return end
        -- ⛔ HOLD THE WORLD SPOT ACROSS THE SWAP: a parent change reinterprets LOCAL coords in
        -- the new parent's frame. The old code called set_Parent UNCONDITIONALLY after the
        -- keep-world setParent -- re-throwing the body to its local coords in world frame. The
        -- crow's tiny hand-local offset hid it; the bat's glove-hover local (0.45,1.30,0.35)
        -- became a far-off world spot = "teleported away, flew over water, drowned" (bats #3/#4).
        local keep = nil
        pcall(function() keep = upos(go2) end)
        pcall(function() ctf:call("set_ParentJoint", "") end)
        pcall(function() ctf:call("setParentJoint", "") end)
        -- restore the ORIGINAL parent (a scene body always has one): handing setParent nil
        -- is silently refused, which left the creature WELDED to the player -- the field's
        -- "invisible stick". The rider-seat detach (the proven pattern) restores, never nils.
        local orig = S.parented_orig
        if orig ~= nil then
            local ok1 = pcall(function() ctf:call("setParent", orig, true) end)
            if not ok1 then pcall(function() ctf:call("set_Parent", orig) end) end
        else
            local ok1 = pcall(function() ctf:call("setParent", nil, true) end)
            if not ok1 then pcall(function() ctf:call("set_Parent", nil) end) end
        end
        if keep then
            local pv = ValueType.new(sdk.find_type_definition("via.Position"))
            pv.x = keep.x; pv.y = keep.y; pv.z = keep.z
            pcall(function() set_upos(go2, pv) end)
        end
        local still = nil
        pcall(function() still = ctf:call("get_Parent") end)
        pcall(function() log.info("[IrisTaming] critter unparent: orig=" .. tostring(orig ~= nil) .. " parent_now=" .. tostring(still ~= nil) .. " held=" .. tostring(keep ~= nil)) end)
    end)
    S.parented_addr = nil
    S.parented_orig = nil
end

local function set_prompt(title, subtext, secs, color)
    -- the on-screen ritual card ("you got engaged" style, a size smaller): center-top banner
    S.prompt = { title = tostring(title or ""), sub = tostring(subtext or ""),
        until_t = os.clock() + (tonumber(secs) or 1.0), color = color or 0xFF80D0FF }
end

local NAME_CHARS = nil
local function name_chars()
    if NAME_CHARS then return NAME_CHARS end
    NAME_CHARS = {}
    for i = 0, 25 do NAME_CHARS[0x41 + i] = { string.char(97 + i), string.char(65 + i) } end
    for d = 0, 9 do NAME_CHARS[0x30 + d] = { tostring(d), tostring(d) } end
    NAME_CHARS[0x20] = { " ", " " }
    NAME_CHARS[0xBD] = { "-", "_" }
    NAME_CHARS[0xDE] = { "'", "'" }
    return NAME_CHARS
end

local function name_pause(on)
    -- ONE balanced pause/unpause, tagged (the baby card's proven freeze -- and the hard-won
    -- law: never loop PauseTypes, never pause at load time)
    pcall(function()
        local pm = sdk.get_managed_singleton("app.PauseManager")
        if not pm then return end
        if S.name_ptype == nil then
            local names = {}
            local td = sdk.find_type_definition("app.PauseManager.PauseType")
            for _, f in ipairs(td:get_fields()) do
                if f:is_static() then
                    local v; pcall(function() v = f:get_data() end)
                    if type(v) == "number" then names[f:get_name()] = v end
                end
            end
            -- prefer the DEBUG-CAMERA pause: it actually freezes gameplay (Menu/System leaked)
            local pick = nil
            for nm2, v2 in pairs(names) do local l = nm2:lower(); if l:find("debug") and l:find("cam") then pick = v2 end end
            if not pick then for nm2, v2 in pairs(names) do if nm2:lower():find("debug") then pick = v2 end end end
            S.name_ptype = pick or names.Menu or names.System or names.All or 1
        end
        pm:call("requestPause(System.Boolean, app.PauseManager.PauseType, System.String, System.Action)",
            on == true, S.name_ptype, "IrisTamingName", nil)
        S.name_paused = (on == true)
    end)
end

local function name_capture()
    -- poll per key with edges: letters/digits/space/hyphen/apostrophe; shift = capitals
    S.name_keys = S.name_keys or {}
    -- ⛔ RAW reads (the input-gate law): this box OWNS the typing -- the gate's
    -- IrisTypingActive flag blocks everyone ELSE, so gated reads here would deadlock
    local kbr = rawget(_G, "iris_kb_raw") or iris_kb
    local shift = false
    pcall(function() shift = kbr(0x10) == true end)
    local function edge(vk)
        local dwn = false
        pcall(function() dwn = kbr(vk) == true end)
        local was = S.name_keys[vk] == true
        S.name_keys[vk] = dwn
        return dwn and not was
    end
    for vk, pair in pairs(name_chars()) do
        if edge(vk) and #tostring(S.name_buf or "") < 24 then
            S.name_buf = tostring(S.name_buf or "") .. (shift and pair[2] or pair[1])
        end
    end
    if edge(0x08) then S.name_buf = tostring(S.name_buf or ""):sub(1, -2) end   -- backspace
    return edge(0x0D)   -- Enter seals
end

local function qrot(q, vx, vy, vz)
    -- rotate a body-space vector by a quaternion (the shoulder perch's math)
    local qx, qy, qz, qw = q.x, q.y, q.z, q.w
    local tx = 2.0 * (qy * vz - qz * vy)
    local ty = 2.0 * (qz * vx - qx * vz)
    local tz = 2.0 * (qx * vy - qy * vx)
    return vx + qw * tx + (qy * tz - qz * ty),
           vy + qw * ty + (qz * tx - qx * tz),
           vz + qw * tz + (qx * ty - qy * tx)
end

local function qmul(a, b)
    -- quaternion product a*b (compose rotations; used to express a WORLD pose in a joint's frame)
    return {
        x = a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
        y = a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
        z = a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
        w = a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
    }
end

local function pin_crow_shoulder(go, pgo)
    -- a bird rides the shoulder by a per-frame WORLD pin onto the ANIMATED shoulder JOINT, read
    -- POST-pose (this runs in the LATE hook) so it tracks the shoulder through turning/leaning/
    -- gait sway and stays stable. NO parenting (parenting inherits the parent scale + needs a
    -- bone-frame counter-rotation = the earlier upside-down/float bugs); the griffin talon-carry
    -- recipe instead: joint world pos, RENDER->UNIVERSAL safe, YAW-ONLY facing (upright in any lean).
    -- The earlier ROOT pin was stable but the root does not move when the shoulder animates, so
    -- the bird would not stick to the shoulder -- the JOINT base is what makes it ride.
    if not (go and pgo) then return end
    pcall(function()
        local ptf = pgo:call("get_Transform")
        local pu = ptf:call("get_UniversalPosition")   -- root UNIVERSAL
        local prp = ptf:call("get_Position")           -- root RENDER
        local prot = ptf:call("get_Rotation")
        if not (pu and prp and prot) then return end
        -- the shoulder joint, POSED. joint:get_Position() is RENDER space; take its offset from
        -- the root in render (the world-tile offset cancels) and re-base onto the root's
        -- UNIVERSAL position -- the griffin coord-safe trick (a raw render pos written as
        -- universal flings the body a whole tile away).
        local bx, by, bz = pu.x, pu.y, pu.z
        for j9 in tostring(C.perch_joint or "R_Arm_Clavicle,Spine_2"):gmatch("[^,%s]+") do
            local j = ptf:call("getJointByName", j9)
            local jp = j and j:call("get_Position")
            if jp then
                bx = pu.x + (jp.x - prp.x)
                by = pu.y + (jp.y - prp.y)
                bz = pu.z + (jp.z - prp.z)
                break
            end
        end
        -- the player's facing yaw (this file's forward-vector convention), + a manual rotate
        local fx = 2.0 * (prot.x * prot.z + prot.w * prot.y)
        local fz = 1.0 - 2.0 * (prot.x * prot.x + prot.y * prot.y)
        local yaw = math.atan(fx, fz)
        local sy, cy = math.sin(yaw), math.cos(yaw)
        -- yaw basis: right=(cos,0,-sin) up=(0,1,0) fwd=(sin,0,cos); a small offset from the joint
        local ox = tonumber(C.perch_x) or 0.1
        local oy = tonumber(C.perch_y) or 0.05
        local oz = tonumber(C.perch_z) or 0.0
        -- EVERY species gets its own shoulder tuning (offsets/rotate/scale -- Aurora: "make
        -- sure every creature has its own rotation slider like the rabbit"): per-band config
        -- keys sp_<band>_px/py/pz/prot/psc on top of the global sliders
        local band0 = tostring(go_name(go) or ""):match("ch%d+")
        local is_bat0 = band0 == "ch299400" or band0 == "ch299440"
        local sp0 = iris_species_perch(band0)
        ox = ox + sp0.x
        oy = oy + sp0.y
        oz = oz + sp0.z
        -- (08-13: the shoulder-comfort publisher lived here for one round and is
        -- REVERTED - Aurora's spec: the IV size is the only size, shoulder included)
        local pos = ValueType.new(sdk.find_type_definition("via.Position"))
        pos.x = bx + cy * ox + sy * oz
        pos.y = by + oy
        pos.z = bz + (-sy) * ox + cy * oz
        set_upos(go, pos)
        local ry = yaw + math.rad(tonumber(C.perch_rot) or 0.0) + math.rad(sp0.rot)
        local qv = ValueType.new(sdk.find_type_definition("via.Quaternion"))
        qv.x = 0.0; qv.y = math.sin(ry / 2.0); qv.z = 0.0; qv.w = math.cos(ry / 2.0)
        -- the BAT roosts UPRIGHT on the shoulder: its rest pose is the inverted hang, so the
        -- pin rolls it 180 about its forward axis (no safe upside-down spot on the Arisen)
        if is_bat0 then
            local q2 = qmul({ x = qv.x, y = qv.y, z = qv.z, w = qv.w }, { x = 0.0, y = 0.0, z = 1.0, w = 0.0 })
            qv.x = q2.x; qv.y = q2.y; qv.z = q2.z; qv.w = q2.w
        end
        go:call("get_Transform"):call("set_Rotation", qv)
    end)
end

-- ⭐⭐ THE GLOBAL SHOULDER SCALE (08-17, C.perch_shrink). THREE writers can put a scale on a
-- perched body: this file's late pin, this file's leap-up arc, and IrisGriffin/stable.lua's IV
-- easer at its choke point. All three multiply by THIS, so they can never disagree by a frame.
-- ⛔ GLOBAL function + a published global VALUE on purpose: the easer lives in another file, and
-- a local over there resolves to a nil global (the cross-file rawget law, learnt the hard way in
-- the rodeo dead-rays saga). Clamped: a fat-fingered config may not scale a companion to nothing.
function iris_perch_shrink()
    local m = tonumber(C.perch_shrink)
    if not m or m ~= m then return 1.0 end   -- nil or NaN out of a mangled config = no change
    if m < 0.25 then return 0.25 end
    if m > 2.0 then return 2.0 end
    return m
end

-- Per-band shoulder placement (GLOBAL: read by the pin + sliders). Per-species scale is
-- deliberately absent: the bloodline IV owns relative size, and the ONE global shrink above
-- owns the ground-vs-shoulder difference. If a single species ever needs its own number, add
-- it here as sp_<band>_psc -- the migration at ~4160 already writes that key.
function iris_species_perch(band9)
    band9 = tostring(band9 or "")
    return {
        x = tonumber(C["sp_" .. band9 .. "_px"]) or 0.0,
        y = tonumber(C["sp_" .. band9 .. "_py"]) or 0.0,
        z = tonumber(C["sp_" .. band9 .. "_pz"]) or 0.0,
        rot = tonumber(C["sp_" .. band9 .. "_prot"]) or 0.0,
    }
end

-- THE DINING SEAT (ox-tame): geometry stopped being negotiated (walk endpoints + facing
-- writes kept composing the shot wrong -- wrong side, beak past the meal): at meal-start the
-- griffin is PLACED -- 3.2m from the carcass on her current side, beak toward it, one write.
local function iris_meter(v, mx)
    -- a compact 10-cell ASCII bar for the rodeo prompts: [====......]
    local f = math.max(0.0, math.min(1.0, (tonumber(v) or 0.0) / math.max(0.0001, tonumber(mx) or 1.0)))
    local k = math.floor(f * 10.0 + 0.5)
    return string.rep("=", k) .. string.rep(".", 10 - k)
end

local function iris_lt_down()
    -- ⭐ LT (0x200 per the mod's own button map ~12677: lt/l2/lefttrigger=0x200) via the gamepad mask --
    -- the rodeo BRACE controller input (07-20, Aurora). RT (0x800) was tried but RT is DD2's GRAB button
    -- and reusing it BROKE the grab; and my first LT guess 0x400 is actually the RIGHT BUMPER (r1/rb), so
    -- it did nothing. 0x200 is the real LT. Defined here (before the tick) so it's in scope.
    local down = false
    pcall(function()
        local gp = sdk.get_native_singleton("via.hid.GamePad")
        local td = sdk.find_type_definition("via.hid.GamePad")
        if not (gp and td) then return end
        local dev = sdk.call_native_func(gp, td, "get_MergedDevice")
        if not dev then dev = sdk.call_native_func(gp, td, "getMergedDevice(System.UInt32)", 0) end
        local mask = dev and tonumber(dev:call("get_Button")) or 0
        down = (math.floor(mask) & 0x200) ~= 0
    end)
    return down
end

local function iris_griffin_resting(go9)
    -- ⭐ is this griffin RESTING at its nest? (Aurora 07-20 + IrisDiveObs.json: Live.Ch253000_SitStart /
    -- SitLoop = nest-sitting.) A resting griffin must NOT be soar-hinted or lured -- she's not hunting.
    local resting = false
    pcall(function()
        local fsm = comp(go9, "via.motion.MotionFsm2")
        if not fsm then return end
        -- SitLoop lives on the LIVE layer (IrisDiveObs saw "Live.Ch253000_SitLoop"), which is NOT
        -- guaranteed to be tree 0 -- scan every tree so a nesting griffin can't slip the gate.
        for tr = 0, 3 do
            local nd = fsm:call("getCurrentNodeName", tr)
            nd = nd and tostring(nd) or ""
            if nd:find("Sit", 1, true) then resting = true; break end
        end
    end)
    return resting
end

local function iris_player_is_attacking()
    -- ⭐ CLASS-AGNOSTIC "the player is mid attack/cast" (Fable recon 07-20): poll the player's
    -- ActionManager CURRENT ACTION NAME across layers and match it to attack/cast patterns. NO hit
    -- needed -- the damageProc route attributes a sorceror's staff bolt to the PROJECTILE, not the
    -- caster, so it never registered; reading the ACTION works for staff AND cleave alike. Records
    -- the seen action name to S.oxtame_atk_dbg so the status line can reveal names to widen patterns.
    local pl = get_player()
    if not pl then return false end
    local pats = tostring(C.oxtame_attack_patterns or "attack,atk,magic,magick,cast,skill,shot,bolt")
    local function match_pat(name)
        if not name or name == "" then return false end
        local lo = tostring(name):lower()
        for raw in pats:gmatch("[^,%s]+") do
            if raw ~= "" and lo:find(raw:lower(), 1, true) then return true end
        end
        return false
    end
    -- (A) LATCH from the requestActionCore hook (GriffinRideProbe stamps the player's last requested
    -- action into _G) -- this fires even when the current-action read is blank (the sorceror case).
    -- ⚠ the window MUST exceed the ox-tame tick interval (~0.7s) or a single cast expires BETWEEN ticks
    -- and never counts (Aurora 07-20: latch saw "rapidshot" but BREAK stayed 0 -- 0.5s < 0.7s tick). Also
    -- widened to 2.5s so a SLOW weapon's swing gap stays latched = same drain rate as a fast staff (fair).
    local latch_node, latch_hit = "", false
    if (os.clock() - (tonumber(_G.IrisPlayerActionAt) or 0.0)) < 2.5 then
        latch_node = tostring(_G.IrisPlayerActionNode or "")
        latch_hit = match_pat(latch_node)
    end
    -- (B) POLL the current action name across layers (works for melee that DOES report a current action)
    local am = nil
    pcall(function() am = pl:call("get_ActionManager") end)
    local poll_hit, seen = false, ""
    if am then
        for li = 0, 5 do
            local nm = nil
            pcall(function() nm = am:call("getCurrentActionName(System.UInt32)", li) end)
            nm = nm and tostring(nm) or ""
            if nm ~= "" then
                if seen == "" then seen = nm end
                if match_pat(nm) then poll_hit = true; seen = nm; break end
            end
        end
    end
    local hit = latch_hit or poll_hit
    -- diagnostic: show whatever name we saw (prefer the poll's, else the latched request)
    local dbg = (seen ~= "" and seen) or (latch_node ~= "" and latch_node) or "-"
    S.oxtame_atk_dbg = (hit and "ATK:" or "act:") .. dbg
    return hit
end

function iris_oxtame_seat(ch9, go9, corpse9, at9)
    local sx9, sz9, fy9, gy9
    pcall(function()
        local dx9 = (tonumber(at9.x) or 0.0) - corpse9.x
        local dz9 = (tonumber(at9.z) or 0.0) - corpse9.z
        local dl9 = math.sqrt(dx9 * dx9 + dz9 * dz9)
        if dl9 < 0.1 then dx9, dz9, dl9 = 1.0, 0.0, 1.0 end
        sx9 = corpse9.x + dx9 / dl9 * 3.2
        sz9 = corpse9.z + dz9 / dl9 * 3.2
        -- GROUND-PROBE the seat spot (07-18: on a STEEP hill the ground 3.2m from the corpse can
        -- sit metres off the corpse's own Y -- pinning to corpse.y then floats/clips her and the
        -- physics fights = the "broken spam" over uneven terrain, Aurora images 146/147). Cast at
        -- the seat spot for the REAL contact height; fall back to corpse.y in the void.
        gy9 = corpse9.y
        pcall(function()
            local b0 = _G.IrisGriffinBridge
            local hb9 = b0 and b0.ground_below and b0.ground_below(sx9, corpse9.y + 4.0, sz9, 6.0, 40.0)
            if hb9 and tonumber(hb9.y) then gy9 = tonumber(hb9.y) end
        end)
        local pv9 = ValueType.new(sdk.find_type_definition("via.Position"))
        pv9.x = sx9; pv9.y = gy9; pv9.z = sz9
        set_upos(go9, pv9)
        fy9 = math.atan(corpse9.x - sx9, corpse9.z - sz9)
        local q9 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
        q9.x = 0.0; q9.y = math.sin(fy9 / 2.0); q9.z = 0.0; q9.w = math.cos(fy9 / 2.0)
        go9:call("get_Transform"):call("set_Rotation", q9)
    end)
    pcall(function() set_player_fsm(go9, false) end)
    -- KEEP her PLANTED (07-18): a one-shot snap gets floated back up by an air-seized griffin's
    -- flight physics (images 144/145 -- she fed, sated, and reached the palm while HOVERING). Pin
    -- her to the seat spot every frame via the bridge ground-hold (position/rotation only --
    -- collision intact so the later mount-climb still works). The rodeo takeoff replaces it. The
    -- pin Y is the PROBED ground height, not corpse.y, so she sits flush on slopes.
    pcall(function()
        if sx9 and sz9 and fy9 then
            local b0 = _G.IrisGriffinBridge
            if b0 and b0.oxtame_hold then b0.oxtame_hold(ch9, sx9, (gy9 or corpse9.y), sz9, fy9) end
        end
    end)
end

-- the EXACT world spot the shoulder pin targets (joint world + yaw-basis offsets + species
-- tuning). Shared by the CLIMB so it tops out precisely where the pin takes over -- climbing
-- one flank and pinning to the other read as a teleport (Aurora, twice).
function iris_perch_point(go9)
    local out9 = nil
    pcall(function()
        local p9 = get_player()
        local pgo9 = p9 and char_go(p9)
        local ptf9 = pgo9 and pgo9:call("get_Transform")
        local pu9 = pgo9 and upos(pgo9)
        local prp9 = ptf9 and ptf9:call("get_Position")
        local prot9 = ptf9 and ptf9:call("get_Rotation")
        if not (pu9 and prp9 and prot9) then return end
        local bx9, by9, bz9 = pu9.x, pu9.y + 1.3, pu9.z
        for j9n in tostring(C.perch_joint or "R_Arm_Clavicle,Spine_2"):gmatch("[^,%s]+") do
            local j9 = ptf9:call("getJointByName", j9n)
            local jp9 = j9 and j9:call("get_Position")
            if jp9 then
                bx9 = pu9.x + (jp9.x - prp9.x)
                by9 = pu9.y + (jp9.y - prp9.y)
                bz9 = pu9.z + (jp9.z - prp9.z)
                break
            end
        end
        local fx9 = 2.0 * (prot9.x * prot9.z + prot9.w * prot9.y)
        local fz9 = 1.0 - 2.0 * (prot9.x * prot9.x + prot9.y * prot9.y)
        local yaw9 = math.atan(fx9, fz9)
        local sy9, cy9 = math.sin(yaw9), math.cos(yaw9)
        local sp9 = iris_species_perch(tostring(go_name(go9) or ""):match("ch%d+"))
        local ox9 = (tonumber(C.perch_x) or 0.1) + sp9.x
        local oy9 = (tonumber(C.perch_y) or 0.05) + sp9.y
        local oz9 = (tonumber(C.perch_z) or 0.0) + sp9.z
        out9 = { x = bx9 + cy9 * ox9 + sy9 * oz9, y = by9 + oy9, z = bz9 + (-sy9) * ox9 + cy9 * oz9 }
    end)
    return out9
end

-- the TYPING GUARD (Aurora: typing to the pawn triggered every IRIS hotkey -- it even
-- unbound her tame key once): every keyboard hotkey read routes through here; while the
-- RiftSpeak prompt box is open, no key exists. GLOBAL -- the probe uses it too.
function iris_kb(vk9)
    -- 08-09: the real policy lives in 000IrisInputGate.lua (REFramework overlay open,
    -- any RiftSpeak box open, a rebind capture armed). The line below it is the
    -- standalone fallback for a missing/failed gate file.
    if type(iris_input_blocked) == "function" and iris_input_blocked() then return false end
    if _G.RiftSpeakPromptOpen == true or _G.RiftSpeak_PromptOpen == true then return false end
    local dn9 = false
    pcall(function() dn9 = reframework:is_key_down(vk9) == true end)
    return dn9
end

-- EVERY collision layer a character carries, one switch (the climb push survived the
-- controller AND AdjustPress disables -- via.physics colliders are their own layer too)
function iris_body_solid(ch9, go9, on9)
    pcall(function() ch9:call("setCharacterControllerEnable", on9 == true) end)
    for _, tn9 in ipairs({ "app.AdjustPress", "via.physics.RequestSetCollider", "app.HitController" }) do
        pcall(function() local c9 = comp(go9, tn9); if c9 then c9:call("set_Enabled", on9 == true) end end)
    end
end

local function creature_label(go2)
    -- proper-case per-creature name from the object name (never lowercase "the wolf")
    local nm = tostring(go_name(go2) or "")
    if nm:find("ch253", 1, true) then return "Griffin" end
    if nm:find("ch223", 1, true) then
        -- a converted cat wears a wolf/dog band name (08-05, Aurora: the puma tame
        -- introduced itself as "Dog") -- ask the cats module which this body really is
        local capi = rawget(_G, "__iris_wild_cats_api")
        if capi and capi.cat_kind then
            local kind = nil
            pcall(function() kind = capi.cat_kind(go2) end)
            if kind == "panther" then return "Panther" end
            if kind == "puma" then return "Puma" end
        end
        -- ⛔ 08-14: that ask was DEAD for nine days (IrisWildCats exported claim_next, play and
        -- is_cat but never cat_kind), which is how a wild puma's native B prompt came to read
        -- "Tame the Dog". NEVER let another file's load order decide a creature's NAME. The
        -- chassis id is the same truth the cats registry is built from, and the same rule the
        -- stable already names by: with the IRIS cat pak the Redwolf prefabs ARE the cats.
        local var = nm:match("ch223001_(%d+)")
        if var == "01" then return "Panther" end
        if var == "00" then return "Puma" end
    end
    if nm:find("ch223001", 1, true) then return "Dog" end
    if nm:find("ch223", 1, true) then return "Wolf" end
    if nm:find("ch299410", 1, true) then return "Crow" end
    if nm:find("ch299430", 1, true) then return "Bird" end
    if nm:find("ch299400", 1, true) then return "Bat" end
    if nm:find("ch299440", 1, true) then return "Bat" end
    if nm:find("ch299420", 1, true) then return "Seabird" end
    if nm:find("ch299210", 1, true) then return "Rat" end
    if nm:find("ch299200", 1, true) then return "Rabbit" end
    if nm:find("ch299003", 1, true) then return "Ox" end
    if nm:find("ch299010", 1, true) then return "Stag" end   -- THE HUNT's quarry since 08-14
    if nm:find("ch299011", 1, true) then
        -- 07-24 (Aurora #6): a CONVERTED horse and a wild doe are both
        -- ch299011 — ask the wild-horses registry which this is.
        local api = rawget(_G, "__iris_wild_horses_api")
        -- ⛔ ASK UNICORN FIRST (08-12). A unicorn is ALSO a horse by design: its `kind` stays
        -- "horse" precisely so the ~15 downstream kind=="horse" consumers keep working, and
        -- is_horse therefore returns true for it. Asking is_horse first named every unicorn
        -- "Horse" - the same ordering trap the stable's display name already had to solve.
        if api and api.is_unicorn and api.is_unicorn(go2) then
            return "Unicorn"
        end
        if api and api.is_horse and api.is_horse(go2) then
            return "Horse"
        end
        return "Doe"
    end
    if nm:find("ch299020", 1, true) then return "Goat" end
    if nm:find("ch299221", 1, true) then return "Hen" end
    if nm:find("ch299220", 1, true) then return "Rooster" end   -- 08-12: the rooster nameplate leaked its raw id
    if nm:find("ch220", 1, true) then return "Goblin" end
    if nm:find("ch221", 1, true) then return "Saurian" end
    if nm:find("ch222", 1, true) then return "Harpy" end
    -- ⭐ THE ONE NAME BOOK (08-12): anything the ladder above missed asks the shared
    -- registry before surrendering to a raw chassis id
    local reg = rawget(_G, "IrisSpecies")
    if reg and reg.name then
        local rn = nil
        pcall(function() rn = reg.name(nm) end)
        if rn then return rn end
    end
    local sp = nm:match("ch%d+")
    return sp and sp or "Creature"
end

local function is_cat(go2)
    local lb = creature_label(go2)
    return lb == "Puma" or lb == "Panther"
end

local function iris_screen_text(s, x, y, col, base)
    -- ⭐ ONE ON-SCREEN FACE (07-21, Aurora: "the same font as the Break/Grip bars"): route
    -- every player-facing string through the shared d2d text layer (IrisFont.lua) so markers
    -- and the creature HUD wear the same serif as the rodeo gauges.
    -- ⛔ WHY A HELPER AND NOT AN IN-PLACE EDIT: REFramework's draw.text takes NO font
    -- argument at all -- it paints on imgui's background drawlist with the default bitmap
    -- face and can never be restyled. It survives here ONLY as the no-d2d fallback.
    -- Resolved LAZILY: autorun load order is alphabetical, so never assume IrisFont is up.
    local F = _G.IrisFont
    if F and F.text and F.text(s, x, y, col, base or 19) then return end
    pcall(draw.text, s, x, y, col)
end

local function draw_marker(go2, label, color)
    pcall(function()
        local tf = go2:call("get_Transform")
        local pos = tf:call("get_Position")   -- RENDER space: world_to_screen's language
        pos.y = pos.y + 1.4
        local sp2 = draw.world_to_screen(pos)
        if sp2 then
            draw.filled_circle(sp2.x, sp2.y, 6, color, 12)
            iris_screen_text(label, sp2.x + 10, sp2.y - 8, color, 17)
        end
    end)
end

local function draw_marker_at_universal(pgo, ux, uy, uz, label, color)
    -- marker at a stored UNIVERSAL position: convert to RENDER space at draw time via the player's
    -- own universal-render offset (render coords shift with world streaming -- storing them drifts
    -- by whole tiles; universal is the stable form, the offset is re-derived every frame)
    pcall(function()
        local tf = pgo:call("get_Transform")
        local rp = tf:call("get_Position")            -- player RENDER
        local up = tf:call("get_UniversalPosition")   -- player UNIVERSAL
        if not (rp and up) then return end
        -- reuse the fetched vector (same trick as draw_marker: mutate, then world_to_screen)
        local ox, oy, oz = up.x - rp.x, up.y - rp.y, up.z - rp.z
        rp.x = ux - ox; rp.y = uy - oy + 1.6; rp.z = uz - oz
        local sp2 = draw.world_to_screen(rp)
        if sp2 then
            draw.filled_circle(sp2.x, sp2.y, 7, color, 12)
            iris_screen_text(label, sp2.x + 10, sp2.y - 8, color, 17)
        end
    end)
end

local function iris_griffin_posture(wch)
    -- ⭐⭐⭐ WHAT IS SHE ACTUALLY DOING (07-25, the card rework). Every wrong card in the rite comes
    -- from the same habit: we narrate OUR INTENTIONS instead of HER BEHAVIOUR. "A wild griffin
    -- SOARS near" fired on any griffin in range -- roosting, asleep, nesting, didn't matter. "Far
    -- off, the griffin BANKS AND TURNS" fired while she sat in her nest. "GET CLEAR, she DIVES"
    -- fired when we dispatched a drive, not when she dived.
    -- Her FSM has always known. Ask it, and the cards stop lying.
    local nm = nil
    pcall(function()
        local b = _G.IrisGriffinBridge
        if b and b.oxtame_node_name then nm = b.oxtame_node_name(wch) end
    end)
    if not nm then return "unknown", nil end
    nm = tostring(nm)
    -- ⛔⛔⛔ THE `Catch.` TREE IS NOT A DIVE (07-26, the hanging-in-the-sky screenshot).
    -- `Catch.Ch253AirSwoopCatchToEatLoopBrake` contains the word "Swoop", so a substring test calls
    -- it a stoop -- but it is her PREDATION GRAB: she has snatched something and is HOVERING WHILE
    -- HOLDING IT. Seizing into it pins her at hover height, the drive cannot pull her down, the
    -- vertical stall hands the body back, and it re-seizes forever -- a griffin hung vertically in
    -- the clouds at 19m with the marker cheerfully reading "DIVING for the offering!".
    -- ⚠ AND WHAT IS SHE HOLDING? We set `PredationTarget = player` to make her come. At close range
    -- that instruction means CATCH AND EAT THE PLAYER. Check this BEFORE the Swoop test, always.
    -- ⭐⭐⭐ A CATCH DIVE IS STILL A DIVE (07-26, Aurora: *"it currently seems to take too long for the
    -- puppet to take over -- so the griffin hits the ground before the puppet takes control"*).
    -- She is right, and the cause is this test being too wide. The whole `Catch.` tree was banned
    -- after the hanging-in-the-clouds run -- but that tree has TWO halves, and only one of them is
    -- the hazard:
    --   `...CatchToEatStart` = the vocal/wings-set WIND-UP. It looks committed, but the root can
    --      still be stationary; it is not evidence of a dive.
    --   `...CatchToEatLoopAccel` = the SWOOP. This only counts as a dive when the root is also
    --      physically travelling down (the caller checks vertical velocity).
    --      exactly the dive the rite is waiting for, and we were refusing it all the way to the floor
    --      (`DESCENT dispatched (grounded pacify)` only fired once she had ALREADY landed, which is
    --      the `Locomotion.FrontFall` crash Aurora keeps seeing).
    --   `...LoopBrake` and the rest = the HOLD. She has caught something and is hovering with it;
    --      seizing there pins her at hover height, the drive cannot pull her down, and she hangs
    --      vertically in the sky forever. THAT is the bug the ban was written for, and it is kept.
    -- ⚠ Remember WHY she is on this tree at all: we set `PredationTarget = player`, so at close range
    -- her dive is "catch and eat the player". The seize clears PredationTarget as it takes her, so
    -- catching her mid-swoop is also what STOPS her completing the catch.
    if nm:find("Catch.", 1, true) then
        -- CatchToEatStart is the howl/crouch/wings-set WIND-UP, not translation. Treating the pose as
        -- a dive caused the 19:27 hand-off: puppet started at 136m while the body was not descending,
        -- FlightControl retained authority, and the two writers drove her into the receding/circle CTD.
        if nm:find("Accel", 1, true) then return "stoop", nm end
        if nm:find("Start", 1, true) then return "lineup", nm end
        return "catch", nm
    end
    -- PreSwoop is only the high circling/line-up. Calling it a stoop lets the puppet seize before
    -- the dive exists—the exact early takeover Aurora ruled out. Wait for SwoopAttack/Catch accel.
    if nm:find("PreSwoop", 1, true) then return "lineup", nm end
    if nm:find("Swoop", 1, true) or nm:find("WindRush", 1, true) then return "stoop", nm end
    if nm:find("Fly.", 1, true) then return "aloft", nm end
    -- ⛔ `SitEnd` contains "Sit" -- she is standing UP, not settled (this substring has bitten the
    -- wake ladder twice already)
    if not nm:find("SitEnd", 1, true) and (nm:find("Sit", 1, true) or nm:find("Liedown", 1, true)
        or nm:find("LieDown", 1, true) or nm:find("Rest", 1, true)) then return "roost", nm end
    return "ground", nm
end

local function iris_griffin_node(wch)
    -- her raw FSM node, for the log. The posture helper above CLASSIFIES it; sometimes you want the
    -- name itself -- a diagnostic that only prints "aloft" cannot tell you WHICH flight node owns her.
    local nm = nil
    pcall(function()
        local b = _G.IrisGriffinBridge
        if b and b.oxtame_node_name then nm = b.oxtame_node_name(wch) end
    end)
    return nm and tostring(nm) or nil
end

local function oxt_beat(st, key, title, sub, secs, color)
    -- ONE CARD PER BEAT, PER SCENE (07-25, Aurora: "a lot of them pop up at the wrong time, or pop
    -- up more than once"). FIVE separate cards used to announce the same moment -- one per dispatch
    -- path (seize / call / relocate / ferry / drive) -- written when only one path could ever fire
    -- in a run. Native travel means several now fire in a single approach, which is the repeat.
    -- A beat is a STORY MOMENT, not a code path: it happens once, whoever causes it.
    if not st then return false end
    st.beats = st.beats or {}
    if st.beats[key] then return false end
    st.beats[key] = true
    set_prompt(title, sub, secs, color)
    return true
end

-- ⭐⭐⭐ THE CARDS ARE HER NODES (07-26, Aurora: "why can't we tie the notifications to the nodes?
-- Surely that'd be easier? and make it only show once so it doesn't spam or appear in weird places.
-- Having it say 'It's diving' when it's actually diving would be nice").
-- She is right, and it is the end point of the whole rework. Every wrong card tonight came from
-- announcing OUR DISPATCH -- five sites all claiming the same moment, each true only sometimes. The
-- story was never in our code, it was in her FSM: she stands, she takes wing, she traces a path, she
-- lines up, she stoops. Watch the node CHANGE and the narration writes itself -- correct by
-- construction, once each, and impossible to fire in a state she is not in.
-- ⭐ 08-11 GENDER-TRUE BANNERS (Aurora: '"She is coming" fires on males too'): the gender
-- used to roll only when the bait was TAKEN (stage bait -> feeding), so every card that
-- fires before that moment hardcoded she/her. Now the roll happens the FIRST time any
-- banner needs it (a wild body carries no gender -- it is ours to invent) and st.gender
-- carries it through the whole scene into the stable record at the pact.
-- Card text uses tokens: {SHE}/{She}/{she} + {her}=POSSESSIVE (her/his) +
-- {herO}/{HERO}=OBJECT (her/him). Possessive and object diverge for males -- never
-- collapse them into one token.
local function oxt_gender(st)
    if st and st.gender ~= "female" and st.gender ~= "male" then
        -- 08-12: the offering ox's chassis knows its own sex (cow band / bull band)
        local g9 = nil
        pcall(function()
            local sp9 = rawget(_G, "IrisSpecies")
            g9 = sp9 and sp9.gender and st.go and sp9.gender(st.go) or nil
        end)
        st.gender = g9 or ((math.random() < 0.5) and "female" or "male")
    end
    return (st and st.gender) or "female"
end
local function oxt_fill(st, txt)
    local f = oxt_gender(st) == "female"
    local s = tostring(txt or "")
    s = s:gsub("{SHE}", f and "SHE" or "HE")
    s = s:gsub("{She}", f and "She" or "He")
    s = s:gsub("{she}", f and "she" or "he")
    s = s:gsub("{her}", f and "her" or "his")
    s = s:gsub("{herO}", f and "her" or "him")
    s = s:gsub("{HERO}", f and "HER" or "HIM")
    return s
end
-- ⛔ ORDER MATTERS: `Catch.Ch253AirSwoopCatchToEat*` contains "Swoop". Specific before general.
local OXT_NODE_CARDS = {
    { m = "Catch.",           key = "catch",   t = "IT HAS YOU",       s = "Talons close -- it means to carry you off. BREAK FREE.",                c = 0xFF4040FF, d = 6.0 },
    { m = "SwoopAttack",      key = "stoop",   t = "THE ANSWER",       s = "The griffin folds {her} wings and DIVES for your offering. GET CLEAR!", c = 0xFFFF8060, d = 8.0 },
    { m = "WindRush",         key = "stoop",   t = "THE ANSWER",       s = "The griffin folds {her} wings and DIVES for your offering. GET CLEAR!", c = 0xFFFF8060, d = 8.0 },
    { m = "PreSwoop",         key = "lineup",  t = "IT LINES UP",      s = "The griffin wheels above the offering, picking {her} moment...",        c = 0xFFFFD080, d = 5.0 },
    { m = "FlightPathTrace",  key = "inbound", t = "{SHE} COMES",      s = "Far off, the griffin turns onto a line for your offering.",             c = 0xFFFFD080, d = 6.0 },
    { m = "PatrolTakeOff",    key = "wing",    t = "{SHE} TAKES WING", s = "The griffin leaves {her} roost -- the scent has reached {herO}.",       c = 0xFFFFD080, d = 6.0 },
}

local function oxt_stoop_beat(st, wch)
    -- ⭐⭐⭐ ONE DOOR FOR THE DIVE CARD (07-26, Aurora: "it said 'it's diving keep clear' when it
    -- wasn't diving, then when it DID dive it said 'It circles'. I thought we had the notifications
    -- gated?"). We did -- at ONE of the five sites. The other four still shouted their original
    -- text from whatever dispatch reached them first, so the beat was spent on a lie and the truth
    -- had nowhere left to fire.
    -- ⇒ every site now calls this, and it asks her body. If she is not stooping it says NOTHING:
    -- GET CLEAR exists to make the player move, and there is nothing to dodge from a griffin in
    -- level flight. The marker already narrates the approach.
    if iris_griffin_posture(wch) ~= "stoop" then return false end
    return oxt_beat(st, "stoop", "THE ANSWER", oxt_fill(st, "The griffin folds {her} wings and DIVES for your offering. GET CLEAR!"), 8.0, 0xFFFF8060)
end

local function nests_load()
    -- the GRIFFIN NEST SURVEY ledger (the egg hunt's map): lazy-loaded so both the panel
    -- and the world markers can be the first to touch it
    if S.nests then
        _G.IrisGriffinNests = S.nests   -- keep the guard's reference fresh across taming reloads
        return S.nests
    end
    S.nests = {}
    pcall(function()
        local d9 = json.load_file("IrisNestSurvey.json")
        if d9 and type(d9.nests) == "table" then S.nests = d9.nests end
    end)
    -- published BY REFERENCE (the roster pattern): IrisFarming's monster guard draws a 50m
    -- no-monster ring around every surveyed nest (griffins + wildlife exempt by species there)
    _G.IrisGriffinNests = S.nests
    return S.nests
end

local function groutes_load()
    -- the cartographer's ledger (griffin route nodes + rest spots), lazy + migrated
    if S.groutes then return S.groutes end
    S.groutes = json.load_file("IrisGriffinRoutes.json") or {}
    S.groutes.nodes = S.groutes.nodes or {}
    -- migrate: 4294967295 = UInt32 -1 = the "off the graph" SENTINEL, not a node (image 50) --
    -- its position was real (it fired at the roost), so it survives as a coord-keyed rest spot
    local sent = S.groutes.nodes["4294967295"]
    if sent then
        S.groutes.nodes["4294967295"] = nil
        sent.rest = true
        local k = string.format("r_%d_%d", math.floor((tonumber(sent.x) or 0) / 10), math.floor((tonumber(sent.z) or 0) / 10))
        if not S.groutes.nodes[k] then S.groutes.nodes[k] = sent end
        pcall(function() json.dump_file("IrisGriffinRoutes.json", S.groutes) end)
    end
    return S.groutes
end

local function groutes_nearest_id(x0, z0, max_r)
    -- ⭐⭐⭐ NEAREST ENGINE NODE to a world point (07-25). The waypoint override takes a NODE ID,
    -- not coordinates, so the cartographer's ledger finally gets to do the job it was built for:
    -- 251 of its 299 entries carry a real engine id, stamped at the moment her CurrentNodeId
    -- changed (so her own universal position WAS that node's world position).
    -- ⛔ NUMERIC KEYS ONLY. The 48 `r_<x/10>_<z/10>` entries are our own coord-keyed rest spots --
    -- they have no engine id and can never be fed back as one.
    -- ⚠ THE COLLISION GUARD IS THE RADIUS. The ledger stores no AIMapHash, so a Vermund id and a
    -- Battahl id share one flat table and could silently collide. A node we accept has to be
    -- physically near the target anyway, and a wrong-map id will be kilometres away -- so the
    -- distance cap doubles as the map filter. Nothing far enough to be ambiguous ever qualifies.
    local best, bestd = nil, tonumber(max_r) or 400.0
    for k9, nd9 in pairs((groutes_load() or {}).nodes or {}) do
        if tostring(k9):match("^%d+$") and nd9 and nd9.x and nd9.z then
            local dx9, dz9 = (tonumber(nd9.x) or 0.0) - x0, (tonumber(nd9.z) or 0.0) - z0
            local d9 = math.sqrt(dx9 * dx9 + dz9 * dz9)   -- XZ only: her lane nodes sit 50-200m up
            if d9 < bestd then best, bestd = math.floor(tonumber(k9)), d9 end
        end
    end
    return best, (best and bestd or nil)
end

local function iris_warp_player(x0, y0, z0)
    -- the game's own player warp (devtools' recipe): TimeSkipManager warp with the CURRENT
    -- time passed back = a pure teleport with proper streaming
    pcall(function()
        local tm0 = sdk.get_managed_singleton("app.TimeManager")
        local tsm0 = sdk.get_managed_singleton("app.TimeSkipManager")
        if not (tm0 and tsm0) then return end
        local pos0 = ValueType.new(sdk.find_type_definition("via.Position"))
        pos0.x = x0; pos0.y = y0; pos0.z = z0
        local rot0 = char_go(get_player()):call("get_Transform"):call("get_Rotation")
        tsm0:call("requestPlayerWarp",
            tm0:call("get_InGameHour"), tm0:call("get_InGameMinute"), tm0:call("get_InGameDay"),
            pos0, rot0, nil, true, true)
    end)
end

local function iris_igh()
    -- the in-game clock as a running hour count (nil when unavailable)
    local v = nil
    pcall(function()
        local tm0 = sdk.get_managed_singleton("app.TimeManager")
        if tm0 then v = (tonumber(tm0:call("get_InGameDay")) or 0) * 24 + (tonumber(tm0:call("get_InGameHour")) or 0) end
    end)
    return v
end

local function spawn_prey(pos)
    -- conjure the hunt's quarry through EnemySpawner's machinery (depend, never edit):
    -- require its spawnRequest module, add one instance, pump it per frame until born
    local ok = false
    pcall(function()
        if not S.spawner then
            local SR = require("EnemySpawner/spawnRequest")
            S.spawner = SR:new()
        end
        if not S.spawner then return end
        local q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
        q.x = 0; q.y = 0; q.z = 0; q.w = 1
        local cfg = {
            spawnIdle = false,   -- alive + moving from birth, not a frozen statue
            ovrScale = { enable = false, scale = 1.0, normalizeSpeed = false },
            postProcScale = false,
        }
        -- ⭐ 08-14: THE HORSE SKIP IS GONE ON PURPOSE. It existed because the quarry was a
        -- ch299011 doe -- the exact chassis IrisWildHorses re-skins -- so one hunt in four
        -- conjured a horse the ritual then (correctly) refused to hunt. The quarry is a STAG
        -- (ch299010) now, a band the horses module never touches (its DOE_PREFIX is ch299011),
        -- so the skip is worse than pointless: skip_next_horse sets a STICKY flag that would eat
        -- the next legitimate wild-horse conversion in the world, once per hunt.
        S.spawner:requestAddInstances(tostring(C.hunt_spawn_cid or "ch299010_A_00"), pos, q, cfg, 1)
        S.spawn_pump_until = os.clock() + 15.0   -- pump only while a birth is pending
        S.doe_spawn_pt = { x = pos.x, y = pos.y, z = pos.z }   -- the conjured doe's birthplace
        S.doe_verify_until = os.clock() + 6.0                  -- then count the bodies
        ok = true
        pcall(function() log.info("[IrisTaming] quarry spawn requested (" .. tostring(C.hunt_spawn_cid or "?") .. ")") end)
    end)
    return ok
end

local function despawn_doe()
    -- destroy OUR conjured quarry (if any) and forget its birthplace, so no leftover doe/corpse
    -- bleeds onto the next hunt (a new wolf must start the whole hunt fresh)
    pcall(function()
        if S.hunt_our then
            local dgo = char_go(S.hunt_our)
            if dgo then dgo:call("destroy(via.GameObject)", dgo) end
        end
    end)
    S.hunt_our = nil
    S.doe_spawn_pt = nil
    S.doe_spawn_uni = nil
end

-- The ox is carrion, so Ch253's predation brain will happily travel near it and then refuse the
-- actual stoop. The player is live prey, but using her as the target makes the result depend on the
-- combat/lock-on lists and can end in a real player catch. A dedicated rat underneath the carcass is
-- both a live target the native predator understands and an honest destination at the offering.
-- It owns a separate spawner: the ritual-hunt doe and this internal scene prop must never delete or
-- claim one another's instances.
local function oxtame_decoy_target(st)
    local ch = st and st.decoy_ch
    if not ch then return nil end
    local ok, go = pcall(char_go, ch)
    if not ok or not go then return nil end
    local dead = false
    pcall(function() dead = is_dead(ch) == true end)
    return dead and nil or ch
end

local function oxtame_request_decoy(st, pos)
    if C.oxtame_live_bait == false or not (st and pos) then return false end
    if oxtame_decoy_target(st) then return true end
    if st.decoy_requested then return false end
    if S.oxtame_decoy_spawner then return false end -- prior scene cleanup has not completed yet
    local ok = false
    pcall(function()
        local SR = require("EnemySpawner/spawnRequest")
        local sp = SR:new()
        sp:updateConfig({
            spawnIdle = true,
            instLimit = 1,
            spawnMultiple = { enable = false, qty = 1 },
        })
        local q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
        q.x = 0; q.y = 0; q.z = 0; q.w = 1
        local p = ValueType.new(sdk.find_type_definition("via.Position"))
        -- Wwise can post the rat's birth squeak before Lua receives its component and disables it.
        -- Birth therefore happens far above audible range. On acquisition we stop/disable its own
        -- containers FIRST, then make the one allowed transform write to the real target beneath
        -- the ox. Think is stopped by spawnIdle, so the staging body cannot act or fall away.
        local target_x = (tonumber(pos.x) or 0.0) + 0.20
        local target_y = (tonumber(pos.y) or 0.0) + 0.05
        local target_z = (tonumber(pos.z) or 0.0) + 0.20
        p.x = target_x
        p.y = target_y + 600.0
        p.z = target_z
        sp:requestAddInstances(tostring(C.oxtame_live_bait_cid or "ch299210_A_00"), p, q, {
            spawnIdle = true,
            ovrScale = { enable = false, scale = 1.0, normalizeSpeed = false },
            postProcScale = false,
        }, 1)
        S.oxtame_decoy_spawner = sp
        S.oxtame_decoy_pump_until = os.clock() + math.max(3.0,
            tonumber(C.oxtame_live_bait_spawn_timeout) or 8.0)
        S.oxtame_decoy_pos = { x = target_x, y = target_y, z = target_z }
        S.oxtame_decoy_cleanup_at = nil
        st.decoy_requested = true
        st.decoy_request_at = os.clock()
        ok = true
        log.info("[OxTame] live-bait decoy requested under the offering")
    end)
    return ok
end

local function oxtame_acquire_decoy(st)
    if not st then return nil end
    local have = oxtame_decoy_target(st)
    if have then return have end
    local sp = S.oxtame_decoy_spawner
    if not (sp and sp.instances) then return nil end
    for i = #sp.instances, 1, -1 do
        local born = nil
        pcall(function()
            local inst = sp.instances[i]
            born = inst and inst.instance and inst.instance:get_Chara()
        end)
        local born_dead = false
        if born then pcall(function() born_dead = is_dead(born) == true end) end
        if born and not born_dead and char_go(born) then
            st.decoy_ch = born
            S.oxtame_decoy_ch = born
            local go = char_go(born)
            pcall(function() set_nav_stop(born, true) end)
            pcall(function() set_immunity_soft(born, true) end)
            -- This body exists only as an AI target. Silence both audio component families rather
            -- than guessing individual rat squeak trigger IDs.
            pcall(function()
                local wc = comp(go, "app.WwiseContainerApp")
                if wc then
                    -- Stop anything emitted during the spawn frame, then prevent later triggers.
                    pcall(function() wc:call("stopAll()") end)
                    wc:call("set_Enabled", false)
                end
            end)
            pcall(function()
                local sc = comp(go, "soundlib.SoundContainer")
                if sc then
                    pcall(function() sc:call("stopAll()") end)
                    sc:call("set_Enabled", false)
                end
            end)
            -- One placement after silence, before the Griffin is ever pointed at it. Never
            -- transform-write a live target during flight: that is the exact AITargetPosition race
            -- which crashed the old full-puppet experiment.
            pcall(function()
                local p0 = S.oxtame_decoy_pos
                if p0 then
                    local p = ValueType.new(sdk.find_type_definition("via.Position"))
                    p.x = p0.x; p.y = p0.y; p.z = p0.z
                    set_upos(go, p)
                end
            end)
            pcall(function() log.info("[OxTame] live-bait decoy born and planted under the offering") end)
            return born
        end
    end
    return nil
end

local function oxtame_decoy_seat(st, griffin, griffin_go)
    if st and st.decoy_retired then return false end
    if st and os.clock() < (tonumber(st.decoy_reseat_at) or 0.0) then return false end
    local tgt = oxtame_decoy_target(st)
    if not (tgt and griffin and griffin_go) then return false end
    local ok = false
    pcall(function()
        local c253 = comp(griffin_go, "app.Ch253000")
        if c253 then c253:call("set_PredationTarget", tgt); ok = true end
    end)
    pcall(function()
        if _G.griffin_seat_enemy_target then _G.griffin_seat_enemy_target(griffin, tgt) end
    end)
    S.oxtame_decoy_griffin = griffin
    return ok
end

local function oxtame_decoy_disarm(st, griffin, griffin_go)
    if st then st.decoy_retired = true end
    local gch = griffin or S.oxtame_decoy_griffin
    local ggo = griffin_go or (gch and char_go(gch))
    pcall(function()
        local c253 = ggo and comp(ggo, "app.Ch253000")
        if c253 then c253:call("set_PredationTarget", nil) end
    end)
    pcall(function()
        local bb = ggo and comp(ggo, "app.AIBlackBoardController")
        if bb then bb:call("clearEnemyTargetList") end
    end)
end

local function ground_probe(x, y, z)
    -- universal-in / universal-out ground contact via the main mod's landing ray (nil = void)
    -- ⛔ HISTORY (2026-07-24): b.ground_below was NEVER EXPORTED, so this returned nil for the
    -- entire life of the ox-tame and ~25 call sites silently used their last-resort fallback.
    -- Setting C.oxtame_ground_probe = false restores that old behaviour in one click, which is
    -- the escape hatch if a branch that has never run in the field misbehaves.
    if C.oxtame_ground_probe == false then return nil end
    local hit = nil
    pcall(function()
        local b = _G.IrisGriffinBridge
        -- 40m of reach could not find the floor under an airborne body -- the exact case the
        -- landing/touchdown callers need. The long cast matches the other fallback rungs.
        if b and b.ground_below then hit = b.ground_below(x, y, z, 8.0, 400.0) end
    end)
    return hit
end

-- ⭐⭐⭐ THE QUARRY MUST LAND ON GROUND YOU CAN WALK TO (08-14, Aurora: the quarry stuck in
-- the rock face by the water, and unreachable three tames running).
-- ground_probe answers exactly ONE question - "what is the highest collision surface at or below
-- this Y" - and it answers it about ANY surface: a boulder's flank, the underside of an arch, the
-- BED of a river. The rays do not hit water at all, so a river reads as perfectly good ground a
-- few metres down. Every hunt-spawn bug so far came from treating that one number as "walkable".
-- These helpers vet a berth five ways, all built from the landing ray we already trust (there is
-- no verified navmesh query anywhere in this install, so reachability is geometric, not nav):
--   1 GROUND    a hit at all (nil = void, which is also what open water reads as)
--   2 ELEVATION downhill tight (water is always DOWN), uphill looser
--   3 HEADROOM  probe again from 25m up: a higher surface means something is OVER the berth
--   4 FLATNESS  a 4-point ring at 2m - catches slopes, steps, ledge lips, boulder tops
--   5 WALK LINE sample the straight line from the player, carrying the reference Y forward. A
--               gorge, a river channel and a wall all read as a step - and a quarry you cannot
--               reach is the same bug as a buried one.
-- ⛔ COST DISCIPLINE: the cheap gates (1+2) run over the whole sweep (48 rays); the expensive
-- ones (3+4+5) only run on the 6 best-scoring survivors, in ONE pass, and the relaxed tier reuses
-- that pass's verdicts rather than re-probing. Worst case ~48 + 6x15 + 32 = ~170 rays, once per
-- hunt, in one frame. This game is CPU-bound: if that ever reads as a hitch, halve the bearings
-- in the sweep first - it is the only unconditional cost here.
local function hunt_probe_y(x, y, z)
    local h = ground_probe(x, y, z)
    return h and tonumber(h.y) or nil
end

local function hunt_ground_y(pp, x, z)
    -- ⛔ START THE RAY A LITTLE OVERHEAD, AND NO MORE. The cast keeps only contacts at or below
    -- (start + 1.0) and returns the HIGHEST of them, so the start height is not just "how far
    -- uphill can I see" - it is "how high can something be and still be mistaken for the ground".
    -- Probing from pp.y (the old code) made ground even a metre uphill invisible and biased every
    -- berth downhill toward pits and water. Probing from pp.y + 6.0 (my first pass at this, caught
    -- in review) made a boulder top or a low branch up to 7m over your head eligible as "ground" -
    -- which conjures the stag onto a rock, i.e. the very unreachable-quarry bug being fixed.
    -- +2.0 recovers the uphill metre or two and nothing else. It must stay in step with
    -- C.hunt_spawn_max_rise.
    return hunt_probe_y(x, pp.y + 2.0, z)
end

local function hunt_berth_deep_ok(pp, x, z, gy, want_line)
    -- ⛔⛔ THE HEADROOM PROBE MUST STAY SHORT (red-team, 08-14 - this is the one that would have
    -- shipped broken). The cast returns the HIGHEST contact at or below start+1.0, and this
    -- engine's rays DO hit tree crowns - the ride probe's own comments say so in four places, it
    -- is why its landing ray clamps its upward reach at all. So probing 25m up did not ask "am I
    -- inside a rock", it asked "is there anything overhead at all", and in woodland the answer is
    -- always yes. Every forest berth came back "roofed", all three tiers refused, and the hunt
    -- would have died at its 12s timeout every single time - in wolf country.
    -- ⇒ Ask the narrow question instead: is there a ceiling within ~4m of my head? That is being
    -- INSIDE something. Burial in a cliff is caught far more reliably by the flatness ring and the
    -- walk line below (a buried point's neighbours disagree wildly, and the approach steps up onto
    -- the rock), and by the post-birth watch in the hunt tick.
    local hy = hunt_probe_y(x, gy + 3.0, z)
    if hy and (hy - gy) > (tonumber(C.hunt_spawn_headroom) or 1.5) then return false, "roofed" end
    local lo, hi = gy, gy
    for _, o in ipairs({ { 2.0, 0.0 }, { -2.0, 0.0 }, { 0.0, 2.0 }, { 0.0, -2.0 } }) do
        -- ⛔ gy + 3.0, NOT gy + 6.0 (round-2 review). The cast accepts contacts to start+1.0, so
        -- a +6.0 start let foliage and rock lips up to 7m above the berth count as a neighbour's
        -- "ground" - and anything over the 2.0 spread fails outright. That put woodland straight
        -- back to being rejected as "slope or ledge", two lines under the headroom fix that was
        -- supposed to end exactly that. A neighbour more than 3m up already fails the spread test,
        -- so the extra reach bought nothing but canopy hits.
        local ry = hunt_probe_y(x + o[1], gy + 3.0, z + o[2])
        if not ry then return false, "ring void" end
        if ry < lo then lo = ry end
        if ry > hi then hi = ry end
    end
    if (hi - lo) > (tonumber(C.hunt_spawn_flat) or 2.0) then return false, "slope or ledge" end
    if not want_line then return true end
    local dx, dz = x - pp.x, z - pp.z
    local dd = math.sqrt(dx * dx + dz * dz)
    if dd < 3.0 then return true end
    local steps = math.max(2, math.floor(dd / 3.0))
    local step_max = tonumber(C.hunt_spawn_step) or 2.5
    local prev = pp.y
    for i = 1, steps do
        local tt = i / steps
        local sy = hunt_probe_y(pp.x + dx * tt, prev + 3.0, pp.z + dz * tt)
        if not sy then return false, "no path" end
        if math.abs(sy - prev) > step_max then return false, "step" end
        prev = sy
    end
    return true
end

-- THE ONE PICKER. Both hunt spawn paths call this now - the two divergent inline sweeps that used
-- to live in the tick had different gates, which is why every previous fix only half-landed.
-- Returns a UNIVERSAL {x,y,z}. Four tiers, each more forgiving than the last: fully vetted, then
-- the best one whose only fault was a rough approach, then the best by ground+elevation alone,
-- then a close ring. It only returns nil when not one of 48 swept points had ground at a sane
-- elevation - which in practice means there is nowhere to stand at all.
local function hunt_pick_berth(pp, fx, fz)
    if not pp then return nil end
    local shortlist, why = {}, {}
    for _, rng in ipairs({ 14.0, 20.0, 26.0, 32.0 }) do
        for a = 0, 11 do
            local th = a * (math.pi / 6.0)
            local dx, dz = math.cos(th), math.sin(th)
            local cx, cz = pp.x + dx * rng, pp.z + dz * rng
            local gy = hunt_ground_y(pp, cx, cz)
            if not gy then
                why["void"] = (why["void"] or 0) + 1
            elseif (pp.y - gy) > (tonumber(C.hunt_spawn_max_drop) or 3.0) then
                why["below you"] = (why["below you"] or 0) + 1
            elseif (gy - pp.y) > (tonumber(C.hunt_spawn_max_rise) or 3.0) then
                why["above you"] = (why["above you"] or 0) + 1
            else
                local front = dx * fx + dz * fz          -- >0 = in front of your camera
                shortlist[#shortlist + 1] = { x = cx, z = cz, y = gy,
                    score = math.abs(rng - 22.0) + math.max(0.0, front) * 40.0
                        + math.abs(gy - pp.y) * 2.0 }    -- level with you beats merely legal
            end
        end
    end
    table.sort(shortlist, function(a, b) return a.score < b.score end)
    -- ONE PASS, not two. A candidate that fails only on the walk line has ALREADY paid for its
    -- headroom and flatness probes, so remembering it as the relaxed fallback is free - the old
    -- second pass re-probed the same points and bought nothing but ~50 raycasts.
    -- ⛔ RANK THE FALLBACKS. "step" is a MEASURED bank of 2.5-4m on the way there - you walk
    -- around it. "no path" is the nil-probe case: a void, or a wall taller than the sampler can
    -- see. They are not the same evidence, and taking whichever merely scored better meant a
    -- berth across a gorge could beat one up a shallow rise.
    local fb_step, fb_path = nil, nil
    local tried = 0
    for _, cnd in ipairs(shortlist) do
        if tried >= 6 then break end
        tried = tried + 1
        local ok, reason = hunt_berth_deep_ok(pp, cnd.x, cnd.z, cnd.y, true)
        if ok then
            pcall(function() log.info(string.format(
                "[IrisTaming] quarry berth vetted %.1f,%.1f,%.1f (score %.1f, %d shortlisted)",
                cnd.x, cnd.y + 0.3, cnd.z, cnd.score, #shortlist)) end)
            return { x = cnd.x, y = cnd.y + 0.3, z = cnd.z }
        end
        if reason then why[reason] = (why[reason] or 0) + 1 end
        if reason == "step" and not fb_step then fb_step = cnd end
        if reason == "no path" and not fb_path then fb_path = cnd end
    end
    local fallback = fb_step or fb_path
    if fallback then
        pcall(function() log.info(string.format(
            "[IrisTaming] quarry berth (no clean approach) %.1f,%.1f,%.1f",
            fallback.x, fallback.y + 0.3, fallback.z)) end)
        return { x = fallback.x, y = fallback.y + 0.3, z = fallback.z }
    end
    -- ⭐ AND IT MUST NEVER COME BACK EMPTY-HANDED. Neither spawn path can recover from nil: one
    -- silently skips the hunt, the other retries the identical geometry once and then times out
    -- with "nothing came of the hunt". Every shortlist entry already has verified ground at a sane
    -- elevation - that is exactly what the whole system had BEFORE this change, and it beats no
    -- quarry at all. Deep vetting is a preference, not a precondition.
    -- ⛔ AND PREFER A POINT WE HAVE NO EVIDENCE AGAINST. shortlist[1] is ALWAYS the first
    -- candidate the deep loop tested, so reaching here means it failed - very likely as "roofed",
    -- which is the gate's own word for "inside something". Handing that one back would be
    -- choosing the known-bad point over the merely unknown. Take the best UNTRIED candidate.
    local unv = shortlist[tried + 1] or shortlist[1]
    if unv then
        pcall(function() log.info(string.format(
            "[IrisTaming] quarry berth UNVETTED (%s of %d, ground+elevation only)",
            shortlist[tried + 1] and "best untried" or "best overall", #shortlist)) end)
        return { x = unv.x, y = unv.y + 0.3, z = unv.z }
    end
    -- LAST RESORT - and it is NOT "your own Y six metres back" any more. THAT was the buried
    -- spawn: stand at the foot of a cliff and it put the body inside the rock. A tight ring
    -- close in, keeping the checks that catch geometry, dropping only flatness and the path.
    for _, rng in ipairs({ 8.0, 11.0 }) do
        for a = 0, 7 do
            local th = a * (math.pi / 4.0)
            local cx, cz = pp.x + math.cos(th) * rng, pp.z + math.sin(th) * rng
            local gy = hunt_ground_y(pp, cx, cz)
            if gy and math.abs(gy - pp.y) < 2.0 then
                -- ⛔ NO HEADROOM GATE HERE. It used to be the ONLY gate on this ring, which is
                -- backwards: the last resort should be the most permissive tier, not the one whose
                -- single test is the least reliable.
                pcall(function() log.info("[IrisTaming] quarry berth: LAST RESORT ring at " .. tostring(rng) .. "m") end)
                return { x = cx, y = gy + 0.3, z = cz }
            end
        end
    end
    local parts = {}
    for k, v in pairs(why) do parts[#parts + 1] = k .. "=" .. tostring(v) end
    pcall(function() log.info("[IrisTaming] quarry spawn REFUSED: no walkable berth ("
        .. table.concat(parts, " ") .. ")") end)
    return nil
end

local function is_game_paused()
    -- the real DD2 pause queries (from the freeze-game research): PauseManager:isPausedAny()
    -- for world pause + GuiManager:isPausedGUI() for menu pause -- NOT get_-prefixed
    local paused = false
    pcall(function()
        local pm = sdk.get_managed_singleton("app.PauseManager")
        if pm then
            local ok, v = pcall(function() return pm:call("isPausedAny") end)
            if ok and v == true then paused = true; return end
        end
        local gm = sdk.get_managed_singleton("app.GuiManager")
        if gm then
            local ok2, v2 = pcall(function() return gm:call("isPausedGUI") end)
            if ok2 and v2 == true then paused = true end
        end
    end)
    return paused
end

local function set_player_fsm(go, on)
    -- the devtools-motion-player ingredient: via.motion.MotionFsm2 drives layer 0 every frame;
    -- disable it and changeMotion clips finally OWN the body (re-enable = FSM resumes cleanly)
    pcall(function()
        local f = comp(go, "via.motion.MotionFsm2")
        if f then f:call("set_Enabled", on) end
    end)
end

local function set_player_speed(player, v)
    pcall(function()
        local m = player:call("get_Motion")
        if m then m:call("set_PlaySpeed", v) end
    end)
end

local function play_player_motion(player, id, bank, start_frame, layer_idx)
    -- the PLAYER performs the ritual too (the bank-60 catalogue): asserted only while the
    -- stage rules already demand stillness, so the forced clip and the input rarely fight
    pcall(function() log.info("[IrisTaming] player clip " .. tostring(math.floor(tonumber(bank) or 60)) .. ":" .. tostring(id)) end)
    pcall(function()
        -- one-shot: dump via.motion.Layer's weight/blend API to the log (layer-1 clips fired
        -- but showed nothing -- likely a blend weight; this names the real setter for later)
        if not S.mlayer_dumped then
            S.mlayer_dumped = true
            local names = {}
            local td = sdk.find_type_definition("via.motion.Layer")
            for _, m in ipairs(td:get_methods() or {}) do
                local mn = tostring(m:get_name() or "")
                if mn:lower():find("weight") or mn:lower():find("blend") or mn:lower():find("rate") then
                    names[#names + 1] = mn
                end
            end
            log.info("[IrisTaming] Layer API: " .. table.concat(names, " "))
        end
    end)
    pcall(function()
        -- STUDIO PATH: layer 0 on a think-stopped player (the proven-visible route for these
        -- clips); the caller guarantees the think-stop before asking for the clip.
        -- LAYER 1 = the UPPER-BODY layer (NickCore names it `upperLayer`), used so a gesture can
        -- play while the FSM keeps driving locomotion on layer 0 - the carry-walk law.
        local li = math.floor(tonumber(layer_idx) or 0)
        local layer = player:call("get_Motion"):call("getLayer", li)
        if layer then
            layer:call("changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)",
                math.floor(tonumber(bank) or 60), math.floor(id or 0), tonumber(start_frame) or 0.0, 10.0, 1, 1)
            -- ⚠ a previous attempt noted "layer-1 clips fired but showed nothing - likely a blend
            -- weight". So on layer 1, force the weight up through whatever setter this build
            -- exposes, and LOG which one took, so a silent no-show names its own fix.
            if li > 0 then
                local won = nil
                for _, sig in ipairs({ "set_Weight", "setWeight", "set_BlendRate", "set_LayerWeight", "set_Rate" }) do
                    if won then break end
                    pcall(function()
                        local td = layer:get_type_definition()
                        if td and td:get_method(sig) then
                            layer:call(sig, 1.0)
                            won = sig
                        end
                    end)
                end
                pcall(function()
                    log.info("[IrisTaming] layer1 weight setter = " .. tostring(won or "NONE FOUND - see 'Layer API' dump"))
                end)
            end
        end
    end)
end

-- ⛔⛔⛔ THE DOWNED-BODY ORACLE (GLOBAL; the liveness law, 08-14 unicorn CTD).
-- A downed IRIS companion is ALIVE AT 1 HP with its AI off, parked in the native action node
-- Damage.Damage_Root.DmgDownLoop which IrisGriffin/downed.lua RE-ASSERTS EVERY FRAME. So
-- get_IsDead is false, get_Hp is 1, and every ordinary liveness test in this file waves it
-- straight through. _G.IrisDownedAddrs (keyed by GAMEOBJECT address) is the ONLY oracle.
-- Writing a transform, a scale or a clip onto such a body = the actinter move crash
-- (app.actinter.cmd.move.MoveBase.updateImpl, surfacing as c0000005 in ActionManager.updateAction).
-- ⇒ ANY tick in this file that drives a companion asks this FIRST and stands down if it is true.
function iris_body_downed(go)
    if not go then return false end
    local downed = false
    pcall(function()
        local d = rawget(_G, "IrisDownedAddrs")
        if type(d) ~= "table" then return end
        local a = go:get_address()
        if a and d[a] then downed = true end
    end)
    return downed
end

local function play_motion(ch, bank, id)
    -- direct clip on layer 0 (the puppet law: clips play with logic managed elsewhere)
    -- ⛔ DOWNED GUARD (2026-07-21): while the griffin mod holds a companion in its DOWNED
    -- state it OWNS that body's animation (the collapse node). Without this the tamed upkeep's
    -- idle cycle re-drove the body every frame and stomped the down node -- the rabbit sat
    -- there grooming its ears instead of collapsing. Two writers, one layer 0.
    local downed_blocked = false
    pcall(function() downed_blocked = iris_body_downed(char_go(ch)) end)
    if downed_blocked then return end
    pcall(function()
        local layer = ch:call("get_Motion"):call("getLayer", 0)
        if layer then
            layer:call("changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)",
                math.floor(bank or 0), math.floor(id or 0), 0.0, 8.0, 1, 1)
        end
    end)
end

local function iris_prog_hud(frac, label)
    -- ⭐ THE UNIVERSAL PROGRESS BAR feed (07-21, Aurora: "a bar for any time a % is climbing"):
    -- call every tick while a rite's progress builds; the probe's d2d suite draws a native-styled
    -- amber gauge lower-center and fades it out when the feed stops. Cards keep the flavor text;
    -- the NUMBER lives on the bar now.
    _G.IrisProgressHUD = { active = true, t = os.clock(),
        frac = math.max(0.0, math.min(1.0, tonumber(frac) or 0.0)), label = tostring(label or "") }
end

-- ⭐⭐ THE TAMING-MODE HUD. Two pieces in IRIS's shared Stable face:
--   1) "-- Taming Mode Active --" on the right, clear of the pawn command wheel.
--   2) a fake "Hold [Back] for Stable" line above the button plaque -- the same trick the griffin
--      ride uses for the prompts DD2 withholds (IrisFont.text's per-call face override exists
--      precisely for that job, see its comment).
-- ⛔ THIS IS NOT COSMETIC. While the mode is on, taming outranks IRIS's own prompts, so your bell
-- and cookpot stop answering B. Without a visible marker that reads as a fresh bug.
local function iris_tame_face_text(str, x, y, argb, px)
    local F = _G.IrisFont
    -- Use the already-shared Stable face. A per-call face override caused new DirectWrite
    -- objects to be born during mount transitions; this surface has no reason to own a font.
    if F and F.text and F.text(str, x, y, argb, px) then return end
    iris_screen_text(str, x, y, argb, px)          -- d2d down: the plain fallback still says it
end

-- ⭐⭐⭐ 08-17 THE CONTROL PLAQUE (Aurora: "instead of the controls written at the top in small
-- text, can we amend the UI like we do for everything else including mounts").
-- DD2's own plaque lives bottom-right, right-aligned, one action per line: the words in muted
-- grey, then the glyph. Face buttons wear the console colours; keyboard keys sit in a boxed well.
-- This renders in that exact grammar so a scout reads as part of the game rather than as debug
-- text pasted over the top of it -- and it is GLOBAL so every future "you are driving an animal"
-- mode (rat, rabbit, bat, and whatever comes next) gets the same face for free.
--
-- rows = { { label = "Ping", pad = "Y", key = "V" }, ... }   -- topmost row first
--   pad = the face/shoulder glyph ("Y"/"X"/"A"/"B"/"L stick"/"R1"...), key = the keyboard glyph.
--   A row may omit either: the plaque draws whichever suits the device in use.
IRIS_PAD_GLYPH_COLOR = {
    -- DD2's own face-button colours, eyeballed off Aurora's plaque screenshots
    Y = 0xFFE8C860,   -- gold
    X = 0xFF70B0E8,   -- blue
    B = 0xFFE07070,   -- red
    A = 0xFF80D890,   -- green
}
function iris_control_plaque(rows, opts)
    if type(rows) ~= "table" or #rows == 0 then return end
    opts = opts or {}
    local w, h = 1920.0, 1080.0
    pcall(function()
        local ds = imgui.get_display_size()
        if ds then w = tonumber(ds.x) or w; h = tonumber(ds.y) or h end
    end)
    local sc = h / 1080.0
    local px = math.max(12.0, tonumber(opts.px) or tonumber(C.tame_hint_px) or 19.0)
    local line = px * 1.5
    -- ⛔ Anchored to the BOTTOM-RIGHT and grown UPWARD, never downward: the game's own plaque
    -- owns that corner and a fixed top edge would drift into it the moment a mode gains a row.
    local right = w - (tonumber(opts.dx) or 40.0) * sc
    local bottom = h - (tonumber(opts.dy) or 250.0) * sc
    local top = bottom - line * #rows
    local on_pad = S.stable_input_device ~= "keyboard"
    -- rough advance width for this face; the plaque is right-aligned so a small error just
    -- shifts a row a pixel or two rather than colliding with anything
    local function adv(s) return (px * 0.52) * #tostring(s or "") end
    -- ⭐ ALEGREYA, deliberately -- the same per-call face override the griffin's fake button
    -- prompts already use (IrisFont:187). It is the closest LEGAL match to DD2's own "francr"
    -- menu face, so this plaque and the ride prompts wear one typeface between them. Cached
    -- face@px inside IrisFont, so the per-call override costs nothing after the first frame.
    local function ptext(s, x, y, col)
        local F = _G.IrisFont
        if F and F.text and F.text(s, x, y, col, px, nil, "Alegreya.ttf") then return end
        iris_tame_face_text(s, x, y, col, px)
    end
    for i, r in ipairs(rows) do
        local y = top + line * (i - 1)
        local glyph = on_pad and r.pad or (r.key or r.pad)
        local label = tostring(r.label or "")
        if r.header then
            -- a section header (the "Back | Hold for Stable" line in the native plaque)
            ptext(label, right - adv(label), y, 0xFFC8C0A8)
        elseif glyph then
            glyph = tostring(glyph)
            local gw
            if on_pad and #glyph <= 2 then
                -- a bare coloured letter, exactly as the game draws its face buttons
                gw = adv(glyph) + 10.0 * sc
                local gx = right - gw + 4.0 * sc
                ptext(glyph, gx, y, IRIS_PAD_GLYPH_COLOR[glyph] or 0xFFE8E0CC)
            else
                -- shoulder/stick names on pad, and EVERY keyboard key, get the boxed well --
                -- the game boxes Ctrl/Shift/Space the same way.
                -- ⛔ draw.filled_rect eats ABGR, NOT ARGB (byte-swapped constants below); the
                -- IrisFont.text calls on either side take ARGB as authored. Do not "tidy" these
                -- into matching -- they are two different packings and always have been.
                gw = adv(glyph) + 12.0 * sc
                local gx = right - gw
                pcall(function()
                    draw.filled_rect(gx, y - 2.0 * sc, gw, px * 1.25, 0x70141010)
                    draw.filled_rect(gx, y - 2.0 * sc, gw, 1.0, 0x5050A0C8)
                    draw.filled_rect(gx, y - 2.0 * sc + px * 1.25, gw, 1.0, 0x5050A0C8)
                end)
                ptext(glyph, gx + 6.0 * sc, y, 0xFFE8E0CC)
            end
            ptext(label, right - gw - 8.0 * sc - adv(label), y, 0xFFA8A49C)
        else
            ptext(label, right - adv(label), y, 0xFFA8A49C)
        end
    end
end

-- Mount-safe rebuild: the game thread resolves one boolean from PauseManager + ui010201;
-- the render callback never touches scene objects and only queues text in the shared font.
-- It is therefore absent from Start/pause/loading screens and from every mount transition.
local TAME_HUD_ENABLED = true
local function iris_tame_mode_hud()
    if not TAME_HUD_ENABLED then return end
    -- This flag is resolved on LateUpdateBehavior, where scene/UI managed objects are safe.
    -- The render callback below only consumes a boolean and queues text.
    if S.tame_hud_world_visible ~= true then return end
    local w, h = 1920.0, 1080.0
    pcall(function()
        local ds = imgui.get_display_size()
        if ds then w = tonumber(ds.x) or w; h = tonumber(ds.y) or h end
    end)
    local sc = h / 1080.0
    -- ⛔ NEITHER PIECE DRAWS OVER A MENU OR A MOUNT. The Stable screen would cover its own hint,
    -- and while riding, the griffin's own fake-prompt cluster owns that corner of the plaque --
    -- stacking a second line into it is how you get two overlapping prompts arguing.
    if rawget(_G, "IrisStableUIOpen") == true or rawget(_G, "IrisFurnishUIOpen") == true
        or rawget(_G, "IrisCustomizeOpen") == true or S.name_pending
        or rawget(_G, "IrisRiddenNow") or rawget(_G, "IrisGriffinMounted") then return end

    -- ── 1. the mode banner -- ONLY while the mode is on ──
    if S.tame_mode == true and C.tame_mode_marker ~= false then
        -- a slow breath so it reads as live state rather than a static HUD element you stop seeing
        local a = 0.62 + 0.22 * math.sin(os.clock() * 2.0)
        local col = 0x00E8D8B0 | (math.floor(math.max(0.0, math.min(1.0, a)) * 255.0) << 24)
        local px = math.max(14.0, tonumber(C.tame_mode_px) or 23.0)
        iris_tame_face_text("-- Taming Mode Active --",
            w - (tonumber(C.tame_mode_dx) or 395.0) * sc,
            h * (tonumber(C.tame_mode_y) or 0.45), col, px)
    end

    -- ── 2. the fake "Hold [Back] for Stable" prompt, above the game's button plaque ──
    -- ⭐ 08-13 (Aurora): ALWAYS UP, not just in taming mode. It is the discoverability line for the
    -- whole Stable screen -- companions, taming, cancel -- and a hint that only appears once you
    -- are already in the mode cannot teach you how to reach the mode.
    if C.tame_stable_hint == false then return end
    local ppx = math.max(12.0, tonumber(C.tame_hint_px) or 19.0)
    local bx = w - (tonumber(C.tame_hint_dx) or 520.0) * sc
    local by = h - (tonumber(C.tame_hint_dy) or 212.0) * sc
    -- Last-used-device wins. Any pad button/axis marks gamepad; any gameplay keyboard
    -- key marks keyboard. This follows DD2's own live plaque switching instead of the
    -- old 20-second pad latch, which lied long after Aurora had gone back to keys.
    local input_now = os.clock()
    if input_now >= (tonumber(S.stable_input_probe_at) or 0.0) then
        S.stable_input_probe_at = input_now + 0.08
        pcall(function()
            local gp = sdk.get_native_singleton("via.hid.GamePad")
            local td = sdk.find_type_definition("via.hid.GamePad")
            local dv = gp and td and sdk.call_native_func(gp, td, "get_MergedDevice")
            if dv then
                local bits = math.floor(tonumber(dv:call("get_Button")) or 0)
                local ax = dv:call("get_AxisL")
                if bits ~= 0 or (ax and (math.abs(tonumber(ax.x) or 0) > 0.22
                    or math.abs(tonumber(ax.y) or 0) > 0.22)) then
                    S.stable_input_device = "pad"
                end
            end
        end)
        pcall(function()
            -- This project uses Windows virtual-key values. via.hid.Keyboard::getDown expects
            -- the engine key enum on this build, so VK_W/VK_O never registered there.
            for _, vk in ipairs({ 0x57, 0x41, 0x53, 0x44, 0x4F, 0x45, 0x20,
                0x25, 0x26, 0x27, 0x28 }) do
                if reframework:is_key_down(vk) == true then
                    S.stable_input_device = "keyboard"
                    break
                end
            end
        end)
    end
    local on_pad = S.stable_input_device ~= "keyboard"
    local keyname = on_pad and "Back" or "O"
    -- the game boxes its keyboard glyphs (Ctrl / Shift / Space in the plaque), so we box ours:
    -- a dim well with the key name in cream, then the words in the plaque's own muted grey
    local kw = (ppx * 0.62) * #keyname + 12.0 * sc
    local kh = ppx * 1.25
    -- ⛔ draw.filled_rect EATS ABGR, NOT ARGB (imgui drawlist packing -- IrisStableUI keeps an rc()
    -- converter for exactly this). Authored gold ARGB 0x50C8A050 pasted straight in comes out
    -- BLUE, because R and B swap. These two constants are already byte-swapped:
    --   well   ARGB 0x70101014 -> ABGR 0x70141010
    --   border ARGB 0x50C8A050 -> ABGR 0x5050A0C8
    -- ⚠ IrisFont.text on the other hand takes ARGB as authored -- do not swap those.
    pcall(function()
        draw.filled_rect(bx, by - 2.0 * sc, kw, kh, 0x70141010)
        draw.filled_rect(bx, by - 2.0 * sc, kw, 1.0, 0x5050A0C8)
        draw.filled_rect(bx, by - 2.0 * sc + kh, kw, 1.0, 0x5050A0C8)
    end)
    iris_tame_face_text(keyname, bx + 6.0 * sc, by, 0xFFE8E0CC, ppx)
    iris_tame_face_text(on_pad and "Hold for Stable" or "for Stable",
        bx + kw + 8.0 * sc, by, 0xFFA8A49C, ppx)

    -- ── ⭐⭐ 3. THE STICK-CLICK PROMPTS (Aurora 08-18): "if you have an active creature who can
    -- go on the shoulder, an 'L3 Shoulder' fake UI -- and when on the shoulder it changes to
    -- 'L3 Let Down', and one for R3 that's 'R3 Scout'."
    -- ⛔ These CANNOT go through IrisPromptBar: DD2's panel has no L3/R3 slot to relabel (the
    -- slot table is LT/LB/Y/X | RT/RB/B/A), and set_slot can only ever rewrite a slot the game
    -- is already showing. So they are drawn, in the same plaque grammar, at the Return anchor.
    if C.perch_prompt == false or S.scout then return end   -- the scout owns that corner in flight
    local rows8 = nil
    -- throttled: this walks S.tamed, and the plaque redraws every frame
    -- ⛔ SCOPE, and it would have failed SILENTLY: this HUD lives at ~:2400, but name_in_csv
    -- (:2733) and species_clips (:5440) are file LOCALS declared BELOW it. In Lua a name used
    -- above its local declaration compiles to a GLOBAL lookup -- so both would have been nil
    -- here, the builder would have thrown inside its own pcall, and the prompt would simply
    -- never appear with nothing in the log to say why. ⇒ the row builder is a GLOBAL function
    -- defined after those locals (globals resolve at call time, and load finishes long before
    -- the first frame). Same reason iris_sendhome_owns is a global 11k lines from its caller.
    if os.clock() >= (tonumber(S.perch_prompt_at) or 0.0) then
        S.perch_prompt_at = os.clock() + 0.25
        S.perch_prompt_rows = nil
        pcall(function()
            if iris_perch_prompt_rows then S.perch_prompt_rows = iris_perch_prompt_rows() end
        end)
    end
    rows8 = S.perch_prompt_rows
    if rows8 then
        pcall(function()
            iris_control_plaque(rows8, {
                dx = tonumber(C.perch_prompt_dx) or 40.0,
                dy = tonumber(C.perch_prompt_dy) or 181.0,
                px = tonumber(C.perch_prompt_px) or 23.5 })
        end)
    end
end

-- Resolve whether normal gameplay HUD is genuinely visible on the game thread. ui010201's
-- DrawSelf is the field-proven menu/loading signal used by the ride HUD: it is hidden in Start,
-- pause and loading screens. Never walk the scene from re.on_frame.
S.tame_hud_world_visible = false
re.on_application_entry("LateUpdateBehavior", function()
    pcall(function()
        local now9 = os.clock()
        if now9 < (tonumber(S.tame_hud_probe_at) or 0.0) then return end
        S.tame_hud_probe_at = now9 + 0.15
        S.tame_hud_world_visible = false
        if is_game_paused() or rawget(_G, "IrisStableUIOpen") == true
            or rawget(_G, "IrisFurnishUIOpen") == true or rawget(_G, "IrisCustomizeOpen") == true
            or S.name_pending or rawget(_G, "IrisRiddenNow") or rawget(_G, "IrisGriffinMounted") then return end
        local cm9 = sdk.get_managed_singleton("app.CharacterManager")
        local pl9 = cm9 and cm9:call("get_ManualPlayer")
        if not (pl9 and pl9:call("get_GameObject")) then return end
        local sm9 = sdk.get_native_singleton("via.SceneManager")
        local smt9 = sdk.find_type_definition("via.SceneManager")
        local scene9 = sm9 and smt9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
        local ui9 = scene9 and scene9:call("findGameObject(System.String)", "ui010201")
        S.tame_hud_world_visible = ui9 and ui9:call("get_DrawSelf") == true or false
    end)
end)

local function iris_ox_is_tamed(ch0)
    -- ⭐ is this ox FAMILY? (07-21, the yoke rite's non-interference law): a tamed ox is invisible
    -- to the griffin's offering machinery -- never watched, never a corpse-offering, never cleaned
    -- up by the reset button. Checks the seal registry AND the live tamed-pet records (the stable
    -- re-adopt path repopulates S.tamed across script resets).
    if not ch0 then return false end
    local a0 = nil
    pcall(function() a0 = ch0:get_address() end)
    if not a0 then return false end
    if S.ox_tamed and S.ox_tamed[a0] then return true end
    for k9 in pairs(S.tamed or {}) do
        local ka = nil
        pcall(function() ka = k9.get_address and k9:get_address() end)
        if ka == a0 then return true end
    end
    return false
end

local function release_creature(ch)
    -- undo every ritual hold (nav stop, think stop, AI, lie cue, shield) -- used on leave and loss
    if not (ch and char_go(ch)) then S.lie_cue = nil; _G.IrisTamingTargetAddr = nil; return end   -- dead/despawned handle
    _G.IrisTamingTargetAddr = nil
    pcall(function() set_player_fsm(char_go(ch), true) end)   -- restore the wolf's motion FSM
    set_player_speed(ch, 1.0)   -- never leave a slowed gait behind
    set_nav_stop(ch, false)
    set_think_stop(ch, false)
    set_immunity(ch, false)
    local go2 = char_go(ch)
    for _, tn in ipairs({ "app.AIDecisionMaker", "app.NavigationAI" }) do
        local c = comp(go2, tn)
        if c then pcall(function() c:call("set_Enabled", true) end) end
    end
    -- Do not call Character.resetActionAndAI here.  On this build the bare
    -- overload is not valid; the old out-of-range path invoked it every frame,
    -- flooding the native bridge while a pawn was being carried.  Restoring
    -- think/nav/AI/FSM above is the complete, safer hand-back.
    S.lie_cue = nil
    if S.call_anim_live and _G.NB_Pose then pcall(function() _G.NB_Pose.stop() end); S.call_anim_live = nil end
    -- drop the arm trim so other lab clips (the pet etc.) don't inherit a bent arm; it re-pushes
    -- from config at every call start (leave it live while tuning: nothing clears outside a tame)
    pcall(function() if _G.NB_Pose and _G.NB_Pose.set_trim then _G.NB_Pose.set_trim(tostring(C.arm_trim_bone or "L_Arm_Upper"), 0, 0, 0) end end)
    pcall(function() if _G.NB_Pose and _G.NB_Pose.set_trim then _G.NB_Pose.set_trim("Head_0", 0, 0, 0) end end)   -- and the falconry gaze
    unparent_critter(ch)   -- never leave a body riding the player's hand
    pcall(function() ch:call("setCharacterControllerEnable", true) end)   -- never leave a no-clip body behind
    pcall(function() set_ground_glue(char_go(ch), true) end)              -- nor a terrain-snapless one
    S.ghost_ch = nil; S.ghost_lease = nil   -- the crossing's ghost lease is settled here
    despawn_doe()   -- abandoning the tame abandons any conjured quarry
end

local function nav_follow(ch, pgo)
    -- real pathfinding follow (PetDogProbe): NavigationAI navigationRequest(GameObject)
    local go = char_go(ch)
    local nav = nil
    pcall(function() nav = ch:get_field("<NavigationAI>k__BackingField") end)
    if not nav then pcall(function() nav = ch:call("get_NavigationAI") end) end
    if not nav then nav = comp(go, "app.NavigationAI") end
    if not nav then return false end
    pcall(function() nav:call("set_IsStopCalled", false) end)
    return pcall(function() nav:call("navigationRequest(via.GameObject)", pgo) end)
end

-- ⭐⭐ THE QUARRY IS NOT PART OF THE PEACE (08-14, Aurora: "the quarry has not been
-- killable"). The hunt's kill is the ONE body inside the ritual's radius that must stay
-- hostile, aimable and mortal - that is the entire errand. Both area sweeps below used to
-- reach it: the truce nulls app.LockOnTarget.TargetData (the de-target lever the homestead
-- box uses to make a resident un-aimable), and the pack hold hands out full set_immunity
-- (IsDamageZero + IsIgnoreDamageHit + DamageCollisionOff). Either one and the quarry cannot
-- be killed, so the hunt can never end.
-- ⛔ A FIELD ON S, NOT A CHUNK-LOCAL: this file lives near Lua's 200-local ceiling.
S.is_quarry = function(ch)
    if not ch then return false end
    local a = nil
    pcall(function() a = ch:get_address() end)
    for _, o in ipairs({ (S.trial and S.trial.hunt_ch) or false, S.hunt_our or false }) do
        if o then
            if rawequal(o, ch) then return true end
            local oa = nil
            pcall(function() oa = o:get_address() end)
            if a and oa and oa == a then return true end
        end
    end
    return false
end

local function truce_bubble(pgo, target_ch)
    -- THE TRUCE: while a taming ritual is active, quiet the hate of everyone nearby (pawns most
    -- of all -- they will otherwise maul the yielded/approached creature as a registered enemy).
    -- Throttled sweep; the field goes still around the moment.
    if C.truce_enabled == false then return end
    local now = os.clock()
    if now - (tonumber(S.truce_last) or 0.0) < 0.5 then return end
    S.truce_last = now
    local pp = pgo and upos(pgo)
    if not pp then return end
    -- 08-14: SWEEP BOTH BUBBLES. The rite regularly parks the courted creature far from the
    -- player - during the hunt it sits pinned while the player chases the quarry out to
    -- hunt_leash (150m) - and a player-centred sweep leaves everything standing next to it fully
    -- hostile. That is why villagers and other packs kept mauling a wolf mid-rite. One extra
    -- dist() per candidate; no second scene walk.
    local wp = nil
    pcall(function() wp = upos(char_go(target_ch)) end)
    -- party members are handled SURGICALLY elsewhere (shield_party_off: wolf-only strips, so pawns
    -- still fight goblins mid-tame and the player's lock-on survives). This sweep must therefore
    -- SKIP the party -- it used to strip_hate+clear_targets them wholesale every 0.5s, which both
    -- blinded the pawns to real attackers and nulled the player's own lock-on.
    local skip = {}
    for _, member in ipairs(party_characters()) do
        pcall(function() skip[member:get_address()] = true end)
    end
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        if not comps then return end
        local n = 0
        pcall(function() n = comps:call("get_Length") or 0 end)
        if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local ch = comps:call("get_Item", i) or comps[i]
                local ca = ch and ch:get_address()
                if ch and ch ~= target_ch and not (ca and skip[ca]) and not S.is_quarry(ch) then
                    local go = char_go(ch)
                    local gp9 = go and upos(go)
                    if gp9 and (dist(gp9, pp) < 30.0 or (wp and dist(gp9, wp) < 30.0)) then
                        strip_hate(ch); clear_targets(ch)
                    end
                end
            end)
        end
    end)
end

local function set_ai(ch, enabled)
    local go = char_go(ch)
    if not go then return end
    for _, tn in ipairs({ "app.AIDecisionMaker", "app.NavigationAI" }) do
        local c = comp(go, tn)
        if c then pcall(function() c:call("set_Enabled", enabled == true) end) end
    end
end

local function is_dead(ch)
    local ok, d = pcall(function() return ch:call("get_IsDead") end)
    if ok and d == true then return true end
    local hp = read_hp(hit_controller(ch))
    return tonumber(hp) ~= nil and tonumber(hp) <= 0.0
end

local function name_in_csv(name, csv)
    for pat in tostring(csv or ""):gmatch("[^,%s]+") do
        if name:find("^" .. pat) then return true end
    end
    return false
end

-- ⛔⛔ NEVER HUNT A HORSE. IrisWildHorses re-skins the DOE chassis, so a converted horse is
-- literally `ch299011` -- the first entry in hunt_prey_band and the same id the hunt conjures.
-- Without this the ritual will happily mark your own horse as quarry and send you to kill it.
-- Only the horse registry can tell the two apart (IrisWildHorses.lua:1640), so ask it.
-- Also refuses anything already tamed, and IRIS's own wild-cat variants for good measure.
local function is_huntable(go, nm)
    if not go then return false end
    nm = nm or go_name(go)
    if not name_in_csv(nm, C.hunt_prey_band) then return false end
    local horse = false
    pcall(function()
        local api = rawget(_G, "__iris_wild_horses_api")
        if api and api.is_horse then horse = api.is_horse(go) == true end
    end)
    if horse then return false end
    -- a creature we have already tamed is family, not food
    local tamed = false
    pcall(function()
        local reg = rawget(_G, "__lyra_animal_audio_variants")
        if reg then
            local rec = reg[tostring(go:get_address())]
            if rec and rec.kind then tamed = true end
        end
    end)
    return not tamed
end

-- weapon sheathed? try the known getters; nil = unknown (UI shows it; check skipped when unknown)
local function player_sheathed(player)
    -- nil = detection FAILING (and nil ~= false passes every check -- armed tames slipped through);
    -- the one-shot probe below dumps the REAL Human draw API to the log for the fix
    -- the REAL getter (from the log probe): get_IsDrawedWeapon -- Capcom grammar.
    -- it goes FIRST; the old guesses were returning wrong booleans and blocking sheathed players
    local candidates = { "get_IsDrawedWeapon" }
    local h = nil
    pcall(function() h = player:call("get_Human") end)
    if h and not S.draw_probe_done then
        S.draw_probe_done = true
        pcall(function()
            local names = {}
            local td = h:get_type_definition()
            for _, m in ipairs(td:get_methods() or {}) do
                local mn = tostring(m:get_name() or "")
                if mn:lower():find("draw") then names[#names + 1] = mn end
            end
            for _, f in ipairs(td:get_fields() or {}) do
                local fn = tostring(f:get_name() or "")
                if fn:lower():find("draw") then names[#names + 1] = "F:" .. fn end
            end
            log.info("[IrisTaming] Human draw API: " .. table.concat(names, " "))
        end)
    end
    for _, obj in ipairs({ h, player }) do
        if obj then
            for _, m in ipairs(candidates) do
                local ok, v = pcall(function() return obj:call(m) end)
                if ok and type(v) == "boolean" then return not v end
            end
        end
    end
    if h then
        for _, fn in ipairs({ "<DrawingWeapon>k__BackingField", "<IsDrawWeapon>k__BackingField", "_DrawingWeapon", "DrawingWeapon" }) do
            local ok, v = pcall(function() return h:get_field(fn) end)
            if ok and type(v) == "boolean" then return not v end
        end
    end
    return nil
end

-- ============================ target acquisition ============================
local function pacify_pack(pgo, target_ch)
    -- THE PACK HOLDS: while you tame the target, freeze + quiet the REST of its pack (same
    -- species nearby) so they stop and WATCH instead of mauling you. Re-asserted; restored on end.
    if C.pack_pacify == false then return end
    local now = os.clock()
    if now - (tonumber(S.pack_last) or 0.0) < 0.25 then return end
    S.pack_last = now
    local pp = pgo and upos(pgo)
    if not pp then return end
    -- 08-14: the pack ring follows the COURTED CREATURE too (the player is up to 150m away
    -- during the hunt, and a player-centred ring left the rest of the pack loose around the one
    -- body we are trying to protect)
    local wp = nil
    pcall(function() wp = upos(char_go(target_ch)) end)
    local species = ""
    -- ⛔ WAS match("ch%d%d%d") - THREE digits, so a ch299-band target (ox ch299003, hen
    -- ch299221, rabbit, rat) collapsed to the band "ch299" and prefix-matched EVERY ch299 animal
    -- within 40m, the hunt's quarry included, then handed them all set_immunity(true). A pack is
    -- the SAME CHASSIS: wolves pack with wolves. Cross-band packs are still covered, deliberately
    -- and explicitly, by the C.target_bands csv on the next line down (default "ch223", which is
    -- what keeps a mixed wolf/puma pack holding together).
    pcall(function() species = (go_name(char_go(target_ch)) or ""):match("ch%d+") or "" end)
    local rng = tonumber(C.pack_range) or 40.0
    S.pack = S.pack or {}
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        if not comps then return end
        local n = 0; pcall(function() n = comps:call("get_Length") or 0 end)
        if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local ch = comps:call("get_Item", i) or comps[i]
                if ch and ch ~= target_ch and not is_dead(ch) and not S.tamed[ch] and not S.is_quarry(ch) then
                    local go = char_go(ch)
                    local nm = go and go_name(go) or ""
                    local packmate = (species ~= "" and nm:find(species, 1, true) == 1) or name_in_csv(nm, C.target_bands)
                    local gp8 = go and upos(go)
                    if packmate and gp8 and (dist(gp8, pp) < rng or (wp and dist(gp8, wp) < rng)) then
                        full_pacify(ch); set_ai(ch, false); set_immunity(ch, true); set_nav_stop(ch, true)
                        S.pack[ch] = true
                    end
                end
            end)
        end
    end)
end

local function restore_pack()
    if not S.pack then return end
    for ch in pairs(S.pack) do
        pcall(function()
            if char_go(ch) then
                set_ai(ch, true); set_immunity(ch, false); set_nav_stop(ch, false)
                pcall(function() ch:call("resetActionAndAI") end)
            end
        end)
    end
    S.pack = {}
end

-- ============================ THE TAMING SHIELD (ask #1) ============================
-- Once you flag a creature for taming (armed via N = "taming mode"), NOTHING may kill it and
-- every ally holds off it -- UNTIL you strike it yourself. Your strike turns it into a COMBAT
-- tame: the allies are released to help, the creature can be hurt again, but an HP floor keeps
-- it from dying. Sheathed = it stays fully shielded (do the peaceful ritual instead).
local function shield_party_off(target_ch)
    -- keep the PAWNS off the courted creature, every frame -- SURGICALLY (if goblins jump
    -- the player mid-tame, the pawns must still fight THEM). Per pawn: clear hate toward THE WOLF only + zero
    -- its re-accrual rate, and pluck ONLY the wolf's entries out of the pawn's EnemyActionTargetList.
    -- That list is the goal-planner's actual menu of attack targets (RiftSpeak [PACIFY]/[FOCUS]
    -- proved the strip works AND that hate-clearing alone does NOT stop targeting -- why the first
    -- "gentle" fix failed and the pawns kept swinging). NEVER call updateEnemyTargetList here (rebuilds).
    -- Player untouched (the lock-on survives). Goblins stay hated + targeted.
    local player = get_player()
    local paddr = nil
    pcall(function() paddr = player and player:get_address() end)
    local wgo = char_go(target_ch)
    local waddr = nil
    pcall(function() waddr = wgo and wgo:get_address() end)
    if not waddr then return end
    -- lease the HOLD hooks onto this creature: the updateEnemyTargetList post-hook strips it from
    -- every rebuilt target list, and the relationship post-hook answers FRIEND for any pair that
    -- involves it, while the lease is fresh (re-set each frame; expires on its own -- no cleanup)
    local chaddr = nil
    pcall(function() chaddr = target_ch:get_address() end)
    _G.IrisTamingHoldWolf = { addr = waddr, ch_addr = chaddr, until_t = os.clock() + 0.5 }
    -- ⛔ TWO STRENGTHS, ON PURPOSE (review round 3, 08-14).
    -- The FULL treatment does three things, and only one of them is harmless to hand a stranger:
    --   clear(wgo)            transient, self-healing, safe on anyone.
    --   setCustomRate(wgo,0)  PERMANENT. There is no writer of 1.0 anywhere in this file and
    --                         neither restore_pack nor release_creature undoes it - so handing it
    --                         to a passing town guard means that guard can NEVER work up hate
    --                         toward that creature again, for the life of the body. Fine for the
    --                         party (we own their lifecycle); not fine for the world.
    --   RemoveAt on EnemyActionTargetList  mutates, from the Lua thread, a container this file's
    --                         own notes say the AI "refills AND consumes inside its own update
    --                         tick, between our frames". Pointing that at four pawns we control is
    --                         one thing; pointing it at 32 arbitrary bodies mid-combat is a
    --                         native-AV surface for no gain.
    -- ⇒ The party gets the full treatment. Everyone else gets the hate CLEAR only - because the
    -- acquisition door (install_hate_door_hook) now stops them re-accruing any, which is exactly
    -- what setCustomRate was there to do, without the permanent write.
    local function stand_down(member, light)
        local maddr = nil
        pcall(function() maddr = member:get_address() end)
        if maddr and maddr ~= paddr then          -- never touch the PLAYER (keeps the lock-on alive)
            local mhs = hate_system(member)
            if mhs then
                pcall(function() mhs:call("clear(via.GameObject)", wgo) end)
                if not light then
                    pcall(function() mhs:call("setCustomRate(via.GameObject, System.Single)", wgo, 0.0) end)
                end
            end
            if light then return end
            pcall(function()
                local bb = comp(char_go(member), "app.AIBlackBoardController")
                local list = bb and bb:call("get_EnemyActionTargetList")
                local n = list and (tonumber(list:call("get_Count")) or 0) or 0
                for i = n - 1, 0, -1 do   -- reverse: RemoveAt shifts the tail
                    pcall(function()
                        local at = list:call("get_Item", i)
                        local ago2 = at and at:call("get_GameObject")
                        if ago2 and ago2:get_address() == waddr then list:call("RemoveAt", i) end
                    end)
                end
            end)
        end
    end
    for _, member in ipairs(party_characters()) do
        stand_down(member)
    end
    -- ⛔⛔ 08-14: THIS SWEEP HAD NEVER TOUCHED A STRAY PAWN. It filtered candidates on
    -- `id:match("^ch100")` - but an unhired/stray pawn is the ch11xxxx chassis, not ch100
    -- (HostileUnhiredPawns-1.2.0.lua:157 buckets ch11* as a sub pawn; get_CharaIDString returns
    -- "ch110021_00"-shaped ids). The ONLY body that filter ever admitted was the MAIN pawn, which
    -- the party loop twenty lines up had already handled. So the block written specifically to
    -- stop a stray pawn mauling the courted wolf was a no-op from the day it was added, which is
    -- exactly what Aurora watched happen: "a stray pawn was attacking the wolf the entire time".
    -- ⇒ The ask is "nobody attacks it", so stop guessing at chassis prefixes and treat EVERY
    -- body near the creature. stand_down is surgical by construction - it clears hate toward THIS
    -- creature, zeroes its accrual RATE, and removes only this one entry from the attacker's
    -- action list. Their fight with anything else is untouched, and the PLAYER is skipped inside
    -- stand_down (that skip is what keeps her lock-on alive).
    local now = os.clock()
    if now >= (tonumber(S.stray_shield_at) or 0.0) then
        S.stray_shield_at = now + 0.25
        pcall(function()
            local sm = sdk.get_native_singleton("via.SceneManager")
            local smt = sdk.find_type_definition("via.SceneManager")
            local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
            local chars = scene and scene:call(
                "findComponents(System.Type)", sdk.typeof("app.Character"))
            local wp = wgo and upos(wgo)
            local list9 = chars and chars:get_elements() or {}
            -- ⛔ A ROLLING CURSOR, NOT THE FIRST 32. findComponents returns a stable order, so a
            -- flat cap meant the same bodies were treated every sweep forever and anything past
            -- the cut was NEVER touched - and a late-registered body (a stray pawn that just
            -- wandered in) sits at a high index, i.e. exactly the one most likely to be missed.
            -- Start where the last sweep stopped and wrap: the whole roster is covered within a
            -- few 0.25s passes at the same per-sweep cost.
            local total9 = #list9
            local done = 0
            if total9 > 0 then
                local start9 = (tonumber(S.stray_shield_i) or 0) % total9
                for k9 = 0, total9 - 1 do
                    if done >= 32 then S.stray_shield_i = (start9 + k9) % total9; break end
                    local member = list9[((start9 + k9) % total9) + 1]
                    pcall(function()
                        if member == target_ch or is_dead(member) then return end
                        local mgo = char_go(member)
                        local mp = mgo and upos(mgo)
                        if wp and mp and dist(wp, mp) <= 55.0 then
                            done = done + 1
                            stand_down(member, true)   -- LIGHT: hate clear only (see stand_down)
                        end
                    end)
                    if k9 == total9 - 1 then S.stray_shield_i = 0 end
                end
            end
            S.stray_shield_n = done
        end)
    end
end

-- THE HOLD HOOK: frame-level target-list stripping LOSES THE RACE -- the pawn AI refills AND
-- consumes its EnemyActionTargetList inside its own update tick, between our frames (the pacify
-- recon proved this; it is why the courted creature kept being attacked despite the per-frame
-- strip). Act inside the game's call stack instead: a POST-hook on updateEnemyTargetList removes
-- the courted creature the instant the list is rebuilt. Gated by a short lease (auto-expires, so
-- there is no cleanup to forget); the pre->post handoff uses thread hook storage (proven pattern).
local function install_hold_hook()
    if _G.IrisTamingHoldHookInstalled then return true end
    local ok = pcall(function()
        local td = sdk.find_type_definition("app.AIBlackBoardController")
        local m = td and td:get_method("updateEnemyTargetList")
        if not m then return end
        sdk.hook(m,
            function(args)
                pcall(function() thread.get_hook_storage().bb = sdk.to_managed_object(args[2]) end)
            end,
            function(retval)
                local hold = _G.IrisTamingHoldWolf
                if not hold or os.clock() > (tonumber(hold.until_t) or 0.0) then return retval end
                -- 08-14: a lease with no GAMEOBJECT address cannot strip anything - the match
                -- below compares an address to nil and is never true. Fail LOUD (once a second)
                -- rather than quietly doing nothing for a whole rite while the panel reads LIVE.
                if not hold.addr then
                    if os.clock() > (tonumber(_G.IrisTamingHoldWarnAt) or 0.0) then
                        _G.IrisTamingHoldWarnAt = os.clock() + 1.0
                        pcall(function() log.info("[IrisTaming] HOLD LEASE has no addr - the target-list strip is doing nothing") end)
                    end
                    return retval
                end
                pcall(function()
                    local bb = thread.get_hook_storage().bb
                    local list = bb and bb:call("get_EnemyActionTargetList")
                    local n = list and (tonumber(list:call("get_Count")) or 0) or 0
                    for i = n - 1, 0, -1 do
                        local at = list:call("get_Item", i)
                        local ago2 = at and at:call("get_GameObject")
                        if ago2 and ago2:get_address() == hold.addr then list:call("RemoveAt", i) end
                    end
                end)
                return retval
            end)
        _G.IrisTamingHoldHookInstalled = true
    end)
    return ok and _G.IrisTamingHoldHookInstalled == true
end
install_hold_hook()

-- ⭐⭐⭐ 08-14 THE ACQUISITION DOOR (Aurora: "we need the wolf not to be a target for pawns,
-- stray pawns, NPCs, other enemies etc").
-- Every defence above answers a question someone else asked - "is this a foe?" (contested: four
-- post-hooks share getRelationshipFromTo) or "what is on my menu?" (updateEnemyTargetList, which
-- RiftSpeak's own pacify recon found the game barely calls: "bbCalls=0 ... the list is filled
-- inline per-frame by some other path"). Both are downstream of the thing that actually starts a
-- fight: hate. In DD2 an AI only ever picks attack targets off its hate list, and hate is only
-- ever written through ONE method. Shut that door and nothing can even begin to want the wolf,
-- whatever chassis it wears and whatever any other mod thinks of the relationship.
-- ⭐ AND IT CANNOT BLOCK THE PLAYER. Hate is an AI-only ledger; Aurora does not swing through a
-- hate system. Striking the creature still fires damageProc -> S.combat_tame -> the shield's
-- combat branch stops calling shield_party_off, the 0.5s lease lapses, this door opens, and the
-- allies pile in exactly as the design wants.
-- ⛔ SIGNATURE IS PROVEN, NOT GUESSED: this exact overload is called live by
-- "GriffinRideProbe - Iris.lua":6412 and SKIP-hooked the same way by RiftSpeak/pacifist.lua:146.
local function install_hate_door_hook()
    if _G.IrisTamingHateDoorInstalled then return true end
    local ok = pcall(function()
        local td = sdk.find_type_definition("app.HateSystem")
        local m = td and td:get_method(
            "addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, "
            .. "System.Single, System.Single, System.Single, System.Single)")
        if not m then return end
        sdk.hook(m,
            function(args)
                -- fast bail FIRST: this fires constantly, all over the game
                local hold = _G.IrisTamingHoldWolf
                if not hold or not hold.addr then return end
                if os.clock() > (tonumber(hold.until_t) or 0.0) then return end
                local skip = false
                pcall(function()
                    local tgo = sdk.to_managed_object(args[3])
                    if tgo and tgo:get_address() == hold.addr then skip = true end
                end)
                if skip then
                    S.hate_door = (tonumber(S.hate_door) or 0) + 1
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end,
            function(retval) return retval end)
        _G.IrisTamingHateDoorInstalled = true
    end)
    return ok and _G.IrisTamingHateDoorInstalled == true
end
install_hate_door_hook()

-- GRAB DETECTION: the game's native pick-up runs through app.Human.requestTryCatch (confirmed by
-- reflection dump). When the player initiates a grab and a beaten creature is waiting, open a short
-- RELEASE WINDOW so the tick un-freezes it right as the native eligibility check reads its state --
-- this lets the beaten down-pose hold until the exact moment of the grab, then hands the body over.
local function install_trycatch_hook()
    if _G.IrisTamingTryCatchHookInstalled then return true end
    local ok = pcall(function()
        local td = sdk.find_type_definition("app.Human")
        local m = td and (td:get_method("requestTryCatch(app.Human.TryCatchType, System.Boolean, System.Boolean, System.Boolean)")
            or td:get_method("requestTryCatch"))
        if not m then return end
        sdk.hook(m, function(args)
            if S.mode == "yielded" and S.target then
                _G.IrisTamingGrabRelease = os.clock() + 1.2   -- the tick reads this to un-freeze the body
            end
            -- SKIP guard is for the RABBIT forced-carry path (a parallel
            -- fix: native catch on a woken standing critter flings the
            -- player, so rabbits skip it and use startBridalCarry instead).
            -- ⭐ The WOLF path does NOT set this guard -- it WANTS the native
            -- catch to run (un-freeze + natural grab, Aurora's combat-tame
            -- recipe), so grabbing a wolf leaves requestTryCatch alone.
            -- TWO INDEPENDENT OWNERS, deliberately separate variables (08-08):
            --   S.wolf_grab_guard   -- the ch223 wolf / wyrmcrystal path. NOT ours.
            --   S.critter_catch_skip -- the GROUND-CRITTER path (rabbit/rat). Set by the
            --                           pet-grab tick; see the setter's comment there.
            -- They were briefly the same variable, which is a trap: a "wolf guard" written
            -- by the rabbit path reads like dead code to anyone doing wolf work, and
            -- deleting it breaks the rabbit with no error -- just the launch coming back.
            -- Keep them apart. Either one skipping is enough.
            -- ⭐ THE PROVEN FIX for this exact symptom lives in IrisFarming (08-06, Aurora:
            -- "grabs and climbs the cow"): requestTryCatch is pickup for critters and
            -- CLING-CLIMB for bigger beasts, so the tend press was seizing the hen. Its cure
            -- is a whole skip of the PLAYER's requestTryCatch while the animal is in reach.
            -- ⚠ NOTE FOUR mods hook this same method and all four bind E/0x45 (IrisTaming,
            -- IrisFarming, IrisHomeLife, IrisHorseRodeo) -- the same one-press-many-handlers
            -- trap already found once inside this file, but across mods.
            -- Logged (throttled) because it has NEVER been verified as firing: if the rabbit
            -- launch persists while this line is silent, the guard is simply not arming.
            if (tonumber(S.wolf_grab_guard) or 0) > os.clock()
                or (tonumber(S.critter_catch_skip) or 0) > os.clock() then
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
        end, function(r) return r end)
        _G.IrisTamingTryCatchHookInstalled = true
    end)
    return ok and _G.IrisTamingTryCatchHookInstalled == true
end
install_trycatch_hook()

-- ===== CLIMB TRACER (08-08 R&D, the pickup launch) =====
-- OBSERVATION ONLY -- never SKIP_ORIGINAL. Arms itself only inside the pickup forensics
-- window (S.pickup_diag_until), so it is silent the rest of the time and cannot affect
-- ordinary climbing. The bassinet hunt (dd2-climb-suppression) proved the mount fires
-- through a NON-obvious entry point -- Character.startClimb was never called; the real one
-- was app.ClimbWallAction.startClimbing selected by HumanClimbWallActionRequester
-- .trySetActionOnGround. So hook the whole candidate list and let the game name it, rather
-- than guessing a third time. app.ObjectClimber is the MONSTER-climb system (a creature IS
-- a climbable object, so it is the prime suspect here, unlike the bassinet).
local function install_climb_tracer()
    -- ⚠ VERSIONED FLAG. sdk.hook installs PERSIST across script reloads, so the guard that
    -- stops hooks stacking ALSO pins the old closures forever: changing which candidates
    -- carry `block = true` has NO effect on a reload unless this name changes. Bump the
    -- suffix whenever the candidate table changes, or you will be testing the old build and
    -- concluding the fix "didn't work".
    if _G.IrisTamingClimbTracerInstalled_v3 then return true end
    -- ⭐ VERDICT (08-08, from the live trace -- this is no longer a guess): every upward
    -- pop while holding a critter is preceded by ~2ms by app.ObjectClimber.startClimb +
    -- app.Character.startClimb. Between pops the player is in FallLoop drifting DOWN. So
    -- the loop is climb -> pop -> fall -> climb: the player repeatedly CLIMBS THE RABBIT.
    -- ObjectClimber is the MONSTER-climb system and a tamed critter registers as a
    -- climbable body. Note this is the OPPOSITE entry point to the bassinet mantle
    -- (dd2-climb-suppression), where Character.startClimb never fired and ClimbWallAction
    -- .startClimbing was the real one -- which never appears here. Two different systems;
    -- only the trace could have told them apart.
    --
    -- `block = true` = also SKIP_ORIGINAL while S.critter_no_climb is live. The others stay
    -- trace-only: they never fired for this bug and blocking them would risk ordinary
    -- climbing for nothing.
    local cands = {
        -- ⭐ THE BASSINET PAIR (08-08). These were trace-only for six rounds and never
        -- printed -- but the position data finally showed a MOUNT WITH NO CLIMB ACTION:
        -- the player snaps from y=15.62 to 16.89 and lands at rabbit+0.29, while L0 never
        -- becomes Climb. That is exactly the bassinet signature, and dd2-climb-suppression
        -- records that its mount fired through ClimbWallAction.startClimbing selected by
        -- HumanClimbWallActionRequester.trySetActionOnGround -- NOT Character.startClimb,
        -- which was never called there either. Blocking those two is what finally stopped
        -- the bassinet mount, confirmed in-game. Same window gate as the rest.
        { "app.ClimbWallAction", "startClimbing", block = true },
        { "app.HumanClimbWallActionRequester", "trySetActionOnGround", block = true },
        { "app.HumanJumpOverWallActionRequester", "trySetActionOnGround", block = true },
        { "app.Character", "startClimb(System.Boolean)", block = true, player_only = true },
        { "app.ObjectClimber", "startClimb", block = true },
        { "app.ObjectClimber", "requestClimb", block = true },
        { "app.HumanClimbObjectActionRequester", "trySetActionOnGround" },
    }
    local hooked = {}
    for _, c in ipairs(cands) do
        pcall(function()
            local td = sdk.find_type_definition(c[1])
            local m = td and td:get_method(c[2])
            if not m then return end
            local label = c[1] .. "." .. c[2] .. (c.block and " [BLOCK]" or "")
            local blocking, player_only = c.block == true, c.player_only == true
            sdk.hook(m, function(args)
                local nowc = os.clock()
                local tracing = S.pickup_diag_until and nowc < S.pickup_diag_until
                if tracing then
                    -- throttle per entry point: these can fire every frame near a wall
                    S.climb_trace_at = S.climb_trace_at or {}
                    local last = tonumber(S.climb_trace_at[label]) or 0.0
                    if nowc - last >= 0.2 then
                        S.climb_trace_at[label] = nowc
                        pcall(function() log.info("[IrisTaming] CLIMB TRACE -> " .. label) end)
                    end
                end
                -- ⛔ RETIRED 08-08. This whole blocker was built chasing the pet-pickup launch
                -- and is now known-unnecessary: the launch was GriffinRideProbe's RT mount
                -- firing on a rabbit (no species gate), fixed there. Suppressing five climb
                -- entry points for a bug that was never here is real debt -- it would stop you
                -- climbing anything while holding a pet. sdk.hook installs cannot be removed
                -- without a game restart, so it is retired at the GATE instead. Left in place
                -- (inert) rather than deleted because it is the ready-made harness if a real
                -- climb conflict ever turns up.
                if true then return end
                if not blocking then return end
                if (tonumber(S.critter_no_climb) or 0.0) <= nowc then return end
                -- Character.startClimb is used by everything that climbs -- gate it to the
                -- PLAYER's body so a pawn or a monster climbing elsewhere is untouched.
                -- (ObjectClimber's `this` is the climber component, not a Character, so it
                -- can't be address-compared -- the narrow time window is its gate instead:
                -- it is only ever live while WE are holding a critter.)
                if player_only then
                    local mine = false
                    pcall(function()
                        local this = sdk.to_managed_object(args[2])
                        local pl = get_player()
                        if this and pl and this:get_address() == pl:get_address() then mine = true end
                    end)
                    if not mine then return end
                end
                -- PER-LABEL throttle (08-08): a single shared throttle made the log
                -- unreadable -- ObjectClimber won the 1s race every time, so Character
                -- .startClimb never printed a BLOCKED line and looked unblocked when it
                -- may not have been. Never share a throttle across things you're comparing.
                S.climb_block_log = S.climb_block_log or {}
                if nowc - (tonumber(S.climb_block_log[label]) or 0.0) > 1.0 then
                    S.climb_block_log[label] = nowc
                    pcall(function() log.info("[IrisTaming] climb BLOCKED (holding a critter) <- " .. label) end)
                end
                return sdk.PreHookResult.SKIP_ORIGINAL
            end, function(r) return r end)
            hooked[#hooked + 1] = label
        end)
    end
    _G.IrisTamingClimbTracerInstalled_v3 = true
    pcall(function() log.info("[IrisTaming] climb tracer armed on " .. #hooked .. ": " .. table.concat(hooked, ", ")) end)
    return true
end
-- ⛔⛔ NOT INSTALLED (08-09). These five hooks chased the pet-pickup launch, which turned out
-- to be GriffinRideProbe RT mount -- they never guarded anything. Leaving them installed-but-inert
-- was still wrong: IrisHorseRodeo ALSO hooks climb-start ("climb-start block armed (mount window +
-- while seated)"), a horse mount IS a climb, and the game crashed TWICE mounting a horse with a
-- native AV (c0000005, Module: Unknown, no managed frames) ~50ms after the rodeo began its mount.
-- Two mods wrapping the same climb methods is not a chain worth keeping for a disproven theory.
-- sdk.hook cannot be uninstalled at runtime, so the only real removal is to stop installing --
-- takes effect on the NEXT GAME START, not a script reload.
-- install_climb_tracer()   -- deliberately not called; kept as a ready-made harness

-- ===== CLIMB ACTION BLOCK (08-08) -- the chokepoint, not another commit point =====
-- Blocking commit points one at a time was losing: only 5 of the 7 candidates even exist
-- (ObjectClimber.requestClimb and HumanClimbObjectActionRequester are not real types), and
-- with startClimb blocked on BOTH the ones that do exist, the trace STILL showed L0:Climb
-- and the per-tick rise got BIGGER (+1.0..+1.4m per ~25ms tick, up from +0.3..+0.5).
-- +1.4m in one tick is not physics -- that is a position write, which fits the player being
-- attached to the rabbit while the carry pins the rabbit to the player: a feedback loop
-- that amplifies every frame. So block the ACTION instead of chasing selectors.
--
-- Same proven shape as the wyrm jump block directly below (which blocks "Jump" for the
-- player at app.ActionManager.requestActionCore and is known NOT to freeze movement --
-- input-processor hooks did that; the action level touches only the named node).
-- Gated on S.critter_no_climb, so it is live ONLY while a critter is in your arms (plus the
-- set-down settle) -- you cannot climb anything while cradling a rabbit, which is correct.
-- "End"/"Finish" names are NEVER blocked: if she is already mid-climb she must be able to
-- leave it, or blocking would strand her on the wall.
-- _G guard: sdk.hook installs PERSIST across script reloads, so a bare install stacks a
-- fresh hook on EVERY reload (and Aurora reloads constantly). Same law as the strike hook.
-- ⛔⛔ NOT INSTALLED (08-09) -- same reasoning as the climb tracer above. This one sat on
-- app.ActionManager.requestActionCore, i.e. EVERY player action request in the game, for a
-- theory that was disproven (zero L0:Climb, launch persisted). With a reproducible native AV
-- during a horse mount, a retired hook on the hottest action path in the game is the first
-- thing to take off the board, not the last.
if false then
pcall(function()
    if _G.IrisTamingClimbActionBlockInstalled then return end
    local m = sdk.find_type_definition("app.ActionManager")
        :get_method("requestActionCore(app.ActionManager.Priority, System.String, System.UInt32)")
    if not m then pcall(function() log.info("[IrisTaming] climb action block: requestActionCore not found") end); return end
    _G.IrisTamingClimbActionBlockInstalled = true
    local seen = {}
    sdk.hook(m, function(args)
        if true then return end   -- ⛔ RETIRED 08-08: see the climb tracer above. The launch
                                  -- was the griffin mod's RT mount, not a climb. This hook sat
                                  -- on EVERY player action request; it must not stay armed.
        if (tonumber(S.critter_no_climb) or 0.0) <= os.clock() then return end
        local block = false
        pcall(function()
            local cm = sdk.get_managed_singleton("app.CharacterManager")
            local pl = cm and cm:call("get_ManualPlayer")
            local pam = pl and pl:call("get_ActionManager")
            local am = sdk.to_managed_object(args[2])
            if not (am and pam and am:get_address() == pam:get_address()) then return end
            local name = sdk.to_managed_object(args[4])
            local s = name and tostring(name:call("ToString()")) or ""
            if s:find("Climb") and not s:find("End") and not s:find("Finish") then
                if not seen[s] then
                    seen[s] = true
                    pcall(function() log.info("[IrisTaming] climb action BLOCKED: '" .. s .. "'") end)
                end
                block = true
            end
        end)
        if block then return sdk.PreHookResult.SKIP_ORIGINAL end
    end, function(r) return r end)
    pcall(function() log.info("[IrisTaming] climb action block: hooked") end)
end)
end   -- if false: climb action block NOT installed (see above)

-- 08-08 JUMP BLOCK (Aurora: "A still jumps -- check what farming does"):
-- farming's PROVEN shape -- hook app.ActionManager.requestActionCore and
-- SKIP any action whose name contains "Jump" for the PLAYER, while a
-- CONTINUOUS positional gate is on (S.wyrm_jump_gate, set every tick the
-- rite label is live). ⛔ input-processor hooks froze ALL movement; the
-- ACTION level touches only the jump node. Self-reports the blocked name.
local wyrm_jump_block = { seen = {} }
pcall(function()
    local m = sdk.find_type_definition("app.ActionManager")
        :get_method("requestActionCore(app.ActionManager.Priority, System.String, System.UInt32)")
    if not m then pcall(function() log.info("[IrisTaming] wyrm jump block: requestActionCore not found") end); return end
    sdk.hook(m, function(args)
        -- 08-11: also holds Jump down while the Stable Screen is open -- pad A is both
        -- "summon" there and Jump here, and the Arisen should not hop on every summon
        if not (S.wyrm_jump_gate or _G.IrisStableUIOpen == true) then return end
        local block = false
        pcall(function()
            local cm = sdk.get_managed_singleton("app.CharacterManager")
            local pl = cm and cm:call("get_ManualPlayer")
            local pam = pl and pl:call("get_ActionManager")
            local am = sdk.to_managed_object(args[2])
            if not (am and pam and am:get_address() == pam:get_address()) then return end
            local name = sdk.to_managed_object(args[4])
            local s = name and tostring(name:call("ToString()")) or ""
            if s:find("Jump") then
                if not wyrm_jump_block.seen[s] then
                    wyrm_jump_block.seen[s] = true
                    pcall(function() log.info("[IrisTaming] wyrm jump block: '" .. s .. "'") end)
                end
                block = true
            end
        end)
        if block then return sdk.PreHookResult.SKIP_ORIGINAL end
    end, function(r) return r end)
    pcall(function() log.info("[IrisTaming] wyrm jump block: hooked (action-level)") end)
end)

-- SOUND TAPE: record recent wwise triggers near the player (id + owner + age) so a heard sound --
-- the oxcart driver's whistle -- can be identified by WHEN it played, not by name (NPC trigger
-- names are bare hashes). Hooks the same surfaces as the screech throttle; records only while
-- the tape is switched on in the panel.
local function tape_record(id, owner_nm)
    if not S.sound_tape_on then return end
    local t = S.sound_tape or {}
    S.sound_tape = t
    local last = t[#t]
    if last and last.id == id and (os.clock() - last.t) < 0.2 then return end   -- collapse machine-gun repeats
    t[#t + 1] = { id = id, who = tostring(owner_nm or "?"), t = os.clock() }
    while #t > 24 do table.remove(t, 1) end
end

local function install_tape_hook()
    if _G.IrisTamingTapeHookInstalled then return true end
    local ok = pcall(function()
        local sigs = {
            "trigger(System.UInt32)",
            "trigger(System.UInt32, via.GameObject)",
            "trigger(System.UInt32, via.GameObject, via.GameObject)",
            "trigger(System.UInt32, via.vec3, via.GameObject)",
            "triggerLogLess(System.UInt32, via.GameObject, via.GameObject)",
            "triggerLogLess(System.UInt32, via.vec3, via.GameObject)",
        }
        local any = false
        for _, tn in ipairs({ "app.WwiseContainerApp", "soundlib.SoundContainer" }) do
            local td = sdk.find_type_definition(tn)
            if td then
                for _, sig in ipairs(sigs) do
                    local m = nil
                    pcall(function() m = td:get_method(sig) end)
                    if m then
                        pcall(function()
                            sdk.hook(m, function(args)
                                if not S.sound_tape_on then return end
                                local id = nil
                                pcall(function() id = tonumber(sdk.to_int64(args[3])) end)
                                if not id or id <= 0 then return end
                                local nm2 = "?"
                                pcall(function()
                                    local this2 = sdk.to_managed_object(args[2])
                                    local go2 = this2 and this2:call("get_GameObject")
                                    if go2 then nm2 = tostring(go2:call("get_Name") or "?") end
                                end)
                                tape_record(id, nm2)
                            end, function(r) return r end)
                            any = true
                        end)
                    end
                end
            end
        end
        if any then _G.IrisTamingTapeHookInstalled = true end
    end)
    return ok and _G.IrisTamingTapeHookInstalled == true
end
install_tape_hook()

-- THE FRIEND SHIELD: the strongest hold of all -- go UPSTREAM of hate and target lists entirely.
-- Combat AI classifies "who is an enemy" through BattleRelationshipHolder.getRelationshipFromTo;
-- while the hold lease is live, any pair involving the courted creature answers FRIEND (2), so no
-- AI -- pawn or monster -- ever classifies it as attackable in the first place. This is the exact
-- mechanism the ride mod uses to friend-shield the party from the tamed mount (proven in-game);
-- returns compare app.Character pointers, hence the lease carries ch_addr. Fast bail when idle:
-- this method fires hundreds of times per frame in big fights, so the pre-hook stashes work only
-- when a lease is actually live.
local function install_rel_hook()
    if _G.IrisTamingRelHookInstalled then return true end
    local ok = pcall(function()
        local td = sdk.find_type_definition("app.BattleRelationshipHolder")
        local m = td and td:get_method("getRelationshipFromTo(app.Character, app.Character)")
        if not m then return end
        sdk.hook(m,
            function(args)
                local st = thread.get_hook_storage()
                st.iris_taming_rel = nil
                st.iris_taming_ghost = nil
                local a3, a4 = sdk.to_int64(args[3]), sdk.to_int64(args[4])
                if a3 == 0 or a4 == 0 then return end
                local hold = _G.IrisTamingHoldWolf
                if hold and hold.ch_addr and os.clock() <= (tonumber(hold.until_t) or 0.0) then
                    st.iris_taming_rel = args
                end
                -- GHOST MODE (the nest hunt): wild griffin <-> party pairs answer FRIEND, so no
                -- griffin AI ever classifies the observers as engageable. Address sets are refreshed
                -- once a second by the tracker sweep; two table lookups = cheap in the hot path.
                local gh = _G.IrisTamingGhost
                if gh and gh.on and gh.griffins and gh.party
                    and ((gh.griffins[a3] and gh.party[a4]) or (gh.griffins[a4] and gh.party[a3])) then
                    st.iris_taming_ghost = true
                end
            end,
            function(retval)
                local st = thread.get_hook_storage()
                if st.iris_taming_ghost then
                    S.ghost_hits = (tonumber(S.ghost_hits) or 0) + 1
                    return sdk.to_ptr(2)   -- FRIEND: the ghost party does not exist to wild griffins
                end
                local args = st.iris_taming_rel
                if not args then return retval end
                local hold = _G.IrisTamingHoldWolf
                if not (hold and hold.ch_addr) then return retval end
                local hit = false
                pcall(function()
                    local a = sdk.to_managed_object(args[3])
                    local b = sdk.to_managed_object(args[4])
                    hit = (a and a:get_address() == hold.ch_addr) or (b and b:get_address() == hold.ch_addr)
                end)
                if hit then
                    S.rel_hits = (tonumber(S.rel_hits) or 0) + 1
                    return sdk.to_ptr(2)   -- FRIEND: nobody classifies the courted creature as a foe
                end
                return retval
            end)
        _G.IrisTamingRelHookInstalled = true
    end)
    return ok and _G.IrisTamingRelHookInstalled == true
end
install_rel_hook()

-- COMBAT-TAME DEATH GUARD: clamp incoming damage so the courted creature's HP can never cross the
-- floor -- from ANYONE (the player OR helping pawns). Proven no-kill pattern (UDD2P/SphinxAndMedusaFix
-- clamps DamageInfo.Damage = hp - 1). Called from BOTH damage hooks: damageProc AND calcDamageReaction
-- (the Sphinx mod's actual clamp point -- the damageProc-only clamp demonstrably missed the killing blow).
local function iris_guard_clamp(args, di)
    if not S.combat_tame then return end
    local rhc = nil
    pcall(function() rhc = sdk.to_managed_object(args[2]) end)
    local curhp = nil
    if rhc then
        for _, gm in ipairs({ "get_Hp", "get_CurrentHitPoint" }) do
            local okh, v = pcall(function() return rhc:call(gm) end)
            if okh and tonumber(v) then curhp = tonumber(v); break end
        end
    end
    if not curhp then S.clamp_dbg = "hp UNREADABLE"; return end
    local floor = tonumber(C.floor_hp) or 1.0
    local maxdmg = math.max(0.0, curhp - floor)
    -- "Damage" is a REAL plain field on DamageInfo (the shipped damage patch writes it directly).
    -- ONLY that form here: a set_field on a nonexistent field paints the red "Last Script Error"
    -- banner even inside pcall (the <Damage>k__BackingField attempt was doing exactly that).
    local dmg = nil
    pcall(function() dmg = tonumber(di:get_field("Damage")) end)
    if dmg == nil then
        S.clamp_dbg = "dmg UNREADABLE"                                   -- diagnostic: clamp can't see the damage field
    elseif dmg > maxdmg then
        pcall(function() di:set_field("Damage", maxdmg + 0.0) end)       -- Single field: float subtype
        S.clamp_dbg = string.format("clamp %.0f->%.0f (hp %.0f)", dmg, maxdmg, curhp)
    else
        S.clamp_dbg = string.format("ok dmg %.0f (hp %.0f)", dmg, curhp)
    end
end

-- the second clamp point: calcDamageReaction is where the shipped no-kill patch actually intervenes
local function install_guard_hook()
    if _G.IrisTamingGuardHookInstalled then return true end
    local ok = pcall(function()
        local td = sdk.find_type_definition("app.HitController")
        local m = td and td:get_method("calcDamageReaction(app.HitController.DamageInfo)")
        if not m then return end
        sdk.hook(m, function(args)
            local watch = _G.IrisTamingWatchGoAddr
            if not watch or not S.combat_tame then return end
            local di = nil
            pcall(function() di = sdk.to_managed_object(args[3]) end)
            if not di then return end
            local dgo, daddr = nil, nil
            pcall(function() dgo = di:get_field("<DamageGameObject>k__BackingField") end)
            pcall(function() daddr = dgo and dgo:get_address() end)
            if not daddr or daddr ~= watch then return end
            iris_guard_clamp(args, di)
        end, function(r) return r end)
        _G.IrisTamingGuardHookInstalled = true
    end)
    return ok and _G.IrisTamingGuardHookInstalled == true
end
install_guard_hook()

-- PRECISE "I hit the wolf" signal: hook the wolf's damage entry, flag when the ATTACKER is the
-- player and the RECEIVER is the courted wolf. Proven pattern (NicksDevtools/DamageTracer.lua,
-- UDD2P/DamageProcPatches.lua). OBSERVATION ONLY -- never SKIP_ORIGINAL. Needs SOFT immunity (below)
-- so the collision check stays live and damageProc actually fires under the shield.
local function install_strike_hook()
    -- _G flag (not a per-load local): sdk.hook installs PERSIST across script reloads, so a fresh
    -- local would stack a new hook every reload. The _G flag makes re-install a no-op.
    if _G.IrisTamingStrikeHookInstalled then return true end
    local ok = pcall(function()
        local td = sdk.find_type_definition("app.HitController")
        local m = td and td:get_method("damageProc(app.HitController.DamageInfo)")
        if not m then return end
        sdk.hook(m, function(args)
            local watch = _G.IrisTamingWatchGoAddr   -- GAMEOBJECT addr (DamageInfo speaks GameObjects)
            if not watch then return end
            local di = nil
            pcall(function() di = sdk.to_managed_object(args[3]) end)
            if not di then return end
            local dgo = nil
            pcall(function() dgo = di:get_field("<DamageGameObject>k__BackingField") end)
            local daddr = nil
            pcall(function() daddr = dgo and dgo:get_address() end)
            if not daddr or daddr ~= watch then return end   -- not the courted wolf -> ignore
            iris_guard_clamp(args, di)
            local ago = nil
            pcall(function() ago = di:get_field("<AttackOwnerObject>k__BackingField") end)
            if not ago then
                pcall(function()
                    local ahc = di:get_field("<AttackHitController>k__BackingField")
                    local ach = ahc and ahc:get_field("<CachedCharacter>k__BackingField")
                    ago = ach and ach:call("get_GameObject")
                end)
            end
            if not ago then pcall(function() ago = di:get_field("<AttackGameObject>k__BackingField") end) end
            if not ago then return end
            local pgo = char_go(get_player())
            local paddr, aaddr = nil, nil
            pcall(function() paddr = pgo and pgo:get_address() end)
            pcall(function() aaddr = ago:get_address() end)
            if paddr and aaddr and paddr == aaddr then
                _G.IrisTamingPlayerStruckWolf = { addr = watch, at = os.clock() }
                S.strike_dbg = "PLAYER strike registered"
            else
                -- attribution diag: ranged/spell hits may resolve the attacker to a projectile
                -- object rather than the caster -- surface WHO the engine says hit it
                local anm = "?"
                pcall(function() anm = tostring(ago:call("get_Name")) end)
                S.strike_dbg = "hit by " .. anm
            end
        end, function(r) return r end)
        _G.IrisTamingStrikeHookInstalled = true
    end)
    return ok and _G.IrisTamingStrikeHookInstalled == true
end
install_strike_hook()

local function player_struck_wolf(player, pgo, ch, go, d)
    -- "am I attacking it?" -- the gate that RELEASES the allies + starts the combat tame.
    -- PRIMARY: the precise damageProc hook -- a REAL connected hit on THIS wolf. No sheathe gate
    -- here: you cannot melee sheathed, and a nil sheathe-read must not veto an actual strike.
    local flag = _G.IrisTamingPlayerStruckWolf
    if flag and (os.clock() - (tonumber(flag.at) or 0.0)) < 0.4 then
        local addr = nil
        pcall(function() addr = go and go:get_address() end)   -- GAMEOBJECT addr, matching the hook's flag
        if addr and flag.addr == addr then return true end
    end
    -- BACKSTOP (if the hook can't fire): weapon DRAWN + squared up in melee reach + facing it.
    -- Sheathed never counts (that's the peaceful ritual). Facing FAILS CLOSED (a bad read is NOT a hit).
    if C.struck_backstop == false then return false end
    if player_sheathed(player) ~= false then return false end          -- sheathed = peace, never released
    if not (d and d <= (tonumber(C.struck_range) or 4.0)) then return false end
    local facing = false
    pcall(function()
        local prot = pgo:call("get_Transform"):call("get_Rotation")
        local fx = 2.0 * (prot.x * prot.z + prot.w * prot.y)
        local fz = 1.0 - 2.0 * (prot.x * prot.x + prot.y * prot.y)
        local pp2, gp2 = upos(pgo), upos(go)
        if pp2 and gp2 then
            local dx, dz = gp2.x - pp2.x, gp2.z - pp2.z
            local dl = math.max(0.05, math.sqrt(dx * dx + dz * dz))
            local fl = math.max(0.05, math.sqrt(fx * fx + fz * fz))
            facing = ((dx / dl) * (fx / fl) + (dz / dl) * (fz / fl)) > 0.3
        end
    end)
    return facing
end

local function protect_tame_target(player, pgo, ch, go, d, hc, hp)
    -- Runs every frame while a creature is flagged for taming (armed). Owns the shield.
    if C.shield_until_struck == false then return end
    -- critters NEVER combat-flip: a parented bird brushing the player registers as a strike
    -- (the flight collision read as "you struck it" and dragged the crow into the wolf yield)
    local is_critter9 = name_in_csv(go_name(go), C.critter_bands)
    if not S.combat_tame and not is_critter9 and player_struck_wolf(player, pgo, ch, go, d) then
        S.combat_tame = true
        S.combat_tame_hp0 = hp        -- HP at the flip -> lets a sheathe back you out if you haven't hurt it yet
        set_prompt("THE FIGHT IS YOURS", "You struck it - your allies join. It cannot die.", 2.5, 0xFFB0B0FF)
        -- WAKE it so it actually fights (the peaceful shield/ritual had it think-stopped + nav-stopped
        -- + AI off). Safe: at the flip it is a parked/pacified body, not mid-native-action.
        set_immunity(ch, false)
        set_think_stop(ch, false); set_nav_stop(ch, false); set_ai(ch, true)
        pcall(function() ch:call("resetActionAndAI") end)
        _G.IrisTamingTargetAddr = nil
        -- ⛔ AND DROP THE SHIELD LEASE THIS INSTANT. The trial publishes a 2.0s lease, so without
        -- this the card says "your allies join" while the hate door and the target-list strip keep
        -- them from acquiring it for up to two more seconds. (Harmless before this batch, because
        -- that publisher used to write addr=nil and both mechanisms no-op'd on it.)
        _G.IrisTamingHoldWolf = nil
    end
    -- BACK OUT: sheathe again BEFORE you have actually hurt it -> drop back to the peaceful shield.
    -- Once you have drawn blood (hp fell) it stays committed (no yo-yo mid-fight).
    if S.combat_tame and player_sheathed(player) == true and hp and S.combat_tame_hp0
        and hp >= (tonumber(S.combat_tame_hp0) or hp) - 1.0 then
        S.combat_tame = nil; S.combat_tame_hp0 = nil
    end
    -- HP floor BOTH ways: nothing may kill the courted creature (belt-and-suspenders in case the
    -- damage-zero shield ever leaks -- closes the pre-context one-shot death gap too).
    if hp and hc and hp < (tonumber(C.floor_hp) or 1.0) then write_hp(hc, tonumber(C.floor_hp) or 1.0) end
    -- REVIVE BACKSTOP: if the damage-clamp ever misses and it flatlines, haul it back (the clamp is
    -- the real guard; this catches a one-frame overkill the clamp didn't see).
    if S.combat_tame and hc and is_dead(ch) then
        write_hp(hc, tonumber(C.floor_hp) or 1.0)
        pcall(function() ch:call("reviveFromFallDead(System.Boolean)", false) end)
    end
    if S.combat_tame then
        -- COMBAT tame: the wolf fights, allies help weaken it, but the floor keeps it alive
        set_immunity(ch, false)
        set_think_stop(ch, false)    -- stay awake to fight (don't re-freeze it)
        pacify_pack(pgo, ch)         -- only THIS wolf is fair game; its pack still holds and watches
    else
        -- PEACEFUL shield: HP untouchable + every ally held off it, BUT collisions stay live so
        -- the moment YOU strike it, the hook fires and it flips to a combat tame.
        set_immunity_soft(ch, true)
        full_pacify(ch)
        shield_party_off(ch)
        truce_bubble(pgo, ch)        -- broad 30m sweep for non-party bystanders too
        pacify_pack(pgo, ch)
    end
end

-- ============================ TAMING MUSIC (ask #2) ============================
-- app.SoundBgmManager OverwriteBgm -- the confirmed path (UDD2P/SphinxAndMedusaFix.lua plays the
-- Sphinx theme this exact way). Plays an EXISTING in-game theme; custom external audio is not
-- reachable from Lua. requestPlay/requestStop take (groupId, phaseId).
local function overwrite_bgm()
    local m = singleton("app.SoundBgmManager")
    if not m then return nil end
    local ob = nil
    pcall(function() ob = m:get_field("<OverwriteBgm>k__BackingField") end)
    return ob
end

local function bgm_play(group, phase, state, free_roam)
    local ob = overwrite_bgm()
    if not ob then return false end
    group = math.floor(tonumber(group) or 23); phase = math.floor(tonumber(phase) or 10)
    if free_roam then
        -- lift the "must be near the boss arena" gate so the theme plays out in the wild
        pcall(function()
            local dic = ob:get_field("_ControllerDic")
            local ctrl = dic and dic[group]
            local plist = ctrl and ctrl:get_field("<PhaseSettingsInfoList>k__BackingField")
            local pinfo = plist and plist[phase]
            if pinfo then pinfo._EnableLimitByDistance = false end
        end)
    end
    local ok = pcall(function() ob:call("requestPlay", group, phase) end)
    if state and tonumber(state) and tonumber(state) >= 0 then
        pcall(function() ob:call("requestStateOverwritePhaseState", group, phase, math.floor(tonumber(state))) end)
    end
    return ok
end

local function bgm_stop(group, phase)
    local ob = overwrite_bgm()
    if not ob then return false end
    return pcall(function() ob:call("requestStop", math.floor(tonumber(group) or 23), math.floor(tonumber(phase) or 10)) end)
end

local function bgm_dump()
    -- walk the OverwriteBgm catalog so the user can browse every theme (group -> phases) and pick one.
    local ob = overwrite_bgm()
    if not ob then log.info("[IrisTaming] BGM dump: no app.SoundBgmManager singleton"); return end
    local out, found = {}, 0
    pcall(function()
        local dic = ob:get_field("_ControllerDic")
        if not dic then log.info("[IrisTaming] BGM dump: no _ControllerDic"); return end
        for g = 0, 120 do
            local ctrl = nil
            pcall(function() ctrl = dic[g] end)
            if ctrl then
                found = found + 1
                local phases = {}
                pcall(function()
                    local plist = ctrl:get_field("<PhaseSettingsInfoList>k__BackingField")
                    local n = 0
                    pcall(function() n = plist:call("get_Count") end)
                    if not n or tonumber(n) == 0 then pcall(function() n = plist:get_size() end) end
                    for p = 0, (tonumber(n) or 0) - 1 do phases[#phases + 1] = p end
                end)
                out[tostring(g)] = phases
                log.info(string.format("[IrisTaming] BGM group %d -> phases {%s}", g, table.concat(phases, ",")))
            end
        end
    end)
    pcall(function() json.dump_file(MOD .. "_bgm_catalog.json", out) end)
    log.info(string.format("[IrisTaming] BGM dump: %d groups -> %s_bgm_catalog.json", found, MOD))
end

local function camp_active()
    -- true while the player is at/resting-at a camp (proven: guild_contracts.lua + RiftSpeak both
    -- poll this). The false->true edge = "arrived at camp" -> tend the carried wolf by the fire.
    local cm = singleton("app.CampManager")
    if not cm then return false end
    local ok, v = pcall(function() return cm:call("get_IsActiveCamp") end)
    return ok and v == true
end

local function find_nearest_creature(pgo)
    -- the motion LAB's "catalogue ANYTHING" target: nearest app.Character (a ch### body) that
    -- isn't the player, regardless of tame band -- so any creature (sheep/ox/boar/...) can be
    -- deep-scanned into its own atlas, not just tameable ones.
    local pp = pgo and upos(pgo)
    if not pp then return nil end
    local self_addr = nil
    pcall(function() self_addr = get_player():get_address() end)
    local best, best_d = nil, 40.0
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        local n = 0
        pcall(function() n = comps:call("get_Length") or 0 end)
        if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local ch = comps:call("get_Item", i) or comps[i]
                local ca = ch and ch:get_address()
                local go = ch and char_go(ch)
                local nm = go and go_name(go) or ""
                if go and ca ~= self_addr and nm:find("ch", 1, true) == 1 and not nm:find("ch000", 1, true) then
                    local p6 = upos(go)
                    local d = p6 and dist(p6, pp) or 1e9
                    if d < best_d then best_d = d; best = ch end
                end
            end)
        end
    end)
    return best
end

-- ⭐ 08-12 LINE OF SIGHT (Aurora courted a rat in a cellar UNDER a bridge she could not
-- see): the hand can only be offered to a creature the eye can find. One ray, player
-- chest -> creature, against the STATIC WORLD only (the rodeo camera's proven rig: own
-- query/result instances, Layer 2, native castRay -- never share ray objects across
-- systems, that was the dead-rays lesson). RENDER space: via.physics knows nothing of
-- universal positions. ONE chunk local (the 200-local ceiling).
local LOS = { rig = {} }
LOS.ensure = function()
    local R = LOS.rig
    if R.ready then return true end
    local ok = pcall(function()
        R.system = sdk.get_native_singleton("via.physics.System")
        R.method = sdk.find_type_definition("via.physics.System")
            :get_method("castRay(via.physics.CastRayQuery, via.physics.CastRayResult)")
        R.query = sdk.create_instance("via.physics.CastRayQuery"):add_ref()
        R.result = sdk.create_instance("via.physics.CastRayResult"):add_ref()
        R.query:clearOptions()
        R.query:enableAllHits()
        R.query:enableNearSort()
        R.filter = R.query:get_FilterInfo()
    end)
    R.ready = ok and R.system ~= nil and R.method ~= nil
        and R.query ~= nil and R.result ~= nil and R.filter ~= nil
    return R.ready == true
end
LOS.vec3 = function(x, y, z)
    local v = nil
    pcall(function()
        v = ValueType.new(sdk.find_type_definition("via.vec3"))
        v.x = x or 0; v.y = y or 0; v.z = z or 0
    end)
    return v
end
LOS.clear = function(pgo0, tgo0)
    -- true = no static world between player and creature. FAIL OPEN when the rig is
    -- unavailable: a broken ray must never quietly turn taming off.
    local clear = true
    pcall(function()
        if not LOS.ensure() then return end
        local R = LOS.rig
        local a = pgo0:call("get_Transform"):call("get_Position")
        local b = tgo0:call("get_Transform"):call("get_Position")
        if not (a and b) then return end
        R.filter:set_Group(0)
        R.filter:set_Layer(2)   -- static world only: creatures and foliage never blind the eye
        R.filter:set_MaskBits(0)
        R.result:clear()
        -- chest-to-chest lift: a ground-level ray snags every doorstep and kerb
        R.query:call("setRay(via.vec3, via.vec3)",
            LOS.vec3(a.x, a.y + 1.2, a.z), LOS.vec3(b.x, b.y + 0.6, b.z))
        R.method:call(R.system, R.query, R.result)
        local n = 0
        pcall(function() n = R.result:get_NumContactPoints() or 0 end)
        if (tonumber(n) or 0) > 0 then clear = false end
    end)
    return clear
end

-- ⭐ 08-12 PAD+TARGETING slice A -- THE TAME BUTTON: keyboard N and pad B/Circle as ONE
-- input (mask 0x40080, the wyrm rite's proven bit). ONE chunk local (the 200-local law).
local TB = {}
TB.pad_down = function()
    local pad = false
    pcall(function()
        local gp = sdk.get_native_singleton("via.hid.GamePad")
        local td = sdk.find_type_definition("via.hid.GamePad")
        local dev = gp and td and sdk.call_native_func(gp, td, "get_MergedDevice")
        if not dev then dev = gp and td and sdk.call_native_func(gp, td, "getMergedDevice(System.UInt32)", 0) end
        local mask = dev and tonumber(dev:call("get_Button")) or 0
        pad = (math.floor(mask) & 0x40080) ~= 0
    end)
    return pad
end

-- ⭐ THE HOWL BUTTON (08-14, Aurora: "on controller we need to keep this as B"). C.howl_key is
-- deliberately NOT the palm key - on keys, a held palm must not auto-pass the howl beat. But a
-- controller has no spare face button, so the howl answers on B/Circle: the same 0x40080 mask
-- every other rite reads through TB.pad_down (wyrm rite, rodeo, InteractButton, the ride probe).
-- ⛔ BOTH howl sites must call THIS - the performer that fires the Bellow roar and the stage
-- clock that scores it. If they ever disagree you roar while the trial refuses to advance, or
-- the trial advances with no roar. The pad half is raw pad_down, NOT pad_ok: pad_ok's camera
-- cone would drop the howl mid-beat and fail the rite (the same trap the critter CALL avoided).
TB.howl_down = function()
    local kb = false
    pcall(function() kb = iris_kb(math.floor(tonumber(C.howl_key) or 0x48)) == true end)
    return kb or TB.pad_down()
end
-- ⭐⭐⭐ THE MISSING ARGUMENT THAT KEPT THE NATIVE B PROMPT OFF EVERY TAME (08-13).
-- `_G.IrisPrompt.set(owner, text, prio, dist, POS, go)` -- every tame call site passed **nil** for
-- pos, and IrisPromptBar's `_world_prompt` bails on `not entry.pos`. So the tames only ever drove
-- the ui010201 BUTTON-PANEL relabel, which the game refuses whenever it is not already offering an
-- interact (a withheld slot sits in PlayState DISABLE_HIDETXT, and writing PlayState is the
-- double-CTD law). That is what "native B prompt at range = walled" actually meant.
-- ⭐ But ui020701 -- the real floating B disc in the WORLD -- is a different surface, and it now
-- draws arbitrary text at an arbitrary position (field-proven on farm beds, weapon plaques and the
-- cookpot). It was simply never asked to draw for a tame. Giving it a position is the whole fix.
-- ⚠ It wants RENDER space, so convert from the creature's transform (which is already render) and
-- lift it clear of the body, the same shape the cookpot prompt uses.
TB.prompt_pos = function(go, lift)
    local v = nil
    pcall(function()
        local rp = go and go:call("get_Transform"):call("get_Position")
        if not rp then return end
        v = Vector3f.new(rp.x, rp.y + (tonumber(lift) or 1.2), rp.z)
    end)
    return v
end

-- ⭐⭐ THE FAKE PROMPT RETIRES (Aurora 08-13, after seeing the real one land: "if we can do that
-- across ALL creatures then we can get rid of the fake prompt").
-- The drawn "[N/B] Tame the X" marker was only ever a stand-in for a native prompt we believed was
-- impossible. Now that ui020701 draws the genuine B disc over the creature, the marker is noise --
-- her screenshot had BOTH stacked on one horse.
-- ⚠ BUT IT STAYS AS A ONE-FRAME SAFETY NET, because the native prompt is not ours to command:
-- IrisPromptBar arbitrates NEAREST-WINS across every IRIS publisher, and it stands down entirely
-- when the GAME is offering its own interact. So a nearer farm bed, a cookpot, or a native prompt
-- can legitimately take the slot while a creature is still a valid candidate. In that frame the
-- drawn marker is the only thing that can say "this one" -- and it is honest, because our own
-- candidate test (LOS + camera cone + range) is what gated it, not the prompt's availability.
-- ⇒ draw it ONLY when the native frame did not render. `native_world_ready` is reset at the top of
-- every LateUpdate, so from the main tick we read last frame's verdict: a one-frame lag, not a
-- stale cache (which is the hazard the prompt notes warn about).
-- ⭐⭐ "IS THIS ALREADY MINE?" (Aurora 08-13: "the tame prompt is coming up for tamed
-- horses/unicorns" -- Epona, her own summoned unicorn, wearing a B Tame prompt).
-- The rodeo's claim is published for any horse you LOOK AT within 9m, and a companion standing next
-- to you qualifies. The other rites dodge this because find_candidate screens tamed bodies; the
-- horse path bypasses find_candidate entirely, so it needs its own screen.
-- ⛔ ADDRESS-CLASS LAW: `IrisGriffinBridge.griffin()` returns the CHARACTER first and the
-- GAMEOBJECT second. We hold a GameObject here, so we must take the SECOND return -- comparing a
-- Character address against a GameObject address is the trap that once made a damage hook never
-- match. is_pet_body is the belt (it keys on GO addresses) but only knows THIS session's tames, so
-- the bridge check is what catches a companion tamed before the last reload.
TB.is_mine = function(go)
    if not go then return false end
    local mine, ga = false, nil
    pcall(function() ga = go:get_address() end)
    if not ga then return false end
    pcall(function()
        local B = _G.IrisGriffinBridge
        if B and B.griffin then
            local _, cgo = B.griffin()                  -- 2nd return = the GameObject
            if cgo and cgo:get_address() == ga then mine = true end
        end
    end)
    if not mine then
        pcall(function()
            local api = _G.IrisTaming
            if api and api.is_pet_body and api.is_pet_body(ga) then mine = true end
        end)
    end
    return mine
end

TB.mark = function(go, text, argb)
    if not go then return end
    local native = false
    pcall(function()
        local api = _G.IrisPrompt
        native = api and api.native_world_ready and api.native_world_ready() == true
    end)
    if native and C.tame_marker_fallback ~= false then return end
    draw_marker(go, text, argb or 0xFF60D0FF)
end

-- ⭐ THE ONE SUBJECT ANSWER (08-13): "what creature is this taming moment about?" Every rite
-- needs it -- the pad gate below, the marker, and the auto-face on the palm all ask this. It was
-- inlined in pad_ok and missing TWO rites, which is why pad B was dead in the griffin rite and on
-- horses: a hold-to-scan flow with no published candidate starves the pad hand.
TB.subject = function()
    if S.ox_rite and S.ox_rite.go then return S.ox_rite.go end
    if S.oxtame and S.oxtame.go then return S.oxtame.go end        -- 08-13: the GRIFFIN rite
    if S.target then return char_go(S.target) end
    if S.tame_mark then return char_go(S.tame_mark) end
    if S.ox_mark_go then return S.ox_mark_go end                   -- the marked ox, pre-rite
    local hgo = rawget(_G, "__iris_horse_taming_claim_go")          -- 08-13: horse / unicorn
    if hgo then
        local okh = false
        pcall(function() okh = hgo:call("get_Transform") ~= nil end)
        if okh then return hgo end
    end
    return nil
end

-- ⭐⭐ AUTO-FACE THE CREATURE ON THE PALM (Aurora 08-13: "every time you use B for palm during
-- taming, it faces the creature you're taming automatically"). Bearing to the target never lies --
-- the camera-forward servo was the source of the old 180-flip and the beyblade spin.
-- ⛔ THE ONE EXCEPTION IS THE WOLF/PUMA CIRCLE: the wolf ORBITS you there, so you are meant to
-- camera-track it. Snapping you to face it would fight the ritual's whole point.
TB.face = function(go, secs)
    if not go then return false end
    -- The CIRCLE (you camera-track the orbiting wolf) AND the STAND YOUR GROUND beats. A 0.15s
    -- hard snap laid on top of a LIVE player MotionFsm2 is the sidestepping Aurora saw - those
    -- stages settle your facing themselves, gently, and must be the sole authority while they run.
    do
        local st9 = S.trial and tostring(S.trial.stage or "") or ""
        if st9 == "circle" or st9 == "rush_tell" or st9 == "rush" then return false end
    end
    local ok = false
    pcall(function()
        local pgo9 = char_go(get_player())
        local pp9 = pgo9 and upos(pgo9)
        local gp9 = upos(go)
        if not (pgo9 and pp9 and gp9) then return end
        local dx9, dz9 = gp9.x - pp9.x, gp9.z - pp9.z
        if (dx9 * dx9 + dz9 * dz9) < 0.04 then return end   -- standing on top of it: no bearing
        local hyaw = math.atan(dx9, dz9)
        local q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
        q.x = 0; q.y = math.sin(hyaw / 2.0); q.z = 0; q.w = math.cos(hyaw / 2.0)
        pgo9:call("get_Transform"):call("set_Rotation", q)
        -- ⛔ NEVER SHORTEN A LONGER LEASE. The pact stroke deliberately locks face_hold for its whole
        -- duration as the SOLE rotation authority -- that lock is what stopped the player beyblading
        -- mid-nursing. A short 0.35s palm lease stamped over it would hand rotation back the moment
        -- the palm released, part-way through the stroke. Extend, never truncate.
        local until9 = os.clock() + (tonumber(secs) or 0.5)
        local prev9 = S.face_hold and tonumber(S.face_hold.until_t) or nil
        if prev9 and prev9 > until9 then until9 = prev9 end
        S.face_hold = { x = q.x, y = q.y, z = q.z, w = q.w, until_t = until9 }
        ok = true
    end)
    return ok
end

TB.pad_ok = function()
    -- pad B doubles as DASH (and half the game): it counts as the tame hand ONLY when
    --   1) a taming moment exists (mark / courtship / rite),
    --   2) the player is not sprinting through it,
    --   3) the camera faces the creature (Aurora: "only when needed, and facing it")
    local subj = TB.subject()
    if subj == nil then return false end
    if (tonumber(S.player_spd) or 0.0) > 2.5 then return false end
    -- ⛔ 0.35 IS DELIBERATELY LOOSE AND MUST STAY THAT WAY. This is the IN-RITE hand: every live
    -- courtship reads it through TB.held(). The wolf CIRCLE stage ORBITS you by design (TB.face
    -- refuses there for exactly that reason), so a tight cone here would drop the palm mid-trial
    -- and fail the rite. Intent is declared by TAMING MODE now, never inferred from aim.
    return TB.aimed(subj, 0.35)
end

-- ⭐ ONE CAMERA-CONE ANSWER (08-13). Extracted from pad_ok so there is a single dot-product in the
-- file rather than two copies drifting apart. cone: 1.0 = dead ahead, 0.0 = 90deg off to the side.
TB.aimed = function(go, cone)
    local ok = false
    pcall(function()
        local cam = sdk.get_primary_camera()
        local crot = cam:call("get_GameObject"):call("get_Transform"):call("get_Rotation")
        local fx = -(2.0 * (crot.x * crot.z + crot.w * crot.y))
        local fz = -(1.0 - 2.0 * (crot.x * crot.x + crot.y * crot.y))
        local fl = math.max(0.05, math.sqrt(fx * fx + fz * fz))
        local sp2 = upos(go)
        local pu2 = upos(char_go(get_player()))
        if not (sp2 and pu2) then return end
        local dx, dz = sp2.x - pu2.x, sp2.z - pu2.z
        local dl = math.max(0.05, math.sqrt(dx * dx + dz * dz))
        ok = ((dx / dl) * (fx / fl) + (dz / dl) * (fz / fl)) > (tonumber(cone) or 0.9)
    end)
    return ok
end

-- ⛔⛔ 08-13: TB.commit / TB.tier / the per-owner commit latches WERE REMOVED HERE ON PURPOSE.
-- They were hold-to-commit: a heuristic that tried to INFER, from press duration plus species
-- reach plus camera cone, whether a B press meant "tame" or "ring that bell". It cost three
-- separate field failures in one session -- a 12m reach that excluded perched birds (dist() counts
-- height), and twice a shared edge-latch consumed by whichever of the three rites ticked first, so
-- no tame could start anywhere. TAMING MODE replaces the whole idea: the player declares intent in
-- the Stable UI, taming prompts exist only while it is on, and nothing has to be guessed.
-- ⇒ Do not re-introduce an intent heuristic here. The mode is the answer.
_G.IrisTamingTB = _G.IrisTamingTB or {}
_G.IrisTamingTB.held = function() return TB.held() end
TB.held = function()
    if _G.IrisStableUIOpen == true then return false end   -- B is the stable screen's close there
    if type(iris_input_blocked) == "function" and iris_input_blocked() then return false end
    local kb = false
    pcall(function() kb = iris_kb(math.floor(tonumber(C.tame_key) or 0x4E)) == true or iris_kb(0x4E) == true end)
    local held = kb or (TB.pad_ok() and TB.pad_down())
    -- ⭐⭐ 08-14 THE PAD HAND MAY NOT STUTTER (Aurora: "the palm looks like it re-triggers over
    -- and over even when I am not moving" - controller only). On a pad the hand is gated by
    -- TB.pad_ok: a ~70 degree camera cone plus a speed test. ONE frame where the creature slips
    -- the cone (the CIRCLE orbits it out on purpose) or one dt spike that fakes a sprint drops
    -- `held`. The performance block reads that as "hand down", hands the body back, NILS S.pclip,
    -- then re-seizes on the very next frame and replays the palm from frame 0. Keyboard N skips
    -- pad_ok entirely, which is exactly why this only ever looked broken on a controller.
    -- ⇒ while the BUTTON is still physically down and a rite is live, a cone blip is not a
    -- release. A true release drops TB.pad_down() on the same frame, so this adds no lag.
    if held then
        S.pad_hand_at = os.clock()
    elseif (S.trial or S.ox_rite) and TB.pad_down()
        and (os.clock() - (tonumber(S.pad_hand_at) or 0.0)) < 0.35 then
        held = true
    end
    -- ⭐ 08-13: the palm IS the face. Every rite reads its hand through TB.held(), so facing here
    -- covers wolf trials, the ox yoke, critter/bird give, the griffin rite and horses in ONE place
    -- instead of six. Re-asserted while held (0.35s lease) so it tracks a creature that moves.
    -- ⛔ TB.face itself refuses during the wolf/puma circle -- see its comment.
    if held and C.tame_autoface ~= false then
        if (os.clock() - (tonumber(S.autoface_at) or 0.0)) > 0.15 then
            S.autoface_at = os.clock()
            TB.face(TB.subject(), 0.35)
        end
    end
    return held
end

-- ⭐⭐⭐ 08-13 THE ARBITER GATE (Aurora: "if I'm next to the oxcart bell and wanting to press
-- examine, if a bed flies past it doesn't do the tame instead -- which is literally what just
-- happened... I tried to milk a cow earlier and instead started a tame with a rabbit not far
-- off"). She is describing a real design hole, not bad luck.
--
-- IrisPromptBar already arbitrates: NEAREST publisher wins, priority only breaks ties inside
-- 0.3m, and the GAME's own interact outranks everyone (native_busy). Its contract is explicit:
-- *publishing a prompt entitles you to nothing -- you must ask who won before you act.*
-- farm_bed / cookpot / farm_animal / home_life / wyrm_rite / weapon_mount all ask.
-- **tame_begin and tame_ox published and then acted on the raw button.** So the tame fired
-- alongside whatever the player actually meant, and being the louder handler, it won.
--
-- ⛔ THIS GATE BELONGS ON *STARTING* A RITE, NOT ON TB.held() ITSELF. Every live rite reads
-- its hand through TB.held() -- the griffin call, the palm raise, feeding, the ox offer hold --
-- and once a rite owns the moment it clears its own prompt, so the arbiter no longer knows its
-- name. Gating TB.held() globally would strand every courtship mid-rite.
--
-- ⭐ It does NOT break taming at range: when nothing else is publishing, the tame IS the
-- winner at any distance. It only stands down when something nearer wants the same button.
TB.may_start = function(owner)
    -- ⛔⛔ 08-13 THE BLANKING INVERSION. IrisPromptBar's set() DELETES every publisher's slot while
    -- IrisStableUIOpen / IrisFurnishUIOpen / IrisFurnishFootprint / IrisFurnishPlacing / IrisRiddenNow
    -- is set. An empty registry makes winner() return nil, which this function read as "nobody else
    -- wants this button" -- so the suppressor was acting as a taming AMPLIFIER: taming's gate swung
    -- OPEN exactly while a menu or a mount owned the screen. Refuse outright instead of inferring.
    if rawget(_G, "IrisStableUIOpen") == true or rawget(_G, "IrisFurnishUIOpen") == true
        or rawget(_G, "IrisFurnishFootprint") == true or rawget(_G, "IrisFurnishPlacing") == true
        or rawget(_G, "IrisRiddenNow") then
        return false
    end
    local P = rawget(_G, "IrisPrompt")
    if not P then return true end            -- no arbiter loaded: behave exactly as before
    local refuse_why = nil
    pcall(function()
        if P.native_busy and P.native_busy() then
            refuse_why = "the game is offering its own interact here"
            return
        end
        local w = P.winner and P.winner() or nil
        -- ⛔ 08-13 TAMING OWNERS ARE ALIASES OF ONE ANOTHER. The rites publish under several owner
        -- keys (tame_begin, tame_ox, tame_horse) but they are ONE feature competing for ONE button,
        -- so a strict w ~= owner made taming stand down against ITSELF -- e.g. IrisTaming publishes
        -- the horse's prompt as "tame_begin" while IrisHorseRodeo starts the rite under its own key,
        -- which would refuse forever. Only a NON-taming winner (a bed, a cookpot, a farm animal)
        -- may take the button away from a tame.
        local tame_w = w and tostring(w):find("^tame_") ~= nil
        local tame_o = tostring(owner):find("^tame_") ~= nil
        -- ⭐⭐ 08-13: IN TAMING MODE THE TAME WINS THE BUTTON outright over IRIS's own publishers
        -- (bed, cookpot, farm animal, weapon mount). The player has DECLARED intent, so a nearer
        -- cookpot no longer gets to speak for them -- that inference is exactly what the mode
        -- exists to abolish.
        -- ⛔ BUT NATIVE STILL WINS (the native_busy check above is untouched). If taming outranked
        -- the game's own interacts you could not open a door, climb a ladder or take a quest item
        -- while the mode was on, and the only cure would be to notice the mode and turn it off.
        if S.tame_mode == true and tame_o then
            -- nothing: only native_busy may refuse us here
        elseif w and w ~= owner and not (tame_w and tame_o) then
            refuse_why = "'" .. tostring(w) .. "' is nearer"
        end
    end)
    if not refuse_why then return true end
    -- throttled receipt: a silent refusal is indistinguishable from a dead feature
    S.may_start_said = S.may_start_said or {}
    local k = tostring(owner)
    if (os.clock() - (tonumber(S.may_start_said[k]) or 0.0)) > 3.0 then
        S.may_start_said[k] = os.clock()
        pcall(function() log.info("[IrisTaming] " .. k .. " stood down: " .. refuse_why) end)
    end
    return false
end

local function find_candidate(pgo)
    -- ⛔ 08-13 (Aurora, riding the cat past wildlife: "tame prompts coming up as I
    -- rode past"): ground-life actions stand down while seated on a rodeo mount.
    -- No candidate = no prompt AND no B press for every rite that screens here.
    if rawget(_G, "IrisRiddenNow") then return nil end
    local pp = pgo and upos(pgo)
    if not pp then return nil end
    -- the stable's ACTIVE companion is off-limits: it is already tamed and already being
    -- driven by the main mod (targeting it put two puppeteers on one body -> crash)
    local comp_addr = nil
    pcall(function()
        local b = _G.IrisGriffinBridge
        local gch = b and b.griffin and b.griffin()
        if gch then comp_addr = gch:get_address() end
    end)
    local pend_addr = nil
    pcall(function()
        if S.finish_pending and S.finish_pending.ch then pend_addr = S.finish_pending.ch:get_address() end
    end)
    -- LOOK-AT LAW: the courtship targets what the CAMERA faces, full stop
    local cfx, cfz = nil, nil
    pcall(function()
        local cam = sdk.get_primary_camera()
        local cgo6 = cam and cam:call("get_GameObject")
        local crot6 = cgo6 and cgo6:call("get_Transform"):call("get_Rotation")
        if crot6 then
            local fx6 = -(2.0 * (crot6.x * crot6.z + crot6.w * crot6.y))
            local fz6 = -(1.0 - 2.0 * (crot6.x * crot6.x + crot6.y * crot6.y))
            local fl6 = math.max(0.05, math.sqrt(fx6 * fx6 + fz6 * fz6))
            cfx, cfz = fx6 / fl6, fz6 / fl6
        end
    end)
    local best, best_d = nil, 30.0   -- among camera-cone candidates, pick the NEAREST (field bug: it courted a far pack wolf)
    if S.ox_rite then return end   -- the yoke rite owns the moment: no critter courtship may arm mid-rite (07-21)
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        if not comps then return end
        local n = 0
        pcall(function() n = comps:call("get_Length") or 0 end)
        if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local ch = comps:call("get_Item", i) or comps[i]
                local go = ch and char_go(ch)
                local nm = go and go_name(go) or ""
                local ca = nil
                pcall(function() ca = ch:get_address() end)
                local horse_owned = false
                pcall(function()
                    local api = rawget(_G, "__iris_wild_horses_api")
                    horse_owned = api and api.is_horse
                        and api.is_horse(go) == true
                end)
                local resident9 = false   -- 08-12: the homestead's own are NEVER candidates
                pcall(function()
                    local hb9 = rawget(_G, "IrisHomesteadBox")
                    resident9 = hb9 and hb9.is_resident and hb9.is_resident(go:get_address()) or false
                end)
                if not horse_owned and not resident9
                    and (name_in_csv(nm, C.target_bands) or name_in_csv(nm, C.critter_bands))
                    and not name_in_csv(nm, C.exclude_bands)
                    and not S.tamed[ch] and not is_dead(ch)
                    and not (comp_addr and ca == comp_addr)
                    and not (pend_addr and ca == pend_addr)
                    and not (S.tamed_addrs and ca and S.tamed_addrs[tostring(ca)])   -- key stored as tostring (was read raw = dead guard)
                    -- a LOCKED-OUT creature is invisible to the hand: it kept winning the
                    -- camera-cone pick and BLOCKED courting anything near it (Aurora's report)
                    and not (S.lockouts and ca and (tonumber(S.lockouts[tostring(ca)]) or 0.0) > os.clock()) then
                    local p6 = upos(go)
                    local d = p6 and dist(p6, pp) or 1e9
                    -- ⭐⭐⭐ 08-13 PER-SPECIES REACH AND AIM (Aurora: far-off birds hijacking the
                    -- press meant for a sign or a bell). This was a flat 30m at dot > 0.5 (~60deg)
                    -- for EVERYTHING -- which is precisely how a crow 25m away and well off-centre
                    -- became a legitimate candidate while she stood at a bell. A crow now has to be
                    -- close and roughly under the crosshair; an ox may still be spotted at 30m.
                    -- ⛔ This screens the MARKER too, not just the start -- a prompt you never
                    -- meant to see is the same bug one step earlier.
                    if d < 30.0 and cfx and p6 then
                        local dx6, dz6 = p6.x - pp.x, p6.z - pp.z
                        local dl6 = math.max(0.05, math.sqrt(dx6 * dx6 + dz6 * dz6))
                        local dot6 = (dx6 / dl6) * cfx + (dz6 / dl6) * cfz
                        -- inside the species cone AND nearest AND actually visible (08-12:
                        -- the cellar rat -- no courting through floors and bridge decks)
                        if dot6 > 0.5 and d < best_d and LOS.clear(pgo, go) then best_d = d; best = ch end
                    end
                end
            end)
        end
    end)
    return best
end

-- ============================ persistence (familiarity survives sessions) ============================
local function load_state()
    pcall(function()
        local d = json.load_file(MOD .. "_state.json")
        if d and d.config then
            -- ⛔ RODEO TUNING lives in CODE, not the save (07-20, Aurora "reset scripts but it all felt
            -- the same"): these knobs were being OVERRIDDEN by stale saved values, so editing the code
            -- defaults did NOTHING. Skip them on load = the code default always wins (Iris tunes via code).
            local rodeo_code_only = {
                oxtame_tame_stam = true, oxtame_break_rate = true, oxtame_strike_grip_rate = true,
                oxtame_grip_buck_drain = true, oxtame_grip_slip_drain = true, oxtame_grip_recover = true,
                oxtame_buck_secs = true, oxtame_pause_secs = true, oxtame_tell_secs = true,
                oxtame_liedown_secs = true, oxtame_flee_up = true, oxtame_dismount_grace = true,
                oxtame_mount_land_node = true, oxtame_turnaround_r = true, oxtame_turnaround_gap = true,
                oxtame_swoop_ask_max = true, oxtame_rodeo_land_veto = true,
                oxtame_rodeo_land_patterns = true, oxtame_rodeo_hover_node = true,
                oxtame_ground_probe = true, oxtame_block_grounded = true,   -- 07-24 ground-probe repair
                oxtame_native_dive = true, oxtame_native_travel_node = true, oxtame_native_travel_from = true,   -- 07-24 forced native dive
                oxtame_full_puppet = true,
                oxtame_meal_secs = true, oxtame_native_land_node = true, oxtame_auto_ferry = true,   -- 07-25
                oxtame_eat_end_clip = true, oxtame_eat_end_secs = true,   -- 07-25 eat-end beat
                oxtame_travel_hold_secs = true, oxtame_takeoff_node = true, oxtame_relocate = true,   -- 07-25 native travel
                oxtame_soar_cooldown = true, oxtame_giveup = true, oxtame_buck_node = true,
                oxtame_tell_node = true, oxtame_flee_node = true, oxtame_attack_patterns = true,
                oxtame_flee_up = true, oxtame_flee_dist = true, oxtame_flee_lift_node = true,
                oxtame_flee_lift_secs = true, oxtame_flee_secs = true,
                oxtame_flee_gone_dist = true, oxtame_fail_cooldown = true, oxtame_rodeo_max_secs = true,
                oxtame_flee_burst_secs = true, oxtame_soar_hint = true,
                oxtame_antislam = true, oxtame_rodeo_min_alt = true,
                oxtame_dive_poke = true, oxtame_dive_poke_node = true,
                oxtame_dive_poke_after = true, oxtame_dive_poke_cd = true, oxtame_dive_poke_target = true,
                oxtame_live_bait = true, oxtame_live_bait_cid = true, oxtame_live_bait_spawn_timeout = true,
                oxtame_seize_needs_dive = true, oxtame_seize_patience = true,   -- 07-25 seize the dive
                oxtame_seize_patience_r = true, oxtame_swoop_ask_cd = true,
                oxtame_scent_near_r = true,
                oxtame_waypoint = true, oxtame_waypoint_max_r = true,   -- 07-25 native destination write
                oxtame_waypoint_grace = true, oxtame_waypoint_progress = true,
                oxtame_waypoint_hold_cd = true,
                oxtame_wake_poke_cd = true, oxtame_sit_exit_node = true, oxtame_lie_exit_node = true,
                oxtame_takeoff_node2 = true, oxtame_air_bridge_node = true,   -- 07-25 wake ladder
                oxtame_relocate = true,   -- 07-20 flip to ON must beat the stale saved false
                oxtame_debug = true,      -- 07-21 release flip to OFF must beat the stale saved true
                oxtame_pose_arm_joints = true, oxtame_pose_head_joints = true,   -- 07-21 real-rig fix must beat the stale saved guesses
                -- An old save can still contain false from the abandoned transform-pin
                -- experiment. Native wolf carry is now code-authoritative.
                wolf_carry_native = true,
                -- Resource creation on an unmounted custom path can crash before Lua can
                -- catch it. This latch is deliberately session-only.
                housecat_mesh_armed = true,
            }
            -- keep the preview-tuned posture angles safe from the save (restored just below)
            local posture_code = {}
            for _, pk in ipairs({ "oxtame_palm_hand_up", "oxtame_palm_head_up", "oxtame_call_hand_up", "oxtame_call_head_up" }) do
                posture_code[pk] = C[pk]
            end
            for k, v in pairs(d.config) do
                -- sp_<band>_* = DYNAMIC per-species keys (perch tuning): no default exists in
                -- C, so the type-match gate would silently drop them on every load
                if not rodeo_code_only[k] and (type(C[k]) == type(v) or (tostring(k):find("^sp_ch%d") and type(v) == "number")) then C[k] = v end
            end
            -- ⭐ POSTURE SIGN MIGRATION (07-24, Aurora: "the palm isn't the upward one I scoped out
            -- with the sliders -- it aims the hand and head DOWN"). These four stay saved-config on
            -- purpose so the sliders remain useful, but a save written BEFORE the sign was
            -- understood (⚠ on this rig NEGATIVE = raise) still holds the old positive numbers and
            -- was silently overriding the preview-tuned code defaults. Every tuned value is
            -- negative, so a POSITIVE saved value is definitionally pre-tune: drop it, keep the
            -- code default, and leave future slider tuning (which writes negatives) untouched.
            for pk, pv in pairs(posture_code) do
                if pv and (tonumber(C[pk]) or 0.0) > 0.0 then C[pk] = pv end
            end
        end
        -- migration: the game spells it "Pitywort" (one T) -- older saved configs carry only the
        -- two-T guess, which never matched the real drop
        if not tostring(C.critter_feed_names or ""):find("pitywort", 1, true) then
            C.critter_feed_names = tostring(C.critter_feed_names or "") .. ",pitywort"
        end
        -- migration: bat feed = FRUIT (catalog-confirmed: apple 1/2, grapes 4/5, fig 10/11; the
        -- NAME list catches all four berry families). Crows happily eat fruit too -- global is fine.
        if not tostring(C.critter_feed_names or ""):find("apple", 1, true) then
            C.critter_feed_names = tostring(C.critter_feed_names or "") .. ",apple,grapes,fig,berry"
            C.critter_feed_items = tostring(C.critter_feed_items or "") .. ",1,2,4,5,10,11"
        end
        -- migration: the aviary grew (2026-07-12) -- bat ch299400 + seabird ch299420 join the
        -- rite and the scout; older saved configs carry only crow+bird
        for _, b9 in ipairs({ "ch299400", "ch299440", "ch299420" }) do
            if not tostring(C.critter_bands or ""):find(b9, 1, true) then
                C.critter_bands = tostring(C.critter_bands or "") .. "," .. b9
            end
            if not tostring(C.bird_bands or ""):find(b9, 1, true) then
                C.bird_bands = tostring(C.bird_bands or "") .. "," .. b9
            end
        end
        -- migration: the RABBIT (2026-07-14) -- first GROUND critter; tameable, never scoutable-by-air
        if not tostring(C.critter_bands or ""):find("ch299200", 1, true) then
            C.critter_bands = tostring(C.critter_bands or "") .. ",ch299200"
        end
        -- migration: the RAT (2026-07-15) -- second ground critter; tames with ROTTEN food
        if not tostring(C.critter_bands or ""):find("ch299210", 1, true) then
            C.critter_bands = tostring(C.critter_bands or "") .. ",ch299210"
        end
        -- migration: the FOWL (2026-08-11, the Homestead Box needs its chickens) -- both
        -- chicken bands join the critter tame; egg-collection at the farm is the payoff
        if not tostring(C.critter_bands or ""):find("ch299220", 1, true) then
            C.critter_bands = tostring(C.critter_bands or "") .. ",ch299220"
        end
        if not tostring(C.critter_bands or ""):find("ch299221", 1, true) then
            C.critter_bands = tostring(C.critter_bands or "") .. ",ch299221"
        end
        -- migration: 08-17 scout keys move onto DD2's OWN keyboard bindings (ping P->V,
        -- dive C->LMB, collect F->E). Only rewritten when the saved value is still the OLD
        -- DEFAULT -- a key Aurora has deliberately rebound is hers and must survive an update.
        if math.floor(tonumber(C.scout_ping_key) or 0) == 0x50 then C.scout_ping_key = 0x56 end
        if math.floor(tonumber(C.scout_caw_key) or 0) == 0x43 then C.scout_caw_key = 0x01 end
        if math.floor(tonumber(C.scout_collect_key) or 0) == 0x46 then C.scout_collect_key = 0x45 end
        -- ...and collect moves off the A pad button onto RT, so the A slot can honestly say "Up"
        if math.floor(tonumber(C.scout_collect_button) or 0) == 0x20020 then C.scout_collect_button = 0x800 end
        -- the old giant timer default (21px) predates the Alegreya pass; lift saved configs too
        if math.floor(tonumber(C.scout_timer_px) or 0) == 21 then C.scout_timer_px = 46.0 end
        -- migration: the first bat roost defaults (0, -0.05, 0) buried him in the armpit
        -- (image 43) -- shift saved configs still on them up and out so he's visible to tune
        if tonumber(C.bat_perch_x) == 0.0 and tonumber(C.bat_perch_y) == -0.05 and tonumber(C.bat_perch_z) == 0.0 then
            C.bat_perch_x = 0.08; C.bat_perch_y = 0.18; C.bat_perch_z = 0.0
        end
        -- migration 2 (image 44 -- upright + adorable, "a slight shove closer to the head"):
        -- inward off the shoulder tip, a touch higher and forward off the backpack line
        if tonumber(C.bat_perch_x) == 0.08 and tonumber(C.bat_perch_y) == 0.18 and tonumber(C.bat_perch_z) == 0.0 then
            C.bat_perch_x = 0.01; C.bat_perch_y = 0.21; C.bat_perch_z = 0.03
        end
        -- The apparent shoulder "growth" in the receipts is a silhouette change: clips
        -- 1/2 spread the crow's wings while clip 0 keeps them folded. The saved default
        -- kept reviving the wide clips after the code had declared the shoulder scale-
        -- neutral. Migrate that exact old default; deliberate custom lists remain intact.
        if tostring(C.perch_idle_clips or "") == "0,0,0,0,1,2" then
            C.perch_idle_clips = "0"
        end
        -- migration: bespoke bat/rabbit shoulder keys fold into the per-band table
        -- (sp_<band>_*) -- every species tunes the same way now (Aurora 07-15)
        if C.sp_ch299200_py == nil then
            C.sp_ch299200_px = tonumber(C.rabbit_perch_x) or 0.0
            C.sp_ch299200_py = tonumber(C.rabbit_perch_y) or 0.06
            C.sp_ch299200_pz = tonumber(C.rabbit_perch_z) or 0.0
            C.sp_ch299200_prot = tonumber(C.rabbit_perch_rot) or 0.0
            C.sp_ch299200_psc = tonumber(C.rabbit_perch_scale) or 0.8
        end
        if C.sp_ch299400_py == nil then
            for _, bb9 in ipairs({ "ch299400", "ch299440" }) do
                C["sp_" .. bb9 .. "_px"] = tonumber(C.bat_perch_x) or 0.01
                C["sp_" .. bb9 .. "_py"] = tonumber(C.bat_perch_y) or 0.21
                C["sp_" .. bb9 .. "_pz"] = tonumber(C.bat_perch_z) or 0.03
            end
        end
        -- migration: the OLD court mode wrote griffin_ghost into the SAVE and a dead scene
        -- could leave it stuck ON (Aurora caught it silently active) -- clear it ONCE; the
        -- court shield is volatile now and never touches this key again
        if C.oxtame_ghost_reset ~= true then
            C.oxtame_ghost_reset = true
            C.griffin_ghost = false
        end
        -- migration: unbound hotkeys self-heal (typing to the pawn walked through the hotkey
        -- capture and set tame/sense to -1 -- Aurora's save; the typing guard now prevents it)
        if math.floor(tonumber(C.tame_key) or 0) <= 0 then C.tame_key = 0x4E end    -- N
        if math.floor(tonumber(C.sense_key) or 0) <= 0 then C.sense_key = 0x4B end  -- K
        -- Wayfarer's Sense tuning (Aurora 2026-07-22): labels linger LONGER, and the stationary
        -- search gesture holds you SHORTER (it made the sense less useful). Clamped here so old
        -- saved configs pick the new feel up.
        if (tonumber(C.sense_secs) or 0) < 15.0 then C.sense_secs = 15.0 end
        -- ⛔ THE 1.5s CLAMP WAS THE "SENSE CUTS OUT MID-ANIMATION" BUG (Aurora 07-26). It forced
        -- the hold to 1.5s on EVERY load, so the FSM reclaimed the body partway through 60:7631
        -- and the gesture visibly snapped off. The 07-22 intent (don't freeze the player for
        -- ages) is right, but truncating the clip is the wrong lever - UPPER-BODY play is, since
        -- then the gesture can run its full length while you keep walking. Clamp only applies to
        -- the old full-body path.
        if C.sense_upper == nil then C.sense_upper = false end
        C.sense_upper = false   -- layer-1 play renders nothing on this build; force it off even
                                -- for configs saved while it was briefly the default
        -- ⛔ and DON'T re-clamp sense_anim_secs: that clamp WAS the truncation bug.
        -- migration: the air-take is field-disproven (native flight out-flies the drive) --
        -- flip saved configs to ground-only once
        if C.oxtame_air_reset ~= true then
            C.oxtame_air_reset = true
            C.oxtame_air_descend = false
        end
        -- migration: the ping finally has a real chime (COMMON/ABILITY 2832279408, Aurora 07-15)
        -- -- older saves hold 0 (silent)
        if math.floor(tonumber(C.scout_ping_sound_id) or 0) == 0 then
            C.scout_ping_sound_id = 2832279408
        end
        -- migration: the sm80_009 mound guess loads + binds but never RENDERS (07-15, twice) --
        -- swap saved configs onto the PROVEN nest mesh at lump scale (visible pipeline, prettier
        -- dirt prop later once one is sniffed); the 0.16 sink would bury a lump-scale nest whole
        if tostring(C.burrow_mound_mesh) == "environment/props/sm8x/sm80/sm80_009/sm80_009_00" then
            C.burrow_mound_mesh = "environment/props/sm5x/sm52/sm52_118/sm52_118_00"
            C.burrow_mound_sink = 0.02
        end
        -- migration: Gm51_144 (town pots) has NO spawnable prefab -- Gm50_000 is the proven egg chassis
        if tostring(C.egg_chassis) == "Gm51_144" then C.egg_chassis = "Gm50_000" end
        -- migration: the hand pin moved from ROOT-anchored to JOINT-anchored offsets (image 61)
        if tonumber(C.egg_hold_x) == 0.0 and tonumber(C.egg_hold_y) == 1.02 and tonumber(C.egg_hold_z) == 0.42 then
            C.egg_hold_x = 0.10; C.egg_hold_y = 0.12; C.egg_hold_z = 0.02
        end
        -- the bowl is OUR woven nest, unconditionally (every path guess is history)
        C.nest_bowl_mesh = "environment/props/sm5x/sm52/sm52_118/sm52_118_00"
        -- bone-era sink/scale would render it 13m wide and half-buried -- one-time correction
        if tonumber(C.nest_bowl_scale) and tonumber(C.nest_bowl_scale) > 1.6 then
            C.nest_bowl_scale = 1.0
            C.nest_bowl_sink = -0.02
        end
        -- migration: the shoulder is now a per-frame pin onto the SHOULDER JOINT (offsets are a
        -- small nudge from the clavicle). The brief ROOT-pin era used a ~shoulder-height Y (~1.4)
        -- which is nonsense against the joint base -- reset those to the small joint-relative default.
        if tonumber(C.perch_y) and tonumber(C.perch_y) > 0.9 then
            C.perch_x = 0.1; C.perch_y = 0.05; C.perch_z = 0.0
        end
        -- LEARNED CAMPS: every camp the player actually uses is remembered (UNIVERSAL coords) and
        -- persists -- the "carry it somewhere safe" marker points at the nearest remembered one.
        -- (No campsite registry was found in any manager; the map learns itself instead.)
        if d and type(d.camps) == "table" then S.camps = d.camps end
        S.camps = S.camps or {}
        -- migration: an early seed used "Volcanic Island Camp" from a teleport LOCATION list --
        -- that is a region name, not an actual campsite gimmick. Only camps learned from a real
        -- get_IsActiveCamp() edge (i.e. an actual campfire) belong here.
        for i = #S.camps, 1, -1 do
            if tostring(S.camps[i].name or "") == "Volcanic Island Camp" then table.remove(S.camps, i) end
        end
        -- migration: the persisted config shadows new defaults -- T (0x54) now belongs to the
        -- griffin grab, so an old saved binding gets force-moved to N
        if C.tame_key == 0x54 then C.tame_key = 0x4E end
        if tonumber(C.rush_back_dist) == 5.0 or tonumber(C.rush_back_dist) == 6.0 then C.rush_back_dist = 10.0 end
        -- pace re-tune (field notes: runs too fast/too long, stops too close): migrate old values
        if tonumber(C.circle_speed) == 0.55 then C.circle_speed = 0.35 end
        if tonumber(C.rush_speed) < 15.0 then C.rush_speed = 25.0 end
        if tonumber(C.rush_stop_d) < 4.5 then C.rush_stop_d = 5.0 end
        if tonumber(C.rush_back_dist) < 12.0 or tonumber(C.rush_back_dist) > 40.0 then C.rush_back_dist = 28.0 end
        if tonumber(C.rush_back_speed) < 6.0 or tonumber(C.rush_back_speed) > 18.0 then C.rush_back_speed = 14.0 end
        if tonumber(C.tell_secs) == 2.2 then C.tell_secs = 3.0 end
        if tostring(C.hunt_prey_band) == "ch299" then C.hunt_prey_band = "ch299011,ch299020,ch299221" end
        -- 08-14 THE QUARRY IS A STAG NOW. Both halves must move together: changing only the cid
        -- leaves the newborn stag failing is_huntable, so it is never adopted into T.hunt_ch, no
        -- marker appears, and the hunt dies at the 12s timeout with "nothing came of the hunt".
        if tostring(C.hunt_spawn_cid) == "ch299011_A_00" then C.hunt_spawn_cid = "ch299010_A_00" end
        if not tostring(C.hunt_prey_band or ""):find("ch299010", 1, true) then
            C.hunt_prey_band = "ch299010," .. tostring(C.hunt_prey_band or "")
        end
        -- ⛔ THE RAY START AND THIS VALUE MUST STAY IN STEP. hunt_ground_y probes from pp.y+2.0
        -- and the cast accepts contacts up to start+1.0, so anything above +3.0 is unreachable
        -- by the probe anyway - a saved 5.0 from the first cut of this feature would just be a
        -- lie in the panel. (The +6.0 start it was written for made low branches read as ground.)
        if tonumber(C.hunt_spawn_max_rise) == 5.0 then C.hunt_spawn_max_rise = 3.0 end
        if tostring(C.target_bands) == "ch2,ch3" then C.target_bands = "ch223" end
        if tonumber(C.cue_stop_clip) == 30 then C.cue_stop_clip = 312 end
        if tonumber(C.cue_tension_clip) == 4030 then C.cue_tension_clip = 2 end   -- 4030 is not a bank-0 clip
        -- deep-scan riches (the wolf had a real walk + settle + howl all along)
        if tonumber(C.cue_walk_clip) == 200 then C.cue_walk_clip = 100 end
        if tonumber(C.circle_anim_speed) == 0.65 then C.circle_anim_speed = 1.0 end
        if tonumber(C.cross_anim_speed) == 0.55 then C.cross_anim_speed = 1.0 end
        if tonumber(C.cue_lie_start) == 87 or tonumber(C.cue_lie_start) == 4600 then C.cue_lie_start = 10 end
        if tonumber(C.cue_lie_loop) == 88 or tonumber(C.cue_lie_loop) == 4601 then C.cue_lie_loop = 11 end
        if tonumber(C.pact_hold_secs) == 2.5 then C.pact_hold_secs = 4.5 end   -- longer headpat (field feedback)
        -- the offering upgraded from the picnic-spread stand-in to the real raw-meat prop
        if tostring(C.feed_prop_mesh) == "environment/props/sm8x/sm80/sm80_221/sm80_221_00" then
            C.feed_prop_mesh = "environment/props/sm8x/sm81/sm81_014/sm81_014_00"
            C.feed_prop_scale = 1.0
        end
        if tostring(C.feed_items) == "27,25,41,45,114,115" then C.feed_items = "30,27,25,28,41,45,114,115,29" end   -- + the beast-steak family
    end)
end

