local function learn_camp(pp)
    -- record the spot when the player camps (dedup within 30m of a known one)
    if not pp then return end
    S.camps = S.camps or {}
    for _, c in ipairs(S.camps) do
        if dist(pp, c) < 30.0 then return end
    end
    S.camps[#S.camps + 1] = { x = pp.x, y = pp.y, z = pp.z, name = string.format("Camp %d", #S.camps + 1) }
    save_state()
    pcall(function() log.info(string.format("[IrisTaming] camp learned at (%.0f, %.0f, %.0f) -- %d known", pp.x, pp.y, pp.z, #S.camps)) end)
end

local function map_campsites()
    -- LIVE campsite positions from the game's own MAP ICONS (app.GuiManager getMapIconList --
    -- the same source RiftSpeak's lead-to uses; icons carry get_DispName + UNIVERSAL get_Pos).
    -- Discovered campsites appear as "Campsite" icons, so this list is exactly the camps the
    -- player can actually see on the map. Cached a few seconds (the list is big).
    local now = os.clock()
    if S.campicons and (now - (tonumber(S.campicons.t) or 0.0)) < 5.0 then return S.campicons.list end
    local out = {}
    pcall(function()
        local gm = singleton("app.GuiManager")
        local list = gm and gm:call("getMapIconList")
        if not list then return end
        local n = 0; pcall(function() n = list:call("get_Count") end)
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local e = list:call("get_Item", i)
                local dn = e and e:call("get_DispName")
                local nm2 = dn and tostring(dn) or ""
                if nm2 ~= "" and nm2:lower():find("camp", 1, true) then
                    local p = e:call("get_Pos")
                    if p then out[#out + 1] = { x = p.x, y = p.y, z = p.z, name = nm2 } end
                end
            end)
        end
    end)
    S.campicons = { t = now, list = out }
    return out
end

local function nearest_camp(pp)
    if not pp then return nil, nil end
    local best, bd = nil, 1e9
    for _, c in ipairs(map_campsites()) do      -- the map's own campsite icons FIRST
        local dd = dist(pp, c)
        if dd < bd then bd = dd; best = c end
    end
    for _, c in ipairs(S.camps or {}) do        -- learned camps as backup (icons need map discovery)
        local dd = dist(pp, c)
        if dd < bd then bd = dd; best = c end
    end
    return best, bd
end

-- ============================ feeding (the tend offers real meat from the pack) ============================
local function item_mgr() return singleton("app.ItemManager") end

local function feed_item_held(player, csv)
    -- first feedable item the player actually carries (ids tried in list order; default = the
    -- beast-meat list, critters pass their own -- greenwarish etc.)
    local mgr = item_mgr()
    if not (mgr and player) then return nil end
    for idstr in tostring(csv or C.feed_items or ""):gmatch("[^,%s]+") do
        local id = tonumber(idstr)
        if id then
            local n = nil
            pcall(function() n = tonumber(mgr:call("getHaveNum(System.Int32, app.Character)", id, player)) end)
            if n and n > 0 then return id end
        end
    end
    return nil
end

local function feed_count_snapshot(player, csv)
    -- Ground drops can merge into an existing world stack, retaining the same
    -- GameObject address.  Address-only "new drop" detection therefore misses a
    -- perfectly real second Greenwarish.  Keep the relevant bag counts as the
    -- authoritative proof that the player performed a fresh drop.
    local out = {}
    local mgr = item_mgr()
    if not (mgr and player) then return out end
    for idstr in tostring(csv or C.critter_feed_items or ""):gmatch("[^,%s]+") do
        local id = tonumber(idstr)
        if id then
            local n = nil
            pcall(function()
                n = tonumber(mgr:call(
                    "getHaveNum(System.Int32, app.Character)", id, player))
            end)
            if n ~= nil then out[id] = n end
        end
    end
    return out
end

local function feed_count_dropped(player, csv, before)
    if type(before) ~= "table" then return nil end
    local mgr = item_mgr()
    if not (mgr and player) then return nil end
    local dropped = nil
    for idstr in tostring(csv or C.critter_feed_items or ""):gmatch("[^,%s]+") do
        local id = tonumber(idstr)
        if id then
            local n = nil
            pcall(function()
                n = tonumber(mgr:call(
                    "getHaveNum(System.Int32, app.Character)", id, player))
            end)
            local old = tonumber(before[id])
            if n ~= nil then
                if old ~= nil and n < old then dropped = dropped or id end
                before[id] = n
            end
        end
    end
    return dropped
end

local function consume_item(player, id)
    -- deleteItem: the proven consume (same call the give/drop recipes use)
    local mgr = item_mgr()
    if not (mgr and player and id) then return false end
    return pcall(function() mgr:call("deleteItem(System.Int32, System.Int32, app.Character)", id, 1, player) end)
end

-- ============================ scout loot (the bird collects on the wing) ============================
-- ADD an item to the player's bag WITH the native "acquired [item]" popup. The proven call from
-- guild_contracts.lua/RiftSpeak inventory.lua: app.ItemManager.getItem 9-arg (the popup is a
-- side-effect of that call, gated by the 8th bool). NOT putItem (that is a ground-drop no-op).
local _iris_getitem_m = nil
local function give_item(player, id, count, popup)
    local mgr = item_mgr()
    if not (mgr and player and id) then return false end
    if _iris_getitem_m == nil then
        pcall(function()
            _iris_getitem_m = sdk.find_type_definition("app.ItemManager"):get_method(
                "getItem(System.Int32, System.Int32, app.Character, System.Boolean, System.Boolean, System.Boolean, app.ItemManager.GetItemEventType, System.Boolean, System.Boolean)")
        end)
        if not _iris_getitem_m then _iris_getitem_m = false end
    end
    if not _iris_getitem_m then return false end
    local ok = false
    pcall(function()
        _iris_getitem_m:call(mgr, math.floor(id), math.floor(tonumber(count) or 1), player,
            true, false, false, nil, popup == true, false)
        ok = true
    end)
    return ok
end

-- 08-08 r3 WLC count/consume = the HOMESTEAD's PROVEN calls (Aurora:
-- "you can't drop items in a camp"). IrisDeedSign already verified
-- getHaveNum + deleteItem in-game for the build materials -- no more
-- runtime-resolver guessing (the r1/r2 log named getItemNumber/
-- removeItemData, but these are the field-proven pair). Player chara =
-- the manual player, same as the homestead uses.
function iris_wlc_count(id)
    local n
    pcall(function()
        local im = sdk.get_managed_singleton("app.ItemManager")
        local ch = sdk.get_managed_singleton("app.CharacterManager")
            :call("get_ManualPlayer")
        if im and ch then
            n = tonumber(im:call(
                "getHaveNum(System.Int32, app.Character)", id, ch))
        end
    end)
    return n
end

function iris_wlc_take(id, num)
    num = math.floor(tonumber(num) or 1)
    local before = iris_wlc_count(id)
    if not before or before < num then return false end
    local after
    pcall(function()
        local im = sdk.get_managed_singleton("app.ItemManager")
        local ch = sdk.get_managed_singleton("app.CharacterManager")
            :call("get_ManualPlayer")
        if im and ch then
            im:call("deleteItem(System.Int32, System.Int32, app.Character)",
                id, num, ch)
            after = iris_wlc_count(id)
        end
    end)
    local ok = before and after and after <= before - num
    pcall(function() log.info(string.format(
        "[IrisTaming] WLC consume x%d: %s -> %s = %s", num,
        tostring(before), tostring(after), ok and "OK" or "FAILED")) end)
    return ok
end

-- 08-08 r3 NATIVE YES/NO DIALOG (the homestead's general-purpose recipe
-- -- IrisDeedSign): app.GuiManager.Dialog = app.ui010101; reqDisp shows
-- a real paused dialog, getDialogState returns 0=None 1=Cancel 2=Sel0
-- 3=Sel1. ⛔ getDialogState LATCHES across sessions -- act only on a
-- CHANGE from the open-time baseline. GUI calls are game-thread only
-- (this runs in the UpdateBehavior tick). Put the SAFE option so it's
-- Sel1 (No), Sel0 = Yes.
local WYRM_DLG = 14   -- app.GuiDefine.GuiType.Dialog
function iris_wyrm_dialog_pick()
    local p
    pcall(function()
        local gm = sdk.get_managed_singleton("app.GuiManager")
        local rv = gm and gm:call("getDialogState")
        if type(rv) == "number" then p = rv
        elseif rv ~= nil then p = sdk.to_int64(rv) & 0xFFFFFFFF end
    end)
    return p
end
function iris_wyrm_dialog_open(prompt, yes_label, no_label)
    pcall(function()
        local gm = sdk.get_managed_singleton("app.GuiManager")
        local dialog = gm and gm:get_field("Dialog")
        if not dialog then return end
        gm:call("requestGuiType", WYRM_DLG)
        dialog:call("reqDisp",
            prompt, yes_label, no_label, "", "",
            true, 0, true, 58, 0, -1, nil,
            false, false, false, false, false, false,
            true, 0.0)
        S.wyrm_dlg = { open = true, opened_at = os.clock(),
            baseline = iris_wyrm_dialog_pick() }
    end)
end
function iris_wyrm_dialog_close()
    pcall(function()
        local gm = sdk.get_managed_singleton("app.GuiManager")
        local dialog = gm and gm:get_field("Dialog")
        if dialog then dialog:call("reqClose") end
        gm:call("requestHideGuiType", WYRM_DLG)
    end)
    S.wyrm_dlg = nil
end
-- ⛔ SOFTLOCK GUARD (homestead law): S is fresh every reload, so a
-- script reset while our paused dialog is up would orphan it (paused
-- world + no reader). Blind-close the Dialog GUI once at load.
pcall(function() iris_wyrm_dialog_close() end)

-- 08-08 WYRM RITE SHELL (Aurora's VFX): cast the ch227 shell ON the
-- beast, scaled to cover it, tinted deep red. The CAST is self-contained
-- (ShellManager); the COLOR rides Nick's effect-container hook via his
-- shared fns.on_post_create_effect table -- DEPEND, never edit, and
-- degrade to the shell's default color if his framework isn't loaded.
local _wyrm_shell_mgr, _wyrm_shell_req_m, _wyrm_shell_udata
local _wyrm_shell_color_armed = false
local _wyrm_shell_pending = {}   -- requestID -> {r,g,b,a}
local function iris_cast_wyrm_shell(owner_go)
    if not owner_go then return end
    pcall(function()
        _wyrm_shell_mgr = _wyrm_shell_mgr or sdk.get_managed_singleton("app.ShellManager")
        _wyrm_shell_req_m = _wyrm_shell_req_m or sdk.find_type_definition("app.ShellManager")
            :get_method("requestCreateShell(via.GameObject, via.vec3, via.Quaternion, app.ShellRequest.ShellCreateInfo, app.ShellParamData, app.ShellRequest.EventCreateShellSuccess, app.ShellRequest.EventBeforeShellInstantiate)")
        if not (_wyrm_shell_mgr and _wyrm_shell_req_m) then return end
        local path = tostring(C.wyrm_shell_path)
        _wyrm_shell_udata = _wyrm_shell_udata
            or sdk.create_userdata("app.ShellParamData", path)
        local udata = _wyrm_shell_udata
        if not udata then return end
        local sid = math.floor(tonumber(C.wyrm_shell_id) or 0)
        local entry = udata.ShellParams._items[sid]
        local hash = entry._ShellParamIdHash
        -- SCALE: wrap the wolf (Nick's modify_base_params recipe; restore
        -- after 0.2s so it doesn't stick on the shared udata)
        local base = entry._ShellParameterBase.ShellBaseParam
        local bu, bs = base.UseScale, base.Scale
        local s = tonumber(C.wyrm_shell_scale) or 4.0
        base.UseScale = true
        base.Scale = Vector3f.new(s, s, s)
        local life = tonumber(C.wyrm_shell_life) or -1.0
        local bul, bl = base.UseLifeTime, base.LifeTime
        if life > 0 then base.UseLifeTime = true; base.LifeTime = life end
        entry._ShellParameterBase.ShellBaseParam = base
        local req = sdk.create_instance("app.ShellRequest.ShellCreateInfo"):add_ref()
        req.ShellParamIdHash = hash
        local tf = owner_go:call("get_Transform")
        -- position ON the beast (root joint, like Nick's tool); rotation
        -- = its facing
        local pos = tf:call("get_Position")
        pcall(function()
            local rj = tf:call("getJointByName", "root")
            if rj then pos = rj:call("get_Position") end
        end)
        local rot = tf:call("get_Rotation")
        -- ⭐ 08-08 (Aurora: "Nick's tool had visual AND sound"): Nick casts
        -- with SOURCE = PLAYER -- the shell's SOUND rides the OWNER, so a
        -- player-owned shell is audible; a wolf-owned one was silent.
        -- Owner = PLAYER (for the sound), positioned on the wolf (for the
        -- visual). Best of both.
        local owner_cast = owner_go
        pcall(function()
            local pg = char_go(get_player())
            if pg then owner_cast = pg end
        end)
        local rid = _wyrm_shell_req_m:call(_wyrm_shell_mgr, owner_cast, pos, rot, req, udata, nil, nil)
        -- queue the color for the effect-container hook to apply
        if rid then
            _wyrm_shell_pending[rid] = {
                tonumber(C.wyrm_shell_r) or 1.0, tonumber(C.wyrm_shell_g) or 1.0,
                tonumber(C.wyrm_shell_b) or 1.0, tonumber(C.wyrm_shell_a) or 1.0 }
        end
        -- restore the shared udata after the cast reads it
        pcall(function()
            local restore_at = os.clock() + 0.2
            S.wyrm_shell_restore = { at = restore_at, base = base,
                bu = bu, bs = bs, bul = bul, bl = bl }
        end)
    end)
    -- arm the color callback ONCE, on Nick's shared hook table (depend)
    if not _wyrm_shell_color_armed then
        _wyrm_shell_color_armed = true
        pcall(function()
            local fns = require("_NickCore/Functions")
            local hh = require("NicksDevtools/Helpers")
            if fns and fns.on_post_create_effect and hh and hh.change_container_colors then
                fns.on_post_create_effect["IRIS Wyrm Rite"] = function(data)
                    if data and data.requestID and _wyrm_shell_pending[data.requestID] then
                        local col = _wyrm_shell_pending[data.requestID]
                        _wyrm_shell_pending[data.requestID] = nil
                        pcall(function() hh.change_container_colors(data.container, 0, col, col) end)
                    end
                end
                pcall(function() log.info("[IrisTaming] wyrm shell color callback armed (Nick FX hook)") end)
            else
                pcall(function() log.info("[IrisTaming] wyrm shell: Nick FX framework absent -- shell casts in default color") end)
            end
        end)
    end
end

local function render_pos(go)
    local ok, p = pcall(function() return go:call("get_Transform"):call("get_Position") end)
    return ok and p or nil
end

local function planar_dist(a, b)
    if not (a and b) then return 1e9 end
    local dx = (tonumber(a.x) or 0) - (tonumber(b.x) or 0)
    local dz = (tonumber(a.z) or 0) - (tonumber(b.z) or 0)
    return math.sqrt(dx * dx + dz * dz)
end

local function scout_find_drop(brp, range)
    -- nearest ground DROP (loot bag) within range of the bird (render space). Returns the entry
    -- + its item id/count/name, so we can grant it OURSELVES on return (true deferral, no dupe).
    local mgr = item_mgr()
    if not (mgr and brp) then return nil end
    local best, bd = nil, range
    pcall(function()
        local dl = mgr:call("get_DropItemList")
        if not dl then return end
        local n = 0
        pcall(function() n = tonumber(dl:call("get_Count")) or 0 end)
        if n == 0 then pcall(function() n = tonumber(dl:call("get_size")) or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local dr = dl:call("get_Item", i) or dl[i]
                local dgo = dr and dr:call("get_GameObject")
                local rp = dgo and render_pos(dgo)
                if rp then
                    local d = planar_dist(rp, brp)
                    if d < bd then bd = d; best = dr end
                end
            end)
        end
    end)
    if not best then return nil end
    local id, count, name = nil, 1, "item"
    pcall(function()
        local ip = best:call("get_ItemParam")
        pcall(function() id = tonumber(ip:call("get_ItemId")) end)
        pcall(function() name = tostring(ip:call("get_Name") or "item") end)
    end)
    pcall(function() count = tonumber(best:call("get_Num")) or 1 end)
    return best, id, count, name
end

local function scout_find_gimmick(brp, range)
    -- nearest live GATHER gimmick (bush/plant/ore) within range. The item is rolled inside the
    -- native interact, so we cannot pre-know it -- collection grants immediately (see scout_collect).
    local gm = singleton("app.GimmickManager")
    if not (gm and brp) then return nil end
    local best, bd = nil, range
    pcall(function()
        local list = gm:call("get_CollectionGimmicks")
        if not list then return end
        local n = 0
        pcall(function() n = tonumber(list:call("get_Count")) or 0 end)
        if n == 0 then pcall(function() n = tonumber(list:call("get_size")) or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local g = list:call("get_Item", i) or list[i]
                local ggo = g and (g:call("get_GameObject"))
                local rp = ggo and render_pos(ggo)
                local live = true
                pcall(function() live = g:call("isInteractEnable", 0) ~= false end)
                if rp and live then
                    local d = planar_dist(rp, brp)
                    if d < bd then bd = d; best = g end
                end
            end)
        end
    end)
    return best
end

-- ⚠ PROBE: lootable corpses. ⛔ findComponents can NOT see SearchDeadBodyInteractController
-- (scanned 0 with lootable bodies in view -- Aurora's log); the LootOverlay recipe is the truth:
-- the controllers must be CAUGHT AT CREATION -- hook setupInteractiveObject() and keep a registry.
-- Only corpses made after script load register (reload = re-kill something to test).
pcall(function()
    S.corpse_reg = S.corpse_reg or {}
    sdk.hook(
        sdk.find_type_definition("app.SearchDeadBodyInteractController"):get_method("setupInteractiveObject()"),
        function(args)
            pcall(function()
                local ctrl = sdk.to_managed_object(args[2])
                if ctrl then S.corpse_reg[ctrl] = true end
            end)
        end, nil)
end)

local function scout_find_corpse(brp, range)
    -- nearest lootable corpse from the hook registry; stale entries pruned as we walk. The scan
    -- summary logs so a fruitless press says WHY. The COLLECT (executeInteract) stays the probe.
    if not brp then return nil end
    local best, bd = nil, range
    local total, able_n, nearest = 0, 0, -1.0
    local stale = {}
    for ctrl in pairs(S.corpse_reg or {}) do
        total = total + 1
        local alive = false
        pcall(function()
            if not sdk.is_managed_object(ctrl) then return end
            alive = true
            if ctrl:call("get_IsEnablePickup") ~= true then return end
            if ctrl:call("isInteractEnable", 0) == false then return end
            able_n = able_n + 1
            local rp = nil
            pcall(function()
                local chara = ctrl:get_field("Chara")
                local g2 = chara and chara:call("get_GameObject")
                rp = g2 and render_pos(g2)
            end)
            if not rp then pcall(function() local cgo = ctrl:call("get_GameObject"); rp = cgo and render_pos(cgo) end) end
            if rp then
                local d = planar_dist(rp, brp)
                if nearest < 0 or d < nearest then nearest = d end
                if d < bd then bd = d; best = ctrl end
            end
        end)
        if not alive then stale[ctrl] = true end
    end
    for c2 in pairs(stale) do S.corpse_reg[c2] = nil end
    pcall(function() log.info(string.format("[IrisTaming] corpse scan: %d registered, %d lootable, nearest %.1fm (reach %.1fm)",
        total, able_n, nearest, range)) end)
    return best
end

local function storage_data_for(player, id)
    -- the player's StorageData entry for item id (the equip-read recipe: master list + get_ItemId).
    -- Container shape varies (List vs array): count via get_Count/get_size/get_Length, items via
    -- get_Item/[i]/get_element - try them all, and report what happened for the drop diag.
    local mgr = item_mgr()
    if not (mgr and player) then return nil, "no ItemManager" end
    local sd, why = nil, "no match"
    pcall(function()
        local cid = player:call("get_CharaID")
        local list = mgr:call("getStorageMasterList(app.CharacterID)", cid)
        if not list then why = "no master list"; return end
        local n = 0
        pcall(function() n = tonumber(list:call("get_Count")) or 0 end)
        if n == 0 then pcall(function() n = tonumber(list:call("get_size")) or 0 end) end
        if n == 0 then pcall(function() n = tonumber(list:call("get_Length")) or 0 end) end
        if n == 0 then why = "master list empty/uncounted"; return end
        for i = 0, n - 1 do
            local e = nil
            pcall(function() e = list:call("get_Item", i) end)
            if e == nil then pcall(function() e = list[i] end) end
            if e == nil then pcall(function() e = list:call("get_element", i) end) end
            if e then
                local iid = nil
                pcall(function() iid = tonumber(e:call("get_ItemId")) end)
                if iid == nil then pcall(function() iid = tonumber(e:get_field("<ItemId>k__BackingField")) end) end
                if iid == id then sd = e; why = "found @" .. i .. "/" .. n; break end
            end
        end
        if not sd then why = "no match in " .. n .. " entries" end
    end)
    return sd, why
end

local function drop_list_snapshot(mgr)
    -- addresses of every ground drop the game currently tracks (to spot OUR new one after putItem)
    local set = {}
    pcall(function()
        local dl = mgr:call("get_DropItemList")
        local n = dl and (tonumber(dl:call("get_Count")) or 0) or 0
        for i = 0, n - 1 do
            pcall(function() set[dl:call("get_Item", i):get_address()] = true end)
        end
    end)
    return set
end

local function find_new_drop(mgr, player, seen)
    -- the drop that was NOT in the snapshot and is near the player = the one just laid down
    local best, bd = nil, 8.0
    pcall(function()
        local prp = char_go(player):call("get_Transform"):call("get_Position")
        local dl = mgr:call("get_DropItemList")
        local n = dl and (tonumber(dl:call("get_Count")) or 0) or 0
        for i = 0, n - 1 do
            pcall(function()
                local dr = dl:call("get_Item", i)
                if not seen[dr:get_address()] then
                    local dgo = dr:call("get_GameObject")
                    local rp = dgo and dgo:call("get_Transform"):call("get_Position")
                    if rp and prp then
                        local dx, dz = rp.x - prp.x, rp.z - prp.z
                        local dd = math.sqrt(dx * dx + dz * dz)
                        if dd < bd then bd = dd; best = dr end
                    end
                end
            end)
        end
    end)
    return best
end

local function find_feed_drop_near(mgr, player, csv, radius)
    -- Used only after the bag count proves that a feed item was just dropped.
    -- Unlike find_new_drop this deliberately permits an old address because DD2
    -- merges matching ground stacks in place.
    local allowed = {}
    for idstr in tostring(csv or C.critter_feed_items or ""):gmatch("[^,%s]+") do
        local id = tonumber(idstr)
        if id then allowed[id] = true end
    end
    local best, bd = nil, tonumber(radius) or 8.0
    pcall(function()
        local prp = char_go(player):call("get_Transform"):call("get_Position")
        local dl = mgr:call("get_DropItemList")
        local n = dl and (tonumber(dl:call("get_Count")) or 0) or 0
        for i = 0, n - 1 do
            pcall(function()
                local dr = dl:call("get_Item", i)
                local ip = dr and dr:call("get_ItemParam")
                local iid = tonumber(ip and ip:call("get_ItemId"))
                local dgo = dr and dr:call("get_GameObject")
                local rp = dgo and dgo:call("get_Transform"):call("get_Position")
                if allowed[iid] and rp and prp then
                    local dx, dz = rp.x - prp.x, rp.z - prp.z
                    local dd = math.sqrt(dx * dx + dz * dz)
                    if dd < bd then bd = dd; best = dr end
                end
            end)
        end
    end)
    return best
end

local function ground_scan_snapshot(pgo0)
    -- addresses of every mesh-bearing GameObject near the player. The offering fallback: player
    -- DISCARDS may never enter get_DropItemList (it read as loot-bags-only in the field), but the
    -- dropped herb IS a real scene object -- a new mesh GO appearing at the feet is the offering.
    local set = {}
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("via.render.Mesh"))
        local prp = pgo0:call("get_Transform"):call("get_Position")
        local n = 0
        pcall(function() n = comps:call("get_Length") or 0 end)
        if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local m = comps:call("get_Item", i) or comps[i]
                local g = m:call("get_GameObject")
                local rp = g:call("get_Transform"):call("get_Position")
                local dx, dz = rp.x - prp.x, rp.z - prp.z
                if dx * dx + dz * dz < 100.0 then set[g:get_address()] = true end
            end)
        end
    end)
    return set
end

local function ground_scan_new(pgo0, seen)
    -- the nearest mesh GO that was NOT in the snapshot (skipping characters); logs every find so
    -- the real name of a dropped herb surfaces in the log for future hardening
    local best, bd = nil, 6.0
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("via.render.Mesh"))
        local prp = pgo0:call("get_Transform"):call("get_Position")
        local n = 0
        pcall(function() n = comps:call("get_Length") or 0 end)
        if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local m = comps:call("get_Item", i) or comps[i]
                local g = m:call("get_GameObject")
                if not seen[g:get_address()] then
                    local gn = go_name(g)
                    if gn:find("ch", 1, true) ~= 1 then   -- never a character body
                        local rp = g:call("get_Transform"):call("get_Position")
                        local dx, dz = rp.x - prp.x, rp.z - prp.z
                        local dd = math.sqrt(dx * dx + dz * dz)
                        if dd < bd then
                            bd = dd; best = g
                            pcall(function() log.info(string.format("[IrisTaming] new ground object: %s at %.1fm", gn, dd)) end)
                        end
                    end
                end
            end)
        end
    end)
    return best
end

local function ground_scan_nearest_drop(pgo0, radius)
    -- Last-resort locator after an inventory decrement proves a drop occurred but
    -- ItemManager exposes no corresponding DropItem entry.  Restrict this to the
    -- engine naming families observed for actual discarded items; the count edge,
    -- not the mesh name, is what authorises it as food.
    local best, bd = nil, tonumber(radius) or 6.0
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call(
            "findComponents(System.Type)", sdk.typeof("via.render.Mesh"))
        local prp = pgo0:call("get_Transform"):call("get_Position")
        local n = 0
        pcall(function() n = comps:call("get_Length") or 0 end)
        if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local m = comps:call("get_Item", i) or comps[i]
                local g = m:call("get_GameObject")
                local gn = tostring(go_name(g) or "")
                local itemish = gn:find("^gm%d") or gn:find("^eqit")
                    or gn:find("^it%d") or gn:find("^sm%d")
                local junk = gn:find("Plane") or gn:find("Trim")
                    or gn:find("__") or gn:find("^ch%d")
                if itemish and not junk then
                    local rp = g:call("get_Transform"):call("get_Position")
                    local dx, dz = rp.x - prp.x, rp.z - prp.z
                    local dd = math.sqrt(dx * dx + dz * dz)
                    if dd < bd then bd = dd; best = g end
                end
            end)
        end
    end)
    return best
end

local function drop_item_begin(player, id, pp)
    -- start a REAL ground drop: ItemManager putItem at the character's feet. The engine may DEFER
    -- the actual spawn (a same-frame check read "no drop, stack unchanged" even on a successful
    -- call), so this returns a WAITER that drop_item_check polls for the drop to materialise.
    -- The 6-arg positional putItem overload is BANNED here: it crashed the game natively.
    local mgr = item_mgr()
    if not (mgr and player and id and pp) then return nil end
    local sd, sd_why = storage_data_for(player, id)
    if not sd then
        S.drop_dbg = "no StorageData for item " .. tostring(id) .. " (" .. tostring(sd_why) .. ")"
        pcall(function() log.info("[IrisTaming] drop: " .. S.drop_dbg) end)
        return nil
    end
    local before = nil
    pcall(function() before = tonumber(mgr:call("getHaveNum(System.Int32, app.Character)", id, player)) end)
    local seen = drop_list_snapshot(mgr)
    local ok3 = pcall(function() mgr:call("putItem(app.ItemDefine.StorageData, System.Int32, app.Character)", sd, 1, player) end)
    pcall(function() log.info(string.format("[IrisTaming] drop begin: put3=%s sd=%s have=%s", tostring(ok3), tostring(sd_why), tostring(before))) end)
    return { id = id, seen = seen, before = before, t0 = os.clock(), until_t = os.clock() + 1.5,
        x = pp.x, y = pp.y, z = pp.z }
end

local function drop_item_check(player, w)
    -- poll the waiter: "pending" until the drop appears / the stack shrinks / the window closes.
    -- Returns "ok", drop | "consumed" (meal happened, no visible entry) | "fail" | "pending".
    local mgr = item_mgr()
    if not (mgr and w) then return "fail" end
    local drop = find_new_drop(mgr, player, w.seen)
    local after = nil
    pcall(function() after = tonumber(mgr:call("getHaveNum(System.Int32, app.Character)", w.id, player)) end)
    local dec = (w.before and after and after < w.before) == true
    if drop then
        if not dec then consume_item(player, w.id) end   -- spawned without decrementing: take the cloned one
        S.drop_dbg = string.format("drop FOUND after %.2fs (have %s->%s)", os.clock() - (w.t0 or 0), tostring(w.before), tostring(after))
        pcall(function() log.info("[IrisTaming] drop: " .. S.drop_dbg) end)
        return "ok", drop
    end
    if os.clock() > (tonumber(w.until_t) or 0.0) then
        S.drop_dbg = string.format("no drop entry after %.1fs (have %s->%s)", os.clock() - (w.t0 or 0), tostring(w.before), tostring(after))
        pcall(function() log.info("[IrisTaming] drop: " .. S.drop_dbg) end)
        if dec then return "consumed" end   -- the meal left the bag: feed anyway (despawn skipped)
        return "fail"
    end
    return "pending"
end

local function norm_u32(v)
    -- wwise ids are UNSIGNED 32-bit; a signed widget wraps big ids negative -- unwrap them
    v = math.floor(tonumber(v) or 0)
    if v < 0 then v = v + 4294967296 end
    return v
end

local function play_player_wwise(player, id)
    -- fire a wwise trigger id on the player's own sound container (the ride mod's proven caller)
    id = norm_u32(id)
    if id <= 0 then return false end
    local wc = nil
    pcall(function() wc = player:get_field("<WwiseContainer>k__BackingField") end)
    if not wc then pcall(function() wc = player:call("get_WwiseContainer") end) end
    local pgo2 = char_go(player)
    if not (wc and pgo2) then return false end
    local ok = false
    pcall(function() ok = wc:call("triggerLogLess(System.UInt32, via.GameObject, via.GameObject)", id, pgo2, pgo2) == true end)
    return ok
end

local function head_look_at(pgo2, pp2, tx, ty, tz, on)
    -- aim the player's HEAD at a world point during the falconry clips: a dynamic additive trim
    -- on Head_0 riding the anim lab's playback (same channel as the arm re-angle). Manual
    -- head-trim sliders stack ON TOP so the aim can be corrected by hand; auto-aim can be
    -- switched off entirely, leaving the sliders as the whole pose.
    if not (_G.NB_Pose and _G.NB_Pose.set_trim) then return end
    if not on then _G.NB_Pose.set_trim("Head_0", 0, 0, 0); return end
    pcall(function()
        local ax, ay = 0.0, 0.0
        if C.head_auto_aim ~= false then
            local prot = pgo2:call("get_Transform"):call("get_Rotation")
            local fx = 2.0 * (prot.x * prot.z + prot.w * prot.y)
            local fz = 1.0 - 2.0 * (prot.x * prot.x + prot.y * prot.y)
            local pyaw = math.atan(fx, fz)
            local dx, dz = tx - pp2.x, tz - pp2.z
            local byaw = math.atan(dx, dz)
            local dyaw = byaw - pyaw
            while dyaw > math.pi do dyaw = dyaw - 2.0 * math.pi end
            while dyaw < -math.pi do dyaw = dyaw + 2.0 * math.pi end
            dyaw = math.max(-1.1, math.min(1.1, dyaw))
            local dh = math.max(0.3, math.sqrt(dx * dx + dz * dz))
            local pitch = math.max(-0.7, math.min(0.7, math.atan((ty - (pp2.y + 1.55)), dh)))
            -- ZXY local euler: X ~ pitch (down = positive, sign empirical), Y ~ yaw
            ax, ay = -pitch, dyaw
        end
        _G.NB_Pose.set_trim("Head_0",
            ax + (tonumber(C.head_trim_x) or 0),
            ay + (tonumber(C.head_trim_y) or 0),
            tonumber(C.head_trim_z) or 0)
    end)
end

local function push_arm_trim()
    -- push the live falconry-arm re-angle into the anim lab's playback
    pcall(function()
        if _G.NB_Pose and _G.NB_Pose.set_trim then
            _G.NB_Pose.set_trim(tostring(C.arm_trim_bone or "L_Arm_Upper"),
                tonumber(C.arm_trim_x) or 0, tonumber(C.arm_trim_y) or 0, tonumber(C.arm_trim_z) or 0)
        end
    end)
end

local function puppet_step(go2, gp2, tx, tz, speed, dtv, stop_d)
    -- one incremental step of a think-stopped body toward a point (FSM off: no root motion to
    -- fight), facing the travel direction. Returns the remaining distance. stop_d keeps a big
    -- body from bulldozing INTO the target (its collision shoves the player = the push loop).
    local dx, dz = tx - gp2.x, tz - gp2.z
    local dd = math.sqrt(dx * dx + dz * dz)
    if dd <= (tonumber(stop_d) or 0.05) then return dd end
    pcall(function()
        local step = math.min((tonumber(speed) or 2.0) * dtv, dd)
        local pv = ValueType.new(sdk.find_type_definition("via.Position"))
        pv.x = gp2.x + dx / dd * step; pv.y = gp2.y; pv.z = gp2.z + dz / dd * step
        set_upos(go2, pv)
        local fyaw = math.atan(dx, dz)
        local q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
        q.x = 0; q.y = math.sin(fyaw / 2.0); q.z = 0; q.w = math.cos(fyaw / 2.0)
        go2:call("get_Transform"):call("set_Rotation", q)
    end)
    return dd
end

local function player_sitting(player)
    -- is the player seated (camp stool / bench)? Read the live action node name (the same surface
    -- the action probes read). Returns sitting, node_name (the name gets logged, so an unmatched
    -- stool node can be added to the match list from the log).
    local nodename = ""
    pcall(function()
        local am = player:get_field("<ActionManager>k__BackingField")
        if not am then am = player:call("get_ActionManager") end
        local list = am and am:get_field("CurrentActionList")
        local n0 = list and list[0]
        if n0 then nodename = tostring(n0:get_field("Name")) end
    end)
    local l = nodename:lower()
    local sit = (l:find("chair", 1, true) ~= nil) or (l:find("sit", 1, true) ~= nil)
        or (l:find("stool", 1, true) ~= nil) or (l:find("bench", 1, true) ~= nil)
    return sit, nodename
end

-- ============================ the VISIBLE offering (display-prop recipe) ============================
-- putItem ground-drops proved a silent no-op, so the offering is a DISPLAY PROP: consume the meat
-- from the bag (deleteItem, proven) + spawn the verified food-spread mesh at the spot; despawn it
-- when eaten. All engine work runs on the UpdateBehavior game thread (the thread law); position
-- uses LOCAL coords (set_Position speaks region-local; universal coords land it kilometers off).
local PROP = { warmed = false, q = {}, seq = 0, cur = nil, warm_refs = {} }

local function feed_prop_spawn(lx, ly, lz, base)
    PROP.q[#PROP.q + 1] = { op = "spawn", x = lx, y = ly, z = lz, base = base }
end

local function feed_prop_clear()
    PROP.q[#PROP.q + 1] = { op = "clear" }
end

-- ===== SPECIES CLIP MAP (atlas-verified 2026-07-12): per-band eat/fly overrides; the crow's
-- config globals stay the fallback. ⛔ bird ch299430's 60:20 is its SLEEP start (the crow's eat
-- id!) -- feeding a bird on crow globals would put it to sleep mid-meal. The BAT ch299400 has
-- no 5100 flight at all (it HOVERS at 5000/5140) and no walk bank.
local SPECIES_CLIPS = {
    ch299410 = { eat_bank = 60, eat_start = 20, eat_loop = 20, bathe = { 0, 10 }, perch_cycle = "0" },   -- crow: folded-wing shoulder idle
    ch299430 = { eat_bank = 60, eat_start = 0, eat_loop = 1, bathe = { 10, 11 }, perch_cycle = "0",      -- bird: compact shoulder idle; 60:20 = SLEEP
        -- 08-05 (Aurora: fly-in jitter + the crotch sag): the bird's 5100 flight_loop drags
        -- baked root motion the crow's doesn't -- puppet flights ride the ARC for movement,
        -- so the in-place vertical flap is the right clip (atlas-verified 0:415)
