local function species_clips(go)
    -- THE HOUSECAT wears the rabbit band (ch299200 chassis) but owns a W3 profile:
    -- the body match beats the band match. Gated on the FULL catalogue actually
    -- being attached this session -- an unregistered bank (or the 3-take bisect,
    -- which lacks ids 8..14) is never asked for clips it does not have.
    if go and S.housecat_go_addr and S.housecat_bank_key
        and S.housecat_gait_at and os.clock() >= S.housecat_gait_at
        and tostring(S.housecat_bank_path or ""):find("full", 1, true) then
        local a = nil
        pcall(function() a = go:get_address() end)
        if a == S.housecat_go_addr then return HC.species end
    end
    local band = tostring(go and go_name(go) or ""):match("ch%d+") or ""
    local t = SPECIES_CLIPS[band]
    if t and t.arm_hover then
        t.arm_dy = tonumber(C.bat_arm_dy) or 0.0   -- glove-hover aim height (slider)
    end
    return t
end

-- ⭐⭐ 08-18 THE STICK-CLICK PROMPT ROWS (Aurora). GLOBAL on purpose: the HUD that draws these
-- sits ~3k lines ABOVE species_clips/name_in_csv, and a local used above its declaration is a
-- nil global -- which fails silently inside the HUD's pcall. Declared here, below both.
-- Returns plaque rows, or nil when there is nothing to offer.
function iris_perch_prompt_rows()
    local pl8 = get_player()
    local pp8 = pl8 and upos(char_go(pl8))
    for ch8, rec8 in pairs(S.tamed or {}) do
        local go8 = char_go(ch8)
        -- ⛔ a downed companion is offered nothing: you cannot shoulder a body downed.lua owns
        if go8 and not iris_body_downed(go8) and name_in_csv(go_name(go8), C.critter_bands) then
            local sp8 = species_clips(go8) or {}
            local scoutable8 = name_in_csv(go_name(go8), C.bird_bands) or sp8.ground == true
            if rec8.perch then
                local r8 = { { label = "Let Down", pad = "L3", key = "G" } }
                if scoutable8 then r8[#r8 + 1] = { label = "Scout", pad = "R3", key = "J" } end
                return r8
            end
            -- Offered only inside the SAME reach the L3 handler itself uses (2.5m), so the
            -- prompt can never advertise a shoulder that the button would then refuse. A
            -- prompt that lies about what a press will do is worse than no prompt.
            local cp8 = upos(go8)
            if cp8 and pp8 and dist(cp8, pp8) <= 2.5 then
                return { { label = "Shoulder", pad = "L3", key = "G" } }
            end
        end
    end
    return nil
end

local function species_idle_clip(go)
    local se = species_clips(go)
    return (se and se.idle) or 0
end

local function scout_find_gm82(brp, range)
    -- world-PLACED pickups: the forensics dump named them (images 45/46 -- the Rotten Apple's
    -- GO is "gm82_000_02" carrying app.Gm82_000_01 + app.ItemFallController). The 4th loot
    -- container. Type-swept first; if that query is blind to them (the corpse law), fall back
    -- to the PROVEN mesh sweep matching gm82-named GOs and pulling the component off each GO.
    local best, bd = nil, range
    pcall(function()
        local sm9 = sdk.get_native_singleton("via.SceneManager")
        local smt9 = sdk.find_type_definition("via.SceneManager")
        local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
        if not scene9 then return end
        local comps9 = nil
        pcall(function() comps9 = scene9:call("findComponents(System.Type)", sdk.typeof("app.Gm82_000_01")) end)
        local n9 = 0
        pcall(function() n9 = comps9:call("get_Length") or 0 end)
        if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
        if (tonumber(n9) or 0) > 0 then
            for i9 = 0, (tonumber(n9) or 0) - 1 do
                pcall(function()
                    local g9 = comps9:call("get_Item", i9) or comps9[i9]
                    local go9 = g9 and g9:call("get_GameObject")
                    local rp9 = go9 and render_pos(go9)
                    if rp9 then
                        local d9 = planar_dist(rp9, brp)
                        if d9 < bd then bd = d9; best = g9 end
                    end
                end)
            end
            return
        end
        -- fallback: mesh sweep, gm82-named GOs
        local mm9 = scene9:call("findComponents(System.Type)", sdk.typeof("via.render.Mesh"))
        local mn9 = 0
        pcall(function() mn9 = mm9:call("get_Length") or 0 end)
        if mn9 == 0 then pcall(function() mn9 = mm9:get_size() or 0 end) end
        for i9 = 0, (tonumber(mn9) or 0) - 1 do
            pcall(function()
                local mc9 = mm9:call("get_Item", i9) or mm9[i9]
                local go9 = mc9 and mc9:call("get_GameObject")
                if not go9 then return end
                if not tostring(go_name(go9)):lower():find("gm82", 1, true) then return end
                local g9 = comp(go9, "app.Gm82_000_01")
                local rp9 = g9 and render_pos(go9)
                if rp9 then
                    local d9 = planar_dist(rp9, brp)
                    if d9 < bd then bd = d9; best = g9 end
                end
            end)
        end
    end)
    return best
end

local function scout_pickup_probe(brp)
    -- DIAG v2 (images 45/46): a world-PLACED "Pick Up" item (the Rotten Apple) is invisible to
    -- all three loot sweeps. v1 swept via.Transform and returned hits=null -- silently nothing.
    -- v2 = the PROVEN via.render.Mesh sweep (the meat-prop dump recipe): a placed pickup
    -- visibly renders, so its GO is reachable through its mesh; the component walk then lets
    -- the real pickup controller NAME ITSELF. Diagnostics recorded so no failure can hide.
    local out = { time = os.date("%Y-%m-%d %H:%M:%S"), meshes = 0, gos_near = 0,
        walk_ok = 0, walk_fail = 0, all_near = {}, hits = {} }
    local okE, errE = pcall(function()
        local sm9 = sdk.get_native_singleton("via.SceneManager")
        local smt9 = sdk.find_type_definition("via.SceneManager")
        local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
        local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("via.render.Mesh"))
        local n9 = 0
        pcall(function() n9 = comps9:call("get_Length") or 0 end)
        if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
        out.meshes = tonumber(n9) or 0
        local seen9 = {}
        for i9 = 0, (tonumber(n9) or 0) - 1 do
            pcall(function()
                local mc9 = comps9:call("get_Item", i9) or comps9[i9]
                local go9 = mc9 and mc9:call("get_GameObject")
                if not go9 then return end
                local ga9 = go9:get_address()
                if seen9[ga9] then return end
                seen9[ga9] = true
                local rp9 = go9:call("get_Transform"):call("get_Position")
                if not rp9 then return end
                local dx9, dy9, dz9 = rp9.x - brp.x, rp9.y - brp.y, rp9.z - brp.z
                local dd9 = math.sqrt(dx9 * dx9 + dy9 * dy9 + dz9 * dz9)
                if dd9 > 8.0 then return end
                out.gos_near = out.gos_near + 1
                local nm9 = tostring(go_name(go9))
                if #out.all_near < 100 then
                    out.all_near[#out.all_near + 1] = { d = tonumber(string.format("%.2f", dd9)), go = nm9 }
                end
                local types9, interesting9 = {}, false
                local wok9 = pcall(function()
                    local cl9 = go9:call("get_Components")
                    local m9 = 0
                    pcall(function() m9 = cl9:call("get_Length") or 0 end)
                    if m9 == 0 then pcall(function() m9 = cl9:get_size() or 0 end) end
                    for j9 = 0, (tonumber(m9) or 0) - 1 do
                        pcall(function()
                            local cx9 = cl9:call("get_Item", j9) or cl9[j9]
                            local tn9 = cx9 and cx9:get_type_definition():get_full_name()
                            if tn9 then
                                types9[#types9 + 1] = tn9
                                local tl9 = tn9:lower()
                                if tl9:find("interact", 1, true) or tl9:find("dropitem", 1, true)
                                    or tl9:find("getitem", 1, true) or tl9:find("pickup", 1, true)
                                    or tl9:find("gimmick", 1, true) then interesting9 = true end
                            end
                        end)
                    end
                end)
                if wok9 and #types9 > 0 then out.walk_ok = out.walk_ok + 1 else out.walk_fail = out.walk_fail + 1 end
                if interesting9 or nm9:lower():find("gm8", 1, true) or nm9:lower():find("item", 1, true) then
                    out.hits[#out.hits + 1] = { d = tonumber(string.format("%.2f", dd9)), go = nm9, components = types9 }
                end
            end)
        end
    end)
    if not okE then out.err = tostring(errE) end
    table.sort(out.hits, function(a, b) return (a.d or 99) < (b.d or 99) end)
    pcall(function() json.dump_file("IrisTaming_pickup_probe.json", out) end)
    return #out.hits
end

local function scout_collect()
    -- the bird pecks the nearest collectible. Ground drops we grab OURSELVES (destroy the world
    -- item, pouch the id) for true deferral; gather/corpse loot the engine grants on contact (we
    -- can't safely claw it back without dupe risk) and we log it for the return summary.
    local player = get_player()
    local b = _G.IrisGriffinBridge
    local bch = b and b.griffin and b.griffin()
    local bgo = bch and char_go(bch)
    if not (player and bgo) then return end
    local brp = render_pos(bgo)
    if not brp then return end
    local range = tonumber(C.scout_loot_range) or 6.0
    S.scout_pouch = S.scout_pouch or { items = {}, gathered = 0, looted = 0 }
    -- speak about the creature ACTUALLY scouting ("your crow" over a rabbit -- Aurora)
    local lbl = "companion"
    pcall(function() lbl = tostring(creature_label(bgo) or "companion"):lower() end)
    local verb = (species_clips(bgo) or {}).ground and "FORAGE" or "PECK"
    -- land + peck for a beat (the drive descends + plays the scavenge clip while this holds)
    local function peck()
        pcall(function() local bb = _G.IrisGriffinBridge
            if bb and bb.scout_peck then
                local se = species_clips(bgo)
                bb.scout_peck(1.3, (se and se.eat_bank) or tonumber(C.crow_scavenge_bank) or 60,
                    (se and se.eat_loop) or tonumber(C.crow_scavenge_clip) or 20)
            end end)
    end

    -- 1) GROUND DROP (safe, deferred): read it, destroy the world GO, pouch the id
    local dr, id, count, name = scout_find_drop(brp, range)
    if dr and id then
        pcall(function() local dgo = dr:call("get_GameObject"); if dgo then dgo:call("destroy", dgo) end end)
        S.scout_pouch.items[#S.scout_pouch.items + 1] = { id = id, count = count or 1, name = name or "item" }
        peck()
        set_prompt(verb, "Your " .. lbl .. " takes the " .. tostring(name or "item") .. ".", 1.6, 0xFF80FFB0)
        return
    end
    -- 2) GATHER gimmick: the item is rolled inside the native interact. With the defer probe on,
    -- a short intercept window opens first -- the getItem hook pouches the grant mid-flight and
    -- the crow carries it home. Probe off (or the grant slips past the hook) = instant, as before.
    local g = scout_find_gimmick(brp, range)
    if g then
        if C.scout_defer_gathers ~= false then S.scout_loot_window = os.clock() + 1.5 end
        local did = false
        pcall(function() g:call("onExecuteInteractBase", 0, player); did = true end)
        if not did then pcall(function() g:call("requestForceInteract", 0, player); did = true end) end
        if did then
            S.scout_pouch.gathered = (S.scout_pouch.gathered or 0) + 1
            peck()
            set_prompt(verb, "Your " .. lbl .. " gathers from the bush.", 1.6, 0xFF80FFB0)
        end
        return
    end
    -- 2.5) WORLD-PLACED pickup (gm82: the Rotten Apple class of loot). Same treatment as a
    -- gather: interact natively, the defer window pouches whatever the engine grants
    local pk = scout_find_gm82(brp, range)
    if pk then
        if C.scout_defer_gathers ~= false then S.scout_loot_window = os.clock() + 1.5 end
        local did = false
        pcall(function() pk:call("onExecuteInteractBase", 0, player); did = true end)
        if not did then pcall(function() pk:call("requestForceInteract", 0, player); did = true end) end
        if did then
            S.scout_pouch.gathered = (S.scout_pouch.gathered or 0) + 1
            peck()
            set_prompt(verb, "Your " .. lbl .. " takes what someone left behind.", 1.6, 0xFF80FFB0)
        end
        return
    end
    -- 3) CORPSE (the gated probe; the same defer window covers its grants)
    if C.scout_loot_corpses == true then
        local ctrl = scout_find_corpse(brp, range)
        if ctrl then
            if C.scout_defer_gathers ~= false then S.scout_loot_window = os.clock() + 1.5 end
            local did = false
            pcall(function() ctrl:call("executeInteract(System.UInt32, app.Character)", 0, player); did = true end)
            if did then
                S.scout_pouch.looted = (S.scout_pouch.looted or 0) + 1
                peck()
                set_prompt(verb, "Your " .. lbl .. " picks at the carrion.", 1.6, 0xFF80FFB0)
            end
            return
        end
    end
    -- nothing our sweeps can see -- run the forensics dump so a missed pickup type (the
    -- placed Rotten Apple) identifies its controller for the next sweep to learn
    local nh = 0
    pcall(function() nh = scout_pickup_probe(brp) end)
    set_prompt("NOTHING HERE", string.format("Get closer to something worth taking. (probe: %d interactives -> json)", nh), 1.6, 0xFF80D0FF)
end

local function scout_deposit()
    -- on return: grant the DEFERRED ground-drop items to the player (native popup), then a
    -- one-line haul summary of everything the crow brought back.
    S.scout_loot_window = nil   -- FIRST: the intercept hook must never eat our own re-grants
    local pouch = S.scout_pouch
    S.scout_pouch = nil
    if not pouch then return end
    local player = get_player()
    local names = {}
    if player then
        for _, it in ipairs(pouch.items or {}) do
            pcall(function() give_item(player, it.id, it.count or 1, true) end)
            names[#names + 1] = (it.count and it.count > 1) and (tostring(it.name) .. " x" .. it.count) or tostring(it.name)
        end
    end
    local extra = {}
    if (pouch.gathered or 0) > 0 then extra[#extra + 1] = pouch.gathered .. " gathered" end
    if (pouch.looted or 0) > 0 then extra[#extra + 1] = pouch.looted .. " looted" end
    local haul = table.concat(names, ", ")
    if #extra > 0 then haul = (haul ~= "" and (haul .. "  (") or "(") .. table.concat(extra, ", ") .. ")" end
    if haul ~= "" then set_prompt("THE CROW'S HAUL", haul, 5.0, 0xFF80FFB0) end
end

-- ===== DEFERRED GATHER (probe): a gather/corpse interact rolls its item INSIDE the native call
-- and grants it straight to the bag ("instant loot" -- Aurora-observed). We can't pre-know the
-- roll, so instead: scout_collect opens a short intercept window around the peck, and this hook
-- on app.ItemManager.getItem catches the grant mid-flight -- pouches the (id, count) and SKIPs
-- the native call. The crow truly CARRIES the loot; scout_deposit re-grants it (with the native
-- popup) on return. Gated hard: the window only ever opens while a scout is live, and only the
-- ARISEN's grants are taken (a pawn's own pickup passes through untouched).
local function item_name_from_id(id)
    local name = "an item"
    pcall(function()
        local mgr = item_mgr()
        local p = nil
        pcall(function() p = mgr and mgr:call("getItemParam(System.Int32)", math.floor(id)) end)
        if not p then pcall(function() p = mgr and mgr:call("getItemData(System.Int32)", math.floor(id)) end) end
        if p then local n = tostring(p:call("get_Name") or ""); if n ~= "" then name = n end end
    end)
    return name
end

pcall(function()
    local m = sdk.find_type_definition("app.ItemManager"):get_method(
        "getItem(System.Int32, System.Int32, app.Character, System.Boolean, System.Boolean, System.Boolean, app.ItemManager.GetItemEventType, System.Boolean, System.Boolean)")
    if not m then return end
    sdk.hook(m, function(args)
        if not S.scout_loot_window then return end   -- near-zero cost when no window is open
        local intercept = false
        pcall(function()
            if os.clock() >= (tonumber(S.scout_loot_window) or 0.0) then S.scout_loot_window = nil; return end
            if not (S.scout and S.scout.phase == "scouting") then return end
            local player = get_player()
            local chara = sdk.to_managed_object(args[5])
            if not (player and chara) then return end
            local pa, ca = nil, nil
            pcall(function() pa = player:get_address() end)
            pcall(function() ca = chara:get_address() end)
            if not (pa and ca and pa == ca) then return end
            local id = sdk.to_int64(args[3]) & 0xFFFFFFFF
            local num = sdk.to_int64(args[4]) & 0xFFFFFFFF
            if num < 1 then num = 1 end
            S.scout_pouch = S.scout_pouch or { items = {}, gathered = 0, looted = 0 }
            S.scout_pouch.items[#S.scout_pouch.items + 1] = { id = id, count = num, name = item_name_from_id(id) }
            intercept = true
            pcall(function() log.info(string.format("[IrisTaming] scout pouched getItem id=%d x%d (deferred)", id, num)) end)
        end)
        if intercept then return sdk.PreHookResult.SKIP_ORIGINAL end
    end, function(rv) return rv end)
end)

local function scout_caw_stages(base)
    -- one X press mid-scout = a 3-WAY SOUND PROBE (~1.2s apart; Aurora counts the caws she
    -- hears): 1) the echo-ghost at the ARISEN, 2) the ghost warped to the BIRD, 3) the crow's
    -- own container. Both paths ring standing together but die when the bird flies far -- the
    -- stage that survives says where the engine's audio bubble actually lives. Ghost stages
    -- warp first, ring a beat later (a same-frame warp+fire rings at the OLD spot).
    if S.scout then
        return { { at = base, mode = "player" }, { at = base + 1.2, mode = "bird" }, { at = base + 2.4, mode = "crow" } }
    end
    return { { at = base, mode = "player" } }   -- the standing TEST button: one caw at your feet
end

-- ===== CROW VISION post-process: real vividness via the tonemap (the proven Weaponlord handle) =====
-- app.RenderingManager -> get__CachedToneMapping() -> a live, settable tonemap object. RE Engine's
-- DD2 build has no confirmed Saturation scalar, but Contrast + EV punch up perceived vibrance; we
-- try Saturation too in case the native type exposes it. Capture the ORIGINALS on entry, re-apply
-- the boost each frame (the controller re-blends), restore the captured values on exit.
local function iris_tonemap()
    local tm = nil
    pcall(function() local rm = sdk.get_managed_singleton("app.RenderingManager"); tm = rm and rm:call("get__CachedToneMapping") end)
    return tm
end

-- the tonemap levers to boost while flying (confirmed from the API dump). ALL offsets (op add):
-- these fields idle at 0.0 on this build, so a multiplier on the original was a silent no-op
-- (only EV -- the one shipped as an offset -- visibly moved). Only NUMBER fields are touched.
local SCOUT_TM = {
    { g = "get_EV",                s = "set_EV",                op = "add", cfg = "scout_vision_ev",      def = 0.25 },
    { g = "get_Contrast",          s = "set_Contrast",          op = "add", cfg = "scout_vg_contrast",    def = 0.25 },
    { g = "get_BoostLocalContrast",s = "set_BoostLocalContrast",op = "add", cfg = "scout_vg_clarity",     def = 0.5  },
    { g = "get_Highlights",        s = "set_Highlights",        op = "add", cfg = "scout_vg_highlights",  def = 0.0  },
    { g = "get_Shadows",           s = "set_Shadows",           op = "add", cfg = "scout_vg_shadows",     def = 0.0  },
}

local function scout_tm_rows()
    -- the applied grade = the built-in SCOUT_TM levers + Aurora's CUSTOM rows adopted from the
    -- Tonemap LAB ("Name=offset;..." in scout_vg_custom -- the self-serve path when the built-in
    -- fields turn out dead on this build). Custom rows apply ONLY during a scout, like the rest.
    local all = {}
    for _, e in ipairs(SCOUT_TM) do all[#all + 1] = e end
    local s = tostring(C.scout_vg_custom or "")
    local cc = S.tm_custom
    if not (cc and cc.str == s) then
        local rows = {}
        for name, off in s:gmatch("([%w_]+)=(%-?%d+%.?%d*)") do
            rows[#rows + 1] = { g = "get_" .. name, s = "set_" .. name, op = "add", fixed = tonumber(off) or 0.0 }
        end
        cc = { str = s, rows = rows }
        S.tm_custom = cc
    end
    for _, e in ipairs(cc.rows) do all[#all + 1] = e end
    return all
end

local function scout_vision_apply(on)
    if C.scout_vision == false then on = false end
    local tm = iris_tonemap()
    if not tm then return end
    local rows = scout_tm_rows()
    if on then
        if not S.tm_orig then
            S.tm_orig = {}
            for _, e in ipairs(rows) do
                pcall(function() local v = tm:call(e.g); if type(v) == "number" then S.tm_orig[e.g] = v end end)
            end
        end
        for _, e in ipairs(rows) do
            local o = S.tm_orig[e.g]
            if o ~= nil then
                local f = e.fixed or tonumber(C[e.cfg]) or e.def
                local nv = (e.op == "mul") and (o * f) or (o + f)
                pcall(function() tm:call(e.s, nv) end)
            end
        end
        S.tm_boosted = true
    elseif S.tm_boosted then
        for _, e in ipairs(rows) do
            local o = S.tm_orig and S.tm_orig[e.g]
            if o ~= nil then pcall(function() tm:call(e.s, o) end) end
        end
        S.tm_boosted = nil; S.tm_orig = nil
    end
end

-- ===== THE EARS (audio-lab find): soundlib.SoundListener rides the MainCamera, but its
-- `IsCalcDistanceDecayAtPlayerPos` computes volume falloff at the PLAYER -- so with the camera
-- on the bird, everything around the bird was 60m of decay away. Flip it false while piloting =
-- the ears truly fly with the bird; restore the captured original on every exit.
local function scout_sound_listener()
    if S.snd_listener ~= nil then return S.snd_listener or nil end   -- false = searched, none found
    local found = nil
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("soundlib.SoundListener"))
        local n = 0
        pcall(function() n = tonumber(comps:call("get_Length")) or 0 end)
        if n == 0 then pcall(function() n = tonumber(comps:get_size()) or 0 end) end
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local c2 = comps:call("get_Item", i) or comps[i]
                if c2 and not found then found = c2 end
            end)
        end
    end)
    S.snd_listener = found or false
    return found
end

local function scout_ears_apply()
    if C.scout_ears_at_bird == false then return end
    pcall(function()
        local sl = scout_sound_listener()
        if not sl then return end
        if S.snd_decay_orig == nil then
            S.snd_decay_orig = sl:call("get_IsCalcDistanceDecayAtPlayerPos") == true
            pcall(function() log.info("[IrisTaming] ears: decay-at-player was " .. tostring(S.snd_decay_orig)
                .. " -> false (the ears fly with the bird)") end)
        end
        sl:call("setCalcDistanceDecayAtPlayerPos", false)
    end)
end

local function scout_ears_restore()
    pcall(function()
        if S.snd_decay_orig == nil then return end
        local sl = S.snd_listener
        if sl then pcall(function() sl:call("setCalcDistanceDecayAtPlayerPos", S.snd_decay_orig == true) end) end
        S.snd_decay_orig = nil
    end)
end

local function scout_force_restore(reason)
    -- THE one canonical scout unwind: safe to call from ANY state, idempotent. Restores control
    -- FIRST (bridge un-suppress), then the camera, then re-arms the perch if the bird still lives.
    -- Every failsafe (panic, timeout, bird-lost, player-death) routes through here -- never a
    -- bespoke partial unwind, so a suppression latch can never be left stuck on.
    pcall(function() scout_vision_apply(false) end)   -- always restore the screen grade
    pcall(function() scout_ears_restore() end)        -- ...and the ears come home
    -- give the game's button panel its own labels back. The registry expires entries on a ~1s
    -- TTL anyway, but an explicit clear means the plaque snaps back on the frame control returns
    -- rather than advertising "Dive-steal" at an Arisen holding a sword.
    pcall(function()
        local P8 = rawget(_G, "IrisPrompt")
        if P8 and P8.clear_slot then P8.clear_slot("iris_scout") end
    end)
    pcall(function() scout_deposit() end)   -- the crow keeps its haul even on an abort
    local sc = S.scout
    S.scout = nil   -- cleared FIRST: a malformed state can never abort the unwind before this
    -- scout_launch_prev is NOT nilled: a still-held launch button must not read as a fresh
    -- edge next tick (the rabbit's instant ground return relaunched forever -- Aurora's log)
    S.scout_ping_prev = nil; S.scout_heartbeat = nil
    S.scout_relaunch_at = os.clock() + 0.6
    -- the digging loop is CONTINUOUS (Aurora) -- no unwind may leave it playing; stop via
    -- BOTH containers (the trigger resolves from the PLAYER's banks, rings at the rabbit)
    if S.snd_burrow_was then
        S.snd_burrow_was = nil
        pcall(function()
            local g0 = sc and char_go(sc.ch)
            local lid = math.floor(tonumber(C.burrow_snd_loop) or 0)
            if lid <= 0 then return end
            local p0 = get_player()
            for _, bg0 in ipairs({ p0 and char_go(p0), g0 }) do
                local sc0 = bg0 and comp(bg0, "soundlib.SoundContainer")
                if sc0 then pcall(function() sc0:call("stopTriggered(System.UInt32, via.GameObject, System.UInt32)", lid, g0 or bg0, 1) end) end
            end
        end)
    end
    S.snd_hop_was = nil; S.snd_pouch_n = nil
    S.scout_pause_t0 = nil; S.scout_cam_suspended = nil; S.scout_loot_window = nil
    pcall(function() if S.cdonor and S.cdonor.go then S.cdonor.go:call("destroy", S.cdonor.go) end end)
    S.cdonor = nil; S.cdonor_want = nil   -- the caw echo-ghost dies with the scout
    -- restore CONTROL first (bridge un-suppress), then the camera -- these must always run
    pcall(function() local b = _G.IrisGriffinBridge; if b and b.scout_force_end then b.scout_force_end() end end)
    pcall(function()
        local cam = _G.IrisCreatureCam
        if cam then if cam.set_on then cam.set_on(false) end; if cam.clear_target then cam.clear_target() end end
    end)
    pcall(function()
        if sc and type(sc) == "table" and sc.ch then
            local rec = S.tamed[sc.ch]
            local go = char_go(sc.ch)
            if rec then
                rec.scouting = nil
                -- ⛔⛔⛔ 08-17 -- THE SECOND HALF OF THE DIVEBOMB CTD, and it lived in the UNWIND.
                -- "not is_dead" was the only test here, and a DOWNED bird passes it (alive at 1 HP
                -- -- the liveness law). So the abort that fires *because* the bird went down would
                -- then re-arm the shoulder pin on it: our per-frame pin writing a body that
                -- downed.lua holds in DmgDownLoop and re-asserts. Fatal, and on the very frame we
                -- were trying to make things safe. A downed bird gets NOTHING re-armed -- the tamed
                -- loop's downed gate holds it hands-off and re-arms the follow when it revives.
                if go and iris_body_downed(go) then
                    rec.perch = nil; rec.follow = nil; rec.fmode = nil
                    rec.perch_ground_scale = nil
                    rec.downed_hold = true
                    pcall(function() rawset(_G, "IrisTamingPerchScaleHold", nil) end)
                elseif go and not is_dead(sc.ch) then rec.perch = true; rec.follow = nil   -- the loop re-arms the pin
                else rec.follow = true; rec.perch = nil end
            end
        end
    end)
    if reason then pcall(function() log.info("[IrisTaming] scout restore: " .. tostring(reason)) end) end
    -- the reason rides on the prompt: if a scout ever ends when it shouldn't, the card says why
    set_prompt("SCOUT ENDED", "Control returns to you." .. (reason and (" (" .. tostring(reason) .. ")") or ""), 2.0, 0xFF80D0FF)
end

re.on_application_entry("LateUpdateBehavior", function()
    -- THE SHOULDER PIN, applied AFTER the skeleton is posed for the frame (the griffin talon
    -- lesson: a pin written in the early tick reads a stale root/joint and drifts). The main
    -- tick sets S.perch_active each frame; here we place the bird at its shoulder spot from the
    -- freshly finalised player root, so it never floats or lags during the walk cycle.
    pcall(function()
        local pa = S.perch_active
        -- ⭐ is the send-home run-off currently driving this body? (published by the theater in
-- GriffinRideProbe). Anything in this file that moves a companion must ask first -- two writers on
-- one body is the bug that has bitten three times tonight. Declared as a GLOBAL on purpose: the
-- follow branch that calls it sits ~11k lines below, where a local would resolve to a nil global.
function iris_sendhome_owns(go)
    if not go then return false end
    local a = rawget(_G, "IrisSendHomeGoAddr")
    if not a then return false end
    local ga = nil
    pcall(function() ga = tostring(go:get_address()) end)
    return ga ~= nil and tostring(a) == ga
end

-- ⭐⭐ PUBLISH THE PERCH (08-13). A shoulder-riding critter is pinned to the player's
        -- shoulder joint every frame from here, so ANY other system that writes that body's position
        -- is in an unwinnable fight with this pin. Aurora's rabbit proved it: the send-home run-off
        -- drove it while this pin held it, and it "appeared at my side, started running on the spot".
        -- S.perch_active is file-local, so there was no way for another module to know. Now there is.
        -- ⛔ GAMEOBJECT address (the address-class law: never compare this against a Character).
        rawset(_G, "IrisTamingPerchGoAddr", nil)
        if not pa or not pa.go then return end
        pcall(function() rawset(_G, "IrisTamingPerchGoAddr", tostring(pa.go:get_address())) end)
        local player = get_player()
        local pgo = player and char_go(player)
        if pgo then pin_crow_shoulder(pa.go, pgo) end
        -- 08-13 EOD, Quoth receipt: ground and shoulder do NOT share the same native
        -- scale environment. ScaleMediator is active on the grounded character and goes
        -- quiet when the perch disables its character systems; the stable easer's larger
        -- IV target then becomes visible. The contract is visual continuity, so L3-up
        -- captures the ground body's ACTUAL LocalScale and this late hook reasserts that
        -- exact value after every other writer. This is not a shoulder multiplier.
        -- ⭐ 08-17: ...and then the ONE global shoulder dial on top (C.perch_shrink). The captured
        -- ground scale is still the BASE -- this multiplies it -- so the slider means exactly
        -- "how much smaller than its ground self does it ride", nothing more.
        local hold = tonumber(pa.scale)
        if hold and hold > 0.05 and hold <= 3.0 then
            local s = hold * iris_perch_shrink()
            pa.go:call("get_Transform"):call("set_LocalScale", Vector3f.new(s, s, s))
        end
        -- ⛔ NO else-branch here on purpose. When the L3 ground capture MISSED there is no base to
        -- multiply, and re-reading the live LocalScale every frame to scale it would compound the
        -- dial to a dot within a second. That case belongs to the real scale owner: stable.lua's
        -- easer multiplies its own resolved target by iris_perch_shrink() at its choke point, so
        -- the dial works with or without a capture and only ever one writer owns the number.
    end)
    -- (08-08: the PALM/CALL posture block moved to PrepareRendering
    -- below -- Aurora: "the palm-out hand was shaking". Written here at
    -- LateUpdateBehavior it raced whatever re-posed the arm after us;
    -- PrepareRendering is the anim lab's proven last-word phase.)
end)

re.on_application_entry("PrepareRendering", function()
    pcall(function()
        -- ⭐ PALM/CALL/HOWL POSTURE (07-21 sliders; 08-08 moved to
        -- PrepareRendering = shake-free, + the HOWL context): pitch the
        -- reaching arm + head about the player's RIGHT axis. Values
        -- read LIVE so the sliders tune in real time.
        -- r2 (Aurora field test): HOWL takes PRIORITY -- during the
        -- Bellow a still-live palm/call phold won the old if-chain, so
        -- the sword arms stayed up THEN the arms-down fired on the
        -- stationary pose after. And only the RIGHT arm needs to drop.
        local ph = S.phold
        local hand_d, head_d, howl_ctx
        if os.clock() < (tonumber(S.howl_arm_until) or 0.0) then
            howl_ctx = true
            hand_d = tonumber(C.howl_hand_down) or 45.0
            head_d = tonumber(C.howl_head_up) or -8.0
        elseif ph and ph.pose
            and os.clock() < (tonumber(ph.until_t) or 0.0) then
            hand_d = (ph.pose == "call") and (tonumber(C.oxtame_call_hand_up) or 70.0) or (tonumber(C.oxtame_palm_hand_up) or 35.0)
            head_d = (ph.pose == "call") and (tonumber(C.oxtame_call_head_up) or 40.0) or (tonumber(C.oxtame_palm_head_up) or 15.0)
        else
            S.pose_base = nil   -- context over: forget the captured bases
            return
        end
        local player = get_player()
        local pgo = player and char_go(player)
        local ptf = pgo and pgo:call("get_Transform")
        if not ptf then return end
        local prot = ptf:call("get_Rotation")
        local fx = 2.0 * (prot.x * prot.z + prot.w * prot.y)
        local fz = 1.0 - 2.0 * (prot.x * prot.x + prot.y * prot.y)
        local fl = math.max(0.05, math.sqrt(fx * fx + fz * fz))
        local rx, rz = fz / fl, -fx / fl   -- the player's RIGHT axis (world, horizontal)
        local function pitch_joint(names, deg)
            deg = tonumber(deg) or 0.0
            if math.abs(deg) < 0.5 then return end
            local h = math.rad(deg) * 0.5
            local s = math.sin(h)
            local axq = { x = rx * s, y = 0.0, z = rz * s, w = math.cos(h) }
            for jn in tostring(names or ""):gmatch("[^,%s]+") do
                local done = false
                pcall(function()
                    local j = ptf:call("getJointByName", jn)
                    if not j then return end
                    -- r2 ANTI-SHAKE (Aurora: "still noticed a palm
                    -- shake"): composing off the joint's CURRENT
                    -- rotation ACCUMULATES on frames where the frozen
                    -- pose doesn't reset it -- offset-on-offset =
                    -- tremble/drift. Capture the joint's BASE local
                    -- rotation once per context and rebuild the SAME
                    -- absolute result every frame instead.
                    S.pose_base = S.pose_base or {}
                    local base = S.pose_base[jn]
                    if not base then
                        local bl = j:call("get_LocalRotation")
                        base = { x = bl.x, y = bl.y, z = bl.z, w = bl.w }
                        S.pose_base[jn] = base
                    end
                    local p = j:call("get_Parent")
                    local pq = p and p:call("get_Rotation")
                    -- world-space base = parent (rotation) * base local
                    local wb = base
                    if pq then
                        wb = {
                            x = pq.w * base.x + pq.x * base.w + pq.y * base.z - pq.z * base.y,
                            y = pq.w * base.y - pq.x * base.z + pq.y * base.w + pq.z * base.x,
                            z = pq.w * base.z + pq.x * base.y - pq.y * base.x + pq.z * base.w,
                            w = pq.w * base.w - pq.x * base.x - pq.y * base.y - pq.z * base.z,
                        }
                    end
                    local q = {
                        x = axq.w * wb.x + axq.x * wb.w + axq.y * wb.z - axq.z * wb.y,
                        y = axq.w * wb.y - axq.x * wb.z + axq.y * wb.w + axq.z * wb.x,
                        z = axq.w * wb.z + axq.x * wb.y - axq.y * wb.x + axq.z * wb.w,
                        w = axq.w * wb.w - axq.x * wb.x - axq.y * wb.y - axq.z * wb.z,
                    }
                    local lq = q
                    if pq then
                        local iq = { x = -pq.x, y = -pq.y, z = -pq.z, w = pq.w }
                        lq = {
                            x = iq.w * q.x + iq.x * q.w + iq.y * q.z - iq.z * q.y,
                            y = iq.w * q.y - iq.x * q.z + iq.y * q.w + iq.z * q.x,
                            z = iq.w * q.z + iq.x * q.y - iq.y * q.x + iq.z * q.w,
                            w = iq.w * q.w - iq.x * q.x - iq.y * q.y - iq.z * q.z,
                        }
                    end
                    local qv = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                    qv.x = lq.x; qv.y = lq.y; qv.z = lq.z; qv.w = lq.w
                    j:call("set_LocalRotation", qv)
                    done = true
                    if not S.pose_joint_logged then
                        S.pose_joint_logged = true
                        log.info("[OxTame] posture joint hit: " .. jn)
                    end
                end)
                if done then return end
            end
        end
        if howl_ctx then
            -- r2 (Aurora): ONLY the right arm needs to come down
            pitch_joint(C.howl_arm_joints_r or "R_Arm_Upper", hand_d)
            pitch_joint(C.oxtame_pose_head_joints or "Head,Neck_1,Neck_0", head_d)
            return
        end
        pitch_joint(C.oxtame_pose_arm_joints or "L_Arm_Upper,L_Arm_Clavicle,L_Arm_Lower", hand_d)
        pitch_joint(C.oxtame_pose_head_joints or "Head,Neck_1,Neck_0", head_d)
    end)
end)

re.on_application_entry("LateUpdateBehavior", function()
    pcall(function()
        -- ⭐ r14 THE WOLF PIN WRITE, LATE (the shoulder-pin / egg-hand-pin law): something
        -- in the stack still writes a companion's transform in the normal tick (the native
        -- rounds saw it as "teleporting down" even with the hold asserted). Writing the pin
        -- in the normal tick means whoever writes LAST wins the frame -- sometimes them,
        -- sometimes us = the launch. Here, after physics and every driver, our write is
        -- final. Armed each tick by the pin branch (S.wolf_pin_active).
        local wp0 = S.wolf_pin_active
        S.wolf_pin_active = nil
        if not (wp0 and wp0.go) then return end
        local p0 = get_player()
        local pg0 = p0 and char_go(p0)
        if not pg0 then return end
        local ptf0 = pg0:call("get_Transform")
        local pu0 = upos(pg0)
        local prp0 = ptf0:call("get_Position")
        local prot0 = ptf0:call("get_Rotation")
        local bx0, by0, bz0 = pu0.x, pu0.y + 1.05, pu0.z
        local j0 = ptf0:call("getJointByName", "Spine_2")
        local jp0 = j0 and j0:call("get_Position")
        if jp0 then
            bx0 = pu0.x + (jp0.x - prp0.x)
            by0 = pu0.y + (jp0.y - prp0.y)
            bz0 = pu0.z + (jp0.z - prp0.z)
        end
        local fx0 = 2.0 * (prot0.x * prot0.z + prot0.w * prot0.y)
        local fz0 = 1.0 - 2.0 * (prot0.x * prot0.x + prot0.y * prot0.y)
        local yaw0 = math.atan(fx0, fz0)
        local sy0, cy0 = math.sin(yaw0), math.cos(yaw0)
        local ox0 = tonumber(C.wolf_pin_x) or 0.0
        local oy0 = tonumber(C.wolf_pin_y) or 0.35
        local oz0 = tonumber(C.wolf_pin_z) or 0.15
        local pv0 = ValueType.new(sdk.find_type_definition("via.Position"))
        pv0.x = bx0 + cy0 * ox0 + sy0 * oz0
        pv0.y = by0 + oy0
        pv0.z = bz0 + (-sy0) * ox0 + cy0 * oz0
        set_upos(wp0.go, pv0)
        local ry0 = yaw0 + math.rad(tonumber(C.wolf_pin_rot) or 90.0)
        local qv0 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
        qv0.x = 0.0; qv0.y = math.sin(ry0 / 2.0); qv0.z = 0.0; qv0.w = math.cos(ry0 / 2.0)
        wp0.go:call("get_Transform"):call("set_Rotation", qv0)
        -- ⭐ OWNERSHIP PROBE (08-08): record what we JUST wrote, as late in the frame as it
        -- is possible to write it. The next tick compares this against what is actually
        -- there. This answers Aurora's question -- "why is the wolf treated so differently
        -- from the rabbit" -- with a number instead of a theory:
        --   drift LARGE  -> something else writes the root; the pin is being overruled.
        --   drift ~ZERO  -> the root is exactly where we put it, and the thrashing is the
        --                   MESH deforming (motion layer / ragdoll / physics bones), which
        --                   no amount of transform-ownership work could ever have fixed.
        S.wolf_pin_wrote = { x = pv0.x, y = pv0.y, z = pv0.z, t = os.clock() }
    end)
    pcall(function()
        -- THE CARRIED-PET TURN (Aurora: "head in one hand, butt in the other"): a world-yaw
        -- offset composed AFTER the native carry poses the body for this frame
        local cr = S.carry_rot_active
        S.carry_rot_active = nil   -- re-armed each tick by the carry branch
        if not (cr and cr.go) then return end
        local deg = tonumber(C.carry_pet_rot) or 90.0
        if deg == 0.0 then return end
        local tf = cr.go:call("get_Transform")
        local q0 = tf:call("get_Rotation")
        local h = math.rad(deg) * 0.5
        local qy = { x = 0.0, y = math.sin(h), z = 0.0, w = math.cos(h) }
        local q = {
            x = qy.w * q0.x + qy.x * q0.w + qy.y * q0.z - qy.z * q0.y,
            y = qy.w * q0.y - qy.x * q0.z + qy.y * q0.w + qy.z * q0.x,
            z = qy.w * q0.z + qy.x * q0.y - qy.y * q0.x + qy.z * q0.w,
            w = qy.w * q0.w - qy.x * q0.x - qy.y * q0.y - qy.z * q0.z,
        }
        local qv = ValueType.new(sdk.find_type_definition("via.Quaternion"))
        qv.x = q.x; qv.y = q.y; qv.z = q.z; qv.w = q.w
        tf:call("set_Rotation", qv)
        -- pull it IN toward the player (it floated out past the hands -- image 127)
        local pull = tonumber(C.carry_pet_pull) or 0.14
        if pull ~= 0.0 then
            local p9 = get_player()
            local pgo9 = p9 and char_go(p9)
            local pu9 = pgo9 and upos(pgo9)
            local bu9 = upos(cr.go)
            if pu9 and bu9 then
                local dx9, dz9 = pu9.x - bu9.x, pu9.z - bu9.z
                local dl9 = math.sqrt(dx9 * dx9 + dz9 * dz9)
                if dl9 > 0.05 then
                    local pv9 = ValueType.new(sdk.find_type_definition("via.Position"))
                    pv9.x = bu9.x + dx9 / dl9 * pull
                    pv9.y = bu9.y
                    pv9.z = bu9.z + dz9 / dl9 * pull
                    set_upos(cr.go, pv9)
                end
            end
        end
    end)
    pcall(function()
        -- THE EGG HOME PIN, applied LATE: physics shoves (mother landings) win against the
        -- early-tick anchor between frames -- writing after physics is how it truly stays put
        for _, B1 in ipairs(S.eggs or {}) do
            if B1.go and not B1.dead and not B1.pin_hold and not B1.was_carried
                and B1.nest_key and not B1.stolen and B1.home_pin and not B1.player_near then
                pcall(function()
                    local v1 = ValueType.new(sdk.find_type_definition("via.Position"))
                    v1.x = B1.home_pin.x; v1.y = B1.home_pin.y; v1.z = B1.home_pin.z
                    set_upos(B1.go, v1)
                end)
            end
        end
    end)
    pcall(function()
        -- THE EGG HAND PIN, applied LATE: the carry constraint writes the egg's transform in
        -- the normal tick -- writing after it is the only way our chest-cradle wins (the
        -- shoulder-pin lesson). Armed by the fragility watcher ONLY on a genuine carry.
        local B0 = nil
        for _, E0 in ipairs(S.eggs or {}) do
            if E0.pin_hold and E0.go and not E0.dead then B0 = E0; break end
        end
        if not B0 then return end
        local player = get_player()
        local pg0 = player and char_go(player)
        if not pg0 then return end
        local ptf0 = pg0:call("get_Transform")
        local prot0 = ptf0:call("get_Rotation")
        -- anchor at a POSED joint (post-pose in this late hook -- the shoulder-perch recipe):
        -- bending down, the "hyup" re-settle bounce, everything the hands do, the egg follows
        -- (root-anchored = frozen at chest height while she crouches -- image 61)
        local ax0, ay0, az0
        for j0 in tostring(C.egg_hold_joint or "L_Arm_Hand,R_Arm_Hand,Spine_2"):gmatch("[^,%s]+") do
            local jj0 = ptf0:call("getJointByName", j0)
            local jp0 = jj0 and jj0:call("get_Position")
            if jp0 then ax0, ay0, az0 = jp0.x, jp0.y, jp0.z; break end
        end
        if not ax0 then
            local pp0 = ptf0:call("get_Position")
            ax0, ay0, az0 = pp0.x, pp0.y + 1.0, pp0.z
        end
        local fx0 = 2.0 * (prot0.x * prot0.z + prot0.w * prot0.y)
        local fz0 = 1.0 - 2.0 * (prot0.x * prot0.x + prot0.y * prot0.y)
        local yaw0 = math.atan(fx0, fz0)
        local sy0, cy0 = math.sin(yaw0), math.cos(yaw0)
        local ox0 = tonumber(C.egg_hold_x) or -0.50
        local oy0 = tonumber(C.egg_hold_y) or 0.02
        local oz0 = tonumber(C.egg_hold_z) or -0.01
        local v0 = ValueType.new(sdk.find_type_definition("via.vec3"))
        v0.x = ax0 + cy0 * ox0 + sy0 * oz0
        v0.y = ay0 + oy0
        v0.z = az0 + (-sy0) * ox0 + cy0 * oz0
        local etf0 = B0.go:call("get_Transform")
        etf0:call("set_Position", v0)
        -- full attitude in the PLAYER's frame: yaw (tip direction), then pitch (nose up/down),
        -- then roll (lean across the forearms) -- so the sliders keep meaning while she turns
        local ry0 = yaw0 + math.rad(tonumber(C.egg_hold_rot) or 0.0)
        local qy0 = { x = 0.0, y = math.sin(ry0 / 2.0), z = 0.0, w = math.cos(ry0 / 2.0) }
        local hp0 = math.rad(tonumber(C.egg_hold_pitch) or 0.0) / 2.0
        local qp0 = { x = math.sin(hp0), y = 0.0, z = 0.0, w = math.cos(hp0) }
        local hr0 = math.rad(tonumber(C.egg_hold_roll) or 0.0) / 2.0
        local qr0 = { x = 0.0, y = 0.0, z = math.sin(hr0), w = math.cos(hr0) }
        local qf0 = qmul(qy0, qmul(qp0, qr0))
        local q0 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
        q0.x = qf0.x; q0.y = qf0.y; q0.z = qf0.z; q0.w = qf0.w
        etf0:call("set_Rotation", q0)
    end)
end)

re.on_application_entry("UpdateBehavior", function()
    pcall(function()
        if C.enabled ~= true then return end
        local base = tostring(C.feed_prop_mesh or "")
        if base == "" then return end
        if not PROP.warmed then
            -- WARM at load: cold resources bind nothing ("cold resources lie"); both tiers' props
            PROP.warm_at = PROP.warm_at or (os.clock() + 5.0)
            if os.clock() < PROP.warm_at then return end
            PROP.warmed = true
            pcall(function() PROP.warm_refs[1] = sdk.create_resource("via.render.MeshResource", base .. ".mesh"):add_ref() end)
            pcall(function() PROP.warm_refs[2] = sdk.create_resource("via.render.MeshMaterialResource", base .. ".mdf2"):add_ref() end)
            local cbase = tostring(C.critter_feed_prop or "")
            if cbase ~= "" and cbase ~= base then
                pcall(function() PROP.warm_refs[3] = sdk.create_resource("via.render.MeshResource", cbase .. ".mesh"):add_ref() end)
                pcall(function() PROP.warm_refs[4] = sdk.create_resource("via.render.MeshMaterialResource", cbase .. ".mdf2"):add_ref() end)
            end
            return
        end
        if #PROP.q == 0 then
            -- the offering must never outlive the yielded moment (auto-clean on every exit)
            if PROP.cur and S.mode ~= "yielded" then PROP.q[#PROP.q + 1] = { op = "clear" } end
            return
        end
        local op = table.remove(PROP.q, 1)
        if op.wait and os.clock() < op.wait then PROP.q[#PROP.q + 1] = op; return end
        if op.op == "clear" then
            if PROP.cur and PROP.cur.go then pcall(function() PROP.cur.go:call("destroy", PROP.cur.go) end) end
            PROP.cur = nil
        elseif op.op == "spawn" and op.phase2 then
            -- phase 2 (a frame later): HOLDER-bind the mesh + material (raw setMesh silently no-ops)
            local mc = op.mc
            local pbase = tostring(op.base or base)
            local res; pcall(function() res = sdk.create_resource("via.render.MeshResource", pbase .. ".mesh") end)
            if not res then return end
            pcall(function() res = res:add_ref() end)
            local holder; pcall(function() holder = res:create_holder("via.render.MeshResourceHolder"):add_ref() end)
            if holder then
                local okm = pcall(function() mc:call("setMesh", holder) end)
                if not okm then pcall(function() mc:call("set_Mesh", holder) end) end
            end
            pcall(function()
                local mt = sdk.create_resource("via.render.MeshMaterialResource", pbase .. ".mdf2")
                if mt then
                    mt = mt:add_ref()
                    local mh = mt:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                    local ok2 = pcall(function() mc:call("set_Material", mh) end)
                    if not ok2 then mc:call("setMaterial", mh) end
                end
            end)
            pcall(function() mc:call("set_Enabled", true) end)
            if PROP.cur then PROP.cur.res = res; PROP.cur.holder = holder end   -- hold refs (GC must not drop the bound mesh)
            if not op.again then   -- curative re-pass ~1.2s later (a cold first bind)
                PROP.q[#PROP.q + 1] = { op = "spawn", phase2 = true, mc = mc, base = op.base, again = true, wait = os.clock() + 1.2 }
            end
        elseif op.op == "spawn" then
            -- phase 1: empty carrier at LOCAL coords; the mesh binds next frame
            if PROP.cur and PROP.cur.go then pcall(function() PROP.cur.go:call("destroy", PROP.cur.go) end); PROP.cur = nil end
            PROP.seq = PROP.seq + 1
            local go2
            pcall(function()
                go2 = sdk.find_type_definition("via.GameObject"):get_method("create(System.String)")
                    :call(nil, "IrisTamingOffering_" .. tostring(PROP.seq))
            end)
            if not go2 then return end
            pcall(function() go2 = go2:add_ref() end)
            pcall(function() go2:call("set_DrawSelf", true) end)
            pcall(function() go2:call("set_UpdateSelf", true) end)
            local mc
            pcall(function() mc = go2:call("createComponent(System.Type)", sdk.typeof("via.render.Mesh")) end)
            if not mc then return end
            pcall(function()
                local v = ValueType.new(sdk.find_type_definition("via.vec3"))
                v.x = op.x; v.y = op.y; v.z = op.z
                go2:call("get_Transform"):call("set_Position", v)
            end)
            local sc = tonumber(C.feed_prop_scale) or 1.0
            if sc ~= 1.0 then
                pcall(function()
                    local sv = ValueType.new(sdk.find_type_definition("via.vec3"))
                    sv.x = sc; sv.y = sc; sv.z = sc
                    local t2 = go2:call("get_Transform")
                    local oks = pcall(function() t2:call("set_LocalScale", sv) end)
                    if not oks then t2:call("set_Scale", sv) end
                end)
            end
            PROP.cur = { go = go2, mc = mc }
            PROP.q[#PROP.q + 1] = { op = "spawn", phase2 = true, mc = mc, base = op.base }
        end
    end)
end)

-- ============== THE EGG LOAD TEST machine (custom IRIS-pak mesh; the offering-prop phases) ==============
local IRIS_EGG_BASE = "custom_tex/iris/griffin_egg"
re.on_application_entry("UpdateBehavior", function()
    pcall(function()
        local E = S.egg_test
        if not E or E.stage == "done" then return end
        local nowE = os.clock()
        if E.stage == "warm" then
            -- cold resources lie: create + hold them, give the streamer a beat
            local r1 = sdk.create_resource("via.render.MeshResource", IRIS_EGG_BASE .. ".mesh")
            if not r1 then
                E.msg = "MESH resource NIL -- the IRIS pak is not mounted (Fluffy install + FULL game restart)"
                E.stage = "done"; S.status = "egg test: " .. E.msg
                return
            end
            pcall(function() E.held[#E.held + 1] = r1:add_ref() end)
            pcall(function()
                local r2 = sdk.create_resource("via.render.MeshMaterialResource", IRIS_EGG_BASE .. ".mdf2")
                if r2 then E.held[#E.held + 1] = r2:add_ref() end
            end)
            E.msg = "resources resolved (pak is mounted!) -- warming..."
            E.stage = "spawn"; E.at = nowE + 2.0
        elseif E.stage == "spawn" and nowE >= (tonumber(E.at) or 0.0) then
            -- phase 1: EMPTY carrier at the player's feet (mesh binds NEXT frame, never same-frame)
            local player9 = get_player()
            local pgo9 = player9 and char_go(player9)
            if not pgo9 then E.msg = "no player"; E.stage = "done"; return end
            local go9
            pcall(function()
                go9 = sdk.find_type_definition("via.GameObject"):get_method("create(System.String)"):call(nil, "IrisTestEgg")
            end)
            if not go9 then E.msg = "GameObject create failed"; E.stage = "done"; S.status = "egg test: " .. E.msg; return end
            pcall(function() go9 = go9:add_ref() end)
            pcall(function() go9:call("set_DrawSelf", true) end)
            pcall(function() go9:call("set_UpdateSelf", true) end)
            local mc9
            pcall(function() mc9 = go9:call("createComponent(System.Type)", sdk.typeof("via.render.Mesh")) end)
            if not mc9 then E.msg = "Mesh component create failed"; E.stage = "done"; S.status = "egg test: " .. E.msg; return end
            pcall(function()
                local tfp9 = pgo9:call("get_Transform")
                local rp9 = tfp9:call("get_Position")
                local rot9 = tfp9:call("get_Rotation")
                local fx9 = 2.0 * (rot9.x * rot9.z + rot9.w * rot9.y)
                local fz9 = 1.0 - 2.0 * (rot9.x * rot9.x + rot9.y * rot9.y)
                local v9 = ValueType.new(sdk.find_type_definition("via.vec3"))
                v9.x = rp9.x + fx9 * 1.2; v9.y = rp9.y; v9.z = rp9.z + fz9 * 1.2
                go9:call("get_Transform"):call("set_Position", v9)
                local sc9 = tonumber(C.egg_scale) or 0.54
                local sv9 = ValueType.new(sdk.find_type_definition("via.vec3"))
                sv9.x = sc9; sv9.y = sc9; sv9.z = sc9
                local t2 = go9:call("get_Transform")
                if not pcall(function() t2:call("set_LocalScale", sv9) end) then pcall(function() t2:call("set_Scale", sv9) end) end
                -- orientation left AS-EXPORTED: it lands resting on its side, which reads
                -- naturally for a nest egg (Aurora vetoed the upright roll -- image 53 was right)
            end)
            E.go = go9; E.mc = mc9
            E.msg = "carrier up -- binding the mesh..."
            E.stage = "bind"; E.at = nowE   -- next tick
        elseif E.stage == "bind" and nowE > (tonumber(E.at) or 0.0) then
            local mc9 = E.mc
            pcall(function() mc9:call("set_Enabled", false) end)
            local res9; pcall(function() res9 = sdk.create_resource("via.render.MeshResource", IRIS_EGG_BASE .. ".mesh") end)
            if res9 then
                pcall(function() res9 = res9:add_ref(); E.held[#E.held + 1] = res9 end)
                pcall(function()
                    local hold9 = res9:create_holder("via.render.MeshResourceHolder"):add_ref()
                    E.held[#E.held + 1] = hold9
                    if not pcall(function() mc9:call("setMesh", hold9) end) then mc9:call("set_Mesh", hold9) end
                end)
            end
            pcall(function()
                local mt9 = sdk.create_resource("via.render.MeshMaterialResource", IRIS_EGG_BASE .. ".mdf2")
                if mt9 then
                    mt9 = mt9:add_ref(); E.held[#E.held + 1] = mt9
                    local mh9 = mt9:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                    E.held[#E.held + 1] = mh9
                    if not pcall(function() mc9:call("set_Material", mh9) end) then mc9:call("setMaterial", mh9) end
                end
            end)
            pcall(function() mc9:call("set_Enabled", true) end)
            E.msg = "bound -- curative re-pass..."
            E.stage = "cure"; E.at = nowE + 1.2
        elseif E.stage == "cure" and nowE >= (tonumber(E.at) or 0.0) then
            -- the offering machine's curative second bind (a cold first bind renders nothing)
            local mc9 = E.mc
            pcall(function()
                local res9 = sdk.create_resource("via.render.MeshResource", IRIS_EGG_BASE .. ".mesh"):add_ref()
                E.held[#E.held + 1] = res9
                local hold9 = res9:create_holder("via.render.MeshResourceHolder"):add_ref()
                E.held[#E.held + 1] = hold9
                if not pcall(function() mc9:call("setMesh", hold9) end) then mc9:call("set_Mesh", hold9) end
                local mt9 = sdk.create_resource("via.render.MeshMaterialResource", IRIS_EGG_BASE .. ".mdf2"):add_ref()
                E.held[#E.held + 1] = mt9
                local mh9 = mt9:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                E.held[#E.held + 1] = mh9
                if not pcall(function() mc9:call("set_Material", mh9) end) then mc9:call("setMaterial", mh9) end
                mc9:call("set_Enabled", true)
            end)
            local mn9 = "?"; pcall(function() mn9 = tostring(E.mc:call("get_MaterialNum")) end)
            E.msg = "DONE. MaterialNum=" .. mn9 .. " (>0 + a visible egg = the pipeline is complete)"
            S.status = "egg test: " .. E.msg
            E.stage = "done"
        end
    end)
end)

-- ============== per-egg machines (MULTI-EGG: S.eggs is a LIST -- clutches of 0-3 per nest) ==============
function iris_egg_dispose(E)
    -- ⛔ LYRA'S LAB LAW (RiftSpeakGimmickSpawnLab): go:destroy() on a GENERATED gimmick leaves
    -- its registration in the manager -- accumulate corpses and the engine faults on stream-in
    -- (Aurora's nest crash after a save reload). The clean end, always:
    -- GimmickManager:deleteCreatedObj(go) + InstanceInfo:release(). (GLOBAL: local-cap safety.)
    if not E then return end
    -- deleting an object OUT of someone's hands wedges ObjectCarry ("hands full" forever,
    -- no pickups ever after) -- release the carry FIRST
    pcall(function()
        if S.carried_egg == E then
            local oc9 = get_player():call("get_ObjectCarry")
            if oc9 and oc9:call("isPickupCarrying") then
                if not pcall(function() oc9:call("putObject") end) then pcall(function() oc9:call("dropObject") end) end
            end
            S.carried_egg = nil
        end
    end)
    pcall(function()
        local gm9 = sdk.get_managed_singleton("app.GimmickManager")
        if gm9 and E.go then gm9:call("deleteCreatedObj(via.GameObject)", E.go) end
    end)
    pcall(function() if E.inst then E.inst:release() end end)
    E.inst = nil
    E.go = nil
end

function iris_reap_eggs_near(cx, cy, cz, radius)
    -- delete ORPHANED egg BODIES (a gm80_009 wearing OUR griffin_egg mesh -- a normal world rock
    -- never does) so a script reset / streaming can't leave a duplicate. cx nil = sweep ALL streamed.
    -- ⛔ NEVER reaps a body we currently TRACK in S.eggs, so it's safe to call before any respawn.
    local reaped = 0
    pcall(function()
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("via.render.Mesh"))
        local n = 0
        pcall(function() n = comps:call("get_Length") or 0 end)
        if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
        local gm = sdk.get_managed_singleton("app.GimmickManager")
        local r2 = (tonumber(radius) or 2.5) ^ 2
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local mc = comps:call("get_Item", i) or comps[i]
                local res = mc and (mc:call("getMesh") or mc:call("get_Mesh"))
                local pth = nil
                pcall(function() pth = tostring(res:call("get_ResourcePath")) end)
                if not (pth and pth:find("griffin_egg", 1, true)) then return end
                local go = mc:call("get_GameObject")
                if not go then return end
                local ga = go:get_address()
                for _, E in ipairs(S.eggs or {}) do
                    if E.go and not E.dead and E.go:get_address() == ga then return end   -- tracked: keep
                end
                if cx then
                    local eu = upos(go)
                    if not eu then return end
                    local dx, dy, dz = eu.x - cx, eu.y - cy, eu.z - cz
                    if (dx * dx + dy * dy + dz * dz) > r2 then return end
                end
                if gm then pcall(function() gm:call("deleteCreatedObj(via.GameObject)", go) end) end
                pcall(function() go:call("destroy", go) end)
                reaped = reaped + 1
            end)
        end
    end)
    return reaped
end

-- PAWNS ARE NOT EGG-BEARERS: the chassis is a rock, and pawns throw rocks (Lyra hurled an
-- egg at its own mother). Pre-hook the native pickup: an IRIS egg is refused to any hands
-- but the PLAYER's. Hook hygiene (the pacifist scar): gated per call on the LIVE egg list --
-- with no eggs it matches nothing and changes nothing.
pcall(function()
    local td9 = sdk.find_type_definition("app.ObjectCarry")
    local m9 = td9 and (td9:get_method("pickupObject(via.GameObject)") or td9:get_method("pickupObject"))
    if not m9 then return end
    sdk.hook(m9, function(args)
        local skip9 = false
        pcall(function()
            if not (S.eggs and #S.eggs > 0) then return end
            -- ⛔ REFramework arg indexing is NOT consistent across methods in this engine (this
            -- file's ActionManager hook found this=args[2]; the TargetController hook uses
            -- args[2]=first param). So DON'T bet a fixed slot -- SCAN args[1..4] and, above all,
            -- NEVER block the player: if the player's OWN ObjectCarry appears in any slot, the
            -- player is the grabber -> ALLOW. Only a provable non-player + egg pair gets skipped.
            local poc_addr9 = nil
            pcall(function() poc_addr9 = get_player():call("get_ObjectCarry"):get_address() end)
            local egg_here9 = false
            local player_here9 = false
            for slot9 = 1, 4 do
                pcall(function()
                    local o9 = sdk.to_managed_object(args[slot9])
                    if not o9 then return end
                    local a9 = o9:get_address()
                    if poc_addr9 and a9 == poc_addr9 then player_here9 = true; return end
                    for _, E0 in ipairs(S.eggs) do
                        if E0.go and not E0.dead and E0.go:get_address() == a9 then egg_here9 = true; return end
                    end
                end)
            end
            -- FAIL OPEN: player present, or no egg found, or player-OC unreadable -> never skip
            if player_here9 or not egg_here9 or not poc_addr9 then return end
            skip9 = true
            S.status = "a pawn reached for the egg -- refused (eggs are not ammunition)"
        end)
        if skip9 then return sdk.PreHookResult.SKIP_ORIGINAL end
    end, nil)
end)

-- Is a WILD griffin near this render-space point? (Aurora 08-06: eggs must never be smashed
-- by the griffin unless the arisen is HOLDING them.) The taunt beacon's own enumeration +
-- family exclusions (companion bridge addr, S.tamed_addrs); 1s cached list, distance checked
-- per call. GLOBAL on purpose - this file has flirted with the 200-local chunk cap.
function iris_wild_g_near(px, py, pz)
    local nowG = os.clock()
    if nowG - (tonumber(S.gnear_at) or 0.0) > 1.0 then
        S.gnear_at = nowG
        S.gnear = {}
        pcall(function()
            local comp_addr9 = nil
            pcall(function()
                local B9 = _G.IrisGriffinBridge
                local g9 = B9 and B9.griffin and B9.griffin()
                if g9 then comp_addr9 = tostring(g9:get_address()) end
            end)
            local sm9 = sdk.get_native_singleton("via.SceneManager")
            local smt9 = sdk.find_type_definition("via.SceneManager")
            local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
            local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("app.Character"))
            local n9 = 0
            pcall(function() n9 = comps9:call("get_Length") or 0 end)
            if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
            for i9 = 0, (tonumber(n9) or 0) - 1 do
                pcall(function()
                    local ch9 = comps9:call("get_Item", i9) or comps9[i9]
                    local go9 = ch9 and char_go(ch9)
                    if not go9 or is_dead(ch9) then return end
                    if not tostring(go_name(go9)):find("ch253", 1, true) then return end
                    local a9 = tostring(ch9:get_address())
                    if comp_addr9 and a9 == comp_addr9 then return end
                    if S.tamed_addrs and S.tamed_addrs[a9] then return end
                    local gp9 = go9:call("get_Transform"):call("get_Position")
                    S.gnear[#S.gnear + 1] = { x = gp9.x, y = gp9.y, z = gp9.z }
                end)
            end
        end)
    end
    for _, g9 in ipairs(S.gnear or {}) do
        local dx9, dy9, dz9 = g9.x - px, g9.y - py, g9.z - pz
        if dx9 * dx9 + dy9 * dy9 + dz9 * dz9 < 144.0 then return true end
    end
    return false
end
local function iris_egg_watch(B0, held0)
    if not (B0.stage == "done" and B0.go and not B0.dead) then return end
            local nowW = os.clock()
