                    pcall(function() mn0 = tonumber((B0.mc or comp(B0.go, "via.render.Mesh")):call("get_MaterialNum")) or 1 end)
                    if mn0 <= 0 and (tonumber(B0.redress_n) or 0) < 10 then
                        B0.redress_n = (tonumber(B0.redress_n) or 0) + 1
                        pcall(function() sdk.create_resource("via.render.MeshResource", "custom_tex/iris/griffin_egg.mesh"):add_ref() end)
                        pcall(function() sdk.create_resource("via.render.MeshMaterialResource", "custom_tex/iris/griffin_egg.mdf2"):add_ref() end)
                        B0.cure_n = 0; B0.stage = "reskin"; B0.at = nowW
                        return   -- hand it back to the machine to re-dress
