                        local dx0, dy0, dz0 = p0.x - pp0.x, p0.y - pp0.y, p0.z - pp0.z
                        if (dx0 * dx0 + dy0 * dy0 + dz0 * dz0) < 1.44 then carried0 = true end
                    end)
                end
