                B0.wt = nowW
                local settling0 = B0.release_t and (nowW - B0.release_t) < 0.25
                if dt0 > 0.0 and dt0 < 0.5 and B0.lastp and not settling0 then
                    local vy0 = (p0.y - B0.lastp.y) / dt0
                    local vh0 = math.sqrt(((p0.x - B0.lastp.x) / dt0) ^ 2 + ((p0.z - B0.lastp.z) / dt0) ^ 2)
                    -- teleports/attach snaps are not physics: ignore absurd spikes wholesale
                    if math.abs(vy0) > 25.0 or vh0 > 25.0 then
                        B0.lastp = { x = p0.x, y = p0.y, z = p0.z }
