                    -- suddenly jolts was hit by something, and eggs lose that argument
                    if not broke then
                        local sp0 = math.sqrt(vh0 * vh0 + vy0 * vy0)
                        local was_still0 = (tonumber(B0.prev_speed) or 0.0) < 0.4
                        if was_still0 and sp0 > (tonumber(C.egg_hit_break) or 2.0) then
                            broke = true; S.status = "the egg was struck -- it breaks"
                        end
                        B0.prev_speed = sp0
                    end
                    -- STRUCK (the hit ledger): any watched damage field changed = a hit landed,
                    -- however gently the body moved -- break on the FIRST strike
                    if not broke and B0.dmg_watch and #B0.dmg_watch > 0 and nowW >= (tonumber(B0.dmg_at) or 0.0) then
                        B0.dmg_at = nowW + 0.15
                        for _, w9 in ipairs(B0.dmg_watch) do
                            local okv9, v9 = pcall(function() return w9.f:get_data(w9.c) end)
                            if okv9 and v9 ~= w9.v then
                                broke = true
                                S.status = "the egg was struck (" .. tostring(w9.n) .. ") -- it breaks"
                                break
                            end
                        end
                    end
                    if broke then
                        B0.dead = true
                        local bx0, by0, bz0 = p0.x, p0.y, p0.z
                        iris_egg_dispose(B0)
                        if not S.eggfx then S.eggfx = { stage = "spawn" } end
                        S.eggfx.want = { x = bx0, y = by0, z = bz0 }
                    end
                end
                if not B0.dead then B0.lastp = { x = p0.x, y = p0.y, z = p0.z } end
            end
end

local function iris_egg_machine(B)
        local nowB = os.clock()
        if B.stage == "prefab" then
            local chassis = tostring(C.egg_chassis or "gm80_009")
            local path = "AppSystem/gimmick/prefab/" .. chassis:lower() .. ".pfb"
            local gid = nil
            pcall(function()
                local td = sdk.find_type_definition("app.GimmickID")
                -- the enum spells it "Gm80_009" but the prefab path wants "gm80_009" --
                -- accept any casing and normalize
                local f = td and td:get_field(chassis)
                if not f and td then f = td:get_field("Gm" .. chassis:gsub("^[Gg][Mm]", "")) end
                if f then gid = f:get_data() end   -- NO-ARG (the CharacterID law)
            end)
            if gid == nil then B.msg = "GimmickID '" .. chassis .. "' unresolved (check spelling/case vs the enum)"; B.stage = "done"; S.status = "egg break: " .. B.msg; return end
            local okp = pcall(function()
                -- reuse the pre-warmed prefab+controller PAIR; else build one the baby's way
                local cache = S.egg_prefab_cache and S.egg_prefab_cache[chassis]
                if cache and cache.prefab and cache.ctrl then
                    B.prefab = cache.prefab; B.ctrl = cache.ctrl
                else
                    local prefab = sdk.create_instance("via.Prefab"):add_ref()
                    prefab:set_Path(path)
                    local ctrl = sdk.create_instance("app.PrefabController"):add_ref()
                    ctrl._Item = prefab
                    pcall(function() ctrl:get_Item():set_Standby(true) end)
                    pcall(function() prefab:set_Standby(true) end)
                    B.prefab = prefab; B.ctrl = ctrl
                    S.egg_prefab_cache[chassis] = { prefab = prefab, ctrl = ctrl }
                end
            end)
            if not okp or not B.prefab then B.msg = "prefab create failed"; B.stage = "done"; S.status = "egg break: " .. B.msg; return end
            -- instance info at a spot ahead of the player (UNIVERSAL coords for the generator)
            local player9 = get_player()
            local pgo9 = player9 and char_go(player9)
            local pp9 = pgo9 and upos(pgo9)
            if not pp9 then B.msg = "no player"; B.stage = "done"; return end
            local fx9, fz9 = 0.0, 1.0
            pcall(function()
                local rot9 = pgo9:call("get_Transform"):call("get_Rotation")
                fx9 = 2.0 * (rot9.x * rot9.z + rot9.w * rot9.y)
                fz9 = 1.0 - 2.0 * (rot9.x * rot9.x + rot9.y * rot9.y)
            end)
            -- the nest world hands us a TARGET (universal); the panel button spawns ahead of the player
            local tgt9 = B.target or { x = pp9.x + fx9 * 1.5, y = pp9.y + 0.15, z = pp9.z + fz9 * 1.5 }
            local okc = pcall(function()
                local inst = sdk.create_instance("app.InstanceInfo"):add_ref()
                local container
                pcall(function() container = inst:get_Container() end)
                if not container then container = sdk.create_instance("app.GenerateInfo.GenerateInfoContainer"):add_ref() end
                local pos = ValueType.new(sdk.find_type_definition("via.Position"))
                pos.x = tgt9.x; pos.y = tgt9.y; pos.z = tgt9.z
                local rot = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                rot.x = 0; rot.y = 0; rot.z = 0; rot.w = 1
                local cat = 5
                pcall(function()
                    local td2 = sdk.find_type_definition("app.GeneratorCategory")
                    local f2 = td2 and td2:get_field("Gimmick")
                    if f2 then cat = f2:get_data() end
                end)
                pcall(function() container._CommonInfo._Category = cat end)
                pcall(function() container._CommonInfo._ObjectID._SelectedGimmickID = gid end)
                pcall(function() container._CommonInfo._InitialPosition = pos end)
                pcall(function() container._CommonInfo._ContextPosition = pos end)
                pcall(function() container._CommonInfo:setContextPosition(pos) end)
                pcall(function() container._CommonInfo._InitialAngle = rot end)
                pcall(function() container._CommonInfo._ContextAngle = rot end)
                pcall(function() container._CommonInfo:setContextAngle(rot) end)
                pcall(function() container._StatusInfo["<ScaleRate>k__BackingField"] = 1.0 end)
                B.inst = inst; B.container = container
            end)
            if not okc or not B.inst then B.msg = "InstanceInfo build failed"; B.stage = "done"; S.status = "egg break: " .. B.msg; return end
            B.msg = "waiting for prefab '" .. path .. "'..."
            B.stage = "wait"; B.t0 = nowB
        elseif B.stage == "wait" then
            local ready = false
            pcall(function() ready = B.prefab:get_Ready() == true end)
            -- JAM GUARD: a pair built too early in a cold boot can never become Ready; a jammed
            -- egg counted as "live" and STARVED the whole clutch. Time out, scrap the pair
            -- (fresh one next attempt), let the self-heal remove this birth and retry.
            if not ready and nowB > (tonumber(B.t0) or 0.0) + 25.0 then
                B.msg = "prefab never ready -- scrapping the pair, the nest will retry"
                B.stage = "done"; B.go = nil
                pcall(function()
                    S.egg_prefab_cache[tostring(C.egg_chassis or "gm80_009")] = nil
                    S.egg_prewarmed = false
                end)
                return
            end
            if ready then
                local gen = sdk.get_managed_singleton("app.GenerateManager")
                if not gen then B.msg = "no GenerateManager"; B.stage = "done"; return end
                S.egg_break_seq = (tonumber(S.egg_break_seq) or 0) + 1
                local sig = "requestCreateInstance(app.PrefabController, app.GenerateInfo.GenerateInfoContainer, System.Int32, app.InstanceInfo, System.Action`2<app.PrefabInstantiateResults,app.DummyArg>, System.Action`2<app.PrefabInstantiateResults,app.DummyArg>)"
                local okr = pcall(function() gen:call(sig, B.ctrl, B.container, 730000 + S.egg_break_seq, B.inst, nil, nil) end)
                if not okr then B.msg = "requestCreateInstance failed"; B.stage = "done"; S.status = "egg break: " .. B.msg; return end
                -- this pair is spent (the baby builds fresh per spawn) -- pre-warm the next one now
                pcall(function()
                    S.egg_prefab_cache[tostring(C.egg_chassis or "gm80_009")] = nil
                    S.egg_prewarmed = false
                    S.egg_prewarm_at = nowB + 2.0
                end)
                B.msg = "chassis requested -- waiting for the body..."
                B.stage = "poll"; B.t0 = nowB
            elseif nowB - (tonumber(B.t0) or nowB) > 25.0 then   -- cold prefabs load SLOW (the 2-3 clicks issue)
                B.msg = "prefab NEVER READY -- no prefab at this path (chassis '" .. tostring(C.egg_chassis or "gm80_009") .. "' can't spawn)"
                B.stage = "done"; S.status = "egg break: " .. B.msg
            end
        elseif B.stage == "poll" then
            local go9
            pcall(function() go9 = B.inst:get_Instance() end)
            if not go9 then pcall(function() go9 = B.inst["<Instance>k__BackingField"] end) end
            if go9 then
                pcall(function() go9 = go9:add_ref() end)
                B.go = go9
                B.msg = "chassis up (" .. tostring(go_name(go9)) .. ") -- dressing it as the egg..."
                B.stage = "reskin"; B.at = nowB + 0.1
            elseif nowB - (tonumber(B.t0) or nowB) > 4.0 then
                if not B.retried then
                    -- the pre-warmed pair sometimes doesn't take (her "2 clicks") -- one click,
                    -- two attempts: retry automatically with a FRESH pair
                    B.retried = true
                    B.prefab = nil; B.ctrl = nil; B.inst = nil; B.container = nil
                    B.msg = "first attempt didn't take -- auto-retrying with a fresh pair..."
                    B.stage = "prefab"
                else
                    B.msg = "instance never appeared (two attempts; tell Iris)"
                    B.stage = "done"; S.status = "egg break: " .. B.msg
                end
            end
        elseif B.stage == "reskin" and nowB >= (tonumber(B.at) or 0.0) then
            -- the baby reskin: HIDE -> holder-bind our mesh + material -> show (dodges #1448)
            local mc9 = comp(B.go, "via.render.Mesh")
            if not mc9 then B.msg = "chassis has no via.render.Mesh on root -- tell Iris the GO name: " .. tostring(go_name(B.go)); B.stage = "done"; S.status = "egg break: " .. B.msg; return end
            B.held = B.held or {}
            pcall(function() mc9:call("set_Enabled", false) end)
            pcall(function()
                local res9 = sdk.create_resource("via.render.MeshResource", "custom_tex/iris/griffin_egg.mesh"):add_ref()
                B.held[#B.held + 1] = res9
                local hold9 = res9:create_holder("via.render.MeshResourceHolder"):add_ref()
                B.held[#B.held + 1] = hold9
                if not pcall(function() mc9:call("setMesh", hold9) end) then mc9:call("set_Mesh", hold9) end
                local mt9 = sdk.create_resource("via.render.MeshMaterialResource", "custom_tex/iris/griffin_egg.mdf2"):add_ref()
                B.held[#B.held + 1] = mt9
                local mh9 = mt9:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                B.held[#B.held + 1] = mh9
                if not pcall(function() mc9:call("set_Material", mh9) end) then mc9:call("setMaterial", mh9) end
            end)
            pcall(function() mc9:call("set_Enabled", true) end)
            pcall(function()
                local sc9 = tonumber(C.egg_scale) or 0.54
                local sv9 = ValueType.new(sdk.find_type_definition("via.vec3"))
                sv9.x = sc9; sv9.y = sc9; sv9.z = sc9
                local t2 = B.go:call("get_Transform")
                if not pcall(function() t2:call("set_LocalScale", sv9) end) then t2:call("set_Scale", sv9) end
            end)
            B.mc = mc9
            B.msg = "dressed -- curative re-bind..."
            B.stage = "cure"; B.at = nowB + 1.2
        elseif B.stage == "cure" and nowB >= (tonumber(B.at) or 0.0) then
            pcall(function()
                local mc9 = B.mc
                local res9 = sdk.create_resource("via.render.MeshResource", "custom_tex/iris/griffin_egg.mesh"):add_ref()
                B.held[#B.held + 1] = res9
                local hold9 = res9:create_holder("via.render.MeshResourceHolder"):add_ref()
                B.held[#B.held + 1] = hold9
                if not pcall(function() mc9:call("setMesh", hold9) end) then mc9:call("set_Mesh", hold9) end
                local mt9 = sdk.create_resource("via.render.MeshMaterialResource", "custom_tex/iris/griffin_egg.mdf2"):add_ref()
                B.held[#B.held + 1] = mt9
                local mh9 = mt9:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                B.held[#B.held + 1] = mh9
                if not pcall(function() mc9:call("set_Material", mh9) end) then mc9:call("setMaterial", mh9) end
                mc9:call("set_Enabled", true)
            end)
            local mn9 = 0
            pcall(function() mn9 = tonumber(B.mc:call("get_MaterialNum")) or 0 end)
            if mn9 <= 0 then
                -- cold bind = invisible egg (image 83): stay in cure and rebind until it's real
                B.cure_n = (tonumber(B.cure_n) or 0) + 1
                if B.cure_n < 12 then
                    B.at = nowB + 2.0
                    B.msg = "egg curing... (" .. tostring(B.cure_n) .. "/12)"
                    return
                end
            end
            B.msg = "BREAKABLE EGG READY (MaterialNum=" .. tostring(mn9) .. "). Fragile: drop it, roll it, or strike it."
            S.status = "egg break: " .. B.msg
            B.stage = "done"
            B.wt = nowB
            B.pin_ok_at = nowB + 0.4   -- home pin captures the SETTLED spot, not the mid-drop one
            pcall(function()
                local p9 = B.go:call("get_Transform"):call("get_Position")
                B.lastp = { x = p9.x, y = p9.y, z = p9.z }
            end)
            -- DAMAGE LEDGER: the rock accumulates hits SOMEWHERE (10 hits = native smash with
            -- rock debris -- Aurora). Snapshot every hp/durability/damage-ish field on its
            -- damage components; ANY change later = a hit landed = OUR shatter, first strike
            B.dmg_watch = {}
            pcall(function()
                local cl9 = B.go:call("get_Components")
                local m9 = 0
                pcall(function() m9 = cl9:call("get_Length") or 0 end)
                if m9 == 0 then pcall(function() m9 = cl9:get_size() or 0 end) end
                for j9 = 0, (tonumber(m9) or 0) - 1 do
                    pcall(function()
                        local cx9 = cl9:call("get_Item", j9) or cl9[j9]
                        local tn9 = cx9 and cx9:get_type_definition():get_full_name() or ""
                        local tl9 = tn9:lower()
                        if tl9:find("dynamicsdamage", 1, true) or tl9:find("hitcontroller", 1, true)
                            or tl9:find("gm80", 1, true) or tl9:find("gm50", 1, true) then
                            local td9 = cx9:get_type_definition()
                            while td9 do
                                for _, f9 in ipairs(td9:get_fields()) do
                                    pcall(function()
                                        if f9:is_static() then return end
                                        local nl9 = f9:get_name():lower()
                                        if nl9:find("hp", 1, true) or nl9:find("life", 1, true) or nl9:find("dura", 1, true)
                                            or nl9:find("health", 1, true) or nl9:find("damage", 1, true)
                                            or nl9:find("break", 1, true) or nl9:find("hitcount", 1, true) then
                                            local v9 = f9:get_data(cx9)
                                            if type(v9) == "number" or type(v9) == "boolean" then
                                                B.dmg_watch[#B.dmg_watch + 1] = { c = cx9, f = f9, v = v9, n = tn9 .. "." .. f9:get_name() }
                                            end
                                        end
                                    end)
                                end
                                td9 = td9:get_parent_type()
                            end
                        end
                    end)
                end
            end)
            B.msg = B.msg .. "  [hit-ledger fields: " .. tostring(#B.dmg_watch) .. "]"
            if not S.eggfx then S.eggfx = { stage = "spawn" } end   -- warm the shatter pool NOW
        end
    end

-- ============== THE BREAKABLE EGG (chassis gimmick + egg reskin; RiftSpeakBaby's proven spawn route) ==============
re.on_application_entry("UpdateBehavior", function()
    pcall(function()
        -- PRE-WARM the chassis prefab shortly after load: a COLD prefab is why the spawn
        -- took "a few clicks" -- by the time the button is pressed, this one is already Ready
        S.egg_prefab_cache = S.egg_prefab_cache or {}
        if not S.egg_prewarm_at then S.egg_prewarm_at = os.clock() + 3.0 end
        if not S.egg_prewarmed and os.clock() >= S.egg_prewarm_at then
            S.egg_prewarmed = true
            pcall(function()
                -- VERBATIM RiftSpeakBaby make_prefab_controller: the prefab must be OWNED by a
                -- PrefabController and standby flipped through BOTH handles or it never loads
                local chassis0 = tostring(C.egg_chassis or "gm80_009")
                local path0 = "AppSystem/gimmick/prefab/" .. chassis0:lower() .. ".pfb"
                local prefab0 = sdk.create_instance("via.Prefab"):add_ref()
                prefab0:set_Path(path0)
                local ctrl0 = sdk.create_instance("app.PrefabController"):add_ref()
                ctrl0._Item = prefab0
                pcall(function() ctrl0:get_Item():set_Standby(true) end)
                pcall(function() prefab0:set_Standby(true) end)
                S.egg_prefab_cache[chassis0] = { prefab = prefab0, ctrl = ctrl0 }
            end)
        end
    end)
    pcall(function()
        if C.egg_fragile == false then return end
        local eggs0 = S.eggs
        if not eggs0 or #eggs0 == 0 then return end
        -- ONE carry sensor per tick, attributed to the nearest alive egg (sticky while held)
        local held_any = false
        pcall(function()
            local oc0 = get_player():call("get_ObjectCarry")
            held_any = (oc0 and oc0:call("isPickupCarrying")) == true
        end)
        if not held_any then pcall(function() held_any = catch_active(get_player()) == true end) end
        if held_any then
            local ce = S.carried_egg
            if not (ce and ce.go and not ce.dead and ce._pick) then
                S.carried_egg = nil
                pcall(function()
                    local pp0 = char_go(get_player()):call("get_Transform"):call("get_Position")
                    local bd0 = 6.25
                    for _, E0 in ipairs(eggs0) do
                        if E0.go and not E0.dead and E0.stage == "done" then
                            local okq, pq = pcall(function() return E0.go:call("get_Transform"):call("get_Position") end)
                            if okq and pq then
                                local dq = (pq.x - pp0.x) ^ 2 + (pq.y - pp0.y) ^ 2 + (pq.z - pp0.z) ^ 2
                                if dq < bd0 then bd0 = dq; S.carried_egg = E0 end
                            end
                        end
                    end
                end)
                if S.carried_egg then S.carried_egg._pick = true end
            end
        else
            if S.carried_egg then S.carried_egg._pick = nil end
            S.carried_egg = nil
        end
        for _, E0 in ipairs(eggs0) do
            iris_egg_watch(E0, held_any and S.carried_egg == E0)
        end
    end)
    pcall(function()
        for _, E0 in ipairs(S.eggs or {}) do
            if E0.stage ~= "done" then iris_egg_machine(E0) end
        end
        S.egg_break = S.carried_egg or (S.eggs and S.eggs[#S.eggs]) or nil
    end)
    -- ===== THE EGG HEIST ENDGAME: prompts -> griffin taunt -> campfire -> incubation -> hatch =====
    pcall(function()
        local nowH = os.clock()
        -- (the way-home marker is PAINTED in the on_frame block near the nest markers -- draw.*
        -- only renders there, not in UpdateBehavior. This tick just SETS S.heist_marker below.)
        if nowH < (tonumber(S.heist_at) or 0.0) then return end
        S.heist_at = nowH + 0.5
        if S.eggworld == nil then
            local d9 = nil
            pcall(function() d9 = json.load_file("IrisEggWorld.json") end)
            S.eggworld = (type(d9) == "table" and type(d9.incubs) == "table") and d9 or { incubs = {} }
            -- ⛔ respawn_at is an os.clock() THROTTLE that got persisted -- os.clock() resets to 0 on
            -- every script reset / restart, so a saved value (e.g. 7285) blocks the respawn for ~2h
            -- against the fresh clock = "the egg never comes back" (Aurora's json). Strip it on load
            -- so the body respawns immediately; it's a runtime-only retry timer.
            for _, inc7 in pairs(S.eggworld.incubs or {}) do inc7.respawn_at = nil end
            -- every fresh read (boot OR save reload) reconciles against the CURRENT in-game clock
            S.eggworld_reconcile_at = os.clock() + 3.0
        end
        local pgo9 = char_go(get_player())
        local pu9 = pgo9 and upos(pgo9)
        if not pu9 then return end
        local igh9 = iris_igh()
        local save9 = false
        -- ⭐ SAVE-AWARE PERMANENCE (Aurora: "reload an old save -> the egg goes back to its previous
        -- state"). Each incubation is stamped with the in-game time it BEGAN (created_igh). Loading
        -- an older save rolls the in-game clock BACK, so any incubation "from the future" (created
        -- after the loaded moment) never happened in this timeline -> discard it. Deferred 3s so the
        -- clock is settled after a load. (No reliable per-save-slot store exists; the game clock IS
        -- the timeline marker.)
        if S.eggworld_reconcile_at and os.clock() >= S.eggworld_reconcile_at then
            local now_igh7 = iris_igh()
            if now_igh7 then
                S.eggworld_reconcile_at = nil
                local dropped7 = 0
                for k7, inc7 in pairs(S.eggworld.incubs or {}) do
                    if tonumber(inc7.created_igh) and tonumber(inc7.created_igh) > now_igh7 + 1.0 then
                        S.eggworld.incubs[k7] = nil
                        dropped7 = dropped7 + 1
                    end
                end
                if dropped7 > 0 then
                    -- forget the future eggs' bodies too, so nothing respawns them
                    for ei7 = #(S.eggs or {}), 1, -1 do
                        local E7 = S.eggs[ei7]
                        if E7.incub and not S.eggworld.incubs[E7.incub] then
                            iris_egg_dispose(E7); table.remove(S.eggs, ei7)
                        end
                    end
                    pcall(function() json.dump_file("IrisEggWorld.json", S.eggworld) end)
                    S.status = string.format("loaded an earlier save -- %d future egg(s) undone", dropped7)
                end
            else
                S.eggworld_reconcile_at = os.clock() + 3.0   -- clock not ready yet; try again
            end
        end
        -- camps in a nest's SHADOW (80m) are invisible to the heist: the marker must never
        -- lead the player to a fire the settle would then refuse
        local function nearest_safe_camp9(pp9)
            local nests9 = nests_load()
            local best9, bd9 = nil, nil
            local function consider9(c9)
                local dxc = (tonumber(c9.x) or 0) - pp9.x
                local dyc = (tonumber(c9.y) or 0) - pp9.y
                local dzc = (tonumber(c9.z) or 0) - pp9.z
                local d9 = math.sqrt(dxc * dxc + dyc * dyc + dzc * dzc)
                if bd9 and d9 >= bd9 then return end
                for _, n9 in ipairs(nests9) do
                    local ax = (tonumber(n9.x) or 0) - (tonumber(c9.x) or 0)
                    local ay = (tonumber(n9.y) or 0) - (tonumber(c9.y) or 0)
                    local az = (tonumber(n9.z) or 0) - (tonumber(c9.z) or 0)
                    if (ax * ax + ay * ay + az * az) < 6400.0 then return end
                end
                best9, bd9 = c9, d9
            end
            for _, c9 in ipairs(map_campsites()) do consider9(c9) end
            for _, c9 in ipairs(S.camps or {}) do consider9(c9) end
            return best9, bd9
        end
        -- 1) PICKUP edges: the hands tell the player the rules
        local ce9 = S.carried_egg
        if ce9 ~= S.heist_prev_ce then
            if ce9 and ce9.incub then
                -- lifted an INCUBATING egg: the warmth is interrupted (the clock pauses)
                local inc9 = S.eggworld.incubs[ce9.incub]
                if inc9 then inc9.settled = false; save9 = true end
                ce9.incub_key_hold = ce9.incub; ce9.incub = nil
                ce9.home_pin = nil; ce9.settle_y = nil
                set_prompt("THE WARMTH FADES", "Incubation pauses in your hands. Settle it by a campfire again.", 5.0)
            elseif ce9 and ce9.nest_key and not ce9.stolen then
                set_prompt("CAREFUL HANDS", "A drop, a throw, a blow -- any will break it. Carry it to a campfire.", 6.0)
            end
            S.heist_prev_ce = ce9
        end
        -- 2) STOLEN carry = the way home + THE TAUNT BEACON (wild griffins only; the tame never)
        local hot9 = ce9 and not ce9.dead and (ce9.stolen or ce9.incub_key_hold)
        if not hot9 then S.heist_marker = nil end
        if hot9 then
            local camp9, campd9 = nearest_safe_camp9(pu9)
            if camp9 then
                S.heist_marker = { x = camp9.x, y = camp9.y, z = camp9.z,
                    label = string.format("%s (%.0fm)", tostring(camp9.name or "Camp"), tonumber(campd9) or 0) }
            else
                S.heist_marker = nil
            end
            if campd9 and campd9 < 12.0 then
                set_prompt("THE FIRE IS NEAR", "Set the egg down gently by the campfire.", 0.6, 0xFF80FFB0)
            else
                set_prompt("GRIFFINS HUNT THE THIEF", campd9 and string.format("Make for a campfire. (%.0fm)", campd9)
                    or "Make for a campfire. (Rest at one once to teach the map.)", 0.6, 0xFFFF8060)
            end
            if C.egg_taunt ~= false and nowH >= (tonumber(S.heist_taunt_at) or 0.0) then
                S.heist_taunt_at = nowH + 1.5
                local comp_addr9 = nil
                pcall(function()
                    local B9 = _G.IrisGriffinBridge
                    local g9 = B9 and B9.griffin and B9.griffin()
                    if g9 then comp_addr9 = tostring(g9:get_address()) end
                end)
                local sm9 = sdk.get_native_singleton("via.SceneManager")
                local smt9 = sdk.find_type_definition("via.SceneManager")
                local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
                local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("app.Character"))
                local n9 = 0
                pcall(function() n9 = comps9:call("get_Length") or 0 end)
                if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
                for i9 = 0, (tonumber(n9) or 0) - 1 do
                    pcall(function()
                        local ch9 = comps9:call("get_Item", i9) or comps9[i9]
                        local go9 = ch9 and char_go(ch9)
                        if not go9 or is_dead(ch9) then return end
                        if not tostring(go_name(go9)):find("ch253", 1, true) then return end
                        local a9 = tostring(ch9:get_address())
                        if comp_addr9 and a9 == comp_addr9 then return end
                        if S.tamed_addrs and S.tamed_addrs[a9] then return end
                        local hs9 = hate_system(ch9)
                        if not hs9 then return end
                        hs9:call("addHateParam(via.GameObject, app.HateRecvCategory, app.HateSystem.WriteType, System.Single, System.Single, System.Single, System.Single)",
                            pgo9, 2, 1, 9999.0, 9999.0, 9999.0, 60.0)
                        pcall(function() hs9:call("updateHateRanking") end)
                    end)
                end
            end
        end
        -- 3) SETTLE: a stolen egg put down within reach of a campfire begins incubation
        for _, E9 in ipairs(S.eggs or {}) do
            if E9.go and not E9.dead and not E9.incub and (E9.stolen or E9.incub_key_hold)
                and E9 ~= S.carried_egg and E9.release_t and (nowH - E9.release_t) > 2.0 then
                pcall(function()
                    local eu9 = upos(E9.go)
                    local camp9, campd9 = nearest_safe_camp9(eu9)
                    if not (camp9 and campd9 and campd9 < 12.0) then
                        -- did they set it down at a SHADOWED fire (roost-side camp)? say why it refuses
                        local anyc9, anyd9 = nearest_camp(eu9)
                        if anyc9 and anyd9 and anyd9 < 12.0 then
                            set_prompt("NO SANCTUARY HERE", "This fire sits in the griffins' shadow. Carry the egg to a farther camp.", 2.0, 0xFFFF8060)
                        end
                    end
                    if camp9 and campd9 and campd9 < 12.0 then
                        local key9 = E9.incub_key_hold or string.format("inc_%d", math.floor(nowH * 10.0))
                        local inc9 = S.eggworld.incubs[key9]
                        if not inc9 then
                            inc9 = { rem_h = (tonumber(C.egg_hatch_days) or 7.0) * 24.0,
                                camp = tostring(camp9.name or "camp"),
                                created_igh = igh9 or false }   -- the in-game moment this began (save-rollback marker)
                            S.eggworld.incubs[key9] = inc9
                        end
                        inc9.x = eu9.x; inc9.y = eu9.y; inc9.z = eu9.z
                        pcall(function()
                            local lp9 = E9.go:call("get_Transform"):call("get_Position")
                            inc9.lx = lp9.x; inc9.ly = lp9.y; inc9.lz = lp9.z
                        end)
                        inc9.settled = true; inc9.last_igh = igh9 or inc9.last_igh
                        E9.incub = key9; E9.incub_key_hold = nil
                        E9.nest_key = nil   -- the clutch already counted the theft
                        E9.home_pin = nil; E9.settle_y = nil
                        save9 = true
                        set_prompt("INCUBATION BEGINS", string.format("The egg warms by the fire. ~%.1f days until it hatches.",
                            (tonumber(inc9.rem_h) or 0.0) / 24.0), 6.0, 0xFF80FFB0)
                        S.status = "an egg incubates at " .. tostring(inc9.camp)
                    end
                end)
            end
        end
        -- 4) THE CLOCK + the near-egg whisper + HATCH
        for key9, inc9 in pairs(S.eggworld.incubs or {}) do
            local body9 = nil
            for _, E9 in ipairs(S.eggs or {}) do
                if E9.incub == key9 and E9.go and not E9.dead then body9 = E9; break end
            end
            -- ORPHANS: a PAUSED entry whose egg no longer exists (it broke in someone's hands,
            -- or was thrown at a tree) is an incubation that ended -- clear the ledger
            if not inc9.settled then
                local held9 = false
                for _, E9 in ipairs(S.eggs or {}) do
                    if (E9.incub == key9 or E9.incub_key_hold == key9) and not E9.dead then held9 = true; break end
                end
                if not held9 then
                    S.eggworld.incubs[key9] = nil
                    save9 = true
                    S.status = "an incubation is lost -- the egg is gone"
                end
            end
            if inc9.settled and igh9 then
                if tonumber(inc9.last_igh) and igh9 > inc9.last_igh then
                    inc9.rem_h = (tonumber(inc9.rem_h) or 0.0) - (igh9 - inc9.last_igh)
                    S.heist_dirty = true
                end
                inc9.last_igh = igh9
            end
            local dx9, dy9, dz9 = (inc9.x or 0) - pu9.x, (inc9.y or 0) - pu9.y, (inc9.z or 0) - pu9.z
            local d9 = math.sqrt(dx9 * dx9 + dy9 * dy9 + dz9 * dz9)
            -- cold world: re-grow the egg body when the player comes near
            if not body9 and inc9.settled and d9 < 130.0 and nowH >= (tonumber(inc9.respawn_at) or 0.0) then
                inc9.respawn_at = nowH + 20.0
                iris_reap_eggs_near(inc9.x, inc9.y, inc9.z, 2.5)   -- clear any orphan here first (no duplicate)
                S.eggs = S.eggs or {}
                S.eggs[#S.eggs + 1] = { stage = "prefab", incub = key9,
                    home = { x = inc9.x, y = inc9.y, z = inc9.z },
                    target = { x = inc9.x, y = (tonumber(inc9.y) or 0.0) + 0.25, z = inc9.z } }
            end
            -- the whisper: only beside the egg (Aurora's rule: never parked on screen)
            if body9 and d9 < 2.5 and (tonumber(inc9.rem_h) or 0.0) > 0.0 then
                set_prompt("THE EGG INCUBATES", string.format("%.1f days until it hatches.",
                    math.max(0.0, tonumber(inc9.rem_h) or 0.0) / 24.0), 0.6, 0xFF80FFB0)
            end
            -- HATCH: time served + a witness + a shell to break
            if (tonumber(inc9.rem_h) or 1.0) <= 0.0 and inc9.settled and body9 and d9 < 60.0 then
                pcall(function()
                    local eu9 = upos(body9.go)
                    body9.dead = true; body9.counted = true
                    if not S.eggfx then S.eggfx = { stage = "spawn" } end
                    S.eggfx.want = { x = eu9.x, y = eu9.y, z = eu9.z }
                    iris_egg_dispose(body9)
                end)
                -- ⛔ GHOST EGG (2026-08-08, Aurora's screenshot: shell floating at the camp
                -- after the hatch): approaching triggers BOTH the cold-world regrow (which
                -- QUEUES a fresh egg spawn) and the hatch -- the hatch disposed the live body,
                -- then the queued twin delivered a shell nobody owns. Kill every queued/live
                -- egg tied to this incubation + reap strays at the spot.
                pcall(function()
                    for i9 = #(S.eggs or {}), 1, -1 do
                        local Q9 = S.eggs[i9]
                        if Q9 and Q9.incub == key9 then
                            if Q9.go then pcall(function() iris_egg_dispose(Q9) end) end
                            table.remove(S.eggs, i9)
                        end
                    end
                    iris_reap_eggs_near(inc9.x, inc9.y, inc9.z, 4.0)
                end)
                local gname9 = tostring(inc9.name or "Hatchling")
                local ggen9 = nil
                pcall(function()
                    local B9 = _G.IrisGriffinBridge
                    if B9 and B9.hatch_companion then
                        ggen9 = B9.hatch_companion({ name = gname9,
                            x = inc9.lx, y = inc9.ly, z = inc9.lz,
                            baby = tonumber(C.egg_hatch_scale) or 0.12,
                            growth_days = tonumber(C.egg_growth_days) or 10.0 })
                    end
                end)
                S.eggworld.incubs[key9] = nil
                save9 = true
                set_prompt("IT HATCHES", string.format("%s (%s) joins your stable -- small, loud, and yours.",
                    gname9, tostring(ggen9 or "?")), 8.0, 0xFF80FFB0)
                S.status = "the egg hatches: " .. gname9
            end
        end
        -- 5b) THE ROOST WARDEN: campsites inside a nest's shadow are put out -- no "Make Camp"
        -- at the griffins' doorstep (found via the GO census: app.gm80_001 = the campsite spot,
        -- Gm80_079 = the bonfire + its interact jacks). Only shadowed pieces stand down; every
        -- other camp in the world is untouched. Re-asserted (streaming re-creates them).
        if C.nest_no_camp ~= false and nowH >= (tonumber(S.warden_at) or 0.0) then
            S.warden_at = nowH + 10.0
            pcall(function()
                local nests9 = nests_load()
                if #nests9 == 0 then return end
                local sm9 = sdk.get_native_singleton("via.SceneManager")
                local smt9 = sdk.find_type_definition("via.SceneManager")
                local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
                if not scene9 then return end
                local hushed9 = 0
                for _, tn9 in ipairs({ "app.gm80_001", "app.Gm80_079", "app.Gm80_079_interact_Bonfire",
                    "app.Gm80_079_interact_PL", "app.Gm80_204", "app.Gm50_026" }) do
                    pcall(function()
                        local comps9 = scene9:call("findComponents(System.Type)", sdk.typeof(tn9))
                        local n9 = 0
                        pcall(function() n9 = comps9:call("get_Length") or 0 end)
                        if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
                        for i9 = 0, (tonumber(n9) or 0) - 1 do
                            pcall(function()
                                local c9 = comps9:call("get_Item", i9) or comps9[i9]
                                local go9 = c9 and c9:call("get_GameObject")
                                local eu9 = go9 and upos(go9)
                                if not eu9 then return end
                                for _, nn9 in ipairs(nests9) do
                                    local ax = (tonumber(nn9.x) or 0) - eu9.x
                                    local ay = (tonumber(nn9.y) or 0) - eu9.y
                                    local az = (tonumber(nn9.z) or 0) - eu9.z
                                    if (ax * ax + ay * ay + az * az) < 6400.0 then
                                        pcall(function() c9:call("set_Enabled", false) end)
                                        pcall(function() go9:call("set_DrawSelf", false) end)
                                        hushed9 = hushed9 + 1
                                        return
                                    end
                                end
                            end)
                        end
                    end)
                end
                if hushed9 > 0 then
                    S.status = string.format("roost warden: %d camp pieces stand down", hushed9)
                end
            end)
        end
        -- 5) growth: nudge the active hatchling toward full size (the probe eases it smoothly)
        if nowH >= (tonumber(S.heist_grow_at) or 0.0) then
            S.heist_grow_at = nowH + 5.0
            pcall(function()
                local B9 = _G.IrisGriffinBridge
                if B9 and B9.growth_refresh then B9.growth_refresh() end
            end)
        end
        if S.heist_dirty and nowH >= (tonumber(S.heist_save_at) or 0.0) then
            S.heist_save_at = nowH + 30.0; S.heist_dirty = nil; save9 = true
        end
        if save9 then pcall(function() json.dump_file("IrisEggWorld.json", S.eggworld) end) end
    end)
    -- ===== THE MOUND TRAIL (burrowing rabbit -- Aurora's Bugs Bunny trail, image 106) =====
    -- DISPOSABLE lumps, nest-bowl-conform (image 112 taught the FULL law): on created props
    -- BOTH DrawSelf flips AND late scale writes silently no-op -- everything (position, scale,
    -- rotation) must be set at CREATION, mesh+material next frame, destroy at expiry. No pool,
    -- no re-placement, no parking.
    pcall(function()
        local nowM = os.clock()
        local B9 = _G.IrisGriffinBridge
        local st9 = B9 and B9.scout_status and B9.scout_status()
        local g9 = B9 and B9.griffin and B9.griffin()
        local go9 = g9 and char_go(g9)
        -- one-shot efx at a body (the sand-engine recipe): scale set at BIRTH (LocalScale
        -- proven on emitters -- the sand-arm thickness slider), reaped by the timer below
        local fx9 = function(path9, sc9, life9)
            pcall(function()
                local rp9 = go9 and go9:call("get_Transform"):call("get_Position")
                if not rp9 then return end
                local res9 = sdk.create_resource("via.effect.EffectResource", tostring(path9))
                if not res9 then return end
                res9 = res9:add_ref()
                local hold9 = res9:create_holder("via.effect.EffectResourceHolder"):add_ref()
                local ego9 = sdk.find_type_definition("via.GameObject"):get_method("create(System.String)"):call(nil, "IrisBurrowFx")
                ego9 = ego9:add_ref()
                local etf9 = ego9:call("get_Transform")
                etf9:call("set_Position", Vector3f.new(rp9.x, rp9.y + 0.05, rp9.z))
                local s9 = tonumber(sc9) or 1.0
                if s9 ~= 1.0 then pcall(function() etf9:call("set_LocalScale", Vector3f.new(s9, s9, s9)) end) end
                local ep9 = ego9:call("createComponent(System.Type)", sdk.typeof("via.effect.EffectPlayer"))
                ep9:call("set_Resource", hold9)
                ep9:call("set_AutoStart", true)
                S.efx_aud_live = S.efx_aud_live or {}
                S.efx_aud_live[#S.efx_aud_live + 1] = { go = ego9, held = { res9, hold9 }, until_t = nowM + (tonumber(life9) or 3.0) }
            end)
        end
        -- ENTRY + EXIT eruptions: the rabbit-sized ground-break (Aurora's divebomb-taped pick)
        -- fires once each time the burrow state flips
        local bnow9 = (st9 and st9.burrowed) == true
        if bnow9 ~= (S.burrow_was == true) and go9 then
            fx9(C.burrow_fx_rock, tonumber(C.burrow_fx_rock_scale) or 0.15, 2.5)
        end
        S.burrow_was = bnow9
        if st9 and st9.burrowed then
            local eu9 = go9 and upos(go9)
            if eu9 then
                local lp9 = S.mound_last
                local dx9 = lp9 and (eu9.x - lp9.x) or 99.0
                local dz9 = lp9 and (eu9.z - lp9.z) or 99.0
                local gap9 = tonumber(C.burrow_mound_gap) or 1.2
                if (dx9 * dx9 + dz9 * dz9) > gap9 * gap9 then
                    S.mound_last = { x = eu9.x, z = eu9.z }
                    -- the moving trail: a dust puff (normal size) every gap meters
                    fx9(C.burrow_fx_dust, tonumber(C.burrow_fx_dust_scale) or 1.0, 3.0)
                    S.mounds = S.mounds or {}
                    local hb9 = ground_probe(eu9.x, eu9.y + 1.0, eu9.z)
                    local hy9 = hb9 and tonumber(hb9.y)
                    -- mesh lumps are OPTIONAL now (the efx replaced them); cliff edges (probed
                    -- ground far from the rabbit) get NO lump -- image 112's rock-face nests
                    if C.burrow_lumps == true and hy9 and math.abs(eu9.y - hy9) < 2.0 and #S.mounds < 40 then
                        local sc0 = tonumber(C.burrow_mound_scale) or 0.16
                        S.mounds[#S.mounds + 1] = { stage = "spawn",
                            want = { x = eu9.x, y = hy9, z = eu9.z, yaw = math.random() * 6.283,
                                sc = sc0 * (1.0 + math.random() * 0.35), t = nowM } }
                    end
                end
            end
        else
            S.mound_last = nil
        end
        local dead9 = nil
        for mi9, M9 in ipairs(S.mounds or {}) do
            if M9.stage == "spawn" then
                M9.stage = "bind"; M9.at = nowM + 0.05
                pcall(function()
                    local w0 = M9.want
                    local go9 = sdk.find_type_definition("via.GameObject"):get_method("create(System.String)"):call(nil, "IrisMound")
                    go9 = go9:add_ref()
                    -- phase 1 = the WHOLE transform, at birth (the only writes that stick)
                    pcall(function() go9:call("set_DrawSelf", true) end)
                    pcall(function() go9:call("set_UpdateSelf", true) end)
                    pcall(function()
                        local v9 = ValueType.new(sdk.find_type_definition("via.Position"))
                        v9.x = w0.x; v9.y = w0.y - (tonumber(C.burrow_mound_sink) or 0.02); v9.z = w0.z
                        set_upos(go9, v9)
                        local tf9 = go9:call("get_Transform")
                        local sv9 = ValueType.new(sdk.find_type_definition("via.vec3"))
                        sv9.x = w0.sc; sv9.y = w0.sc * 0.6; sv9.z = w0.sc   -- squashed = a lump, not a bowl
                        if not pcall(function() tf9:call("set_LocalScale", sv9) end) then tf9:call("set_Scale", sv9) end
                        local qv9 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                        qv9.x = 0.0; qv9.y = math.sin(w0.yaw * 0.5); qv9.z = 0.0; qv9.w = math.cos(w0.yaw * 0.5)
                        tf9:call("set_Rotation", qv9)
                    end)
                    M9.go = go9
                    M9.mc = go9:call("createComponent(System.Type)", sdk.typeof("via.render.Mesh"))
                end)
                if not M9.go then M9.stage = "dead" end
            elseif M9.stage == "bind" and nowM >= (tonumber(M9.at) or 0.0) then
                -- phase 2 (next frame): resources onto the placed carrier
                local base9 = tostring(C.burrow_mound_mesh or "")
                local probe9 = nil
                pcall(function() probe9 = sdk.create_resource("via.render.MeshResource", base9 .. ".mesh") end)
                if not probe9 then
                    M9.tries = (tonumber(M9.tries) or 0) + 1
                    if M9.tries >= 5 then
                        M9.stage = "live"   -- give up binding; the reaper below still collects it
                        pcall(function() log.info("[IrisTaming] mound mesh NOT loadable (bad path?): " .. base9) end)
                    else
                        M9.at = nowM + 1.0
                    end
                else
                    pcall(function()
                        local res9 = sdk.create_resource("via.render.MeshResource", base9 .. ".mesh"):add_ref()
                        M9.held = { res9 }
                        local hold9 = res9:create_holder("via.render.MeshResourceHolder"):add_ref()
                        M9.held[#M9.held + 1] = hold9
                        if not pcall(function() M9.mc:call("setMesh", hold9) end) then M9.mc:call("set_Mesh", hold9) end
                        local mt9 = sdk.create_resource("via.render.MeshMaterialResource", base9 .. ".mdf2")
                        if mt9 then
                            mt9 = mt9:add_ref(); M9.held[#M9.held + 1] = mt9
                            local mh9 = mt9:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                            M9.held[#M9.held + 1] = mh9
                            if not pcall(function() M9.mc:call("set_Material", mh9) end) then M9.mc:call("setMaterial", mh9) end
                        end
                        pcall(function() M9.mc:call("set_Enabled", true) end)
                    end)
                    M9.stage = "live"
                    -- one forensic line per session
                    if not S.mound_logged then
                        S.mound_logged = true
                        local mn9 = 0
                        pcall(function() mn9 = tonumber(M9.mc:call("get_MaterialNum")) or 0 end)
                        local w0 = M9.want
                        pcall(function() log.info(string.format("[IrisTaming] mound placed: sc=%.2f MatNum=%d at (%.0f, %.1f, %.0f)", w0.sc, mn9, w0.x, w0.y, w0.z)) end)
                    end
                end
            elseif M9.stage == "live" and nowM > ((tonumber((M9.want or {}).t) or 0.0) + (tonumber(C.burrow_mound_life) or 7.0)) then
                M9.stage = "dead"
            end
            if M9.stage == "dead" then
                pcall(function() if M9.go then M9.go:call("destroy", M9.go) end end)   -- plain created GO: destroy is safe (sand-engine proven)
                M9.go = nil; M9.mc = nil; M9.held = nil
                dead9 = dead9 or {}; dead9[#dead9 + 1] = mi9
            end
        end
        if dead9 then
            for i9 = #dead9, 1, -1 do table.remove(S.mounds, dead9[i9]) end
        end
        -- efx audition reaper: one-shot emitters die 6s after their PLAY press
        if S.efx_aud_live then
            for i9 = #S.efx_aud_live, 1, -1 do
                local E9 = S.efx_aud_live[i9]
                if nowM > (tonumber(E9.until_t) or 0.0) then
                    pcall(function() if E9.go then E9.go:call("destroy", E9.go) end end)
                    table.remove(S.efx_aud_live, i9)
                end
            end
        end
    end)
    -- ===== WYRMFEEDING (Aurora's homestead-style flow, 08-08) =====
    -- At a campfire, near the active companion, holding >=1 Wyrmslife
    -- Crystal (359): a context label floats over the beast -> press
    -- (E / A, jump suppressed) -> native Yes/No dialog -> Yes = palm
    -- offering, the crystal is consumed and growth eases in over the
    -- coming in-game day. The growth PULSE runs every tick regardless.
    pcall(function()
        local B9 = _G.IrisGriffinBridge
        if not (B9 and B9.wyrmfeed) then return end
        pcall(function() if B9.growth_refresh then B9.growth_refresh() end end)

        -- STUDIO PALM RESTORE (hard watchdog -- the player must NEVER be
        -- left think-stopped): restore FSM + think + playspeed when the
        -- pose window ends. Runs every tick so a missed frame still heals.
        if S.wyrm_player_pose and os.clock() >= (tonumber(S.wyrm_player_pose.until_t) or 0.0) then
            S.wyrm_player_pose = nil
            pcall(function()
                local pl9 = player_character()
                if pl9 then
                    set_think_stop(pl9, false)
                    pcall(function() set_player_fsm(char_go(pl9), true) end)
                    pcall(function() pl9:call("get_Motion"):call("set_PlaySpeed", 1.0) end)
                end
            end)
            S.phold = nil
        end
        -- rite reaction settle: re-hold the companion after its howl so
        -- it doesn't wander off mid-rite
        if S.wyrm_rite_settle and os.clock() >= (tonumber(S.wyrm_rite_settle.at) or 0.0) then
            S.wyrm_rite_settle = nil
            pcall(function()
                if B9.companion_hold then B9.companion_hold(true) end
            end)
        end
        -- restore the shared shell udata's base params after the cast read
        -- them (so the scale/lifetime bump doesn't stick globally)
        if S.wyrm_shell_restore and os.clock() >= (tonumber(S.wyrm_shell_restore.at) or 0.0) then
            local r9 = S.wyrm_shell_restore
            S.wyrm_shell_restore = nil
            pcall(function()
                r9.base.UseScale = r9.bu
                r9.base.Scale = r9.bs
                r9.base.UseLifeTime = r9.bul
                r9.base.LifeTime = r9.bl
            end)
        end

        -- while a dialog is up, poll ONLY its answer (game is paused)
        if S.wyrm_dlg and S.wyrm_dlg.open then
            local pick = iris_wyrm_dialog_pick()
            local settled = os.clock()
                > (tonumber(S.wyrm_dlg.opened_at) or 0.0) + 0.25
            -- 08-08 (Aurora: "first Yes did nothing, second worked"):
            -- getDialogState LATCHES a stale answer; if it equals the
            -- real first press we miss it. During the settle window,
            -- keep RE-BASELINING to the resting latch, so once settled a
            -- fresh press is always a genuine CHANGE = registers first try.
            if not settled then S.wyrm_dlg.baseline = pick end
            if settled and pick ~= nil
                and pick ~= S.wyrm_dlg.baseline then
                iris_wyrm_dialog_close()
                -- ⛔ TRUE RetVal enum (homestead memory, typedef-dumped):
                -- None=0 Sel0/YES=1 Sel1/NO=2 Cancel=5. The deed-sign
                -- CODE COMMENT (Sel0=2) is the OLD WRONG one that caused
                -- the "Leave-buys-plot" bug -- I trusted it, so pressing
                -- NO (2) fed anyway. YES is 1.
                if pick == 1 then   -- Sel0 = YES
                    if iris_wlc_take(359, 3) then
                        local fed9 = 0
                        pcall(function() fed9 = B9.wyrmfeed(true) or 0 end)
                        if fed9 == -1 then
                            pcall(function() give_item(get_player(), 359, 3, false) end)  -- refund the rite
                            set_prompt("TOO YOUNG", "The hatchling grows on its own clock -- the wyrm's life must wait.", 3.0, 0xFFFFD080)
                        elseif fed9 > 0 then
                            -- THE RITE REACTION (Aurora 08-08): player
                            -- holds the palm out (PrepareRendering
                            -- posture -- additive, no think-stop = no
                            -- freeze risk), and the beast FACES you and
                            -- HOWLS as the dragon's life takes root (the
                            -- proven pact howl, bank0:4610). VFX/SFX =
                            -- Aurora's follow-up.
                            -- ⛔⛔ 08-11 ROUND 2 -- THE REAL "SHOCKED ANIM" BUG: the old
                            -- code set S.phold WITHOUT a clip field, and the phold
                            -- consumer plays `S.phold.clip or 830` -- so the machinery
                            -- painted 60:830 (the startled emote) over whatever we
                            -- played manually (round 1 blamed the bank; the manual play
                            -- was ALWAYS stomped the same tick). While S.phold is live
                            -- the phold machinery OWNS the body -- never hand-play
                            -- beside it. Fix = give phold the REAL clip: 60:6200, the
                            -- riftstone palm raise (the taming hand-out itself).
                            -- follow = hold for the clip's real length (the sense
                            -- recipe); the machinery does its own think-stop + restore.
                            S.phold = { clip = 6200, pose = "palm",
                                until_t = os.clock() + 4.0, follow = true }
                            S.wyrm_player_pose = { until_t = os.clock() + 4.5 }  -- backstop: never left frozen
                            pcall(function()
                                local wch9 = B9.griffin and B9.griffin()
                                local wgo9 = wch9 and char_go(wch9)
                                if not wgo9 then return end
                                -- face the beast toward the player
                                pcall(function()
                                    local wtf9 = wgo9:call("get_Transform")
                                    local wp9 = wtf9:call("get_Position")
                                    local ppc9 = char_go(get_player())
                                        :call("get_Transform"):call("get_Position")
                                    local yaw9 = math.atan(ppc9.x - wp9.x, ppc9.z - wp9.z)
                                    local q9 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                                    q9.x = 0; q9.y = math.sin(yaw9 * 0.5)
                                    q9.z = 0; q9.w = math.cos(yaw9 * 0.5)
                                    wtf9:call("set_Rotation", q9)
                                end)
                                -- un-freeze the held companion so the
                                -- clip shows, then howl
                                pcall(function() set_think_stop(wch9, false) end)
                                pcall(function() play_motion(wch9, 0, tonumber(C.cue_howl_clip) or 4610) end)
                                -- ⭐ THE VFX (Aurora): the dragon-red shell
                                -- wraps the beast as the wyrm's life takes
                                -- root
                                pcall(function() iris_cast_wyrm_shell(wgo9) end)
                                -- re-hold it after the howl (~3.5s) so it
                                -- doesn't wander off mid-rite
                                S.wyrm_rite_settle = { ch = wch9, at = os.clock() + 3.5 }
                            end)
                            set_prompt("THE WYRM'S LIFE",
                                "It takes the crystals from your hand. Rest by the fire -- by morning it will have grown to a mount.",
                                5.0, 0xFFFF9060)
                            S.status = "wyrmfeeding: rest till morning to complete the growth"
                        end
                    else
                        set_prompt("THE WYRM'S LIFE",
                            "The offering would not leave your pack (see log).",
                            3.5, 0xFFFF8080)
                    end
                end
            end
            -- stuck guard: a dialog with no answer for 30s self-closes
            if os.clock() > (tonumber(S.wyrm_dlg.opened_at) or 0.0) + 30.0 then
                iris_wyrm_dialog_close()
            end
            return
        end

        -- gate the offer: throttle the scan, need the active companion
        local nowW = os.clock()
        if nowW < (tonumber(S.wyrm_scan_at) or 0.0) then return end
        S.wyrm_scan_at = nowW + 0.3
        -- r2 GATE DIAGNOSTIC (Aurora: no label, A does nothing): log the
        -- FIRST failing gate, but only when the reason CHANGES, so the
        -- log names exactly what blocks without spamming.
        local function wgate(msg)
            if S.wyrm_gate_last ~= msg then
                S.wyrm_gate_last = msg
                pcall(function() log.info("[IrisTaming] wyrm gate: " .. msg) end)
            end
        end
        local g9 = B9.griffin and B9.griffin()
        local go9 = g9 and char_go(g9)
        local crp9 = go9 and go9:call("get_Transform"):call("get_Position")
        if not crp9 then S.wyrm_offer_go = nil
            wgate("no active companion body (is Shadow summoned + active?)"); return end
        -- near the beast? (player within 5m)
        local pgo9 = char_go(get_player())
        local pp9 = pgo9 and pgo9:call("get_Transform"):call("get_Position")
        if not pp9 then return end
        local dxp9, dzp9 = pp9.x - crp9.x, pp9.z - crp9.z
        local dd9 = math.sqrt(dxp9 * dxp9 + dzp9 * dzp9)
        if dd9 > 5.0 then
            S.wyrm_offer_go = nil
            wgate(string.format("too far from the beast (%.1fm > 5m)", dd9)); return
        end
        -- have the 3-crystal rite cost? (WYRM_RITE_COST)
        local have9 = iris_wlc_count(359)
        if not have9 or have9 < 3 then S.wyrm_offer_go = nil
            wgate("only " .. tostring(have9) .. " crystals (need 3)"); return end
        -- 08-08 r3 DEPLOYED-CAMP GATE (Aurora: "only when the camp is put
        -- UP, not just near any campfire"). app.CampManager runs a state
        -- machine (CampStateActive when a camp is deployed). Probe its
        -- deployed/active signal at runtime -- try a set of plausible
        -- getters + read the current-state type name for "Active"; the
        -- winner is logged ONCE (self-reporting, the farming pattern).
        -- If CampManager can't be resolved at all, fall back to the fire
        -- scan so the rite still works, but say so in the log.
        -- 08-08 r4: the getter dump NAMED it -- app.CampManager
        -- .get_IsActiveCamp = true only while a camp is DEPLOYED (Aurora:
        -- "only when the camp is put up, not any campfire"). No more fire
        -- fallback -- that's what let the rite fire at random world fires.
        local camp9 = false
        pcall(function()
            local cm9 = sdk.get_managed_singleton("app.CampManager")
            if cm9 then camp9 = cm9:call("get_IsActiveCamp") == true end
        end)
        if not camp9 then S.wyrm_offer_go = nil
            wgate("no DEPLOYED camp (set the camp up first)"); return end
        wgate(string.format("READY (active camp, %.1fm)", dd9))

        -- ALL conditions met: the context label lives (drawn in the
        -- marker pass), and E / B opens the rite. 08-11 (Aurora): pad
        -- button moved A -> B to match the game's native interact button
        -- (all IRIS context prompts standardise on B). B is not Jump, so
        -- the old jump suppression is gone with it.
        S.wyrm_offer_go = go9
        -- Share the same native ui020701 prompt used by farming and weapon plaques. Position is
