                            if d0 and d0 < 45.0 then
                                S.ox_watch = S.ox_watch or {}
                                local W1 = S.ox_watch[ch0:get_address()] or {}
                                S.ox_watch[ch0:get_address()] = W1
                                W1.alive = nowO
