                                if not W1.moved and u0 then
                                    local mdx1 = u0.x - W1.px
                                    local mdz1 = u0.z - W1.pz
                                    if mdx1 * mdx1 + mdz1 * mdz1 > 9.0 then W1.moved = true end
                                end
                            end
                            return
                        end
