                        if d0 and d0 * d0 < bestc0 then bestc0 = d0 * d0; corpse0 = u0; cgo0 = go0 end
                    elseif nm0:find("ch253", 1, true) then
                        if comp_addr0 and ch0:get_address() == comp_addr0 then return end
                        if is_dead(ch0) then return end
