                        local d0 = u0 and dist(u0, pu0)
                        if d0 and d0 * d0 < bestw0 then bestw0 = d0 * d0; wgo0 = go0; wch0 = ch0 end
                    end
                end)
            end
        end)
        -- A PRE-SCENE HINT (07-18 -- ⛔ NO shield here anymore): the shield used to rise for ANY
        -- wild griffin in the scene sweep whenever court mode was on, so EVERY griffin near the
        -- player went peaceful, always (Aurora: one dived, didn't attack, and left -- "the guard
        -- was still up even with the reset"; the reset DID clear it, the tick just re-raised it on
        -- proximity). The shield now follows the SCENE (raised below, only once an offering is
        -- genuinely armed). This is just an informational nudge -- griffin wheels near AND oxen are
        -- about AND you're close = taming is possible. Throttled; wild griffins stay WILD until an
        -- offering is down.
        -- ⛔ only the AMBIENT nudge -- silent once a scene is live (07-20, Aurora: "stop the 'a wild
        -- griffin soars near' messages after the tame starts"). S.oxtame exists from the offering
        -- (bait) through the rodeo, so this hint only fires when nothing is underway yet.
        -- ⭐ TOWN HUSH (07-21, Aurora): no "soars near" flavor inside a town -- you can't stage an
        -- ox offering on a high street, so the card is pure noise there. Native one-call check
        -- (app.PawnUtil.isPlayerInTownArea, the ShutUpPawns geofence); read failure = not-in-town.
        local in_town0 = false
        pcall(function()
            in_town0 = sdk.find_type_definition("app.PawnUtil"):get_method("isPlayerInTownArea"):call(nil) == true
        end)
        if S.tame_mode == true and C.oxtame_soar_hint == true and C.oxtame_court ~= false
            and wgo0 and not S.oxtame and not in_town0 and not iris_griffin_resting(wgo0)
            and nowO >= (tonumber(S.oxtame_soar_at) or 0.0) then
            local ox_about0 = false
            pcall(function()
                for _, W1 in pairs(S.ox_watch or {}) do
                    if not W1.dead and W1.moved == true
                        and nowO - (tonumber(W1.alive) or 0.0) < 120.0 then ox_about0 = true; break end
                end
            end)
            local wu1 = upos(wgo0)
            if ox_about0 and wu1 and dist(wu1, pu0) < 500.0 then
                S.oxtame_soar_at = nowO + 180.0   -- taming mode only; at most once every three minutes
                -- ⭐ SAY WHAT SHE IS DOING (07-25, Aurora: "'a griffin soars near' when the griffin
                -- is sitting in its nest"). This fired on PROXIMITY alone. Ask her posture instead --
                -- and the roosting line quietly teaches the thing players most need to know: a
                -- griffin asleep on her nest will still answer an offering.
                local post1 = iris_griffin_posture(wch0)
                if post1 == "roost" or post1 == "ground" then
                    set_prompt("A GRIFFIN ROOSTS NEARBY", "It rests, for now. Even a sleeping hunger can be called -- with an offering worth the flight.", 7.0, 0xFFFFD080)
                else
                    set_prompt("A WILD GRIFFIN SOARS NEAR", "Stay your hand. If it hungers, an offering will call to it...", 7.0, 0xFFFFD080)
                end
                pcall(function() log.info(string.format("[OxTame] soars-near hint: %s at %.0fm", tostring(go_name(wgo0)), dist(wu1, pu0))) end)
            end
        end
        -- THE QUALIFICATION (Aurora's law: mercy is for the one who hunts FOR it) -- a fresh
        -- corpse only becomes the offering if it died ON YOUR WATCH, with a griffin loaded to
        -- SEE it, and the griffin was not standing on it (her own kill is no gift)
        if corpse0 and cgo0 and not (S.oxtame and S.oxtame.corpse_go) then
            local ok0 = false
            pcall(function()
                -- resolve the corpse's character address via its GameObject sweep entry
                local addr0 = nil
                pcall(function()
                    local cch0 = comp(cgo0, "app.Character")
                    addr0 = cch0 and cch0:get_address()
                end)
                local W0 = addr0 and S.ox_watch and S.ox_watch[addr0]
                if not W0 then return end   -- never seen alive on your watch = carrion, not a gift
                if not W0.dead then
