                    pcall(function() iris_play_trigger_on(st0.go, 655309512) end)
                    pcall(function() st0.ch:call("get_Motion"):call("set_PlaySpeed", 1.0) end)   -- un-freeze the lie pose
                    pcall(function() local b0 = _G.IrisGriffinBridge; if b0 and b0.oxtame_pin_release then b0.oxtame_pin_release() end end)
                    pcall(function() local fc0 = comp(st0.go, "app.FlightControl"); if fc0 then fc0:call("set_Enabled", true) end end)
                    pcall(function() local dm0 = comp(st0.go, "app.AIDecisionMaker"); if dm0 then dm0:call("set_Enabled", true) end end)
                    -- restore the ground authority the pact pin borrowed (see the pact keep-alive)
                    pcall(function() local gf0 = comp(st0.go, "app.GroundFixer"); if gf0 then gf0:call("set_Enabled", true) end end)
                    pcall(function() set_ai(st0.ch, true) end)
                    local sealed9 = false
                    pcall(function() local b0 = _G.IrisGriffinBridge; if b0 and b0.tame_creature then sealed9 = b0.tame_creature(st0.ch, st0.gender) == true end end)
                    S.name_pending = { kind = "stable", label = "griffin", gender = st0.gender }
                    S.name_buf = ""
                    set_prompt("THE PACT IS SEALED", ((st0.gender == "female") and "She" or "He") .. " is yours -- broken to no one, bound by choice. " .. ((st0.gender == "female") and "She" or "He") .. " takes a rider's size, and waits for a name.", 10.0, 0xFF80FFB0)
                    pcall(function() log.info("[OxTame] PACT sealed: tame_creature=" .. tostring(sealed9) .. " -> naming card") end)
                    S.oxtame = nil; S.oxtame_shield = nil
                    return
                end
            else
                st0.pact_palm = math.max(0.0, (tonumber(st0.pact_palm) or 0.0) - 0.35)
                if nowO >= (tonumber(st0.pact_say) or 0.0) then
                    st0.pact_say = nowO + 8.0
                    set_prompt("THE PACT WAITS", ((st0.gender == "female") and "She" or "He") .. " is spent and still. Stand before " .. ((st0.gender == "female") and "her" or "him") .. " and HOLD OUT YOUR HAND (hold N / B).", 8.0, 0xFFFFD080)
                end
            end
        elseif st0.stage == "flee" then
            -- ⭐⭐ FAIL = QUICK FLIGHT BURST -> FADE-TO-BLACK RESET (07-20, Aurora's design: "best of both
            -- worlds"). We stop FIGHTING the native flee: every past bug (re-dive, re-aggro, T-pose) came
            -- from letting her run loose near you AFTER the throw. Instead -- release her so she flaps up +
            -- banks away for a beat (the visible burst; NO forced node = NO T-pose), THEN send her far and
            -- TimeSkip-warp the player to solid ground behind a FADE-TO-BLACK = a clean reset. The fade
            -- fires BEFORE she can turn back, so the re-dive / re-aggro simply never get the chance. She's
            -- kept friended + disarmed through the short burst so she can't swing in the meantime.
            local gch = st0.ch; local ggo = st0.go
            local function iris_oxtame_fail_end()
                -- refuse THIS corpse for the cooldown (a FRESH kill still arms = the intended retry)
                local cd = tonumber(C.oxtame_fail_cooldown) or 60.0
                local caddr = nil
                pcall(function() caddr = st0.corpse_go and st0.corpse_go:get_address() end)
                if caddr then S.oxtame_declined = { addr = caddr, until_t = nowO + cd } end
                S.oxtame_soar_at = math.max(tonumber(S.oxtame_soar_at) or 0.0, nowO + cd)
                S.oxtame = nil; S.oxtame_shield = nil
            end
            if not (gch and char_go(gch)) then iris_oxtame_fail_end(); return end
            -- keep her harmless through the burst
            pcall(function() pacify_toward_party(gch) end)
            pcall(function() local b0 = _G.IrisGriffinBridge; if b0 and b0.oxtame_friend_world then b0.oxtame_friend_world(gch, 300.0) end end)
            pcall(function() local b0 = _G.IrisGriffinBridge; if b0 and b0.oxtame_disarm_target then b0.oxtame_disarm_target(gch) end end)
            local fdt = nowO - (tonumber(st0.flee_t0) or nowO)
            if not st0.flee_lifted then
                st0.flee_lifted = true
                -- release to native AI (un-puppet), then FIRE a travelling soar node so she actually
                -- BURSTS AWAY instead of hovering (Aurora 07-20: "it kind of hovered while it faded --
                -- I'd rather it fly off"). She's un-puppeted now, so the flight node animates (it only
                -- T-posed when fired on a puppeted body), and allow_flight is legal here (rider is off).
                pcall(function() local b0 = _G.IrisGriffinBridge; if b0 and b0.oxtame_release_wild then b0.oxtame_release_wild(gch) end end)
                pcall(function() local b0 = _G.IrisGriffinBridge; if b0 and b0.oxtame_buck then b0.oxtame_buck(gch, tostring(C.oxtame_flee_node or "Fly.Flight.Ch253SoaringFlight"), true) end end)
            end
            if fdt >= (tonumber(C.oxtame_flee_burst_secs) or 1.4) then
                -- THE RESET, behind the fade:
                -- 1) send her far so she's GONE when the black lifts
                pcall(function()
                    local gu = upos(ggo); local pu = upos(char_go(get_player()))
                    if gu then
                        local dx = (tonumber(gu.x) or 0.0) - (pu and tonumber(pu.x) or 0.0)
                        local dz = (tonumber(gu.z) or 0.0) - (pu and tonumber(pu.z) or 0.0)
                        local dl = math.max(1.0, math.sqrt(dx * dx + dz * dz))
                        local pv = ValueType.new(sdk.find_type_definition("via.Position"))
                        pv.x = (tonumber(gu.x) or 0.0) + dx / dl * (tonumber(C.oxtame_flee_dist) or 350.0)
                        pv.y = (tonumber(gu.y) or 0.0) + (tonumber(C.oxtame_flee_up) or 200.0)
                        pv.z = (tonumber(gu.z) or 0.0) + dz / dl * (tonumber(C.oxtame_flee_dist) or 350.0)
                        set_upos(ggo, pv)
                    end
                end)
                -- 2) zero the player's stamina so the native climb lets go for sure, then TimeSkip-warp
                --    the player onto solid ground = the fade-to-black cover (breaks the climb cleanly)
                pcall(function() local sm9 = get_player() and get_player():call("get_StaminaManager"); if sm9 then sm9:call("set_RemainingAmount", 0.0) end end)
                pcall(function()
                    local pgo9 = char_go(get_player()); local pp9 = pgo9 and upos(pgo9)
                    if pp9 then
                        local gy9 = tonumber(pp9.y) or 0.0
                        local hb9 = ground_probe(pp9.x, pp9.y + 2.0, pp9.z)
                        if not (hb9 and tonumber(hb9.y)) then
                            pcall(function()
                                local b0 = _G.IrisGriffinBridge
                                local gb = b0 and b0.ground_below and b0.ground_below(pp9.x, pp9.y + 2.0, pp9.z, 8.0, 500.0)
                                if gb and tonumber(gb.y) then hb9 = gb end
                            end)
                        end
                        if hb9 and tonumber(hb9.y) then gy9 = tonumber(hb9.y) end
                        iris_warp_player(pp9.x, gy9 + 0.5, pp9.z)
                    end
                end)
                pcall(function() log.info("[OxTame] flee: burst done -> fade-to-black reset (griffin sent off, player grounded, scene cleared)") end)
                iris_oxtame_fail_end()
                return
            end
        end
    end)
    if not okT9 and not S.oxtame_err then
        -- a dying tick must CONFESS (the 00:21 silence): once per session
        S.oxtame_err = true
        pcall(function() log.info("[OxTame] TICK ERROR: " .. tostring(errT9)) end)
    end
end)

-- RODEO INPUT INTEGRATOR. The courtship tick above is intentionally throttled because it
-- performs expensive native/scene probes. Grip used to inherit that 0.7-second throttle:
-- one sampled frame of LT or attack was billed as though it lasted the whole interval.
-- Account the controls every game frame; the slow tick keeps phase changes and outcomes.
re.on_application_entry("UpdateBehavior", function()
    pcall(function()
        local st = S.oxtame
        local now = os.clock()
        if not (st and st.stage == "rodeo" and st.duel_init) then
            S.oxtame_input_last = now
            return
        end
        if is_game_paused() then
            S.oxtame_input_last = now
            return
        end
        local dt = math.max(0.0,
            math.min(0.10, now - (tonumber(S.oxtame_input_last) or now)))
        S.oxtame_input_last = now
        if dt <= 0.0 then return end
        local braced, striking = false, false
        pcall(function() braced = (iris_kb(0x4E) == true) or iris_lt_down() end)
        pcall(function() striking = iris_player_is_attacking() == true end)
        local grip = tonumber(st.grip) or 1.0
        local tsmax = math.max(0.1, tonumber(C.oxtame_tame_stam) or 5.0)
        local tame_stam = tonumber(st.tame_stam) or tsmax
        if st.duel_phase == "buck" then
            local rate = braced and (tonumber(C.oxtame_grip_buck_drain) or 0.14)
                or (tonumber(C.oxtame_grip_slip_drain) or 0.40)
            grip = grip - rate * dt
        elseif striking then
            tame_stam = tame_stam - (tonumber(C.oxtame_break_rate) or 1.0) * dt
            grip = grip - (tonumber(C.oxtame_strike_grip_rate) or 0.12) * dt
        elseif not braced then
            grip = grip + (tonumber(C.oxtame_grip_recover) or 0.25) * dt
        end
        st.grip = math.max(0.0, math.min(1.0, grip))
        st.tame_stam = math.max(0.0, math.min(tsmax, tame_stam))
        _G.IrisRodeoHUD = {
            active = true, t = now, grip = st.grip,
            brk = math.max(0.0, math.min(1.0, 1.0 - st.tame_stam / tsmax)),
            phase = tostring(st.duel_phase), striking = striking,
        }
    end)
end)

-- ============== THE SHATTER ENGINE (4 shell fragments from the IRIS pak; pooled + scripted ballistics) ==============
local EGG_SHELLS = { "shell_a", "shell_b", "shell_c", "shell_d" }

local function iris_play_trigger_on(go0, id0, src0)
    -- the browser's RELIABLE route (Nick's recipe): find the trigger BY ID in a body's banks
    -- and fire it through createRequestInfo -- some triggers (job/skill sfx) only answer this,
    -- not a raw triggerLogLess. Resolution cached per id.
    -- src0 (optional) = the body whose BANKS hold the trigger; go0 = where it RINGS. Nick's
    -- player proves the split: trigger from the SOURCE list, target passed to createRequestInfo
    -- (Aurora's scout ids live in the PLAYER's banks, not the rabbit's -- 07-15 silence).
    if not (go0 and id0 and id0 > 0) then return false end
    local ok0 = false
    pcall(function()
        local bank0 = src0 or go0
        local wwise0 = comp(bank0, "app.WwiseContainerApp")
        local cont0 = comp(bank0, "soundlib.SoundContainer")
        if not (wwise0 and cont0) then return end
        S.snd_trig_cache = S.snd_trig_cache or {}
        local hit0 = S.snd_trig_cache[id0]
        local trig0 = nil
        if hit0 then
            pcall(function()
                trig0 = wwise0._UserDataList[hit0.u]._UserDataList[hit0.s]._TriggerInfoList[hit0.t]
                if trig0 and trig0._TriggerId ~= id0 then trig0 = nil end
            end)
        end
        if not trig0 then
            local ul0 = wwise0._UserDataList
            for u0 = 0, ul0:get_Count() - 1 do
                local sl0 = nil
                pcall(function() sl0 = ul0[u0]._UserDataList end)
                for s0 = 0, (sl0 and sl0:get_Count() or 0) - 1 do
                    local tl0 = nil
                    pcall(function() tl0 = sl0[s0]._TriggerInfoList end)
                    for t0 = 0, (tl0 and tl0:get_Count() or 0) - 1 do
                        local cand0 = nil
                        pcall(function() cand0 = tl0[t0] end)
                        if cand0 and cand0._TriggerId == id0 then
                            trig0 = cand0
                            S.snd_trig_cache[id0] = { u = u0, s = s0, t = t0 }
                            break
                        end
                    end
                    if trig0 then break end
                end
                if trig0 then break end
            end
        end
        if not trig0 then return end
        local ri0 = cont0:call("createRequestInfo(soundlib.SoundTriggerInfo, via.GameObject, via.GameObject, System.UInt32, System.Boolean, System.Boolean, System.UInt32, via.simplewwise.CallbackType, System.Action`1<soundlib.SoundManager.RequestInfo>, System.Action`1<soundlib.SoundManager.RequestInfo>, System.Action`1<soundlib.SoundManager.RequestInfo>, System.Action`1<soundlib.SoundManager.RequestInfo>)",
            trig0, go0, go0, trig0._OffsetJointHash, false, false, 0, 0, nil, nil, nil, nil)
        if ri0 then
            ri0 = ri0:add_ref()
            ri0["<Container>k__BackingField"] = cont0
            cont0:call("trigger(soundlib.SoundManager.RequestInfo)", ri0)
            ok0 = true
        end
    end)
    return ok0
end
re.on_application_entry("UpdateBehavior", function()
    pcall(function()
        local F = S.eggfx
        if not F then return end
        local nowF = os.clock()
        if F.stage == "spawn" then
            if not S.iris_reaped then return end   -- the reaper sweeps old shells first
            -- build the POOL once. ⛔ STREAMING LAW (MaterialNum 0,0,0,0 -- image 55): meshes only
            -- stream in NEAR the camera, so the pool must live AT the player -- hidden via
            -- DrawSelf=false, never parked far away
            local player8 = get_player()
            local pgo8 = player8 and char_go(player8)
            local pp8 = pgo8 and pgo8:call("get_Transform"):call("get_Position")
            if not pp8 then return end
            F.frags = {}
            for i, nm in ipairs(EGG_SHELLS) do
                local go9
                pcall(function()
                    go9 = sdk.find_type_definition("via.GameObject"):get_method("create(System.String)"):call(nil, "IrisEggShell_" .. nm)
                end)
                if go9 then
                    pcall(function() go9 = go9:add_ref() end)
                    pcall(function() go9:call("set_DrawSelf", false) end)   -- hidden, not far away
                    pcall(function() go9:call("set_UpdateSelf", true) end)
                    local mc9
                    pcall(function() mc9 = go9:call("createComponent(System.Type)", sdk.typeof("via.render.Mesh")) end)
                    pcall(function()
                        local v9 = ValueType.new(sdk.find_type_definition("via.vec3"))
                        v9.x = pp8.x; v9.y = pp8.y; v9.z = pp8.z
                        go9:call("get_Transform"):call("set_Position", v9)
                    end)
                    F.frags[i] = { go = go9, mc = mc9, held = {}, nm = nm, hidden = true }
                end
            end
            F.stage = "bind"; F.at = nowF
        elseif F.stage == "bind" and nowF > (tonumber(F.at) or 0.0) then
            -- pak sanity FIRST: shells only exist in IRIS v1.1+ -- a stale mounted pak
            -- (no full game restart after the Fluffy swap) binds nothing, silently
            local probe9 = nil
            pcall(function() probe9 = sdk.create_resource("via.render.MeshResource", "custom_tex/iris/shell_a.mesh") end)
            if not probe9 then
                F.msg = "shell meshes NOT in the mounted pak -- v1.1 installed? game FULLY restarted after the swap?"
                F.stage = "idle"; F.want = nil
                S.status = "egg burst: " .. F.msg
                return
            end
            F.msg = "shards binding..."
            for _, fr in ipairs(F.frags) do
                pcall(function()
                    local base9 = "custom_tex/iris/" .. fr.nm
                    local res9 = sdk.create_resource("via.render.MeshResource", base9 .. ".mesh"):add_ref()
                    fr.held[#fr.held + 1] = res9
                    local hold9 = res9:create_holder("via.render.MeshResourceHolder"):add_ref()
                    fr.held[#fr.held + 1] = hold9
                    if not pcall(function() fr.mc:call("setMesh", hold9) end) then fr.mc:call("set_Mesh", hold9) end
                    local mt9 = sdk.create_resource("via.render.MeshMaterialResource", base9 .. ".mdf2"):add_ref()
                    fr.held[#fr.held + 1] = mt9
                    local mh9 = mt9:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                    fr.held[#fr.held + 1] = mh9
                    if not pcall(function() fr.mc:call("set_Material", mh9) end) then fr.mc:call("setMaterial", mh9) end
                end)
            end
            F.stage = "cure"; F.at = nowF + 1.2
        elseif F.stage == "cure" and nowF >= (tonumber(F.at) or 0.0) then
            local mns = {}
            for _, fr in ipairs(F.frags) do
                pcall(function()
                    local base9 = "custom_tex/iris/" .. fr.nm
                    local res9 = sdk.create_resource("via.render.MeshResource", base9 .. ".mesh"):add_ref()
                    fr.held[#fr.held + 1] = res9
                    local hold9 = res9:create_holder("via.render.MeshResourceHolder"):add_ref()
                    fr.held[#fr.held + 1] = hold9
                    if not pcall(function() fr.mc:call("setMesh", hold9) end) then fr.mc:call("set_Mesh", hold9) end
                    local mt9 = sdk.create_resource("via.render.MeshMaterialResource", base9 .. ".mdf2"):add_ref()
                    fr.held[#fr.held + 1] = mt9
                    local mh9 = mt9:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                    fr.held[#fr.held + 1] = mh9
                    if not pcall(function() fr.mc:call("set_Material", mh9) end) then fr.mc:call("setMaterial", mh9) end
                end)
                pcall(function() mns[#mns + 1] = tostring(fr.mc:call("get_MaterialNum")) end)
            end
            F.stage = "ready"
            F.msg = "shards READY (MaterialNum: " .. table.concat(mns, ",") .. ")"
            S.status = "egg shards warmed (MaterialNum: " .. table.concat(mns, ",") .. ")"
        elseif F.stage == "ready" then
            -- idle pool RIDES with the player (hidden) so its meshes stay streamed-in
            if not F.burst and nowF >= (tonumber(F.follow_at) or 0.0) then
                F.follow_at = nowF + 1.0
                pcall(function()
                    local player8 = get_player()
                    local pgo8 = player8 and char_go(player8)
                    local pp8 = pgo8 and pgo8:call("get_Transform"):call("get_Position")
                    if not pp8 then return end
                    for _, fr in ipairs(F.frags) do
                        if fr.hidden then
                            local v9 = ValueType.new(sdk.find_type_definition("via.vec3"))
                            v9.x = pp8.x; v9.y = pp8.y; v9.z = pp8.z
                            fr.go:call("get_Transform"):call("set_Position", v9)
                        end
                    end
                end)
            end
            -- a queued burst fires the moment the pool is warm; a NEW want INTERRUPTS any
            -- burst still resting/sinking (20s shard-life made re-clicks look dead)
            if F.want then
                local W = F.want; F.want = nil
                F.burst = { ground = tonumber(W.y) or 0.0, last = nowF }
                local pw = tonumber(C.egg_burst_power) or 3.9
                for i, fr in ipairs(F.frags) do
                    fr.hidden = nil; fr.rest = nil; fr.bounced = nil
                    pcall(function() fr.go:call("set_DrawSelf", true) end)
                    fr.q = { x = 0, y = 0, z = 0, w = 1 }
                    local ang = (i - 1) * 1.65 + math.random() * 0.8
                    fr.vx = math.cos(ang) * pw * (0.5 + math.random() * 0.6)
                    fr.vz = math.sin(ang) * pw * (0.5 + math.random() * 0.6)
                    fr.vy = pw * (0.8 + math.random() * 0.7) * (i == 1 and 1.25 or 1.0)   -- the crown pops highest
                    local sx, sy2, sz = math.random() - 0.5, math.random() - 0.5, math.random() - 0.5
                    local sl = math.sqrt(sx * sx + sy2 * sy2 + sz * sz)
                    if sl < 0.01 then sx, sl = 1.0, 1.0 end
                    fr.ax, fr.ay, fr.az = sx / sl, sy2 / sl, sz / sl
                    fr.spin = 5.0 + math.random() * 6.0
                    pcall(function()
                        local tf9 = fr.go:call("get_Transform")
                        local v9 = ValueType.new(sdk.find_type_definition("via.vec3"))
                        v9.x = W.x; v9.y = W.y + 0.18; v9.z = W.z
                        tf9:call("set_Position", v9)
                        local sc9 = tonumber(C.egg_scale) or 0.54
                        local sv9 = ValueType.new(sdk.find_type_definition("via.vec3"))
                        sv9.x = sc9; sv9.y = sc9; sv9.z = sc9
                        if not pcall(function() tf9:call("set_LocalScale", sv9) end) then tf9:call("set_Scale", sv9) end
                        local qv9 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                        qv9.x = 0; qv9.y = 0; qv9.z = 0; qv9.w = 1
                        tf9:call("set_Rotation", qv9)
                    end)
                end
                local sid9 = math.floor(tonumber(C.egg_crack_sound_id) or 0)
                if sid9 > 0 then
                    local pgo0 = char_go(get_player())
                    if not iris_play_trigger_on(pgo0, sid9) then
                        pcall(function() play_player_wwise(get_player(), sid9) end)   -- raw-id fallback
                    end
                end
            end
            -- BALLISTICS: integrate, bounce once, rest, sink away
            local B2 = F.burst
            if B2 then
                local dt = math.min(0.05, nowF - (tonumber(B2.last) or nowF))
                B2.last = nowF
                local life = tonumber(C.egg_shard_life) or 6.0
                local alldone = true
                for _, fr in ipairs(F.frags) do
                    if not fr.hidden then
                        alldone = false
                        pcall(function()
                            local tf9 = fr.go:call("get_Transform")
                            local p9 = tf9:call("get_Position")
                            if not fr.rest then
                                fr.vy = fr.vy - 9.8 * dt
                                p9.x = p9.x + fr.vx * dt
                                p9.y = p9.y + fr.vy * dt
                                p9.z = p9.z + fr.vz * dt
                                if p9.y <= B2.ground and fr.vy < 0 then
                                    p9.y = B2.ground
                                    if not fr.bounced and math.abs(fr.vy) > 1.2 then
                                        fr.bounced = true
                                        fr.vy = -fr.vy * 0.25; fr.vx = fr.vx * 0.55; fr.vz = fr.vz * 0.55
                                    else
                                        fr.rest = nowF
                                    end
                                end
                                tf9:call("set_Position", p9)
                                local half9 = fr.spin * dt * 0.5
                                local s9 = math.sin(half9)
                                fr.q = qmul({ x = fr.ax * s9, y = fr.ay * s9, z = fr.az * s9, w = math.cos(half9) }, fr.q)
                                local qv9 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                                qv9.x = fr.q.x; qv9.y = fr.q.y; qv9.z = fr.q.z; qv9.w = fr.q.w
                                tf9:call("set_Rotation", qv9)
                            elseif nowF - fr.rest > life then
                                p9.y = p9.y - 0.22 * dt   -- sink away instead of popping out
                                tf9:call("set_Position", p9)
                                if nowF - fr.rest > life + 1.4 then
                                    fr.hidden = true
                                    pcall(function() fr.go:call("set_DrawSelf", false) end)   -- back to the invisible pool
                                end
                            end
                        end)
                    end
                end
                if alldone then F.burst = nil end   -- the pool survives for the next death
            end
        end
    end)
end)

-- ============== THE NEST WORLD (bowls at flagged survey spots + a live egg in the nearest nest) ==============
re.on_application_entry("UpdateBehavior", function()
    pcall(function()
        -- THE REAPER: our display GOs (bowls / shells / test eggs) SURVIVE script resets --
        -- the lua refs die but the engine objects persist (the lingering bone pile). Sweep
        -- previous runs' leftovers ONCE, before this run spawns its own.
        if not S.iris_reaped then
            if not S.iris_reap_at then S.iris_reap_at = os.clock() + 5.0 end
            if os.clock() >= S.iris_reap_at then
                S.iris_reaped = true
                pcall(function()
                    local sm9 = sdk.get_native_singleton("via.SceneManager")
                    local smt9 = sdk.find_type_definition("via.SceneManager")
                    local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
                    local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("via.render.Mesh"))
                    local n9 = 0
                    pcall(function() n9 = comps9:call("get_Length") or 0 end)
                    if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
                    local reaped9 = 0
                    for i9 = 0, (tonumber(n9) or 0) - 1 do
                        pcall(function()
                            local go9 = (comps9:call("get_Item", i9) or comps9[i9]):call("get_GameObject")
                            local nm9 = tostring(go_name(go9))
                            -- PREFIX match: the engine suffixes duplicate GO names (IrisNestBowl.001...)
                            -- so exact equality let old nests pile up into a stick carpet (image 79)
                            local kill9 = nm9:find("^IrisNestBowl") or nm9:find("^IrisTestEgg") or nm9:find("^IrisEggShell_")
                                or nm9:find("^IrisMound") or nm9:find("^IrisBurrowFx") or nm9:find("^IrisEfxAudition")
                            -- leftover NEST EGGS from a previous run: gm80_009 bodies parked within
                            -- 12m of a surveyed nest (the two-egg pileup -- image 71)
                            if not kill9 and nm9:find("gm80_009", 1, true) then
                                pcall(function()
                                    local eu9 = upos(go9)
                                    for _, n9 in ipairs(nests_load()) do
                                        local dx9, dy9, dz9 = eu9.x - (n9.x or 0), eu9.y - (n9.y or 0), eu9.z - (n9.z or 0)
                                        if (dx9 * dx9 + dy9 * dy9 + dz9 * dz9) < 144.0 then kill9 = true; break end
                                    end
                                end)
                            end
                            if kill9 then
                                go9:call("destroy", go9)
                                reaped9 = reaped9 + 1
                            end
                        end)
                    end
                    if reaped9 > 0 then
                        pcall(function() log.info("[IrisTaming] reaped " .. tostring(reaped9) .. " leftover display props from a previous run") end)
                    end
                end)
            end
        end
    end)
    pcall(function()
        if C.egg_world ~= true then return end
        if not S.iris_reaped then return end   -- never spawn before the reaper has swept
        -- BOOT GRACE, anchored to the PLAYER (clock-from-script-load expired at the MAIN MENU
        -- and spawns still fired into the loading fade): 12s after the Arisen truly exists
        if not S.nw_player_seen then
            local pboot = get_player()
            if pboot and char_go(pboot) then
                S.nw_player_seen = os.clock()
                -- WARM every IRIS resource NOW ("cold resources lie" -- the all-MatNum=0 fresh
                -- boot, image 83): held refs get the whole 12s grace to become real
                S.nw_warm_refs = {}
                for _, b9 in ipairs({
                    "custom_tex/iris/griffin_egg",
                    "custom_tex/iris/shell_a", "custom_tex/iris/shell_b",
                    "custom_tex/iris/shell_c", "custom_tex/iris/shell_d",
                    "environment/props/sm5x/sm51/sm51_581/sm51_581_00",
                    "environment/props/sm5x/sm51/sm51_582/sm51_582_00",
                    "environment/props/sm5x/sm52/sm52_118/sm52_118_00",
                    "environment/props/sm8x/sm80/sm80_009/sm80_009_00",   -- the burrow mound lump
                }) do
                    pcall(function() S.nw_warm_refs[#S.nw_warm_refs + 1] = sdk.create_resource("via.render.MeshResource", b9 .. ".mesh"):add_ref() end)
                    pcall(function() S.nw_warm_refs[#S.nw_warm_refs + 1] = sdk.create_resource("via.render.MeshMaterialResource", b9 .. ".mdf2"):add_ref() end)
                end
                -- ⛔ ORPHANED-EGG REAPER (Aurora: script-reset DUPLICATED the egg). A script reset
                -- wipes S.eggs but LEAVES the physical egg gimmick in the world -> respawn then adds
                -- a SECOND on top. On fresh boot, delete EVERY leftover egg body (S.eggs is empty
                -- here, so all are orphans); the ledger respawns exactly one.
                local reaped7 = iris_reap_eggs_near(nil)
                if reaped7 > 0 then S.status = string.format("cleared %d leftover egg(s) from the last session", reaped7) end
            end
            return
        end
        -- SAVE-LOAD WATCH (Aurora: "reloaded saves have no eggs"): a reload rebuilds the world;
        -- stale egg bodies read as DIED and each corpse counted AGAINST its clutch (taken++),
        -- so nests sat empty until the 5-hour re-roll. A new player GO address = a new world:
        -- start the egg world fresh (clutches re-roll, stale eggs forgotten, new boot grace).
        pcall(function()
            local pgo0 = char_go(get_player())
            if not pgo0 then return end
            local addr0 = tostring(pgo0:get_address())
            if S.nw_player_addr == nil then
                S.nw_player_addr = addr0
            elseif S.nw_player_addr ~= addr0 then
                S.nw_player_addr = addr0
                -- release every old registration BEFORE forgetting the list (Lyra's law --
                -- dangling generated-instance registrations were THE nest-crash after reload)
                for _, E0 in ipairs(S.eggs or {}) do iris_egg_dispose(E0) end
                S.eggs = {}
                S.carried_egg = nil
                S.egg_break = nil
                S.nw_nests = {}
                S.egg_prefab_cache = {}
                S.egg_prewarmed = false
                S.heist_prev_ce = nil
                S.heist_marker = nil
                S.nw_player_seen = os.clock()   -- fresh grace: the rebuilt world needs its 12s
                -- re-read the egg-world from disk + reconcile it against the loaded save's clock
                -- (an older save undoes future incubations -- Aurora's save-rollback ask)
                S.eggworld = nil
                S.heist_prev_ce = nil
                S.status = "world reloaded -- the clutches roll anew"
            end
        end)
        if os.clock() < (tonumber(S.nw_player_seen) or 0.0) + 12.0 then return end
        local nowN = os.clock()
        -- scan (throttled): who is close enough to exist?
        if nowN >= (tonumber(S.nw_scan_at) or 0.0) then
            S.nw_scan_at = nowN + 1.5
            local player9 = get_player()
            local pgo9 = player9 and char_go(player9)
            local pu9 = pgo9 and upos(pgo9)
            if pu9 then
                S.nw_props = S.nw_props or {}
                S.egg_taken = S.egg_taken or {}
                -- SELF-HEAL + THE ROBBERY LEDGER (per egg): failed births vanish (the clutch
                -- retries), broken/stolen eggs count against their nest's roll
                S.nw_nests = S.nw_nests or {}
                for ei9 = #(S.eggs or {}), 1, -1 do
                    local E9 = S.eggs[ei9]
                    if E9.stage == "done" and not E9.go and not E9.dead then
                        iris_egg_dispose(E9)        -- failed births release their registration too
                        table.remove(S.eggs, ei9)   -- streaming rejected the birth
                    elseif E9.nest_key and E9.dead and not E9.counted then
                        E9.counted = true
                        if not E9.stolen then
                            local led9 = S.nw_nests[E9.nest_key]
                            if led9 then led9.taken = (led9.taken or 0) + 1 end
                        end
                    elseif E9.nest_key and not E9.stolen and E9.was_carried and E9.go and E9.home then
                        pcall(function()
                            local eu9 = upos(E9.go)
                            local ex9, ey9, ez9 = eu9.x - E9.home.x, eu9.y - E9.home.y, eu9.z - E9.home.z
                            if (ex9 * ex9 + ey9 * ey9 + ez9 * ez9) > 225.0 then
                                E9.stolen = true
                                local led9 = S.nw_nests[E9.nest_key]
                                if led9 then led9.taken = (led9.taken or 0) + 1 end
                                S.status = "the egg leaves the nest -- walk carefully"
                            end
                        end)
                    end
                end
                for _, n9 in ipairs(nests_load()) do
                    pcall(function()
                        local key9 = string.format("%d_%d", math.floor(tonumber(n9.x) or 0), math.floor(tonumber(n9.z) or 0))
                        local dx9, dy9, dz9 = (n9.x or 0) - pu9.x, (n9.y or 0) - pu9.y, (n9.z or 0) - pu9.z
                        local d9 = math.sqrt(dx9 * dx9 + dy9 * dy9 + dz9 * dz9)
                        if d9 < 130.0 then
                            -- the BOWL: flagged spots grow a nest (display prop, universal-anchored)
                            -- + BONE-PILE dressing. Aurora's rule: if a NATIVE nest already stands
                            -- here (fingerprint = its sm51 bone-pile props), spawn EGGS ONLY.
                            -- Probe close (60m) so the area's props are actually streamed in.
                            if n9.bowl and not S.nw_props[key9] and d9 < 60.0 then
                                local native9 = 0
                                pcall(function()
                                    local sm9 = sdk.get_native_singleton("via.SceneManager")
                                    local smt9 = sdk.find_type_definition("via.SceneManager")
                                    local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
                                    local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("via.render.Mesh"))
                                    local nn9 = 0
                                    pcall(function() nn9 = comps9:call("get_Length") or 0 end)
                                    if nn9 == 0 then pcall(function() nn9 = comps9:get_size() or 0 end) end
                                    for ii9 = 0, (tonumber(nn9) or 0) - 1 do
                                        pcall(function()
                                            local mc0 = comps9:call("get_Item", ii9) or comps9[ii9]
                                            local res0 = mc0 and (mc0:call("getMesh") or mc0:call("get_Mesh"))
                                            local pth0 = nil
                                            pcall(function() pth0 = tostring(res0:call("get_ResourcePath")) end)
                                            local real0 = pth0 and pth0:find("sm52_118", 1, true)   -- the REAL nest asset = instant native
                                            if pth0 and (real0 or pth0:find("sm51_581", 1, true) or pth0:find("sm51_582", 1, true)) then
                                                local go0 = mc0:call("get_GameObject")
                                                if tostring(go_name(go0)):find("^Iris") then return end   -- not our own dressing
                                                local eu0 = upos(go0)
                                                local dxb, dyb, dzb = eu0.x - (n9.x or 0), eu0.y - (n9.y or 0), eu0.z - (n9.z or 0)
                                                if (dxb * dxb + dyb * dyb + dzb * dzb) < 100.0 then native9 = native9 + (real0 and 2 or 1) end
                                            end
                                        end)
                                    end
                                end)
                                if native9 >= 2 then
                                    -- the real nest stands here (quest-spawned, e.g. Dragonsbreath):
                                    -- honor it; eggs still come from the clutch
                                    S.nw_props[key9] = { stage = "native" }
                                else
                                    S.nw_props[key9] = { stage = "spawn", nx = n9.x, ny = n9.y, nz = n9.z }
                                for bi9 = 1, 3 do
                                    local ba9 = bi9 * 2.09 + (tonumber(n9.x) or 0) * 0.7
                                    local br9 = 1.0 + (bi9 % 2) * 0.8
                                    S.nw_props[key9 .. "_bone" .. tostring(bi9)] = {
                                        stage = "spawn",
                                        nx = (tonumber(n9.x) or 0) + math.cos(ba9) * br9,
                                        ny = n9.y,
                                        nz = (tonumber(n9.z) or 0) + math.sin(ba9) * br9,
                                        mesh = (bi9 == 2) and "environment/props/sm5x/sm51/sm51_582/sm51_582_00"
                                            or "environment/props/sm5x/sm51/sm51_581/sm51_581_00",
                                        scale = 1.0,
                                    }
                                end
                                end
                            end
                            -- THE CLUTCH: each nest rolls 0-3 eggs; robbed/broken count against
                            -- the roll; an emptied nest re-rolls after egg_reroll_mins
                            if d9 < 100.0 then
                                local led9 = S.nw_nests[key9]
                                if not led9 then
                                    led9 = { roll = math.random(0, 3), taken = 0, rolled_at = nowN }
                                    S.nw_nests[key9] = led9
                                end
                                local live9 = 0
                                for _, E9 in ipairs(S.eggs or {}) do
                                    if E9.nest_key == key9 and not E9.dead and not E9.stolen then live9 = live9 + 1 end
                                end
                                if led9.rolled_igh == nil then led9.rolled_igh = iris_igh() or false end
                                local elapsed_ok9
                                local igh9 = iris_igh()
                                if igh9 and led9.rolled_igh and led9.rolled_igh ~= false then
                                    elapsed_ok9 = (igh9 - led9.rolled_igh) >= (tonumber(C.egg_reroll_hours) or 5.0)
                                else
                                    elapsed_ok9 = (nowN - (tonumber(led9.rolled_at) or 0.0)) > (tonumber(C.egg_reroll_mins) or 20) * 60.0
                                end
                                if live9 == 0 and led9.taken >= (led9.roll or 0) and elapsed_ok9 then
                                    led9.roll = math.random(0, 3); led9.taken = 0
                                    led9.rolled_at = nowN; led9.rolled_igh = iris_igh() or false
                                end
                                if live9 < math.max(0, (led9.roll or 0) - (led9.taken or 0))
                                    and nowN >= (tonumber(S.nw_egg_spawn_at) or 0.0) then
                                    S.nw_egg_spawn_at = nowN + 4.0   -- stagger births
                                    local ea9 = (live9 + (led9.taken or 0)) * 2.4 + (tonumber(n9.x) or 0)
                                    local ex9 = (tonumber(n9.x) or 0) + math.cos(ea9) * 0.9
                                    local ez9 = (tonumber(n9.z) or 0) + math.sin(ea9) * 0.9
                                    iris_reap_eggs_near(ex9, (tonumber(n9.y) or 0) + 0.3, ez9, 1.2)   -- no clutch duplicate
                                    S.eggs = S.eggs or {}
                                    S.eggs[#S.eggs + 1] = { stage = "prefab",
                                        nest_key = key9,
                                        home = { x = n9.x, y = n9.y, z = n9.z },
                                        target = { x = (tonumber(n9.x) or 0) + math.cos(ea9) * 0.9,
                                                   y = (tonumber(n9.y) or 0) + 0.3,
                                                   z = (tonumber(n9.z) or 0) + math.sin(ea9) * 0.9 } }
                                    S.status = "an egg rests in the nest (" .. tostring(n9.label or key9) .. ")"
                                end
                            end
                        end
                    end)
                end
                -- bowls hold their universal spot through tile streaming (re-assert, cheap)
                for _, pr9 in pairs(S.nw_props) do
                    if pr9.stage == "done" and pr9.go then
                        pcall(function()
                            local base_y9 = (pr9.gy ~= false and pr9.gy) or tonumber(pr9.ny) or 0
                            local sink9 = pr9.mesh and 0.03 or (tonumber(C.nest_bowl_sink) or -0.02)
                            local v9 = ValueType.new(sdk.find_type_definition("via.Position"))
                            v9.x = pr9.nx; v9.y = base_y9 + sink9; v9.z = pr9.nz
                            set_upos(pr9.go, v9)
                        end)
                    end
                end

            end
        end
        -- bowl prop machine: display-GO phases (spawn -> bind next frame -> cure)
        for _, pr9 in pairs(S.nw_props or {}) do
            pcall(function()
                if pr9.stage == "spawn" then
                    if nowN < (tonumber(pr9.at) or 0.0) then return end
                    local go9
                    pcall(function()
                        go9 = sdk.find_type_definition("via.GameObject"):get_method("create(System.String)"):call(nil, "IrisNestBowl")
                    end)
                    if not go9 then
                        -- cold-load whiffs RETRY instead of dying (the missing-nest-on-load bug)
                        pr9.tries = (tonumber(pr9.tries) or 0) + 1
                        if pr9.tries < 8 then pr9.at = nowN + 8.0 else pr9.stage = "dead"; pr9.err = "GO create failed 8x" end
                        return
                    end
                    pcall(function() go9 = go9:add_ref() end)
                    pcall(function() go9:call("set_DrawSelf", true) end)
                    pcall(function() go9:call("set_UpdateSelf", true) end)
                    local mc9
                    pcall(function() mc9 = go9:call("createComponent(System.Type)", sdk.typeof("via.render.Mesh")) end)
                    pcall(function()
                        -- GROUND-SNAP (the floating nest): the logged y can be a mid-air rest node;
                        -- the terrain below is the truth
                        if pr9.gy == nil then
                            local hit9 = ground_probe(pr9.nx, (tonumber(pr9.ny) or 0) + 2.0, pr9.nz)
                            pr9.gy = (hit9 and tonumber(hit9.y)) or false
                        end
                        local base_y9 = (pr9.gy ~= false and pr9.gy) or tonumber(pr9.ny) or 0
                        local sink9 = pr9.mesh and 0.03 or (tonumber(C.nest_bowl_sink) or -0.02)
                        local v9 = ValueType.new(sdk.find_type_definition("via.Position"))
                        v9.x = pr9.nx; v9.y = base_y9 + sink9; v9.z = pr9.nz
                        set_upos(go9, v9)
                        local sc9 = tonumber(pr9.scale) or tonumber(C.nest_bowl_scale) or 1.0
                        local sv9 = ValueType.new(sdk.find_type_definition("via.vec3"))
                        sv9.x = sc9; sv9.y = sc9; sv9.z = sc9
                        local t2 = go9:call("get_Transform")
                        if not pcall(function() t2:call("set_LocalScale", sv9) end) then t2:call("set_Scale", sv9) end
                    end)
                    pr9.go = go9; pr9.mc = mc9; pr9.held = {}
                    pr9.stage = "bind"; pr9.at = nowN
                elseif pr9.stage == "bind" and nowN > (tonumber(pr9.at) or 0.0) then
                    local base9 = pr9.mesh or C.nest_bowl_mesh or "environment/props/sm5x/sm52/sm52_118/sm52_118_00"   -- dressing props override (bones); the nest = the REAL Capcom asset
                    local probe9 = nil
                    pcall(function() probe9 = sdk.create_resource("via.render.MeshResource", base9 .. ".mesh") end)
                    if not probe9 then
                        -- transient at cold load -- retry; only a persistent miss means a bad pak
                        pr9.tries = (tonumber(pr9.tries) or 0) + 1
                        if pr9.tries < 8 then
                            pr9.at = nowN + 8.0
                            pr9.err = "mesh not loadable yet, retrying (" .. tostring(pr9.tries) .. "/8)"
                        else
                            pr9.err = "mesh NOT loadable: " .. base9 .. " (is the IRIS pak installed?)"
                            pr9.stage = "done"
                        end
                        return
                    end
                    pr9.err = nil
                    pcall(function()
                        local res9 = sdk.create_resource("via.render.MeshResource", base9 .. ".mesh"):add_ref()
                        pr9.held[#pr9.held + 1] = res9
                        local hold9 = res9:create_holder("via.render.MeshResourceHolder"):add_ref()
                        pr9.held[#pr9.held + 1] = hold9
                        if not pcall(function() pr9.mc:call("setMesh", hold9) end) then pr9.mc:call("set_Mesh", hold9) end
                        local mt9 = sdk.create_resource("via.render.MeshMaterialResource", base9 .. ".mdf2")
                        if mt9 then
                            mt9 = mt9:add_ref(); pr9.held[#pr9.held + 1] = mt9
                            local mh9 = mt9:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                            pr9.held[#pr9.held + 1] = mh9
                            if not pcall(function() pr9.mc:call("set_Material", mh9) end) then pr9.mc:call("setMaterial", mh9) end
                        end
                    end)
                    pr9.stage = "cure"; pr9.at = nowN + 1.2
                elseif pr9.stage == "cure" and nowN >= (tonumber(pr9.at) or 0.0) then
                    local base9 = pr9.mesh or C.nest_bowl_mesh or "environment/props/sm5x/sm52/sm52_118/sm52_118_00"   -- dressing props override (bones); the nest = the REAL Capcom asset
                    pcall(function()
                        local res9 = sdk.create_resource("via.render.MeshResource", base9 .. ".mesh"):add_ref()
                        pr9.held[#pr9.held + 1] = res9
                        local hold9 = res9:create_holder("via.render.MeshResourceHolder"):add_ref()
                        pr9.held[#pr9.held + 1] = hold9
                        if not pcall(function() pr9.mc:call("setMesh", hold9) end) then pr9.mc:call("set_Mesh", hold9) end
                        local mt9 = sdk.create_resource("via.render.MeshMaterialResource", base9 .. ".mdf2")
                        if mt9 then
                            mt9 = mt9:add_ref(); pr9.held[#pr9.held + 1] = mt9
                            local mh9 = mt9:create_holder("via.render.MeshMaterialResourceHolder"):add_ref()
                            pr9.held[#pr9.held + 1] = mh9
                            if not pcall(function() pr9.mc:call("set_Material", mh9) end) then pr9.mc:call("setMaterial", mh9) end
                        end
                    end)
                    -- VERIFY the bind (cures used to declare victory blind = invisible props):
                    -- MatNum 0 -> stay in cure and rebind until it's real
                    local mn9 = 0
                    pcall(function() mn9 = tonumber(pr9.mc:call("get_MaterialNum")) or 0 end)
                    if mn9 > 0 then
                        pr9.stage = "done"
                        pr9.err = nil
                    else
                        pr9.cure_n = (tonumber(pr9.cure_n) or 0) + 1
                        if pr9.cure_n < 12 then
                            pr9.at = nowN + 2.0
                            pr9.err = "curing... (" .. tostring(pr9.cure_n) .. "/12)"
                        else
                            pr9.stage = "done"
                            pr9.err = "bound 0 materials after 12 cures (tell Iris)"
                        end
                    end
                end
            end)
        end
    end)
end)

-- ============================ picking it up (native carry, with a driven fallback) ============================
local function gp_mask()
    -- current gamepad button bitmask (RiftSpeak's proven reader). RT (DD2's grab button) = 0x800.
    local mask = 0
    pcall(function()
        local gp = sdk.get_native_singleton("via.hid.GamePad")
        local td = sdk.find_type_definition("via.hid.GamePad")
        if not (gp and td) then return end
        local dev = sdk.call_native_func(gp, td, "get_MergedDevice")
        if not dev then pcall(function() dev = sdk.call_native_func(gp, td, "getMergedDevice(System.UInt32)", 0) end) end
        if dev then mask = tonumber(dev:call("get_Button")) or 0 end
    end)
    return math.floor(mask)
end

-- ===== SCOUT FAILSAFE (UNGATED) =====
-- The panic key + the hard cap must depend on NOTHING. The main tick's scout logic lives behind
-- C.enabled / player-valid / not-paused gates -- so if a player DISABLES the mod mid-scout (the
-- exact thing a stuck player tries), that graceful path dies and the Arisen would stay frozen +
-- input-starved forever. This hook runs unconditionally, every frame, and force-restores on:
-- panic, a stalled main tick (mod disabled / player lost), bird/player death, or the hard cap.
-- Placed AFTER gp_mask so the L3+R3 panic combo resolves during a soft-lock (not just Backspace).
re.on_frame(function()
    if not S.scout then return end
    pcall(function()
        local now = os.clock()
        local sc = S.scout
        -- 1) PANIC -- always, first, from any state
        local mask = 0; pcall(function() mask = gp_mask() end)
        local combo = math.floor(tonumber(C.scout_panic_combo) or 0x3000)
        if iris_kb(math.floor(tonumber(C.scout_panic_key) or 0x08)) or ((mask & combo) == combo) then
            scout_force_restore("panic"); return
        end
        -- 2) PAUSE: the menu owns the frame. Hand the camera back (an overridden camera breaks --
        -- and crashed -- the pause menu), FREEZE the scout clock, and pass NO other judgment:
        -- character/GO handles can read stale behind a menu, and a "lost"/"stalled" verdict fired
        -- off stale reads was ending the scout the moment the player paused. On unpause every
        -- scout timestamp shifts by the pause length -- a menu visit costs zero flight time.
        local paused = false; pcall(function() paused = is_game_paused() end)
        if paused then
            if not S.scout_cam_suspended then
                S.scout_cam_suspended = true
                pcall(function() local cam = _G.IrisCreatureCam; if cam and cam.set_on then cam.set_on(false) end end)
                pcall(function() scout_vision_apply(false) end)   -- normal screen grade for the menu
                pcall(function() scout_ears_restore() end)        -- normal ears for the menu too
            end
            S.scout_pause_t0 = S.scout_pause_t0 or now
            -- stuck-pause backstop: if the pause flag never clears (a suppressed player with no
            -- auto-restore path = soft-lock), a very long "pause" force-restores anyway
            if now - S.scout_pause_t0 > 120.0 then scout_force_restore("stuck pause") end
            return
        end
        if S.scout_pause_t0 then
            local shift = now - S.scout_pause_t0
            S.scout_pause_t0 = nil
            for _, k in ipairs({ "t0", "deadline", "fb0" }) do
                if tonumber(sc[k]) then sc[k] = sc[k] + shift end
            end
            for _, k in ipairs({ "scout_heartbeat", "scout_grab_cd", "scout_caw_cd", "scout_ping_cd" }) do
                if tonumber(S[k]) then S[k] = S[k] + shift end
            end
        end
        if S.scout_cam_suspended then
            S.scout_cam_suspended = nil
            -- only re-take the camera if the player is still PILOTING; a pause during the
            -- flyback (control already returned) must never hijack the camera on unpause
            if sc.phase == "scouting" then
                pcall(function() local cam = _G.IrisCreatureCam
                    if cam then if cam.set_target then cam.set_target(char_go(sc.ch)) end; if cam.set_on then cam.set_on(true) end end end)
            end
        end
        -- 3) bird gone / player dead
        local player = get_player()
        if (not (sc.ch and char_go(sc.ch))) or is_dead(sc.ch) or (player and is_dead(player)) then
            scout_force_restore("lost"); return
        end
        -- 3b) ⛔⛔⛔ THE BIRD WENT DOWN (08-17, Aurora's divebomb-into-the-sea CTD).
        -- The brine put the crow down mid-dive and NONE of the tests above noticed: a downed
        -- companion is alive at 1 HP with IsDead false (the liveness law), so the scout kept
        -- piloting a body that downed.lua had already claimed, HP-pinned and parked in
        -- DmgDownLoop -- while the Arisen stayed frozen and input-starved. Fly it no further.
        if iris_body_downed(char_go(sc.ch)) then
            scout_force_restore("your companion went down")
            pcall(function()
                set_prompt("SCOUT ENDED", "It went down out there. Get to it before the timer runs out.",
                    4.0, 0xFFE0A040)
            end)
            return
        end
        -- 4) ABSOLUTE hard cap -- pure arithmetic (t0 shifts with pauses, so menus don't eat it)
        if now >= (tonumber(sc.t0) or now) + (tonumber(C.scout_secs) or 60.0) + 30.0 then
            scout_force_restore("hard cap"); return
        end
        -- 5) main tick STALLED (mod disabled / player handle lost). The main scout block stamps
        -- S.scout_heartbeat every frame it runs; if that goes stale while the game is NOT paused,
        -- control is frozen with no graceful path -> restore.
        local stalled = now - (tonumber(S.scout_heartbeat) or now)
        if stalled > 1.0 then
            scout_force_restore("tick stalled"); return
        end
    end)
end)

-- SCOUT HUD: a visible countdown + the controls while piloting the bird
re.on_frame(function()
    if not (S.scout and S.scout.phase == "scouting") then return end
    if S.scout_cam_suspended then return end   -- paused: no overlay/HUD over the menu
    pcall(function() scout_vision_apply(true) end)   -- REAL vividness via the tonemap, refreshed each frame
    pcall(function() scout_ears_apply() end)         -- decay at the CAMERA (the bird), re-asserted each frame
    -- EARS-FOLLOW probe: drag every found wwise listener onto the bird each frame (run the
    -- AUDIO LAB dump first to find them). If the caw rings far away with this on, the listener
    -- was the wall and this becomes the shipped behavior.
    if C.scout_ears_follow == true and S.audio_listeners and #S.audio_listeners > 0 then
        pcall(function()
            local b9 = _G.IrisGriffinBridge
            local ch9 = b9 and b9.griffin and b9.griffin()
            local g9 = ch9 and char_go(ch9)
            local rp9 = g9 and render_pos(g9)
            if not rp9 then return end
            for _, L9 in ipairs(S.audio_listeners) do
                pcall(function() L9.go:call("get_Transform"):call("set_Position", rp9) end)
            end
        end)
    end
    pcall(function()
        local left = math.max(0, (tonumber(S.scout.deadline) or 0.0) - os.clock())
        local w, h = 1920.0, 1080.0
        pcall(function() local ds = imgui.get_display_size(); if ds and ds.x then w = ds.x; h = ds.y end end)
        -- CROW VISION: the tonemap boost above does the vividness; this is just a faint violet UV
        -- hue cast on top (the tonemap has no colour knob), NO border
        if C.scout_vision ~= false then
            pcall(function() draw.filled_rect(0, 0, w, h, math.floor(tonumber(C.scout_tint) or 0x14C0A0FF)) end)
        end
        local cx = w * 0.5
        local pn = 0
        pcall(function() local p = S.scout_pouch; if p then pn = #(p.items or {}) + (p.gathered or 0) + (p.looted or 0) end end)
        -- ⭐ 08-17 (Aurora: "make the countdown timer bigger and use the Alegreya text so it
        -- matches the UI font"). Alegreya is the ladder's closest LEGAL match to DD2's own
        -- "francr" menu face, so the timer now reads as part of the game's furniture. The
        -- face is requested per-call; IrisFont caches handles, so this is not a per-frame
        -- DirectWrite object (the mount-transition lesson at iris_tame_face_text).
        local tpx = math.max(18.0, tonumber(C.scout_timer_px) or 46.0)
        local tstr = string.format("%.0fs", left)
        local F9 = _G.IrisFont
        local tcol = (left <= 5.0 and (math.floor(os.clock() * 4.0) % 2 == 0)) and 0xFFFF9060 or 0xFF80FFB0
        if not (F9 and F9.text and F9.text(tstr, cx - tpx * 0.55, 34, tcol, tpx, true, "Alegreya.ttf")) then
            iris_screen_text(tstr, cx - tpx * 0.55, 34, tcol, tpx)
        end
        -- ⭐ 08-17 r2 (Aurora: "move this pouch notice somewhere less obscured, make the font
        -- bigger, and use proper case"). It sat directly under the timer, which is exactly where
        -- the stamina bar draws -- so the one readout that tells her the flight was WORTH it was
        -- hidden behind a gauge. Moved out from under it, sized up, and Title Case like the rest
        -- of the game's furniture. Alegreya, to match the timer it belongs to.
        if pn > 0 then
            local ppx9 = math.max(16.0, tonumber(C.scout_pouch_px) or 30.0)
            local ptxt9 = "Pouch " .. pn
            local px9 = w * (tonumber(C.scout_pouch_x) or 0.5) - (ppx9 * 0.28) * #ptxt9
            local py9 = h * (tonumber(C.scout_pouch_y) or 0.135)
            local F8 = _G.IrisFont
            if not (F8 and F8.text and F8.text(ptxt9, px9, py9, 0xFFE8D9A8, ppx9, true, "Alegreya.ttf")) then
                iris_screen_text(ptxt9, px9, py9, 0xFFE8D9A8, ppx9)
            end
        end
        -- ── ⭐⭐⭐ 08-17 r2 (Aurora: "what I meant was to REPLACE the actual in-game UI with the
        -- commands like we do with all the mounts and the tools"). Right -- and that service
        -- already exists: IrisPromptBar rewrites the GAME'S own button panel via set_slot, which
        -- is how the horse/wolf/griffin/drake and the hoe/pickaxe/axe all do it. Drawing our own
        -- panel above the native one was two panels arguing; this is one panel telling the truth.
        -- ⭐ AND IT SOLVES THE KEYBOARD GLYPHS FOR FREE: the GAME draws the glyph beside the label,
        -- so a keyboard player sees DD2's own key art. That is precisely why our binds must equal
        -- DD2's binds for the same slot -- otherwise the panel we relabelled would lie.
        --   L02 Y/V = Ping · L03 X/LMB = Dive-steal · R02 B/Shift = Soar
        --   R03 A/Space = Up (Jump -> up: the key was ALREADY Space)
        --   L01 LB/Ctrl = Land (the key was ALREADY Ctrl) · R00 RT/E = Collect (Grab -> collect)
        -- ⚠ Only a slot the game is ALREADY showing can be relabelled (the PlayState wall), so
        -- LT/RB are left alone rather than blanked -- a withheld slot ignores us anyway.
        local sp9 = species_clips(char_go(S.scout.ch)) or {}
        local ground9 = sp9.ground == true
        local slots9 = sp9.hud_slots
        if not slots9 then
            if ground9 then
                slots9 = {
                    PNL_L02 = "Ping",   PNL_L03 = sp9.burrow and "Ambush" or "Pickpocket",
                    PNL_R02 = sp9.burrow and "Burrow" or "Dash",
                    PNL_R00 = "Collect", PNL_R03 = "Hop",
                }
            else
                slots9 = {
                    PNL_L02 = "Ping",     PNL_L03 = "Dive-steal",
                    PNL_R02 = "Soar",     PNL_R00 = "Collect",
                    PNL_L01 = "Descend",  PNL_R01 = "Ascend",
                    -- ⛔ LT does NOTHING for a bird. Blank it with a SPACE, never "" -- an empty
                    -- string into a live via.gui.Text is the mount CTD (IrisPromptBar converts
                    -- it anyway, but say what we mean). A space keeps the glyph and frame and
                    -- simply stops the panel advertising Sheathe/Draw at a crow.
                    PNL_L00 = " ",
                }
                -- ⭐ ASCEND LIVES ON A DIFFERENT SLOT PER DEVICE, so the glyph never lies.
                -- Pad: R1/RB genuinely IS ascend (asc = r1 - l1), so RB says it.
                -- Keyboard: RB's glyph is a MOUSE button, but our ascend key is SPACE -- whose
                -- glyph belongs to A/Jump. So on keyboard the label moves to A and RB goes quiet.
                -- Descend needs no such split: L1 and Ctrl are both correct on their own device.
                if S.stable_input_device == "keyboard" then
                    slots9.PNL_R01 = " "
                    slots9.PNL_R03 = "Ascend"
                else
                    slots9.PNL_R03 = " "
                end
            end
        end
        pcall(function()
            local P9 = rawget(_G, "IrisPrompt")
            if not (P9 and P9.set_slot) then return end
            for slot9, txt9 in pairs(slots9) do P9.set_slot("iris_scout", slot9, txt9) end
        end)
        -- RETURN has no panel slot of its own (R3 is not in DD2's prompt set), so it stays as our
        -- one drawn row -- Aurora: "keep the R3 one, but move it closer to the other controls".
        -- Positioned by sliders so she can place it herself instead of me guessing twice.
        pcall(function()
            iris_control_plaque({ { label = "Return", pad = "R3", key = "J" } },
                { dx = tonumber(C.scout_return_dx) or 40.0,
                  dy = tonumber(C.scout_return_dy) or 205.0,
                  px = tonumber(C.scout_return_px) or 19.0 })
        end)
        -- SPRINT stamina bar (fed from the griffin bridge's scout_status)
        local st = nil
        pcall(function() local b = _G.IrisGriffinBridge; if b and b.scout_status then st = b.scout_status() end end)
        if st and st.stamina then
            -- ⭐ native-styled gauge (07-21): feed the probe's d2d house gauge; the flat rect below
            -- only draws when the d2d suite is absent
            _G.IrisScoutHUD = { active = true, t = os.clock(),
                stamina = math.max(0.0, math.min(1.0, tonumber(st.stamina) or 0.0)),
                sprinting = st.sprinting == true, lock = st.sprint_lock == true }
            if _G.IrisHudD2DOk ~= true then
            local bw, bh = 220.0, 9.0
            local bx, by = cx - bw * 0.5, 92.0
            draw.filled_rect(bx - 1, by - 1, bw + 2, bh + 2, 0xC0000000)
            local fill = math.max(0.0, math.min(1.0, tonumber(st.stamina) or 0.0))
            local col = st.sprint_lock and 0xFFFF6060 or (st.sprinting and 0xFF60D0FF or 0xFF80FFB0)
            draw.filled_rect(bx, by, bw * fill, bh, col)
            end
        end
    end)
end)

local function grab_button_down()
    -- keyboard grab (E) OR the gamepad grab button (RT). This is how you pick up the beaten creature.
    local kb = false
    pcall(function() kb = iris_kb(math.floor(tonumber(C.grab_key) or 0x45)) == true end)
    if kb then return true end
    local bit = math.floor(tonumber(C.grab_button_bit) or 0x800)
    return (gp_mask() & bit) ~= 0
end

local function catch_processor(player)
    local hcp = nil
    pcall(function() local h = player:call("get_Human"); hcp = h and h:call("get_CatchProcessor") end)
    if not hcp then hcp = comp(char_go(player), "app.HumanCatchProcessor") end
    return hcp
end

local function catch_active(player)
    local a = false
    pcall(function() local cc = player:call("get_CatchController"); a = (cc and cc:call("get_IsActive") == true) or false end)
    return a
end

local function dump_caught_types(ch)
    -- one-shot: what carry types does THIS creature actually accept? (A wolf reported "52" --
    -- its OWN CatchType, none of the standard human carries -- which is why those never took.)
    if S.caught_dumped then return end
    S.caught_dumped = true
    pcall(function()
        local out = {}
        pcall(function() out.valid_caught_types = tostring(ch:call("get_ValidCaughtTypes")) end)
        pcall(function() out.reject = ch:call("isRejectCaughtBecauseOfOwnStatus") end)
        pcall(function() out.reject_notemp = ch:call("isRejectCaughtBecauseOfOwnStatusWithoutTempStatus") end)
        S.caught_type = tonumber(tostring(out.valid_caught_types or ""):match("%d+"))   -- the declared type drives the catch
        json.dump_file(MOD .. "_caught_types.json", out)
        log.info("[IrisTaming] caught types=" .. tostring(out.valid_caught_types) .. " reject=" .. tostring(out.reject))
    end)
end

-- r11: THE SAME-FRAME KEEP. The tape proved the bind SUCCEEDS (CarryStart, CaughtController
-- engaged) and the victim-side abort lands ~20ms later -- BEFORE the on_frame keep's first
-- tick ever runs. The proven carries (llm_freetalk, combat tame) live because their keep
-- flags are already down when the abort condition is evaluated. So set them in the SAME
-- call stack as the successful start, not a frame later.
local function wolf_keep_flags(player)
    pcall(function()
        local cc = player:call("get_CatchController")
        if not cc then return end
        pcall(function() cc:call("set_IsContinue(System.Boolean)", true) end)
        pcall(function() cc:call("set_IsRejectAbortOnDefault(System.Boolean)", true) end)
        pcall(function() cc:call("set_IsDisableEscape(System.Boolean)", true) end)
        pcall(function() cc:call("requestDisableEscape") end)
        local caught = cc:get_field("CaughtCtrl")
        if caught then
            pcall(function() caught:call("set_IsContinue(System.Boolean)", true) end)
            pcall(function() caught:call("set_IsRejectAbortOnDefault(System.Boolean)", true) end)
            pcall(function() caught:set_field("IsDisableEscapeInternal", true) end)
            pcall(function() caught:set_field("IsTempDisableEscape", true) end)
        end
    end)
end

local function try_native_carry(player, ch)
    -- native detection won't OFFER a beast as a grab target (same wall RiftSpeak hit with children),
    -- so CALL the carry API directly. ORDER MATTERS: startCarry (CatchType 2 = the over-shoulder
    -- carry, the one the vanilla game uses for a beaten wolf) FIRST. startCarrySmallAnimal goes
    -- LAST -- it ACTIVATES on a wolf but has no valid pose for that size (the floating-wolf glitch).
    -- (get_ValidCaughtTypes "52" is a BITMASK -- bits 2/4/5 -- not a single type id; bit 2 = Carry.)
    local hcp = catch_processor(player)
    if not hcp then return "no-hcp" end
    for _, t in ipairs({
        { sig = "startCarry(app.Character, System.Boolean)", two = true, name = "carry" },
        { sig = "startBridalCarry(app.Character)", two = false, name = "bridal" },
        { sig = "startCarrySmallAnimal(app.Character, System.Boolean)", two = true, name = "smallanimal" },
    }) do
        if catch_active(player) then wolf_keep_flags(player); return t.name end
        pcall(function()
            if t.two then hcp:call(t.sig, ch, false) else hcp:call(t.sig, ch) end
        end)
        if catch_active(player) then wolf_keep_flags(player); return t.name end
    end
    return "none"
end

-- ===== 08-08 r10 CRASH-SURVIVING TAPE =====
-- The 15:28 crash ate the framework log (truncated on relaunch), so every carry
-- forensic line ALSO lands in reframework/data/IrisCarryTape.txt (io.open is
-- data-sandboxed -- bare filename = reframework/data). Re-assigned every load so
-- persistent hook closures always reach the freshest writer via _G.
_G.IrisCarryTapeFn = function(line)
    pcall(function()
        local f = io.open("IrisCarryTape.txt", "a")
        if f then f:write(os.date("%H:%M:%S ") .. tostring(line) .. "\n"); f:close() end
    end)
end
local function carry_tape(line)
    local tp = _G.IrisCarryTapeFn
    if tp then tp(line) end
    pcall(function() log.info("[IrisTaming] " .. tostring(line)) end)
end

-- ⭐⭐ SECONDARY MOTION / RAGDOLL GATE (08-08) -- the wolf-carry fix.
-- Measured facts that led here: with the body pinned, root DRIFT was 0.000m for 10s (nobody
-- is fighting the transform), yet the MESH thrashed -- and it got worse the longer the carry
-- ran. That profile is a DIVERGENCE, not a trigger. The component dump named the culprits:
--   via.motion.Chain2        -- secondary bone dynamics (fur, tail, ears). Integrates bone
--                               VELOCITY frame to frame. We teleport the root every frame, so
--                               it sees a colossal implied velocity, flings the chain out, and
--                               accumulates error until the body is strung across the screen.
--   via.motion.JointConstraints -- same class of problem, constraint solve against a body that
--                               moved impossibly far since last frame.
--   via.dynamics.Ragdoll / app.CharacterRagdoll -- TWO ragdoll components. EnableRagdoll()
--                               reported call_ok=true, but that only means the call did not
--                               throw; it plausibly only touches the app-side one, leaving the
--                               via.dynamics simulation live.
-- A rabbit survives the same pin because it has almost no secondary motion to diverge; a wolf
-- is fur, tail and a full ragdoll. Toggle them together, restore them together.
-- THE CARRY KEEP (combat-tame flags). A caught LIVE creature struggles free on the escape
-- timer, and CarryStart otherwise falls through to CarryCancel within a few hundred ms --
-- which is both the "it drops instantly" and the knockback. Must be applied on the BIND
-- FRAME and every frame after; arming it even 0.6s late means it never runs at all.
local function wolf_carry_keep(player9, g9)
    if not player9 then return end
    pcall(function()
        local cc9 = player9:call("get_CatchController")
        if not cc9 then return end
        pcall(function() cc9:call("set_IsContinue(System.Boolean)", true) end)
        pcall(function() cc9:call("set_IsRejectAbortOnDefault(System.Boolean)", true) end)
        pcall(function() cc9:call("set_IsDisableEscape(System.Boolean)", true) end)
        pcall(function() cc9:call("requestDisableEscape") end)
        local ca9 = cc9:get_field("CaughtCtrl")
        if ca9 then
            pcall(function() ca9:call("set_IsContinue(System.Boolean)", true) end)
            pcall(function() ca9:call("set_IsRejectAbortOnDefault(System.Boolean)", true) end)
            pcall(function() ca9:set_field("IsDisableEscapeInternal", true) end)
            pcall(function() ca9:set_field("IsTempDisableEscape", true) end)
        end
    end)
    if g9 then pcall(function() strip_hate(g9) end) end
end

local function wolf_native_end(player9)
    -- Unlock both halves before asking HumanCatchProcessor for the gentle native
    -- carry end. Shared by the visible set-down and the invisible first-use
    -- controller prime below.
    if not player9 then return end
    pcall(function()
        local cc9 = player9:call("get_CatchController")
        if not cc9 then return end
        pcall(function() cc9:call("set_IsContinue(System.Boolean)", false) end)
        pcall(function() cc9:call("set_IsRejectAbortOnDefault(System.Boolean)", false) end)
        pcall(function() cc9:call("set_IsDisableEscape(System.Boolean)", false) end)
        local ca9 = cc9:get_field("CaughtCtrl")
        if ca9 then
            pcall(function() ca9:call("set_IsContinue(System.Boolean)", false) end)
            pcall(function() ca9:call("set_IsRejectAbortOnDefault(System.Boolean)", false) end)
            pcall(function() ca9:set_field("IsDisableEscapeInternal", false) end)
            pcall(function() ca9:set_field("IsTempDisableEscape", false) end)
        end
    end)
    pcall(function()
        local hum9 = player9:call("get_Human")
        local hcp9 = hum9 and hum9:call("get_CatchProcessor")
        if not hcp9 then hcp9 = hum9 and hum9["<CatchProcessor>k__BackingField"] end
        if not hcp9 then return end
        for _, f9 in ipairs({
            function() hcp9:call("endCarry") end,
            function() hcp9:call("requestEndCarry") end,
        }) do if pcall(f9) then break end end
    end)
end

local function wolf_secondary_motion(go9, on9)
    if not go9 then return 0 end
    local hits9 = 0
    for _, tn9 in ipairs({
        "via.motion.Chain2",
        "via.motion.JointConstraints",
        "via.dynamics.Ragdoll",
        "app.CharacterRagdoll",
    }) do
        pcall(function()
            local t9 = sdk.typeof(tn9)
            local c9 = t9 and go9:call("getComponent(System.Type)", t9)
            if c9 then c9:call("set_Enabled", on9 == true); hits9 = hits9 + 1 end
        end)
    end
    return hits9
end

-- r14: EVERY collision-ish component on the wolf goes dark for the pin. iris_body_solid's
-- 3-component list was chosen on CRITTER chassis; a ch223 monster carries press colliders
-- outside it, and one live press collider grinding the player's capsule = the +Y launch
-- (the rabbit ghost comment documents the exact mechanism). Enumerate + tape what we find
-- so the true culprit gets a name. Defensive per the broken-scan law: if enumeration reads
-- zero, SAY so on tape -- iris_body_solid still covers the known three either way.
local function wolf_collision_sweep(ch9, go9, on9)
    pcall(function() ch9:call("setCharacterControllerEnable", on9 == true) end)
    local names9, n9 = {}, 0
    pcall(function()
        local arr9 = go9:call("get_Components")
        pcall(function() n9 = arr9:get_size() end)
        if (tonumber(n9) or 0) == 0 then pcall(function() n9 = arr9:call("get_Count") end) end
        for i9 = 0, (tonumber(n9) or 0) - 1 do
            pcall(function()
                local c9 = nil
                pcall(function() c9 = arr9:get_element(i9) end)
                if not c9 then pcall(function() c9 = arr9:call("get_Item", i9) end) end
                if not c9 then return end
                local tn9 = tostring(c9:get_type_definition():get_full_name())
                if tn9:find("Press") or tn9:find("Collider") or tn9:find("CharacterController")
                    or tn9:find("HitController") then
                    pcall(function() c9:call("set_Enabled", on9 == true) end)
                    names9[#names9 + 1] = tn9
                end
            end)
        end
    end)
    if #names9 > 0 then
        carry_tape("wolf pin sweep " .. (on9 and "RESTORE" or "OFF") .. " (" .. tostring(n9) .. " comps): " .. table.concat(names9, ", "))
    else
        carry_tape("wolf pin sweep: 0 collision comps matched of " .. tostring(n9) .. " -- enumeration may have failed (fixed list still applied)")
    end
end

-- ===== 08-08 r7 CARRY-ABORT FORENSICS (companion wolf CarryStart -> CarryCancel hunt) =====
-- Window-gated spies: when the player's catch on the companion dies within 2 frames, the log
-- names WHICH terminal call dismantled it (catcher side vs victim side) and what the claim
-- check (HumanCatchProcessor.onCatchCheck) answered. Zero effect outside the window.
-- The gate lives in _G, not S: sdk.hook closures PERSIST across script reloads (the file's
-- own law at 2168), so a reloaded script's fresh S table would strand an S-gated spy.
if not _G.IrisTamingCarryAbortSpiesInstalled then
    _G.IrisTamingCarryAbortSpiesInstalled = true
    local function carry_spy(tn, mn)
        pcall(function()
            local td = sdk.find_type_definition(tn)
            local m = td and td:get_method(mn)
            if not m then return end
            sdk.hook(m, function(args)
                if (tonumber(_G.IrisWolfCarryDiagUntil) or 0.0) > os.clock() then
                    pcall(function() log.info("[IrisTaming] carry-abort spy: " .. tn .. "." .. mn) end)
                    pcall(function() local tp = _G.IrisCarryTapeFn; if tp then tp("carry-abort spy: " .. tn .. "." .. mn) end end)
                end
            end, function(retval) return retval end)
        end)
    end
    -- catcher-side terminal paths (the player's CatchController)
    carry_spy("app.CatchController", "abort(System.Boolean)")
    carry_spy("app.CatchController", "endFromFsm(via.behaviortree.ActionArg)")
    carry_spy("app.CatchController", "onFinish(System.Boolean)")
    carry_spy("app.CatchController", "requestCatchCancelActionOnAbort()")
    -- victim-side terminal notifications (the wolf's CaughtController)
    carry_spy("app.CaughtController", "abort(System.Boolean)")
    carry_spy("app.CaughtController", "abortDirect()")
    carry_spy("app.CaughtController", "notifyAbort()")
    carry_spy("app.CaughtController", "notifyEnd()")
    carry_spy("app.CaughtController", "notifyEscape()")
    carry_spy("app.CaughtController", "onFinish()")
    -- the CLAIM: did the player's catch accept the hit character at all?
    pcall(function()
        local td = sdk.find_type_definition("app.HumanCatchProcessor")
        local m = td and (td:get_method("onCatchCheck(app.HitController.DamageInfo)")
            or td:get_method("onCatchCheck"))
        if m then
            sdk.hook(m, function(args) end, function(retval)
                if (tonumber(_G.IrisWolfCarryDiagUntil) or 0.0) > os.clock() then
                    local rv = "?"
                    pcall(function() rv = tostring(sdk.to_int64(retval)) end)
                    pcall(function() log.info("[IrisTaming] carry claim: onCatchCheck -> " .. rv) end)
                    pcall(function() local tp = _G.IrisCarryTapeFn; if tp then tp("carry claim: onCatchCheck -> " .. rv) end end)
                end
                return retval
            end)
        end
    end)
end

-- ===== 08-08 r9 THE FRIEND-HIT SPOOF (companion wolf carry -- the fix the kind-mask groped for) =====
-- The log's verdict was exact: the catch collision HITS the companion but the hit reads
-- AttackRelationship = FRIEND, so nothing binds and CarryStart cancels 2 frames later.
-- r7/r8 tried to change WHAT THE WOLF IS (CharacterKind 8) and crashed the action interface
-- (the standing ally-switch law). r9 changes WHAT THE CHECK READS instead: while the grab
-- window is open, the relationship/friend-hit functions lie about this ONE pair
-- (player <-> wolf). These are the SAME hooks Monster Infighting Improved and
-- HostileUnhiredPawns run globally and live-safe; ours are scoped to one character pair
-- for the grab + carry only. Zero state on the wolf ever changes = nothing to crash,
-- nothing to restore, and the stable still knows her by kind 2 the whole time.
-- Window = _G.IrisWolfCarryRelSpoof { p = player addr, t = wolf addr, until_t } (in _G,
-- not S -- hook closures persist across script reloads, the file's own law at 2168).
-- ⚡ PERF (2026-08-10, Iris): the three hooks below land on getRelationshipFromTo,
-- useFriendHitAdjust and isFriendAttack -- all hot combat paths. They used to be installed
-- at LOAD, but every one of their callbacks bails on `if not _G.IrisWolfCarryRelSpoof`,
-- and that flag is READ six times and ASSIGNED ZERO times anywhere in the tree: r9's
-- arming code was never written. So the game paid six native->Lua crossings per
-- relationship / friend-hit query, forever, for callbacks that could never fire.
-- Installation is now LAZY -- nothing is hooked until the window is actually armed, which
-- is also the arming entry point r9 was missing. REFramework cannot unhook, so this stays
-- a one-way install; that is exactly r9's intent (arm at the wolf-grab edge, then behave).
-- Arm with:  _G.IrisTamingArmRelSpoof(player_addr, wolf_addr, secs)
function _G.IrisTamingInstallRelSpoof()
    if _G.IrisTamingRelSpoofInstalled then return end
    _G.IrisTamingRelSpoofInstalled = true
    local function spoof_win()
        local w = _G.IrisWolfCarryRelSpoof
        if not w then return nil end
        if os.clock() > (tonumber(w.until_t) or 0.0) then return nil end
        return w
    end
    local function pair_match(a, b)
        local w = spoof_win()
        if not w or not a or not b or a == 0 or b == 0 then return false end
        return (a == w.p and b == w.t) or (a == w.t and b == w.p)
    end
    local function spoof_log(what)
        -- once per window per gate, and only while the diag window is armed
        local w = _G.IrisWolfCarryRelSpoof
        if w and not w[what] and (tonumber(_G.IrisWolfCarryDiagUntil) or 0.0) > os.clock() then
            w[what] = true
            pcall(function() log.info("[IrisTaming] rel spoof fired: " .. what) end)
            pcall(function() local tp = _G.IrisCarryTapeFn; if tp then tp("rel spoof fired: " .. what) end end)
        end
    end
    -- 1) the relationship source of truth: FRIEND -> HOSTILE for the pair.
    --    (Return encoding proven by HostileUnhiredPawns: 0 neutral / 1 hostile / 2 friendly.)
    pcall(function()
        local m = sdk.find_type_definition("app.BattleRelationshipHolder")
            :get_method("getRelationshipFromTo(app.Character, app.Character)")
        if not m then return end
        sdk.hook(m, function(args)
            local st = thread.get_hook_storage()
            st.spoof = nil
            if not _G.IrisWolfCarryRelSpoof then return end   -- hot path: one lookup, out
            pcall(function()
                st.spoof = pair_match(sdk.to_int64(args[3]), sdk.to_int64(args[4]))
            end)
        end, function(retval)
            local st = thread.get_hook_storage()
            if st and st.spoof then spoof_log("relationship"); return sdk.to_ptr(1) end
            return retval
        end)
    end)
    -- 2) the friend-hit ADJUST (character-pair signature; arg slots shift if the method is
    --    static, so match on both plausible windows -- a false positive is impossible, both
    --    slots must equal OUR two bodies)
    pcall(function()
        local m = sdk.find_type_definition("app.HostileRelationshipAdjust")
            :get_method("useFriendHitAdjust(app.Character, app.Character)")
        if not m then return end
        sdk.hook(m, function(args)
            local st = thread.get_hook_storage()
            st.spoof = nil
            if not _G.IrisWolfCarryRelSpoof then return end
            pcall(function()
                st.spoof = pair_match(sdk.to_int64(args[2]), sdk.to_int64(args[3]))
                    or pair_match(sdk.to_int64(args[3]), sdk.to_int64(args[4]))
            end)
        end, function(retval)
            local st = thread.get_hook_storage()
            if st and st.spoof then spoof_log("friendhit_adjust"); return sdk.to_ptr(false) end
            return retval
        end)
    end)
    -- 3) the hit-side gate itself: isFriendAttack(DamageInfo). Pair-scoped by walking the
    --    DamageInfo the way SurgeTape proved: AttackHitController -> shell owner (or cached
    --    character) = attacker; DamageHitController -> cached character = victim.
    pcall(function()
        local m = sdk.find_type_definition("app.HitController")
            :get_method("isFriendAttack(app.HitController.DamageInfo)")
        if not m then return end
        sdk.hook(m, function(args)
            local st = thread.get_hook_storage()
            st.spoof = nil
            if not _G.IrisWolfCarryRelSpoof then return end
            pcall(function()
                local di = sdk.to_managed_object(args[3])
                if not di then return end
                local atk, vic = nil, nil
                local ahc = di["<AttackHitController>k__BackingField"]
                if ahc then
                    local shell = nil
                    pcall(function() shell = ahc["<CachedShell>k__BackingField"] end)
                    if shell then pcall(function() atk = shell["<OwnerCharacter>k__BackingField"] end) end
                    if not atk then pcall(function() atk = ahc["<CachedCharacter>k__BackingField"] end) end
                end
                pcall(function()
                    local dhc = di["<DamageHitController>k__BackingField"]
                    if dhc then vic = dhc["<CachedCharacter>k__BackingField"] end
                end)
                st.spoof = pair_match(atk and atk:get_address() or 0, vic and vic:get_address() or 0)
            end)
        end, function(retval)
            local st = thread.get_hook_storage()
            if st and st.spoof then spoof_log("isFriendAttack"); return sdk.to_ptr(false) end
            return retval
        end)
    end)
end

-- Arm the r9 friend-hit spoof for ONE character pair, installing the hooks on first use.
-- p_addr / t_addr are app.Character addresses (get_address()), matching the pair_match
-- comparison above; secs defaults to the r9 grab window. This is the call site r9 needed --
-- until something invokes it, the three hooks above are never installed and cost nothing.
function _G.IrisTamingArmRelSpoof(p_addr, t_addr, secs)
    if not (p_addr and t_addr) or p_addr == 0 or t_addr == 0 then return false end
    _G.IrisTamingInstallRelSpoof()
    _G.IrisWolfCarryRelSpoof = {
        p = p_addr, t = t_addr,
        until_t = os.clock() + (tonumber(secs) or 1.2),
    }
    return true
end

-- ===== 08-08 r11 THE ABORT GATE (establish window) =====
-- Tape verdict r10: the bind SUCCEEDS (CarryStart + CaughtController engaged, spoof fired)
-- and then CaughtController.abort -> CatchController.abort kills it ONE FRAME in -- faster
-- than any on_frame keep can answer. So for a short window around OUR grab, the abort
-- entry points are simply refused (SKIP_ORIGINAL). Window-scoped (~1.2s, armed only at the
-- wolf grab edge, cleared on every exit), so no other catch in the game is ever touched --
-- and the llm_freetalk law stands: OUR set-down always ends via CarryEnd, never abort, so
-- nothing we rely on is being blocked. Every refusal is taped: the spam pattern names the
-- caller's persistence.
if not _G.IrisTamingAbortGateInstalled then
    _G.IrisTamingAbortGateInstalled = true
    local function gate_on()
        local g = _G.IrisWolfCarryAbortGate
        return (g ~= nil) and os.clock() < (tonumber(g.until_t) or 0.0)
    end
    local function gate_hook(tn, mn)
        pcall(function()
            local td = sdk.find_type_definition(tn)
            local m = td and td:get_method(mn)
            if not m then return end
            sdk.hook(m, function(args)
                if gate_on() then
                    pcall(function() local tp = _G.IrisCarryTapeFn; if tp then tp("abort-gate BLOCKED " .. tn .. "." .. mn) end end)
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end, function(retval) return retval end)
        end)
    end
    gate_hook("app.CaughtController", "abort(System.Boolean)")
    gate_hook("app.CaughtController", "abortDirect()")
    gate_hook("app.CaughtController", "notifyAbort()")
    gate_hook("app.CatchController", "abort(System.Boolean)")
    gate_hook("app.CatchController", "requestCatchCancelActionOnAbort()")
end

-- ============================ the tame finish (shared by both paths) ============================
local function do_commit(ch, why)
    -- PHASE B: the body has SETTLED into clean native control -> the stable takes it.
    -- (register_griffin's ally-switch + scale must not run on a mid-forced-motion body.)
    local go = char_go(ch)
    if not go then S.status = "handover lost the body (despawned?)"; return end
    -- re-assert pacify + clear hate one more time right before the heavy register: NOTHING may be
    -- mid-attack when the stable writes kind/group/AI context onto it (the native crash)
    pcall(function() full_pacify(ch) end)
    pcall(function() strip_hate(ch); clear_targets(ch) end)
    -- 08-12 (a spawned BULL sealed as "female Ox"): chassis truth OUTRANKS every roll --
    -- for sexed chassis (cow/bull, hen/rooster) the produce gates already decided
    local chassis_gen = nil
    pcall(function()
        local sp = rawget(_G, "IrisSpecies")
        chassis_gen = sp and sp.gender and sp.gender(go) or nil   -- the BODY: the individual's roll, not the band's
    end)
    local gen = chassis_gen or (S.trial and S.trial.gender) or S.pact_gender
        or ((math.random() < 0.5) and "female" or "male")
    S.pact_gender = nil
    local bridged = false
    if _G.IrisGriffinBridge and _G.IrisGriffinBridge.tame_creature then
        local okc, res = pcall(function() return _G.IrisGriffinBridge.tame_creature(ch, gen) end)
        bridged = okc and res == true
    end
    if not bridged then
        -- fallback (bridge absent): the local peaceful-pet roster (brain off, nav on, shielded)
        S.tamed[ch] = { name = go_name(go), follow = true, gender = gen }
        full_pacify(ch)
        set_immunity(ch, true)
        local tgo = char_go(ch)
        local dm = comp(tgo, "app.AIDecisionMaker")
        if dm then pcall(function() dm:call("set_Enabled", false) end) end
        local nv = comp(tgo, "app.NavigationAI")
        if nv then pcall(function() nv:call("set_Enabled", true) end) end
    end
    S.tame_cd_until = os.clock() + (tonumber(C.tame_cooldown) or 30.0)
    S.posttame = { ch = ch, at = os.clock() + 6.0 }   -- the truce outlives the handover
    S.tamed_addrs = S.tamed_addrs or {}
    pcall(function() S.tamed_addrs[tostring(ch:get_address())] = true end)   -- never court a tamed one again
    S.target = nil; S.armed = nil; S.mode = "idle"; S.trial = nil; S.combat_tame = nil; S.camp_tend = nil; S.yield_down = nil; S.iris_carry = nil; S.feed_drop = nil; S.camp_rite = nil   -- the ritual fully lets go
    S.name_pending = { kind = bridged and "stable" or "local", ch = ch, gender = gen, label = creature_label(go) }
    S.name_buf = ""
    S.status = "TAMED (" .. tostring(why) .. "): " .. go_name(go) .. " [" .. gen .. "]" .. (bridged and " - joined the STABLE (griffin orders apply)" or " - local pet mode")
    set_prompt("TAMED", (gen == "female" and "She" or "He") .. " walks with you now.", 5.0, 0xFF80FFB0)
    save_state()
    return gen, bridged
end

local function do_handover(ch, why)
    -- PHASE A of the pact: SETTLE the body into clean native control FIRST. Releasing think-stop
    -- and handing to the stable (register + ally-switch + scale) in the SAME frame crashed the
    -- game natively (the body was mid-forced-motion). Reset to idle, drop our holds, then let it
    -- stand for half a second before the heavy registration in do_commit.
    local go = char_go(ch)
    if not go then S.status = "handover lost the body (despawned?)"; return end
    set_nav_stop(ch, false)
    S.seal_howl = nil   -- the howl has had its full say by now; this reset is what used to cut it
    pcall(function() play_motion(ch, 0, 0) end)   -- neutral idle: no forced howl/lie clip lingering
    set_think_stop(ch, false)
    _G.IrisTamingTargetAddr = nil
    S.lie_cue = nil
    pcall(function() set_player_fsm(go, true) end)   -- motion FSM back = a clean pose for the register
    -- CRASH FIX: restoring the FSM woke its combat AI, which lunged at a pawn -- and the
    -- register writing context onto a MID-ATTACK body was the native crash. Keep it PACIFIED through
    -- the whole handover: brain OFF, hate cleared BOTH ways, immune, until the stable owns it.
    pcall(function() full_pacify(ch) end)
    pcall(function()
        local dm = comp(char_go(ch), "app.AIDecisionMaker")
        if dm then dm:call("set_Enabled", false) end
    end)
    pcall(function() strip_hate(ch); clear_targets(ch) end)
    for _, member in ipairs(party_characters()) do
        pcall(function() strip_hate(member); clear_targets(member) end)
    end
    set_immunity(ch, true)
    restore_pack()   -- the pack watched; the alpha is yours now -- let them go
    S.finish_commit = { ch = ch, why = why, at = os.clock() + 0.5 }
    S.status = "the pact settles..."
end

local function try_finish(player, pgo, ch, go, why, at_hand)
    local d = dist(upos(pgo), upos(go))
    if not at_hand and d > (tonumber(C.finish_range) or 2.5) then
        S.status = string.format("too far for the hand-out (%.1fm)", d)
        return false
    end
    local sheathed = player_sheathed(player)
    if C.require_sheathed and sheathed == false then
        S.status = "sheathe your weapon - the hand asks for trust"
        return false
    end
    if C.require_food == true then
        -- STUB: real inventory check pending research; the toggle stands in for "has its food"
        S.status = "it waits for food... (require_food stub: untick to test the flow)"
        return false
    end
    -- THE PACT: hand the creature to the GRIFFIN companion system (identical to the
    -- griffin minus the ride -- stable, follow/stay/come/attack, persistence, the works)
    pcall(function() S.familiar[tostring(ch:get_address())] = nil end)
    S.familiar = {}   -- fresh familiarity for the next wolf (no fast-track carry-over)
    S.mode = "idle"; S.target = nil; S.pressure = 0.0; S.combat_tame = nil; S.yield_down = nil; S.iris_carry = nil; S.feed_drop = nil; S.camp_rite = nil
    S.held_ground = nil
    -- phase 1: release EVERYTHING and give the body a sane idle -- never hand over a body
    -- that is mid-forced-clip with a half-asleep action system
    local seal_cat = is_cat(go)
    local seal_ox = creature_label(go) == "Ox"
    -- 08-12 (Mootilda sealed at 1/700): whatever the wild body suffered before or during
    -- the rite, the pact MENDS it -- a fresh companion never starts at death's door
    pcall(function()
        local hc9 = hit_controller(ch)
        local _, mx9 = read_hp(hc9)
        if mx9 and mx9 > 1 then write_hp(hc9, mx9) end
    end)
    if seal_ox then
        play_motion(ch, 0, 0)   -- the ox seals in stillness -- no howl clip on a grazer rig (07-21)
    elseif seal_cat then
        play_motion(ch, 60, 0)   -- a cat doesn't howl the pact (08-05): it SITS before you
    else
        play_motion(ch, 0, tonumber(C.cue_howl_clip) or 4610)   -- THE PACT SEALS WITH A HOWL
        -- ...and the howl is a FAMILY, not a clip: 4610 start -> 4611 loop -> 4612 end. Only the
        -- start was ever played, and the handover's neutral-idle reset landed on top of it 1.6s
        -- later, so the pact ended on a wolf drawing breath. The machine below chains all three
        -- and the handover waits for it. (Atlas-verified: ch23_000_com_howling_start/loop/end.)
        local hs9 = tonumber(C.seal_howl_start_secs) or 1.5
        local hl9 = tonumber(C.seal_howl_loop_secs) or 2.2
        S.seal_howl = { ch = ch, stage = "start",
            loop_at = os.clock() + hs9, end_at = os.clock() + hs9 + hl9 }
    end
    _G.IrisTamingTargetAddr = nil
    S.lie_cue = nil
    S.crossing = nil
    -- (Aurora 08-08: "started as ♀, tamed as ♂"): the trial-success
    -- handler nils S.trial the moment try_finish returns, but
    -- do_commit runs ~2s LATER and read the gender off S.trial --
    -- gone = 50/50 reroll. Stash it across the settle window.
    S.pact_gender = (S.trial and S.trial.gender) or S.pact_gender
    -- the settle window has to outlast whatever the seal is performing
    local seal_secs = 1.6
    if S.seal_howl then
        seal_secs = (tonumber(C.seal_howl_start_secs) or 1.5)
            + (tonumber(C.seal_howl_loop_secs) or 2.2)
            + (tonumber(C.seal_howl_end_secs) or 1.8)
    end
    S.finish_pending = { ch = ch, at = os.clock() + seal_secs, why = why }
    if seal_ox then
        S.status = "it lows - the pact is sealed"
        set_prompt("THE PACT IS SEALED", "It lows for you, deep and content.", 2.5, 0xFF80FFB0)
    elseif seal_cat then
        S.status = "it sits before you - the pact is sealed"
        set_prompt("THE PACT IS SEALED", "It sits before you, unhurried. You are chosen.", 2.5, 0xFF80FFB0)
    else
        S.status = "it howls - the pact is sealed"
        set_prompt("THE PACT IS SEALED", "It howls for you.", 2.5, 0xFF80FFB0)
    end
    return true
end

-- ============================ THE YOKE RITE (the ox tame, 07-21) ============================
-- Aurora's pack-beast: you don't BREAK an ox, you WIN it. Deliberate start only (hold N / B near a
-- pasture ox -- passive arming would sabotage the griffin's ox-offering hunt, the review's law).
-- approach (be near, be slow) -> greens (id-based feed) -> THE WALK (a gently-puppeted meander,
-- stay by its side) -> palm -> the standard stable finisher (the wolf's exact family path).
-- Every exit runs release_creature (the review's restore law: no immortal think-stopped statues).
re.on_application_entry("UpdateBehavior", function()
    pcall(function()
        if C.enabled == false or C.ox_rite_enabled == false then return end
        local now = os.clock()
        -- ⛔ 08-12 (Aurora: "I paused, when I unpaused the ox was gone... these things
        -- should never continue, count down or even show when pause menu is open"):
        -- the rite FREEZES whole while any pause holds -- timers re-baseline on the
        -- freeze so nothing counts, and nothing draws.
        if is_game_paused() then
            if S.ox_rite then S.ox_rite.last = now end
            S.ox_arm_t0 = nil
            return
        end
        local player = get_player()
        local pgo = player and char_go(player)
        local pp = pgo and upos(pgo)
        if not pp then return end
        local nheld = TB.held()   -- 08-12 slice A: keyboard N or pad B, one hold
        local R = S.ox_rite
        if not R then
            -- ARMING: a held N near a wild pasture ox, with NOTHING else underway (the review's
            -- exclusion list: any live scene/rite/feed/name-card blocks a fresh yoke)
            if S.oxtame or S.trial or S.camp_rite or S.mode == "trusting" or S.feed_drop
                or S.name_pending or S.combat_tame or S.yield_down or S.iris_carry then
                S.ox_arm_t0 = nil; return
            end
            -- ⭐ 08-13 TAMING MODE: no mark, no prompt, no arm while it is off (see the generic
            -- path). S.ox_rite is nil here, so a yoke already under way is never affected.
            if S.tame_mode ~= true then
                S.ox_arm_t0 = nil
                S.ox_mark = nil; S.ox_mark_go = nil
                pcall(function() if _G.IrisPrompt then _G.IrisPrompt.set("tame_ox", "") end end)
                return
            end
            -- round 13 (B on oxen was dead): the scan runs ALWAYS (throttled 0.3s) and
            -- MARKS its candidate -- the pad hand needs a subject BEFORE the rite exists,
            -- and the ox deserves the same begin-marker as every other tameable
            local found0 = nil
            if S.ox_scan_at and now < S.ox_scan_at
                and S.ox_mark and S.ox_mark.ch and char_go(S.ox_mark.ch) then
                found0 = S.ox_mark
            else
            S.ox_scan_at = now + 0.3
            pcall(function()
                local sm0 = sdk.get_native_singleton("via.SceneManager")
                local smt0 = sdk.find_type_definition("via.SceneManager")
                local scene0 = sm0 and sdk.call_native_func(sm0, smt0, "get_CurrentScene")
                local comps0 = scene0 and scene0:call("findComponents(System.Type)", sdk.typeof("app.Character"))
                local n0 = 0
                pcall(function() n0 = comps0:call("get_Length") or 0 end)
                if n0 == 0 then pcall(function() n0 = comps0:get_size() or 0 end) end
                local best0 = 12.0
                for i0 = 0, (tonumber(n0) or 0) - 1 do
                    pcall(function()
                        local ch0 = comps0:call("get_Item", i0) or comps0[i0]
                        local go0 = ch0 and ch0:call("get_GameObject")
                        if not go0 then return end
                        local nm0 = tostring(go_name(go0) or "")
                        -- 08-12 (the cart-ox arming, screenshot 53): cart oxen are refused by
                        -- OWNERSHIP (app.OxcartAI.CachedOx via the shared registry), not by
                        -- name -- and the old _B name exclusion is LIFTED: _B is the bull,
                        -- not the cart ox, and any unemployed ox may be won.
                        local employed0 = false
                        pcall(function()
                            local sp0 = rawget(_G, "IrisSpecies")
                            employed0 = sp0 and sp0.cart_ox and sp0.cart_ox(go0:get_address()) or false
                        end)
                        -- a locked-out ox (the stalled-yoke insult, or any courtship lockout)
                        -- is invisible to the arming until its patience returns
                        local locked0 = false
                        pcall(function()
                            local ga9 = go0:get_address()
                            locked0 = ga9 and S.lockouts
                                and (tonumber(S.lockouts[tostring(ga9)]) or 0.0) > os.clock() or false
                        end)
                        local resident0 = false   -- 08-12: the homestead's own are NEVER candidates
                        pcall(function()
                            local hb0 = rawget(_G, "IrisHomesteadBox")
                            resident0 = hb0 and hb0.is_resident and hb0.is_resident(go0:get_address()) or false
                        end)
                        if nm0:find("ch299003", 1, true) and not employed0 and not locked0 and not resident0
                            and not is_dead(ch0) and not iris_ox_is_tamed(ch0) then
                            local u0 = upos(go0)
                            local d0 = u0 and dist(u0, pp)
                            if d0 and d0 < best0 then best0 = d0; found0 = { ch = ch0, go = go0 } end
                        end
                    end)
                end
            end)
            S.ox_mark = found0
            end
            -- the MARK: the candidate ox wears the begin-marker + the shared prompt line
            if found0 and found0.go then
                S.ox_mark_go = found0.go
                local lbl0 = "Ox"
                pcall(function() lbl0 = tostring(creature_label(found0.go)) end)
                pcall(function()
                    local sp0 = rawget(_G, "IrisSpecies")
                    local g0 = sp0 and sp0.gender and sp0.gender(found0.go) or nil
                    if lbl0 == "Ox" then lbl0 = (g0 == "male" and "Bull") or (g0 == "female" and "Cow") or lbl0 end
                end)
                TB.mark(found0.go, "[N/B] Tame the " .. lbl0)   -- native B wins; this is the fallback
                pcall(function()
                    local mp0 = upos(found0.go)
                    -- 08-13: pos was nil here too -- the ox never got the native prompt either
                    if _G.IrisPrompt then _G.IrisPrompt.set("tame_ox", "Tame the " .. lbl0,
                        20, mp0 and dist(mp0, pp) or 99.0, TB.prompt_pos(found0.go), found0.go) end
                end)
            else
                S.ox_mark_go = nil
                pcall(function() if _G.IrisPrompt then _G.IrisPrompt.set("tame_ox", "") end end)
            end
            if found0 and nheld and player_sheathed(player) == false then
                S.ox_arm_t0 = nil
                set_prompt("LOWER YOUR WEAPON", "The ox will not accept an armed approach.", 3.0, 0xFF5050FF)
                return
            end
            -- ⭐ 08-13: ask the arbiter before the offer hold may begin (see TB.may_start)
            if not (nheld and TB.may_start("tame_ox")) then S.ox_arm_t0 = nil; return end
            if not found0 then S.ox_arm_t0 = nil; return end
            S.ox_arm_t0 = S.ox_arm_t0 or now
            -- the hand goes OUT during the offer hold (Aurora: "the initial start doesn't
            -- do the hand out pose") -- the same palm every other tame leads with
            pcall(function()
                local phc9 = math.floor(tonumber(C.player_hand_clip) or 6200)
                if not (S.phold and S.phold.clip == phc9) then
                    S.phold = { clip = phc9, until_t = now + 1.5 }
                else
                    S.phold.until_t = now + 1.5
                end
            end)
            iris_prog_hud((now - S.ox_arm_t0) / 1.2, "The Offer")
            if now - S.ox_arm_t0 >= 1.2 then
                S.ox_arm_t0 = nil
                S.ox_rite = { ch = found0.ch, go = found0.go, stage = "approach", t0 = now, appr = 0.0, last = now }
                S.ox_mark = nil; S.ox_mark_go = nil   -- the mark's job is done; the rite owns the moment
                pcall(function() if _G.IrisPrompt then _G.IrisPrompt.set("tame_ox", "") end end)
                -- 08-12 (Aurora: "it did IT WAITS but was still walking as normal"): think-stop
                -- only blocks NEW decisions -- a move command already in flight keeps walking.
                -- SEIZE the body at rite start: cancel the live action, pin navigation.
                -- release_creature clears both on every abort; the seal clears nav explicitly.
                pcall(function() found0.ch:call("resetActionAndAI") end)
                pcall(function() set_nav_stop(found0.ch, true) end)
                -- round 8 (STILL walking through the approach): IsStopCalled is a polite
                -- request that app.NavigationAI honors and the ox's MonsterNavigationController
                -- ignores. The wolf hold's proven grip: DISABLE the AI components outright.
                -- release_creature re-enables both on every exit; the wolf seals fine through
                -- the same try_finish with this exact state.
                pcall(function() set_ai(found0.ch, false) end)
                -- round 9 (the wolf grip ALSO failed on this chassis): anchor for the drift
                -- leash, and a one-shot census of every AI/nav-ish component so the log NAMES
                -- the mover the wolf doesn't have (receipts for the real kill next round)
                pcall(function() S.ox_rite.anchor = upos(found0.go) end)
                pcall(function()
                    local comps0 = found0.go:call("get_Components")
                    local n0 = 0
                    pcall(function() n0 = comps0:get_size() end)
                    if n0 == 0 then pcall(function() n0 = tonumber(comps0:call("get_Length")) or 0 end) end
                    local names0 = {}
                    for i0 = 0, (tonumber(n0) or 0) - 1 do
                        pcall(function()
                            local c0 = comps0:call("get_Item", i0) or comps0[i0]
                            local tn0 = c0:get_type_definition():get_full_name()
                            if tn0:find("AI") or tn0:find("Nav") or tn0:find("Situation")
                                or tn0:find("Schedule") or tn0:find("Move") or tn0:find("Think") then
                                names0[#names0 + 1] = tn0
                            end
                        end)
                    end
                    log.info("[OxRite] mover census: " .. table.concat(names0, ", "))
                    local ts0 = nil
                    pcall(function() ts0 = found0.ch:call("get_IsThinkStop") end)
                    log.info("[OxRite] think-stop readback: " .. tostring(ts0))
                end)
                -- offering snapshots taken HERE (not at offer-open) so greens dropped early,
                -- during the approach, still read as new when the offer stage looks
                pcall(function()
                    local mgr9 = item_mgr()
                    if mgr9 then S.ox_rite.give_seen = drop_list_snapshot(mgr9) end
                    S.ox_rite.give_gseen = ground_scan_snapshot(pgo)
                    S.ox_rite.give_gscan_at = now + 1.0
                end)
                set_prompt("THE YOKE RITE", "The ox regards you. Stay near, and move gently.", 7.0, 0xFFFFD080)
                pcall(function() log.info("[OxRite] armed on " .. tostring(go_name(found0.go))) end)
            end
            return
        end
        -- ===== the rite is LIVE =====
        local ch, go = R.ch, R.go
        -- ⭐ round 11 -- THE CENSUS RECEIPT: think-stop reads back NIL on ch299003 (the switch
        -- does not exist on this chassis) and app.MonsterNavigationController is on the body.
        -- Nav controllers translate the TRANSFORM directly -- no FSM, no root motion needed --
        -- which is why every animation-side hold failed. This is the muscle. Cut it during
        -- the rite; every exit and the seal switch it back on.
        local function yoke_nav_muscle(on9)
            pcall(function()
                local mn9 = comp(char_go(ch), "app.MonsterNavigationController")
                if mn9 then mn9:call("set_Enabled", on9 == true) end
            end)
        end
        if not (ch and char_go(ch)) or is_dead(ch) then
            -- death/despawn mid-rite: stand down CLEAN, and DECLINE the corpse for the griffin
            -- (the review's grim catch: your bonding ox must not become the next offering)
            if ch and char_go(ch) then
                pcall(function()
                    local ga0 = go and go:get_address()
                    if ga0 then S.oxtame_declined = { addr = ga0, until_t = now + 120.0 } end
                end)
                yoke_nav_muscle(true)
                pcall(function() set_player_fsm(go, true) end)
                pcall(function() release_creature(ch) end)
            end
            S.ox_rite = nil
            set_prompt("THE RITE BREAKS", "The moment is lost.", 5.0, 0xFF5050FF)
            pcall(function() log.info("[OxRite] stand-down: the ox died or despawned") end)
            return
        end
        local gp = upos(go)
        if not gp then return end
        -- the rite SHIELD (08-12, Mootilda sealed at 1/700): pawns fight on around a
        -- multi-minute rite -- the courted ox is pawn-proof from first regard to the seal.
        -- release_creature clears it on every abort; the seal-heal mends any earlier hurt.
        pcall(function() set_immunity(ch, true) end)
        local dp = dist(gp, pp)
        local dt0 = now - (tonumber(R.last) or now)
        R.last = now
        if dt0 <= 0.0 or dt0 > 0.25 then dt0 = 0.033 end
        local psp = 0.0
        if R.ppos then psp = dist(pp, R.ppos) / math.max(0.016, dt0) end
        R.ppos = pp
        local npressed = nheld and R.nprev ~= true
        R.nprev = nheld
        -- 08-12 round 8 (Aurora: "the same cancel logic for each part of the tame"): ONE
        -- stand-down for every stage's stalled patience -- lockout, full body restore, card.
        local function yoke_stand_down(msg9)
            pcall(function()
                local ga0 = go and go:get_address()
                if ga0 then S.lockouts = S.lockouts or {}; S.lockouts[tostring(ga0)] = os.clock() + 120.0 end
            end)
            yoke_nav_muscle(true)
            pcall(function() set_player_fsm(go, true) end)
            pcall(function() release_creature(ch) end)
            S.ox_rite = nil
            set_prompt("IT WANTS NONE OF THIS", msg9, 7.0, 0xFF5050FF)
            pcall(function() log.info("[OxRite] stand-down: " .. tostring(msg9)) end)
        end
        if player_sheathed(player) == false then
            yoke_stand_down("You drew steel. The ox shies and leaves.")
            return
        end
        -- round 10 (Aurora: "and face the player too"): a slow, heavy turn toward you while
        -- it holds -- ~70 degrees/s, never a snap. Direction from universal deltas (they are
        -- translation-invariant); the yaw write is the puppet_step recipe.
        local function yoke_face_player()
            pcall(function()
                local gp9 = upos(go); if not gp9 then return end
                local tr9 = go:call("get_Transform")
                local q0 = tr9:call("get_Rotation")
                local cur9 = math.atan(2.0 * (q0.w * q0.y + q0.x * q0.z),
                    1.0 - 2.0 * (q0.y * q0.y + q0.x * q0.x))
                local want9 = math.atan(pp.x - gp9.x, pp.z - gp9.z)
                local d9 = ((want9 - cur9 + math.pi) % 6.2831853) - math.pi
                local cap9 = 1.2 * dt0
                if d9 > cap9 then d9 = cap9 elseif d9 < -cap9 then d9 = -cap9 end
                local y9 = cur9 + d9
                local q9 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                q9.x = 0; q9.y = math.sin(y9 / 2.0); q9.z = 0; q9.w = math.cos(y9 / 2.0)
                tr9:call("set_Rotation", q9)
            end)
        end
        -- walking away ends it gracefully (any stage); 08-12 round 8: past 40m it is simply
        -- ABANDONED -- no lockout (leaving is not an insult). Round 12: the reading must
        -- PERSIST a full second -- a single-frame garbage universal read (the tile re-base
        -- shear) fired a phantom abandon while Aurora stood BESIDE the ox.
        if dp > 40.0 then
            R.far40_t = R.far40_t or now
        else
            R.far40_t = nil
        end
        if R.far40_t and now - R.far40_t > 1.0 then
            yoke_nav_muscle(true)
            pcall(function() set_player_fsm(go, true) end)
            pcall(function() release_creature(ch) end)
            S.ox_rite = nil
            set_prompt("THE RITE IS ABANDONED", "You have left it behind. The ox returns to its grazing.", 7.0, 0xFFFFD080)
            pcall(function() log.info("[OxRite] stand-down: abandoned (>40m held 1s)") end)
            return
        elseif dp > 25.0 then
            R.far_t = R.far_t or now
            if now - R.far_t > 15.0 then
                yoke_nav_muscle(true)
                pcall(function() set_player_fsm(go, true) end)
                pcall(function() release_creature(ch) end)
                S.ox_rite = nil
                set_prompt("IT RETURNS TO ITS GRAZING", "The ox loses interest. Come back, and come gently.", 7.0, 0xFFFFD080)
                pcall(function() log.info("[OxRite] stand-down: player left") end)
                return
            end
        else
            R.far_t = nil
        end
        yoke_nav_muscle(false)   -- round 11: the muscle stays cut every rite frame, all stages
        if R.stage == "approach" then
            -- it holds its ground and watches (the dog-probe hold: think stopped = no wander-off;
            -- round 8: + the wolf grip, AI components OFF -- the ox's monster-nav ignores polite stops)
            pcall(function() set_think_stop(ch, true) end)
            pcall(function() set_ai(ch, false) end)
            -- round 10 (Aurora: the leash just STUTTERS -- "force its motion to be standing
            -- idle from the atlas"): the clip-visibility law was the answer all along. FSM
            -- off + the atlas standing idle (0:0 com_idle_loop, no root motion) = the body
            -- holds itself still, and a lying ox stands up into the moment.
            pcall(function() set_player_fsm(go, false) end)
            pcall(function()
                if R.clip ~= 0 then R.clip = 0; play_motion(ch, 0, 0) end
            end)
            yoke_face_player()
            if dp <= 8.0 and psp < 2.5 then
                R.appr = math.min(4.0, (tonumber(R.appr) or 0.0) + dt0)
            elseif psp >= 4.5 then
                R.appr = 0.0   -- charging at it undoes the moment (no shy walk-away: hunting stays frictionless)
            end
            -- patience: The Measure must RISE. 25s without a new high-water mark = it tires.
            R.appr_stall = R.appr_stall or now
            if (tonumber(R.appr) or 0.0) > (tonumber(R.appr_hi) or 0.0) then
                R.appr_hi = R.appr; R.appr_stall = now
            elseif now - (tonumber(R.appr_stall) or now) > 25.0 then
                yoke_stand_down("It tires of your distance. The ox returns to its grazing.")
                return
            end
            iris_prog_hud((tonumber(R.appr) or 0.0) / 4.0, "The Measure")
            -- 08-12 wording (Aurora read "approach" as the OX approaching): these cards
            -- direct HER feet -- the ox holds its ground on purpose
            if dp > 8.0 then
                set_prompt("THE APPROACH", "Walk to it slowly -- rushing breaks the moment.", 0.6, 0xFF80D0FF)
            else
                set_prompt("THE APPROACH", "Stand near and be still -- it is taking your measure.", 0.6, 0xFF80D0FF)
            end
            if (tonumber(R.appr) or 0.0) >= 4.0 then
                R.stage = "offer"; R.t0 = now
                set_prompt("IT ABIDES YOU", "It does not turn away. Offer it something green.", 7.0, 0xFF80FFB0)
            end
        elseif R.stage == "offer" then
            pcall(function() set_think_stop(ch, true) end)
            pcall(function() set_ai(ch, false) end)   -- round 8: the wolf grip holds through the offer too
            -- round 10: the idle hold until the greens are laid -- then the eat-walk owns the body
            if not R.fed then
                pcall(function() set_player_fsm(go, false) end)
                pcall(function()
                    if R.clip ~= 0 then R.clip = 0; play_motion(ch, 0, 0) end
                end)
                yoke_face_player()
            end
            -- patience: a full minute to open the pack and lay the greens (menus don't pause
            -- the world) -- then it tires of waiting
            if not R.fed then
                R.offer_t0 = R.offer_t0 or now
                if now - (tonumber(R.offer_t0) or now) > 60.0 then
                    yoke_stand_down("Nothing was laid before it. The ox returns to its grazing.")
                    return
                end
            end
            if R.fed then
                -- 08-12 (Aurora: "the ox doesn't even approach the food"): it WALKS to the
                -- laid greens (the wolf feed-machine shape) and EATS with its real clips --
                -- atlas-verified ch299003 liv 60:0 eat_start -> 60:1 eat_loop.
                -- ⛔ THE CLIP-VISIBILITY LAW (the sliding ox): think-stop alone leaves the
                -- FSM owning layer 0 -- clips only SHOW with the FSM off. Off during the
                -- driven beats, restored at the walk->palm handoff and every exit.
                pcall(function() set_player_fsm(go, false) end)
                if R.feedpt and not R.eating and dist(gp, R.feedpt) > 2.0 then
                    pcall(function() puppet_step(go, gp, R.feedpt.x, R.feedpt.z, 1.0, dt0, 1.2) end)
                    pcall(function()
                        if R.clip ~= 100 then R.clip = 100; play_motion(ch, 0, 100) end
                    end)
                    R.fed = now   -- the eat beat times from ARRIVAL at the greens
                else
                    if not R.eating then
                        R.eating = true
                        R.clip = nil
                        pcall(function() play_motion(ch, 60, 0) end)   -- eat_start
                        R.eat_loop_at = now + 1.2
                    end
                    if R.eat_loop_at and now >= R.eat_loop_at then
                        R.eat_loop_at = nil
                        pcall(function() play_motion(ch, 60, 1) end)   -- eat_loop
                    end
                    if now - (tonumber(R.fed) or now) > 4.0 then
                        -- the REAL drop is eaten: despawn its ground object
                        pcall(function()
                            if R.drop_go then R.drop_go:call("destroy", R.drop_go); R.drop_go = nil end
                        end)
                        -- round 13 (Aurora: "after eating, the ox faces you and lows"): the
                        -- beat between meal and yoke -- atlas 0:2 com_idle_cry IS the moo
                        R.stage = "low"; R.low_t0 = now; R.clip = nil; R.eating = nil
                        pcall(function() play_motion(ch, 0, 2) end)
                        set_prompt("IT LOWS FOR YOU", "The offering is taken. It turns to you and lows, long and deep.", 4.0, 0xFF80FFB0)
                    end
                end
            else
                -- 08-12 round 3 (Morningtide and Pitywort lay IGNORED): pack discards never
                -- enter get_DropItemList -- that list read as loot-bags-only in the field
                -- (the law learned at the critter tames, comment at ground_scan_snapshot).
                -- The REAL detector is the critter pair: a drop-list DELTA plus a scene-mesh
                -- delta for the discards the list never shows.
                -- 08-12 round 7 (Aurora RAN AWAY and "it eats" fired): both detectors measure
                -- from the PLAYER -- running through the world streams new meshes (and loot
                -- drops) around you, and any of them read as the offering. Two laws now:
                -- detection only runs with the player NEAR the ox, and the offering only
                -- counts if it lies NEAR THE OX -- the card says "before it", so does the code.
                if dp > 10.0 then
                    set_prompt("IT WAITS", "Return to it -- the offering must be laid before it.", 0.6, 0xFF80D0FF)
                    return
                end
                local mgr9 = item_mgr()
                if not R.give_seen and mgr9 then
                    R.give_seen = drop_list_snapshot(mgr9)
                    R.give_gseen = ground_scan_snapshot(pgo)
                    R.give_gscan_at = now + 1.0
                end
                local drop9 = (mgr9 and R.give_seen) and find_new_drop(mgr9, player, R.give_seen) or nil
                local drop_go9 = nil
                if not drop9 and R.give_gseen and now >= (tonumber(R.give_gscan_at) or 0.0) then
                    R.give_gscan_at = now + 1.0   -- the scene sweep is heavy: once a second
                    drop_go9 = ground_scan_new(pgo, R.give_gseen)
                end
                -- round 13 junk law, ported from the critter give (the phantom offering: it
                -- "ate" a streamed mesh and marched straight to the yoke): a ground-scan
                -- find must be item-shaped, never engine scenery
                if not drop9 and drop_go9 then
                    -- round 14 CORRECTION (the refused Greenwarish): real dropped ITEMS wear
                    -- engine names too (gm/it/sm prefixes) -- those PASS. Only true scenery
                    -- patterns are junk: characters, planes, trims, double-underscore names.
                    local l9 = ""
                    pcall(function() l9 = tostring(go_name(drop_go9) or "") end)
                    if l9 == "" or l9:find("^ch%d") or l9:find("Plane")
                        or l9:find("Trim") or l9:find("__") then
                        pcall(function() log.info("[OxRite] ground-scan REJECTED scenery: '" .. l9 .. "'") end)
                        drop_go9 = nil
                    end
                end
                if drop9 or drop_go9 then
                    local dgo9 = nil
                    pcall(function() dgo9 = (drop9 and drop9:call("get_GameObject")) or drop_go9 end)
                    -- drop render -> UNIVERSAL through the player's own offset
                    local ux9, uy9, uz9 = pp.x, pp.y, pp.z
                    pcall(function()
                        local rp9 = dgo9:call("get_Transform"):call("get_Position")
                        local prp9 = pgo:call("get_Transform"):call("get_Position")
                        ux9 = pp.x + (rp9.x - prp9.x); uy9 = pp.y + (rp9.y - prp9.y); uz9 = pp.z + (rp9.z - prp9.z)
                    end)
                    -- BEFORE THE OX: within its WALK, not its nose (round 12 -- the 6m radius
                    -- silently rejected honest drops and the two 0.6s cards strobed; the
                    -- eat-walk exists precisely to cover distance)
                    local doff9 = dist({ x = ux9, y = uy9, z = uz9 }, gp)
                    local near_ox9 = doff9 <= 12.0
                    if not near_ox9 then
                        pcall(function() log.info(string.format(
                            "[OxRite] offering rejected: %.1fm from the ox (limit 12)", doff9)) end)
                    end
                    if near_ox9 then
                        R.feedpt = { x = ux9, y = uy9, z = uz9 }
                        R.drop_go = dgo9
                        R.fed = now
                        set_prompt("THE OFFERING", "The greens lie before it. It comes to eat.", 5.0, 0xFF80FFB0)
                        pcall(function() log.info("[OxRite] offering seen via " .. (drop9 and "drop-list" or "ground-scan")) end)
                    else
                        set_prompt("IT WAITS", "Lay it closer -- the offering must rest nearer the ox.", 2.5, 0xFF80D0FF)
                    end
                else
                    set_prompt("IT WAITS", "Open your pack and DROP something green before it -- Greenwarish or other greens.", 0.6, 0xFF80D0FF)
                end
            end
        elseif R.stage == "low" then
            -- the LOW: it turns to face you and cries its own cry -- then the yoke
            pcall(function() set_think_stop(ch, true) end)
            pcall(function() set_ai(ch, false) end)
            pcall(function() set_player_fsm(go, false) end)
            yoke_face_player()
            -- round 14: 2.6s cut the cry short -- give the low its full breath
            if now - (tonumber(R.low_t0) or now) > 4.6 then
                R.stage = "walk"; R.bond = 0.0; R.wp = nil; R.clip = nil
                set_prompt("THE YOKE", "Walk with it. Stay by its side as it wanders.", 7.0, 0xFF80FFB0)
            end
        elseif R.stage == "walk" then
            -- ⭐ THE WALK: the signature beat. The ox MEANDERS under a gentle puppet (the review's
            -- law: native graze can stall forever, so the walking is guaranteed) and the bond fills
            -- only while you keep its side.
            pcall(function() set_think_stop(ch, true) end)
            pcall(function() set_player_fsm(go, false) end)   -- clips must OWN the body (the sliding-ox law)
            -- 08-12 round 4 (Aurora: "random 180 turns... sudden shunts"): no more waypoint
            -- lottery. The ox carries a HEADING that drifts in gentle bounded arcs -- a new
            -- goal heading at most ~60 degrees away every 5-9s, and the live heading slews
            -- toward it at ~35 deg/s. Every turn is a walked curve, never a snap.
            if R.hdg == nil then
                -- seed from the body's current facing so the first step continues it, not snaps
                R.hdg = 0.0
                pcall(function()
                    local q9 = go:call("get_Transform"):call("get_Rotation")
                    R.hdg = math.atan(2.0 * (q9.w * q9.y + q9.x * q9.z),
                        1.0 - 2.0 * (q9.y * q9.y + q9.x * q9.x))
                end)
                R.hdg_tgt = R.hdg
            end
            if not R.hdg_tgt or now > (tonumber(R.hdg_t) or 0.0) then
                R.hdg_tgt = R.hdg + (math.random() - 0.5) * 2.1
                R.hdg_t = now + 5.0 + math.random() * 4.0
            end
            local trn9 = ((R.hdg_tgt - R.hdg + math.pi) % 6.2831853) - math.pi
            local cap9 = 0.6 * dt0
            if trn9 > cap9 then trn9 = cap9 elseif trn9 < -cap9 then trn9 = -cap9 end
            R.hdg = R.hdg + trn9
            -- amble pace (round 4: "walking a bit too fast"), stepping along the heading
            pcall(function() puppet_step(go, gp, gp.x + math.sin(R.hdg) * 4.0, gp.z + math.cos(R.hdg) * 4.0, 0.85, dt0, 1.2) end)
            pcall(function()
                -- latch the walk clip (com convention: 100 = walk loop; restarting it every frame
                -- is the anim-spam trap, so assert only on change)
                if R.clip ~= 100 then R.clip = 100; play_motion(ch, 0, 100) end
            end)
            -- round 14 (Aurora: "you need to KEEP TIME with it"): the bond fills only while
            -- you are near AND walking at its pace -- the ox ambles at 0.85 m/s, so the
            -- accepted band is a generous walk (0.35..1.9). Sprinting past or standing
            -- rooted earns nothing; the stall clock does the judging if it goes on.
            if dp <= 6.0 then
                -- round 15 (the strobing card): raw per-frame speed JITTERS across the band
                -- edges. Smooth it (EMA), and the VERDICT is sticky -- a new judgment must
                -- hold 0.35s before the card changes its mind. The bond follows the sticky
                -- verdict, so it fills steadily for honest walking.
                R.psp_s = (tonumber(R.psp_s) or psp) * 0.85 + psp * 0.15
                local v9 = (R.psp_s > 2.1 and "fast") or (R.psp_s < 0.30 and "slow") or "ok"
                if v9 ~= R.pace_pend then R.pace_pend = v9; R.pace_pend_t = now end
                R.pace_state = R.pace_state or "ok"
                if v9 ~= R.pace_state and now - (tonumber(R.pace_pend_t) or now) > 0.35 then
                    R.pace_state = v9
                end
                if R.pace_state == "ok" then
                    R.bond = math.min(20.0, (tonumber(R.bond) or 0.0) + dt0)
                    set_prompt("THE YOKE", "Stay with it -- side by side, step for step.", 0.6, 0xFF80D0FF)
                elseif R.pace_state == "fast" then
                    set_prompt("THE YOKE", "Too hurried -- match its amble.", 0.6, 0xFFFFD080)
                else
                    set_prompt("THE YOKE", "Walk WITH it -- standing still is not walking together.", 0.6, 0xFFFFD080)
                end
            elseif dp > 10.0 then
                set_prompt("THE YOKE", "You fall behind -- keep its side.", 0.6, 0xFF5050FF)
            end
            iris_prog_hud((tonumber(R.bond) or 0.0) / 20.0, "The Yoke")
            -- 08-12 round 7 (Aurora: "if it stays at 0% too long the ox should run away and
            -- end the tame"): the ox has PATIENCE. If the bond has not RISEN in 20s -- never
            -- started or abandoned mid-walk -- it wants none of this. The shared lockout
            -- ledger keeps the insulted ox uncourtable for two minutes.
            R.bond_stall = R.bond_stall or now
            if (tonumber(R.bond) or 0.0) > (tonumber(R.bond_hi) or 0.0) then
                R.bond_hi = R.bond; R.bond_stall = now
            elseif now - (tonumber(R.bond_stall) or now) > 20.0 then
                yoke_stand_down("You did not keep its side. The ox shakes off the moment and returns to its grazing.")
                return
            end
            if (tonumber(R.bond) or 0.0) >= 20.0 then
                R.stage = "palm"; R.clip = 2
                R.cry_until = now + 4.6   -- round 14 (Aurora): the yoke completes with the
                pcall(function() play_motion(ch, 0, 2) end)   -- idle cry again -- it LOWS
                -- round 10: FSM STAYS OFF -- the native idle was the walking-away problem;
                -- the atlas idle holds it until the seal restores everything
                set_prompt("IT SLOWS AND STANDS", "Stand before it, and hold out your hand (hold N / B).", 8.0, 0xFF80FFB0)
            end
        elseif R.stage == "palm" then
            pcall(function() set_think_stop(ch, true) end)
            pcall(function() set_ai(ch, false) end)
            pcall(function() set_player_fsm(go, false) end)   -- round 10: the atlas idle owns it to the seal
            pcall(function()
                -- round 14: let the completion LOW finish before the idle takes over
                if now >= (tonumber(R.cry_until) or 0.0) and R.clip ~= 0 then
                    R.clip = 0; play_motion(ch, 0, 0)
                end
            end)
            yoke_face_player()
            -- patience: 30s for the hand to come out and STAY -- a new high-water mark resets it
            R.palm_stall = R.palm_stall or now
            if (tonumber(R.palm) or 0.0) > (tonumber(R.palm_hi) or 0.0) then
                R.palm_hi = R.palm; R.palm_stall = now
            elseif now - (tonumber(R.palm_stall) or now) > 30.0 then
                yoke_stand_down("The hand never came. The ox returns to its grazing.")
                return
            end
            if dp < 3.5 and nheld then
                R.palm = (tonumber(R.palm) or 0.0) + dt0
                local phc0 = math.floor(tonumber(C.player_hand_clip) or 6200)
                -- plain hand-out, NO posture pitch: an ox head meets the hand at its own height
                if not (S.phold and S.phold.clip == phc0) then
                    S.phold = { clip = phc0, until_t = now + 1.5 }
                else
                    S.phold.until_t = now + 1.5; S.phold.pose = nil
                end
                iris_prog_hud((tonumber(R.palm) or 0.0) / 3.0, "The Palm")
                set_prompt("THE PALM", "Hold... it leans into your hand.", 1.2, 0xFF80FFB0)
                if (tonumber(R.palm) or 0.0) >= 3.0 then
                    -- SEAL: register the family ox FIRST (the offering machinery must never see it
                    -- again), then the standard finisher -- the wolf's exact stable path
                    pcall(function()
                        local a0 = ch:get_address()
                        if a0 then S.ox_tamed = S.ox_tamed or {}; S.ox_tamed[a0] = true end
                    end)
                    S.ox_rite = nil
                    yoke_nav_muscle(true)                           -- round 11: the muscle comes back at the seal
                    pcall(function() set_nav_stop(ch, false) end)   -- the rite pinned nav at arm; the companion must walk
                    pcall(function() set_player_fsm(go, true) end)  -- round 10: the FSM comes back at the seal
                    try_finish(player, pgo, ch, go, "the yoke rite", true)
                    pcall(function() log.info("[OxRite] SEALED: the ox joins the family") end)
                    return
                end
            else
                R.palm = 0.0
                set_prompt("THE PALM", "Stand before it and hold N / B -- offer your hand.", 0.6, 0xFF80D0FF)
            end
        end
    end)
end)

-- ============================ per-frame ============================
-- ============ the NAME CARD, D2D (RiftSpeak baby-card style, PRIMAL palette) ============
function iris_name_make_fonts(sh)
    -- ⭐ ONE ON-SCREEN FACE: ask IrisFont first so the name card wears the shared serif
    -- and follows the shared size slider; the local ladder survives as the no-IrisFont
    -- fallback. Cache keyed on the RESOLVED px so moving the slider rebuilds the faces.
    local F = _G.IrisFont
    local key = tostring(math.floor(sh)) .. ":" .. tostring((F and F.px) and F.px(44) or "-")
    if S.name_fonts and S.name_font_key == key then return S.name_fonts end
    if not (_G.d2d and d2d.Font and d2d.Font.new) then return nil end
    local scale = sh / 1080.0
    local function font(px)
        if F and F.d2d and F.px then
            local shared = F.d2d(px)
            if shared then return shared, F.px(px) end
        end
        px = math.max(12, math.floor(px * scale))
        for _, fn in ipairs({ "LinLibertine_R.ttf", "times.ttf", "NotoSansJP-Regular.ttf" }) do
            local ok, f = pcall(d2d.Font.new, fn, px)
            if ok and f then return f, px end
        end
        return nil, px
    end
    local ft = {}
    ft.title_f, ft.title_px = font(44)
    ft.name_f, ft.name_px = font(40)
    ft.body_f, ft.body_px = font(24)
    if not (ft.title_f and ft.name_f and ft.body_f) then return nil end
    S.name_fonts, S.name_font_h, S.name_font_key = ft, sh, key
    return ft
end

-- Controller edges for the naming card. Resolve enum names instead of baking Xbox masks;
-- PlayStation/Nintendo layouts still report their semantic Decide/Cancel fields here.
function iris_name_pad_edges()
    if not S.name_pad_bits then
        local bits = { a = 0, b = 0 }
        pcall(function()
            local td = sdk.find_type_definition("via.hid.GamePadButton")
            local names = {}
            for _, f in ipairs(td:get_fields()) do pcall(function() names[f:get_name()] = f:get_data() end) end
            local function pick(...)
                for _, n in ipairs({ ... }) do if tonumber(names[n]) then return math.floor(names[n]) end end
                return 0
            end
            bits.a = pick("Decide", "A", "RDown", "Cross", "South")
            bits.b = pick("Cancel", "B", "RRight", "Circle", "East")
        end)
        S.name_pad_bits = bits
    end
    local mask = 0
    pcall(function()
        local gp = sdk.get_native_singleton("via.hid.GamePad")
        local td = sdk.find_type_definition("via.hid.GamePad")
        local dv = gp and td and sdk.call_native_func(gp, td, "get_MergedDevice")
        if not dv then dv = gp and td and sdk.call_native_func(gp, td, "getMergedDevice(System.UInt32)", 0) end
        mask = math.floor(tonumber(dv and dv:call("get_Button")) or 0)
    end)
    if S.name_pad_prev == nil then S.name_pad_prev = mask; return false, false end
    local edge9 = mask & (~math.floor(tonumber(S.name_pad_prev) or 0))
    S.name_pad_prev = mask
    local bits = S.name_pad_bits or { a = 0, b = 0 }
    return bits.a ~= 0 and (edge9 & bits.a) ~= 0,
        bits.b ~= 0 and (edge9 & bits.b) ~= 0
end

function iris_name_draw_card()
    if not S.name_pending then return end
    if not (_G.d2d and d2d.fill_rect and d2d.text) then return end
    local sw, sh = 1920, 1080
    local ok, w, h = pcall(d2d.surface_size); if ok and w and h and h > 0 then sw = w; sh = h end
    local ft = iris_name_make_fonts(sh); if not ft then return end
    local scale = sh / 1080.0
    local now = os.clock()
    local function argb(a, rgb) if a < 0 then a = 0 elseif a > 1 then a = 1 end return math.floor(255 * a) * 0x1000000 + (rgb % 0x1000000) end
    local function measure(font, s)
        local mw2 = #tostring(s) * 9
        local ok2, mw = pcall(d2d.measure_text, font, tostring(s))
        if ok2 and mw and mw > 0 then mw2 = mw end
        return mw2
    end
    -- Stable/decoration palette: smoke panel, gold hairlines, cream hierarchy.
    local C_SHADOW, C_ACCENT, C_PANEL = 0x000000, 0xC8A050, 0x14141A
    local C_TITLE, C_NAME, C_DIM = 0xE8D8A8, 0xFFF0C8, 0x8E8A82
    pcall(d2d.fill_rect, 0, 0, sw, sh, argb(0.72, C_SHADOW))
    local pad = math.floor(34 * scale)
    local accent_h = math.max(2, math.floor(2 * scale))
    local cw = math.max(620 * scale, math.min(sw * 0.5, 900 * scale))
    local chh = accent_h + pad + (ft.title_px or 44) + math.floor(22 * scale)
        + (ft.body_px or 24) + math.floor(8 * scale) + (ft.name_px or 40)
        + math.floor(18 * scale) + (ft.body_px or 24) + pad
    local cx = math.floor((sw - cw) * 0.5)
    local cy = math.floor((sh - chh) * 0.5)
    local b = math.max(2, math.floor(2.5 * scale))
    pcall(d2d.fill_rect, cx + b * 3, cy + b * 3, cw, chh, argb(0.45, C_SHADOW))
    pcall(d2d.fill_rect, cx, cy, cw, chh, argb(0.96, C_PANEL))
    pcall(d2d.fill_rect, cx, cy, cw, accent_h, argb(1.0, C_ACCENT))
    pcall(d2d.fill_rect, cx, cy + chh - accent_h, cw, accent_h, argb(1.0, C_ACCENT))
    local function center(font, s, ty, col)
        local tx = math.floor(cx + (cw - measure(font, s)) * 0.5)
        pcall(d2d.text, font, s, tx + 2, ty + 2, argb(0.7, C_SHADOW))
        pcall(d2d.text, font, s, tx, ty, argb(1.0, col))
    end
    local y = cy + accent_h + pad
    -- gender rides the christening: "Name the female Bat who chose you"
    local who = S.name_pending.label or "one"
    if S.name_pending.gender then who = tostring(S.name_pending.gender) .. " " .. who end
    center(ft.title_f, "THE STABLE  /  RENAME", y, C_TITLE)
    y = y + (ft.title_px or 44) + math.floor(22 * scale)
    center(ft.body_f, "Name the " .. who .. " who chose you", y, C_DIM)
    y = y + (ft.body_px or 24) + math.floor(8 * scale)
    local blink = (math.floor(now * 2) % 2 == 0) and "_" or " "
    center(ft.name_f, tostring(S.name_buf or "") .. blink, y, C_NAME)
    y = y + (ft.name_px or 40) + math.floor(18 * scale)
    center(ft.body_f, "Type a name    [Enter / A] Confirm    [Esc / B] Cancel", y, C_DIM)
end

-- external open-rename hook: the main mod's stable Rename buttons pop THIS name card
_G.IrisTaming = _G.IrisTaming or {}
-- on-screen banner for sibling mods (2026-08-08: the ride-size gate's refusal was invisible
-- -- panel-only status. Same card the hatch/incubation messages use.)
_G.IrisTaming.prompt = function(title, sub, secs, color)
    pcall(function() set_prompt(tostring(title or ""), tostring(sub or ""), tonumber(secs) or 3.0, color) end)
end
-- ⛔⛔⛔ 08-17: let IrisGriffin/downed.lua end a scout AT THE SOURCE, in the same breath it throws
-- a rider off a downed mount. The watchdog catches this too, but downed_enter is the earliest
-- possible frame -- before it disables components and claims the animation layer -- and "earliest"
-- is the whole game when the alternative is two owners on an action-claimed body.
-- Safe from any state and idempotent (scout_force_restore's own contract).
_G.IrisTaming.scout_abort = function(reason)
    if not S.scout then return false end
    pcall(function() scout_force_restore(tostring(reason or "aborted")) end)
    return true
end
_G.IrisTaming.is_scouting = function(go_addr)
    -- "is THIS body the one currently being flown as a scout drone?" (GameObject address)
    local yes = false
    pcall(function()
        local sc = S.scout
        if not (sc and sc.ch) then return end
        local g = char_go(sc.ch)
        if g and go_addr and g:get_address() == go_addr then yes = true end
    end)
    return yes
end
_G.IrisTaming.open_rename = function(stable_id, current_name)
    S.name_pending = { kind = "stable_id", stable_id = stable_id }
    S.name_buf = tostring(current_name or "")
    S.name_pad_prev = nil
end
-- external CHRISTENING hook (07-24, the horse tame): another mod just
-- sealed a creature into the stable via the bridge — pop the full
-- "Name the <gender> <label> who chose you" card for it
_G.IrisTaming.open_christening = function(label, gender)
    S.name_pending = { kind = "stable", label = tostring(label or "one"),
        gender = gender }
    S.name_buf = ""
    S.name_pad_prev = nil
    -- ⭐⭐ 08-13 AUTO-LEAVE TAMING MODE ON A SUCCESSFUL TAME (Aurora's default, with the checkbox
    -- to override). This is THE universal success hook -- every rite routes its seal through the
    -- christening, the horse rodeo included -- so one place covers all of them.
    -- ⛔ ALWAYS ANNOUNCE IT. A mode that switches itself off silently is the same usability trap
    -- as one that switches itself on silently: the next time B does not offer a tame, the player
    -- has no way to know why. The card is the receipt.
    if S.tame_mode == true and C.tame_mode_stay ~= true then
        S.tame_mode = false
        S.tame_mark = nil; S.ox_mark = nil; S.ox_mark_go = nil
        pcall(function()
            if _G.IrisPrompt then
                _G.IrisPrompt.set("tame_begin", ""); _G.IrisPrompt.set("tame_ox", "")
            end
        end)
        set_prompt("TAMING MODE ENDED", "The bond is made. (Keep it on in the Stable screen's Taming page.)", 4.0, 0xFF80D0FF)
        pcall(function() log.info("[IrisTaming] taming mode -> OFF (auto, tame sealed)") end)
    end
end
-- the probe's companion nameplate defers to ours: bodies in the local roster (critters)
-- already carry a plate here -- without this check the active critter wore two
_G.IrisTaming.has_pet = function(addr)
    if not addr then return false end
    for kch in pairs(S.tamed or {}) do
        local ok, a = pcall(function() return kch:get_address() end)
        if ok and a == addr then return true end
    end
    return false
end
-- 08-11 (the released-rabbit fallout): a stable RELEASE must also free the TAMING-side
-- pet -- critters live in BOTH rosters, and this one kept the plate, the petting and the
-- shoulder-perch alive after the bond was severed ("just called Rabbit", still droning).
-- Takes the CHARACTER address (same as has_pet -- the address-class law).
_G.IrisTaming.forget_pet = function(addr)
    if not addr then return false end
    for kch in pairs(S.tamed or {}) do
        local ok, a = pcall(function() return kch:get_address() end)
        if ok and a == addr then
            S.tamed[kch] = nil
            return true
        end
    end
    return false
end
-- ONE switch for every plate, taming-side checkbox: the probe asks before drawing its own
_G.IrisTaming.nameplates_on = function() return C.companion_nameplate ~= false end
-- 08-12 (Wild Blood must never touch a pet): is this GO address one of the taming-side
-- pets? Takes the GAMEOBJECT address (named _body to keep the address-class law visible).
_G.IrisTaming.is_pet_body = function(go_addr)
    if not go_addr then return false end
    local hit = false
    pcall(function()
        for kch in pairs(S.tamed or {}) do
            local g = char_go(kch)
            if g and g:get_address() == go_addr then hit = true; break end
        end
    end)
    return hit
end

-- HOUSE CAT: the rabbit chassis is spawned here and enters S.tamed immediately.
-- IrisTaming is therefore the sole owner of its movement, solidity and pickup;
-- the retired IrisPets/PetDogProbe-style controller never drives this body.
function HC.pin_mesh()
    if C.housecat_mesh_armed ~= true then
        S.housecat_status = "disarmed"
        return false
    end
    if S.housecat_res and S.housecat_mdf_res and S.housecat_mdf_holder then return true end
    if not S.housecat_res then
        local res = sdk.create_resource("via.render.MeshResource", HC.mesh)
        if not res then
            S.housecat_status = "mesh unavailable -- mount the v0.7-or-newer house-cat PAK first"
            return false
        end
        res:add_ref()
        S.housecat_res = res
    end
    local mdf = sdk.create_resource("via.render.MeshMaterialResource", HC.mdf)
    if not mdf then
        S.housecat_status = "material unavailable -- install the v0.7-or-newer house-cat PAK"
        return false
    end
    mdf:add_ref()
    local mdf_holder = nil
    pcall(function()
        mdf_holder = mdf:create_holder("via.render.MeshMaterialResourceHolder")
        if mdf_holder then mdf_holder:add_ref() end
    end)
    if not mdf_holder then
        S.housecat_status = "house-cat material holder creation failed"
        return false
    end
    S.housecat_mdf_res = mdf
    S.housecat_mdf_holder = mdf_holder
    S.housecat_warm_at = os.clock()
    S.housecat_status = "mesh and material streaming"
    return true
end

function HC.mesh_ready()
    if not HC.pin_mesh() then return false, S.housecat_status end
    local age = os.clock() - (tonumber(S.housecat_warm_at) or 0.0)
    if age < HC.warm_secs then
        S.housecat_status = string.format("mesh streaming %.0f / %.0f seconds", age, HC.warm_secs)
        return false, S.housecat_status
    end
    return true
end

-- W3 CAT MOTION BANK (v8 catalogue, 2026-08-18): the proven IrisWildHorses
-- DynamicMotionBank recipe verbatim -- load the motlist resource, pin it,
-- register bank 904 on the spawned body's Motion. Gated behind its OWN arm
-- latch because only the v0.9+ pak serves the motlist path.
function HC.load_motlist()
    if C.housecat_bank_armed ~= true then
        S.housecat_bank_status = "bank disarmed"
        return false
    end
    local src = HC.bank_sources[math.floor(tonumber(C.housecat_bank_source) or 1)] or HC.bank_sources[1]
    local path = src.path
    if S.housecat_bank_holder and S.housecat_bank_path == path then return true end
    -- source switched: drop old refs BEFORE loading the new one (UAF law)
    S.housecat_bank_holder, S.housecat_bank_res = nil, nil
    collectgarbage("collect")
    log.info("[IrisTaming] hcbank A: create_resource " .. tostring(path))
    local holder = nil
    local ok = pcall(function()
        local res = sdk.create_resource("via.motion.MotionListResource", path)
        log.info("[IrisTaming] hcbank B: resource " .. tostring(res ~= nil))
        if res then
            res:add_ref()
            S.housecat_bank_res = res
            holder = res:create_holder("via.motion.MotionListResourceHolder")
            log.info("[IrisTaming] hcbank C: holder " .. tostring(holder ~= nil))
            if holder then holder:add_ref() end
        end
    end)
    S.housecat_bank_holder = holder
    if ok and holder then
        S.housecat_bank_path = path
        S.housecat_bank_status = "motlist loaded: " .. tostring(src.label)
        return true
    end
    S.housecat_bank_status = "motlist unavailable: " .. tostring(src.label)
    return false
end

function HC.register_bank()
    local ch = S.housecat_ch
    if not ch then S.housecat_bank_status = "no house-cat body"; return false end
    if not HC.load_motlist() then return false end
    local motion = nil
    pcall(function() motion = ch:call("get_Motion") end)
    if not motion then S.housecat_bank_status = "body has no Motion component"; return false end
    log.info("[IrisTaming] hcbank C2: motion component acquired")
    local key = nil
    pcall(function() key = motion:get_address() end)
    key = tostring(key or motion) .. "|" .. tostring(S.housecat_bank_path)
    if S.housecat_bank_key == key then return true end
    local ok, err = pcall(function()
        local count = tonumber(motion:call("getDynamicMotionBankCount")) or 0
        log.info("[IrisTaming] hcbank D: dynamic bank count " .. tostring(count))
        local bank, index = nil, count
        for i = 0, count - 1 do
            local cand = motion:call("getDynamicMotionBank", i)
            local cid = nil
            if cand then pcall(function() cid = cand:call("get_BankID") end) end
            if tonumber(cid) == HC.bank_id then
                bank, index = cand, i
                break
            end
        end
        if not bank then
            motion:call("setDynamicMotionBankCount", count + 1)
            log.info("[IrisTaming] hcbank E: count grown to " .. tostring(count + 1))
            bank = sdk.create_instance("via.motion.DynamicMotionBank")
            bank = bank and bank:add_ref() or nil
            log.info("[IrisTaming] hcbank F: bank instance " .. tostring(bank ~= nil))
            if not bank then error("could not create DynamicMotionBank") end
            S.housecat_bank_pin = bank
        end
        bank:call("set_MotionList", S.housecat_bank_holder)
        log.info("[IrisTaming] hcbank G: set_MotionList done")
        bank:call("set_OverwriteBankID", true)
        bank:call("set_BankID", HC.bank_id)
        log.info("[IrisTaming] hcbank H: ids set")
        motion:call("setDynamicMotionBank", index, bank)
        log.info("[IrisTaming] hcbank I: attached at index " .. tostring(index))
    end)
    if ok then
        S.housecat_bank_key = key
        S.housecat_bank_status = "bank 904 registered on this cat"
        -- gait profile goes live only after the freshly-attached bank has had
        -- time to finish its async load -- never play into a seconds-old bank
        if not S.housecat_gait_at then
            S.housecat_gait_at = os.clock() + 2.0
            pcall(function() log.info("[IrisTaming] hcstage register ok (gait live in 2s)") end)
        end
    else
        S.housecat_bank_status = "bank registration failed: " .. tostring(err)
    end
    return ok
end

function HC.apply_mesh(ch)
    local go = char_go(ch)
    if not go then return false, "spawned body is not ready" end
    local ready, why = HC.mesh_ready()
    if not ready then return false, why end

    local holder = nil
    pcall(function()
        holder = S.housecat_res:create_holder("via.render.MeshResourceHolder")
        if holder then holder:add_ref() end
    end)
    if not holder then return false, "mesh holder creation failed" end

    local mesh = comp(go, "via.render.Mesh")
    if not mesh then return false, "rabbit body has no via.render.Mesh" end
    pcall(function() mesh:call("set_Enabled", false) end)
    local ok, err = pcall(function() mesh:call("setMesh", holder) end)
    if not ok then ok, err = pcall(function() mesh:call("set_Mesh", holder) end) end
    local material_ok, material_err = pcall(function()
        mesh:call("set_Material", S.housecat_mdf_holder)
    end)
    if not material_ok then
        material_ok, material_err = pcall(function()
            mesh:call("setMaterial", S.housecat_mdf_holder)
        end)
    end
    pcall(function() mesh:call("set_Enabled", true) end)
    if not ok then
        pcall(function() holder:release() end)
        return false, "mesh assignment failed: " .. tostring(err)
    end
    if not material_ok then
        pcall(function() holder:release() end)
        return false, "material assignment failed: " .. tostring(material_err)
    end
    if S.housecat_holder then pcall(function() S.housecat_holder:release() end) end
    S.housecat_holder = holder
    return true
end

function HC.forget_body()
    local ch = S.housecat_ch
    if ch then
        pcall(function()
            if S.tamed_addrs then S.tamed_addrs[tostring(ch:get_address())] = nil end
        end)
        S.tamed[ch] = nil
    end
    S.housecat_ch = nil
    S.housecat_go_addr = nil
end

function HC.delete()
    HC.forget_body()
    if S.housecat_spawner then pcall(function() S.housecat_spawner:deleteAll() end) end
    S.housecat_spawner = nil
    S.housecat_pending = false
    S.housecat_spawn_queued = false
    S.housecat_rebind_at = nil
    S.housecat_settle_at = nil
    S.housecat_bank_at = nil
    S.housecat_gait_at = nil
    S.housecat_bank_key = nil  -- motion component died with the body; re-register on next spawn
    if S.housecat_prefab_ctrl then pcall(function() S.housecat_prefab_ctrl:release() end) end
    if S.housecat_prefab then pcall(function() S.housecat_prefab:release() end) end
    S.housecat_prefab_ctrl = nil
    S.housecat_prefab = nil
end

function HC.adopt(ch)
    local go = char_go(ch)
    if not go then return false, "spawned Character has no GameObject" end

    -- This is the same local companion roster used by every tamed rabbit, rat,
    -- chicken and bird. Do not also register it with another pet controller.
    S.tamed[ch] = {
        name = "House Cat",
        follow = true,
        gender = "female",
        housecat = true,
    }
    S.tamed_addrs = S.tamed_addrs or {}
    pcall(function() S.tamed_addrs[tostring(ch:get_address())] = true end)
    S.housecat_ch = ch
    pcall(function() S.housecat_go_addr = go:get_address() end)   -- species_clips body match

    full_pacify(ch)
    strip_hate(ch)
    clear_targets(ch)
    set_immunity(ch, true)
    set_think_stop(ch, false)
    set_nav_stop(ch, false)
    pcall(function() set_player_fsm(go, true) end)
    pcall(function() ch:call("setCharacterControllerEnable", true) end)
    pcall(function() iris_body_solid(ch, go, true) end)
    set_ground_glue(go, true)

    local dm = comp(go, "app.AIDecisionMaker")
    if dm then pcall(function() dm:call("set_Enabled", false) end) end
    local nav = comp(go, "app.NavigationAI")
    if nav then pcall(function() nav:call("set_Enabled", true) end) end
    return true
end

function HC.install_prefab(spawner)
    local prefab = sdk.create_instance("via.Prefab")
    if not prefab then return false, "via.Prefab creation failed" end
    prefab:add_ref()
    local ok_path = pcall(function() prefab:call("set_Path", HC.prefab) end)
    local exists = false
    pcall(function() exists = prefab:call("get_Exist") end)
    if not ok_path or not exists then
        pcall(function() prefab:release() end)
        return false, "rabbit prefab unavailable"
    end

    local ctrl = sdk.create_instance("app.PrefabController")
    if not ctrl then
        pcall(function() prefab:release() end)
        return false, "PrefabController creation failed"
    end
    ctrl:add_ref()
    local ok_ctrl = pcall(function() ctrl._Item = prefab end)
    if not ok_ctrl then ok_ctrl = pcall(function() ctrl:set_field("_Item", prefab) end) end
    if not ok_ctrl then
        pcall(function() ctrl:release() end)
        pcall(function() prefab:release() end)
        return false, "PrefabController assignment failed"
    end

    S.housecat_prefab = prefab
    S.housecat_prefab_ctrl = ctrl
    spawner.getPfbCtrl = function(_self, _char_id) return ctrl end
    return true
end

function HC.spawn()
    local ready, why = HC.mesh_ready()
    if not ready then
        if S.housecat_res and S.housecat_mdf_holder then
            S.housecat_spawn_queued = true
            S.housecat_status = "coat warming; house-cat spawn queued automatically"
            return true
        end
        S.housecat_status = tostring(why)
        return false
    end
    local player = get_player()
    local pgo = player and char_go(player)
    if not pgo then S.housecat_status = "load into the world first"; return false end

    local SR = nil
    local ok_sr = pcall(function() SR = require("EnemySpawner/spawnRequest") end)
    if not ok_sr or not SR then S.housecat_status = "SpawnRequest unavailable"; return false end

    HC.delete()
    local spawner = SR:new()
    local ok_prefab, prefab_why = HC.install_prefab(spawner)
    if not ok_prefab then S.housecat_status = tostring(prefab_why); return false end

    local pos, rot = nil, nil
    pcall(function()
        local tf = pgo:call("get_Transform")
        local pp, fwd = tf:call("get_UniversalPosition"), tf:call("get_AxisZ")
        rot = tf:call("get_Rotation")
        local d = tonumber(C.housecat_spawn_distance) or 2.6
        pos = ValueType.new(sdk.find_type_definition("via.Position"))
        pos.x = pp.x + (fwd and fwd.x or 0.0) * d
        pos.y = pp.y
        pos.z = pp.z + (fwd and fwd.z or 0.0) * d
    end)
    if not pos then S.housecat_status = "could not resolve spawn position"; return false end

    local cfg = {
        spawnIdle = true,
        instLimit = 1,
        spawnMultiple = { enable = false, qty = 1 },
        ovrScale = { enable = false, scale = 1.0, normalizeSpeed = false },
    }
    spawner:updateConfig(cfg)
    spawner:requestAddInstances("ch299200_A_00", pos, rot, cfg, 1)
    S.housecat_spawner = spawner
    S.housecat_pending = true
    S.housecat_status = "IRIS house-cat spawn requested"
    return true
end

function HC.queued_spawn_tick()
    if S.housecat_spawn_queued ~= true then return end
    local ready = HC.mesh_ready()
    if not ready then return end
    S.housecat_spawn_queued = false
    HC.spawn()
end

function HC.spawn_tick()
    local spawner = S.housecat_spawner
    if not spawner then return end
    pcall(function()
        spawner:updateInstanceCounts()
        spawner:requestSpawnOutstanding()
        if spawner:hasAnyOutstandingPostProc() then spawner:processPostProc() end
    end)
    if not S.housecat_pending then return end

    local ch = nil
    pcall(function()
        local inst = spawner.instances and spawner.instances[1]
        ch = inst and inst.instance and inst.instance:get_Chara()
    end)
    if not ch then return end

    S.housecat_pending = false
    local mesh_ok, mesh_why = HC.apply_mesh(ch)
    if not mesh_ok then
        S.housecat_status = "spawned, but " .. tostring(mesh_why)
        return
    end
    local adopt_ok, adopt_why = HC.adopt(ch)
    if not adopt_ok then
        S.housecat_status = "mesh applied, but IRIS adoption failed: " .. tostring(adopt_why)
        return
    end
    -- ⛔ SETTLE DELAY (08-18 r4, the v0.9.4 spawn CTD): every session that ever
    -- worked registered the bank SECONDS after spawn, by hand, on a settled
    -- body. Auto-registering one frame after get_Chara() (and scaling on that
    -- same first tick) is brand-new timing on a body still in post-proc --
    -- defer both until the body has stood in the world for a moment.
    S.housecat_settle_at = os.clock() + 2.0
    S.housecat_status = "House Cat: IRIS local companion (following)"
    S.housecat_rebind_at = os.clock() + 1.2
    S.status = S.housecat_status
    set_prompt("HOUSE CAT", "She is now owned by IRIS Taming. Grab her like a tamed rabbit.", 5.0, 0xFF80FFB0)
    pcall(function() log.info("[IrisTaming] house cat spawned, meshed and adopted into S.tamed") end)
end

function HC.cure_material_tick()
    local due = tonumber(S.housecat_rebind_at)
    if not due or os.clock() < due then return end
    local ch = S.housecat_ch
    local rec = ch and S.tamed[ch]
    if not (ch and rec) then S.housecat_rebind_at = nil; return end
    if rec.carried == true or rec.carried_script == true then
        S.housecat_rebind_at = os.clock() + 0.5
        return
    end
    S.housecat_rebind_at = nil
    local ok, why = HC.apply_mesh(ch)
    if ok then
        S.housecat_status = "House Cat: IRIS companion (coat resident)"
        pcall(function() log.info("[IrisTaming] house-cat material cure rebind complete") end)
    else
        S.housecat_status = "house-cat material cure failed: " .. tostring(why)
    end
end

-- GROUND SCALE = the natural dial x the SIZE gene through the ONE genetics
-- calculator (iris_size_mult_for, cross-file so rawget -- the dead-rays law).
-- No gene on the body yet = gene 15 = species-true x1.0, so today the dial is
-- the whole story and IV blood bites the day a tamed cat carries genes.
function HC.size_gene()
    local rec = S.housecat_ch and S.tamed[S.housecat_ch]
    local g = rec and rec.iv and tonumber(rec.iv.size)
    if not g then g = tonumber(rawget(_G, "IrisHousecatSizeGene")) end
    return g or 15
end

function HC.ground_scale()
    local nat = tonumber(C.housecat_natural_scale) or 1.2
    local m = 1.0
    pcall(function()
        local f = rawget(_G, "iris_size_mult_for")
        if type(f) == "function" then m = tonumber(f("ch299200", HC.size_gene(), nat)) or 1.0 end
    end)
    return nat * m
end

-- Scale is COMPUTED fresh each tick (dial x gene, carried multiplies the carry
-- dial on top) -- no capture/restore dance to go stale. The shoulder-perch
-- easer owns the body while rec.perch is set; stand down there.
function HC.carry_scale_tick()
    local ch = S.housecat_ch
    local rec = ch and S.tamed[ch]
    local go = ch and char_go(ch)
    if not (rec and go) then return end
    -- STAGED settle (08-18 r5): the r4 crash still fired scale + register +
    -- first-gait-clip in the SAME instant. Separate them so the next crash's
    -- log timestamp names the guilty stage:
    --   settle+0s  scale applies        ("hcstage scale")
    --   settle+2s  bank registers       ("hcstage register" + hcbank A..I)
    --   register+2s gait profile live   ("hcstage gait live", set in register_bank)
    if S.housecat_settle_at then
        if os.clock() < S.housecat_settle_at then return end
        S.housecat_settle_at = nil
        S.housecat_bank_at = os.clock() + 2.0
        pcall(function() log.info("[IrisTaming] hcstage scale (first apply now, register in 2s)") end)
    end
    if S.housecat_bank_at then
        if os.clock() >= S.housecat_bank_at then
            S.housecat_bank_at = nil
            if C.housecat_bank_armed == true then
                pcall(function() log.info("[IrisTaming] hcstage register") end)
                HC.register_bank()
            end
        end
    end
    if rec.perch then rec.hc_scale_now = nil; return end
    local s = HC.ground_scale()
    if rec.carried == true or rec.carried_script == true then
        s = s * (tonumber(C.housecat_carry_scale) or 0.72)
    end
    if math.abs((tonumber(rec.hc_scale_now) or 0.0) - s) > 0.0005 then
        local oks = pcall(function()
            go:call("get_Transform"):call("set_LocalScale", Vector3f.new(s, s, s))
        end)
        if oks then rec.hc_scale_now = s end
    end
end

-- The rabbit carry clip curls FrontLeg_Toes like compact rabbit forefeet.
-- On the Witcher cat mesh that becomes the hooked clubs Aurora photographed.
-- Relax only the two distal front joints while carried; leave the upper limb,
-- locomotion and native two-actor carry machinery completely untouched.
function HC.carry_paw_tick()
    if C.housecat_carry_paw_fix == false then return end
    local ch = S.housecat_ch
    local rec = ch and S.tamed[ch]
    local go = ch and char_go(ch)
    if not (rec and go and (rec.carried == true or rec.carried_script == true)) then return end
    local tf = go:call("get_Transform")
    if not tf then return end
    for _, spec in ipairs(HC.carry_front_joints) do
        pcall(function()
            local joint = tf:call("getJointByName", spec[1])
            if not joint then return end
            local current = joint:call("get_LocalRotation")
            local base = joint:call("get_BaseLocalRotation")
            if not (current and base) then return end
            local t = spec[2] == "toe"
                and (tonumber(C.housecat_carry_toe_relax) or 0.85)
                or (tonumber(C.housecat_carry_wrist_relax) or 0.25)
            t = math.max(0.0, math.min(1.0, t))
            local bx, by, bz, bw = base.x, base.y, base.z, base.w
            if current.x * bx + current.y * by + current.z * bz + current.w * bw < 0.0 then
                bx, by, bz, bw = -bx, -by, -bz, -bw
            end
            local x = current.x + (bx - current.x) * t
            local y = current.y + (by - current.y) * t
            local z = current.z + (bz - current.z) * t
            local w = current.w + (bw - current.w) * t
            local n = math.sqrt(x * x + y * y + z * z + w * w)
            if n > 0.00001 then
                joint:call("set_LocalRotation", Quaternion.new(x / n, y / n, z / n, w / n))
            end
        end)
    end
end

-- TAIL DIAL (08-18, Aurora: "their tail clips through the ground"): the W3 cat
-- carries its tail low, so slopes and rocks swallow it. The rabbit rig has ONE
-- Tail joint -- lift is a per-frame local pre-rotation (carry_paw_tick's proven
-- pattern), relax blends toward the rest pose. Both are live sliders; the
-- proper clip-space fix waits for the v09 mesh/anim track.
function HC.tail_tick()
    local ch = S.housecat_ch
    local rec = ch and S.tamed[ch]
    local go = ch and char_go(ch)
    if not (rec and go) then return end
    local lift = tonumber(C.housecat_tail_lift) or 0.0
    local relax = tonumber(C.housecat_tail_relax) or 0.0
    if lift == 0.0 and relax <= 0.0 then return end
    pcall(function()
        local tf = go:call("get_Transform")
        local joint = tf and tf:call("getJointByName", "Tail")
        if not joint then return end
        local cur = joint:call("get_LocalRotation")
        if not cur then return end
        local x, y, z, w = cur.x, cur.y, cur.z, cur.w
        if relax > 0.0 then
            local base = joint:call("get_BaseLocalRotation")
            if base then
                local bx, by, bz, bw = base.x, base.y, base.z, base.w
                if x * bx + y * by + z * bz + w * bw < 0.0 then bx, by, bz, bw = -bx, -by, -bz, -bw end
                local t = math.max(0.0, math.min(1.0, relax))
                x = x + (bx - x) * t; y = y + (by - y) * t
                z = z + (bz - z) * t; w = w + (bw - w) * t
            end
        end
        if lift ~= 0.0 then
            -- child-space pitch: q' = q x rx(lift)
            local s, c = math.sin(lift * 0.5), math.cos(lift * 0.5)
            x, y, z, w = w * s + x * c, y * c + z * s, z * c - y * s, w * c - x * s
        end
        local n = math.sqrt(x * x + y * y + z * z + w * w)
        if n > 0.00001 then
            joint:call("set_LocalRotation", Quaternion.new(x / n, y / n, z / n, w / n))
        end
    end)
end

_G.IrisTaming.spawn_housecat = HC.spawn
_G.IrisTaming.delete_housecat = HC.delete
re.on_application_entry("LateUpdateBehavior", function()
    pcall(HC.carry_scale_tick)
    pcall(HC.cure_material_tick)
end)
re.on_application_entry("PrepareRendering", function()
    pcall(HC.carry_paw_tick)
    pcall(HC.tail_tick)
end)
-- GRIP AID: the probe's climb-stamina hold extends to WILD GRIFFINS while this is on
-- (ride the commuter to its nest without falling out of the sky)
_G.IrisTaming.grip_aid_on = function() return C.grip_aid == true end
-- ping feedback settings (the probe fires the sound + arms the flash at ping time):
-- sound id 0 falls back to the caw id so "some kind of notification" works out of the box
_G.IrisTaming.ping_fx = function()
    -- SOUND now rings from the taming side at the keypress (the chosen chime lives in the
    -- PLAYER's banks -- the probe's own-container triggerLogLess could never play it); the
    -- probe keeps only the FLASH
    return 0, C.scout_ping_flash ~= false
end
-- hotkey get/set for the centralized Hotkeys UI (main mod panel)
_G.IrisTaming.get_tame_key = function() return math.floor(tonumber(C.tame_key) or 0x4E) end
_G.IrisTaming.set_tame_key = function(vk) C.tame_key = math.floor(tonumber(vk) or 0x4E); pcall(save_state) end
-- ⭐⭐⭐ 08-13 TAMING MODE API (Aurora's design, and it replaces an entire failed approach).
-- The problem this solves: B is the tame hand AND dodge AND every interact in the game, so the mod
-- was forever GUESSING whether a press meant "tame this crow" or "ring that bell". Reach, cone and
-- hold-duration heuristics were all tried in one session and all failed in the field. A mode does
-- not guess: the player DECLARES intent in the Stable screen, taming prompts exist only while it is
-- on, and the ambiguity simply stops existing.
-- Leaving the mode is an explicit cancel edge. The request is still consumed on a live game
-- frame (never from the paused Stable screen), so the existing release path remains crash-safe.
_G.IrisTaming.mode_on = function() return S.tame_mode == true end
_G.IrisTaming.mode_set = function(v)
    local want = (v == true)
    if want == (S.tame_mode == true) then return want end
    S.tame_mode = want
    if not want then
        pcall(function()
            if _G.IrisTaming.cancel_rite then _G.IrisTaming.cancel_rite() end
        end)
        -- leaving: retract every offer immediately. A prompt that outlives the mode is exactly
        -- the stale-advertisement bug the prompt bar's TTL was written to avoid.
        S.tame_mark = nil; S.ox_mark = nil; S.ox_mark_go = nil
        pcall(function()
            if _G.IrisPrompt then
                _G.IrisPrompt.set("tame_begin", ""); _G.IrisPrompt.set("tame_ox", "")
            end
        end)
    end
    pcall(function() log.info("[IrisTaming] taming mode -> " .. (want and "ON" or "OFF")) end)
    return want
end
-- "is there anything a Cancel would actually act on?" -- every rite root, so the menu entry can
-- dim itself honestly rather than pretending it did something.
_G.IrisTaming.rite_active = function()
    return (S.target ~= nil) or (S.trial ~= nil) or (S.armed == true) or (S.ox_rite ~= nil)
        or (S.oxtame ~= nil)
        or (S.combat_tame ~= nil) or (S.iris_carry ~= nil) or (S.feed_drop ~= nil)
        or (S.camp_rite ~= nil) or (S.yield_down ~= nil)
        or (rawget(_G, "__iris_horse_taming_rite_active") and true or false)
end
-- the checkbox behind "auto-leave after a tame". This one IS config, so it persists -- unlike the
-- live mode, which must always boot off.
_G.IrisTaming.mode_stay_on = function() return C.tame_mode_stay == true end
_G.IrisTaming.mode_stay_set = function(v)
    C.tame_mode_stay = (v == true)
    pcall(save_state)
    return C.tame_mode_stay
end
-- ⛔ RAISES A REQUEST, DOES NOT ACT. The Stable screen calls this from a PAUSED frame, and
-- touching creature bodies on a paused frame is this project's documented crash class. The main
-- tick consumes S.cancel_req on the next LIVE frame and runs the one shared cleanup there.
_G.IrisTaming.cancel_rite = function()
    if not _G.IrisTaming.rite_active() then return false end
    S.cancel_req = true
    return true
end
_G.IrisTaming.get_sense_key = function() return math.floor(tonumber(C.sense_key) or 0x4B) end
_G.IrisTaming.set_sense_key = function(vk) C.sense_key = math.floor(tonumber(vk) or 0x4B); pcall(save_state) end

pcall(function() math.randomseed(os.time() % 1000000) end)
local function pick_next(T, now)
    -- each ritual used at most ONCE per tame (no circle-circle / charge-charge) -- a
    -- random SUBSET in random order, so tames vary in both which rituals and how many
    if not T.plan then
        local others = { "circle", "rush_tell", "stare", "howl" }
        for i = #others, 2, -1 do local j = math.random(i); others[i], others[j] = others[j], others[i] end
        T.plan = { others[1], others[2], others[3] }   -- 3 of the 4 non-hunt rituals, shuffled
        table.insert(T.plan, math.random(#T.plan + 1), "hunt")   -- THE HUNT always features, random slot -> 4 rituals
        T.plan_i = 0
    end
    T.plan_i = (tonumber(T.plan_i) or 0) + 1
    local nxt = T.plan[T.plan_i]
    if not nxt then
        T.stage = "laststeps"; T.t0 = now; S.wolf_clip = nil
        -- THE LAST STEPS OPEN CLEAN (08-14): the crossing's latch and the pact's one-shots live
        -- on T and S, and NOTHING used to clear them here. A stale S.lie_cue from an abandoned
        -- rite skips the lie-down outright, and a stale T.arrived would seal the pact from across
        -- the clearing.
        T.arrived = nil; T.ghost_at = nil; T.pact_at = nil; T.pat_played = nil; T.walked = nil
        -- ⛔ T.hand_seen IS THE LOAD-BEARING ONE (red-team 08-14). stare and howl both set it and
        -- neither clears it on the way out, and the plan always contains at least one of them - so
        -- the crossing opened with the latch already true, which arms its 5s "you lowered the
        -- hand" fail clock the instant the player lets go between stages. And laststeps runs
        -- inside 3m, where trial_fail's `attack` test is always true: the whole rite would end in
        -- a mauling for not already having the palm out.
        T.hand_seen = nil; T.nohand = nil
        S.lie_cue = nil; S.lie_at = nil
        S.status = "NOW: hand out (HOLD N / B) and hold it - it is deciding."
        return
    end
    T.stage = nxt; T.t0 = now; S.wolf_clip = nil
    if nxt == "circle" then
        T.angle = nil; T.slack = 0.0; T.ring_r = nil; T.cdir = (math.random() < 0.5) and 1.0 or -1.0
        S.status = "IT CIRCLES - hand up, turn with it."
    elseif nxt == "stare" then
        T.slack = 0.0; T.stare_pt = nil; T.hand_seen = nil; T.grace = nil
        S.status = "IT STARES YOU DOWN - hand up, hold its gaze."
    elseif nxt == "howl" then
        T.slack = 0.0; T.howl_pt = nil; T.howl_cue = nil; T.hand_seen = nil; T.grace = nil
        -- CATS don't sing for the pack (08-05, Aurora: the howl-back "doesn't seem very
        -- catlike"): the same slot renders as THE SIT -- it sits and studies you sideways,
        -- and your answer is slow calm, not a bellow. Same key, same timers, feline skin.
        T.cat_sit = is_cat(char_go(S.target)) or nil
        S.kneel_loop = nil   -- every sit opens with the full sink-to-the-ground
        S.status = T.cat_sit and "IT SITS, WATCHING YOU SIDEWAYS - keep the hand raised."
            or "IT RAISES ITS HEAD - keep the hand raised."
    elseif nxt == "hunt" then
        despawn_doe()   -- fresh hunt: no leftover doe/corpse from a past tame
        -- if the meet spotted real live prey, this slot adopts it rather than conjuring
        local adopt = nil
        -- ⛔ 08-14: despawn_doe above can have DESTROYED this handle between the meet and the
        -- hunt slot, and char_go on a dead body throws a native InvalidOperationException that
        -- unwinds the whole tick (seen in the log as a burst of via.Component.get_GameObject
        -- exceptions the instant the hunt opened). Guard the whole adoption.
        pcall(function()
            if T.pending_prey and not is_dead(T.pending_prey) then
                local pg = char_go(T.pending_prey)
                if pg and is_huntable(pg) then adopt = T.pending_prey end
            end
        end)
        T.pending_prey = nil
        T.hunt_sit = nil; T.hunt_ch = adopt; T.hold_pt2 = nil; T.hunt_corpse = nil
        T.offer_scan_at = 0.0; T.hunt_scan_at = 0.0; T.spawned = nil; T.hunt_start = now; T.doe_respawned = nil
        T.quarry_checked = nil; T.quarry_recheck_at = nil; T.quarry_free_at = nil; T.quarry_born_at = nil
        T.qmove_pt = nil; T.qmove_t = nil; T.qstuck_at = nil
        S.status = "IT HUNGERS - prey stirs nearby. HUNT it and bring the kill."
    else
        T.rush_phase = nil; T.snarl_at = nil; T.charge_d = nil; T.snarl_pt = nil; T.flinch_t = nil
        S.status = "IT COILS TO STRIKE - stand your ground."
    end
end

re.on_frame(function()
    if IPPS then IPPS(false) end
    -- ⭐ THE WAYPOINT WATCH (07-25): the test button's answer, written to the log rather than left
    -- to anyone's memory of what they thought they saw. Once a second for 60s: her distance, the
    -- ground she has closed, her live FSM node, and what her route brain currently holds. A single
    -- read of this tells us whether the destination write actually moves her -- and if her AI
    -- overwrites TargetNodeId a few seconds later, that shows up here as the target changing.
    -- release the node-test pin once its beat is up (the pin must be PER-FRAME to beat
    -- app.Character re-asserting her real position, but it must also LET GO or she is a statue)
    if S.nodetest_release and os.clock() > S.nodetest_release then
        S.nodetest_release = nil
        pcall(function()
            local b7 = _G.IrisGriffinBridge
            if b7 and b7.oxtame_pin_release then b7.oxtame_pin_release() end
        end)
        pcall(function() log.info("[OxTame] NODE TEST: pin released -- she is on the node, her AI has her") end)
    end
    if S.wp_watch then
        pcall(function()
            local W = S.wp_watch
            local now9 = os.clock()
            if now9 > (tonumber(W.until_t) or 0.0) then
                log.info("[OxTame] WAYPOINT WATCH ended")
                S.wp_watch = nil
                return
            end
            if now9 < (tonumber(W.next_t) or 0.0) then return end
            W.next_t = now9 + 1.0
            local pu9 = upos(char_go(get_player()))
            local u9 = W.go and upos(W.go)
            local d9 = (u9 and pu9) and dist(u9, pu9) or -1.0
            local b0 = _G.IrisGriffinBridge
            local nm9 = (b0 and b0.oxtame_node_name) and b0.oxtame_node_name(W.ch) or "?"
            local rd9 = (b0 and b0.oxtame_waypoint_read) and b0.oxtame_waypoint_read(W.ch) or nil
            log.info(string.format("[OxTame] wpwatch t=%4.1fs d=%.0fm (closed %.0fm) node=%s | target=%s cur=%s next=%s resting=%s",
                now9 - (tonumber(W.t0) or now9), d9, (tonumber(W.d0) or d9) - d9, tostring(nm9),
                tostring(rd9 and rd9.target), tostring(rd9 and rd9.cur), tostring(rd9 and rd9.next),
                tostring(rd9 and rd9.resting)))
        end)
    end
    -- the ritual banner draws whenever alive (independent of the logic below)
    pcall(function()
        if S.prompt and os.clock() < (tonumber(S.prompt.until_t) or 0.0) then
            -- ⭐⭐ THE RITUAL CARD (07-21, Aurora): feed the shared d2d layer so the card wears
            -- the SAME serif + gold-hairline-over-smoke frame as the Grip/Break gauges. When it
            -- takes the feed we return -- the imgui window below is now the no-d2d fallback only.
            local F = _G.IrisFont
            if F and F.card then
                F.card(tostring(S.prompt.title), tostring(S.prompt.sub), S.prompt.color or 0xFF80D0FF)
                if F.card_live and F.card_live() then return end
            end
            if S.font_big == nil then
                -- FALLBACK font at banner sizes (set_window_font_scale is NOT a REF binding --
                -- calling it errored mid-window and skipped end_window: the "Missing End()" assert).
                -- ⚠ imgui.load_font needs a FILE in reframework/fonts -- it cannot take a family
                -- name, so the d2d face ("Constantia" etc.) is unavailable here; IrisFont.imgui
                -- serves LinLibertine_R.ttf, and nil = the built-in bitmap face as the last resort.
                local fb = nil
                if F and F.imgui then fb = F.imgui(30) end
                if not fb then local okb, h9 = pcall(imgui.load_font, nil, 30); fb = (okb and h9) or nil end
                S.font_big = fb or false
                local fm = nil
                if F and F.imgui then fm = F.imgui(19) end
                if not fm then local okm, h9 = pcall(imgui.load_font, nil, 19); fm = (okm and h9) or nil end
                S.font_mid = fm or false
            end
            local ds = nil
            pcall(function() ds = imgui.get_display_size() end)
            local w = (ds and ds.x) or 1920
            local h = (ds and ds.y) or 1080
            pcall(function() imgui.set_next_window_pos(Vector2f.new(w * 0.5, h * 0.14), 0, Vector2f.new(0.5, 0.0)) end)
            local opened = false
            pcall(function() opened = imgui.begin_window("##IrisTamingPrompt", nil, 1 | 2 | 4 | 8 | 32 | 64 | 128) end)
            if opened then
                if S.font_big then pcall(imgui.push_font, S.font_big) end
                pcall(imgui.text_colored, tostring(S.prompt.title), S.prompt.color or 0xFF80D0FF)
                if S.font_big then pcall(imgui.pop_font) end
                if S.font_mid then pcall(imgui.push_font, S.font_mid) end
                pcall(imgui.text, tostring(S.prompt.sub))
                if S.font_mid then pcall(imgui.pop_font) end
                pcall(imgui.end_window)
            end
        end
    end)
    -- ===== WAYFARER'S SENSE (was Creature Sense; renamed 2026-07-21 when timber joined) =====
    -- scan pulse: vignette + highlight tameable wildlife AND harvestable trees
    pcall(function()
        local sdn = false
        pcall(function() sdn = iris_kb(math.floor(tonumber(C.sense_key) or 0x4B)) end)
        if sdn and not S.sense_prev then
            S.sense_until = os.clock() + (tonumber(C.sense_secs) or 8.0)
            -- the Arisen SEARCHES: play the 60:7631 scanning gesture as the sense fires
            -- upper = don't seize the body (walk through it); follow = hold for the clip's REAL
            -- length instead of a fixed guess, which is what made it cut out mid-gesture
            -- 08-12 (Aurora: "frustrating to wait"): the gesture runs FASTER
            -- (speed applies to the live layer) and carries a [B] early-out.
            -- (Feet-free was tried long ago: layer 1 refuses this clip, the
            -- self-heal below always falls back to the full-body seize.)
            S.phold = { clip = tonumber(C.sense_anim) or 7631,
                until_t = os.clock() + (tonumber(C.sense_anim_secs) or 3.5),
                no_pin = true, upper = (C.sense_upper ~= false), follow = true,
                speed = tonumber(C.sense_anim_speed) or 1.6, cancel = true }
        end
        S.sense_prev = sdn
        if C.sense_enabled == false then return end
        if not (S.sense_until and os.clock() < S.sense_until) then return end
        local player = get_player(); local pgo = player and char_go(player)
        if not pgo then return end
        local pp = upos(pgo)
        local left = S.sense_until - os.clock()
        local total = tonumber(C.sense_secs) or 8.0
        local fade = math.min(1.0, math.min((total - left) / 0.4, left / 0.6))
        -- vignette: dim the world so the highlights pop
        local ds = nil; pcall(function() ds = imgui.get_display_size() end)
        local W = (ds and ds.x) or 1920; local H = (ds and ds.y) or 1080
        pcall(function() draw.filled_rect(0, 0, W, H, math.floor(0x55 * fade) * 0x1000000 + 0x20140A) end)
        -- the sense has a NAME now (Aurora + Iris, 2026-07-21): show it while the pulse lingers
        pcall(function()
            local tcol = math.floor(0xE0 * fade) * 0x1000000 + 0x70D8FF
            iris_screen_text("~ Wayfarer's Sense ~", W * 0.5 - 110, H * 0.10, tcol, 24)
        end)
        -- sweep the scene for tameable creatures and light them up
        local sm = sdk.get_native_singleton("via.SceneManager")
        local smt = sdk.find_type_definition("via.SceneManager")
        local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
        local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
        local n = 0; pcall(function() n = comps:call("get_Length") or 0 end)
        if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
        local rng = tonumber(C.sense_range) or 80.0
        local afull = math.floor(0xFF * fade) * 0x1000000
        -- who's already MY tamed companion? (the griffin mod owns the griffin) -- resolve ONCE per pulse
        local companion_addr, companion_nm = nil, nil
        pcall(function()
            local B = _G.IrisGriffinBridge
            if B and B.griffin then
                local g = B.griffin()
                if g then companion_addr = tostring(g:get_address()); companion_nm = (B.companion_name and B.companion_name()) or "Companion" end
            end
        end)
        for i = 0, (tonumber(n) or 0) - 1 do
            pcall(function()
                local ch = comps:call("get_Item", i) or comps[i]
                local go = ch and char_go(ch)
                if not go or is_dead(ch) or S.tamed[ch] then return end
                local ach = nil; pcall(function() ach = tostring(ch:get_address()) end)
                if ach and S.tamed_addrs and S.tamed_addrs[ach] then return end
                local nm = go_name(go)
                local companion_name = (companion_addr and ach and ach == companion_addr) and companion_nm or nil
                local tier, rgb, sense_name = nil, nil, nil
                local resident_name = nil
                pcall(function()
                    local hb9 = rawget(_G, "IrisHomesteadBox")
                    local ga9 = go:get_address()
                    if hb9 and hb9.is_resident and hb9.is_resident(ga9) then
                        resident_name = (hb9.resident_name and hb9.resident_name(ga9)) or "Homestead animal"
                    end
                end)
                if resident_name then
                    -- A resident is already family.  Mark it as such before the species
                    -- ladder, otherwise the shared cow/hen/rabbit chassis advertises a tame
                    -- which every actual rite should refuse.
                    companion_name, tier, rgb = resident_name, "lives at the homestead", 0x66FF66
                elseif companion_name then tier, rgb = "your companion", 0x66FF66   -- already tamed: GREEN + pet name, not a target
                elseif name_in_csv(nm, C.critter_bands) then tier, rgb = "tameable pet", 0xFF9020
                elseif name_in_csv(nm, C.target_bands) then tier, rgb = "tameable", 0xFF9020
                elseif nm:find("ch299003", 1, true) then
                    -- 08-12: an EMPLOYED ox (oxcart ownership via the registry) is spoken for --
                    -- the label must never promise a tame the rite will refuse
                    local employed8, g8 = false, nil
                    pcall(function()
                        local sp8 = rawget(_G, "IrisSpecies")
                        employed8 = sp8 and sp8.cart_ox and sp8.cart_ox(go:get_address()) or false
                        g8 = sp8 and sp8.gender and sp8.gender(go) or nil   -- the BODY: per-individual roll
                    end)
                    -- 08-12 (Aurora: "see what's spawned where"): the sense reads the chassis --
                    -- identical models, honest labels
                    sense_name = (g8 == "male" and "Bull") or (g8 == "female" and "Cow") or nil
                    if employed8 then tier, rgb = "yoked to its cart", 0x909090
                    else tier, rgb = "tameable pack-beast", 0xFFC040 end   -- the ox: yoke rite, ride comes later (07-21 honesty fix)
                elseif nm:find("ch299011", 1, true) then
                    -- ⭐⭐ HORSES AND UNICORNS JOIN THE SENSE (Aurora 08-12: "horses/unicorns don't
                    -- appear in wayfarer sense", screenshot: a wild horse 8m away with only timber
                    -- marked). They never could, and the cause was absence rather than a filter:
                    -- **ch299011 is in NO sense band** - target_bands is "ch223" (wolves),
                    -- critter_bands is the small tier, sense_mount_bands is "ch253,ch299003" - so
                    -- every horse fell down the whole ladder into `if not tier then return end`.
                    -- (hunt_prey_band DOES list ch299011, but that is the wolf hunt's prey config,
                    -- a different feature. I first assumed is_huntable() was rejecting them; it is
                    -- not involved here at all.)
                    -- ⚠ ONE CHASSIS, THREE CREATURES: wild doe, converted horse, and unicorn all wear
                    -- ch299011, and ONLY the wild-horses registry can separate them - name matching
                    -- provably cannot. Same ask creature_label makes above.
                    -- ⛔ ORDER IS LOAD-BEARING: is_unicorn MUST come first, because a unicorn is also
                    -- a horse by design (kind stays "horse" to keep ~15 consumers working).
                    local api9 = rawget(_G, "__iris_wild_horses_api")
                    local uni9, hor9 = false, false
                    pcall(function()
                        if not api9 then return end
                        uni9 = api9.is_unicorn and api9.is_unicorn(go) == true
                        hor9 = api9.is_horse and api9.is_horse(go) == true
                    end)
                    if uni9 then
                        -- ⭐ Aurora's ask: rainbow font + "Ultra Rare Tameable!". The hue sweep is the
                        -- same one her unicorn's COAT runs (UNI.hsv, 0.12 cycles/sec), ported here as
                        -- pure arithmetic on purpose: the sense must not depend on a cross-file
                        -- function that may not be loaded, and there is no engine API to guess.
                        -- The creature sweep already runs every frame, so the label animates for free.
                        local h9 = (os.clock() * 0.12) % 1.0
                        local i9 = math.floor(h9 * 6.0)
                        local f9 = h9 * 6.0 - i9
                        local v9, s9 = 1.0, 0.85      -- vivid for TEXT; the coat uses 0.55 to read pearlescent
                        local p9 = v9 * (1.0 - s9)
                        local q9 = v9 * (1.0 - f9 * s9)
                        local t9 = v9 * (1.0 - (1.0 - f9) * s9)
                        local r9, g9, b9 = v9, p9, q9
                        local m9 = i9 % 6
                        if m9 == 0 then r9, g9, b9 = v9, t9, p9
                        elseif m9 == 1 then r9, g9, b9 = q9, v9, p9
                        elseif m9 == 2 then r9, g9, b9 = p9, v9, t9
                        elseif m9 == 3 then r9, g9, b9 = p9, q9, v9
                        elseif m9 == 4 then r9, g9, b9 = t9, p9, v9 end
                        sense_name, tier = "Unicorn", "Ultra Rare Tameable!"
                        rgb = math.floor(r9 * 255) * 0x10000 + math.floor(g9 * 255) * 0x100 + math.floor(b9 * 255)
                    elseif hor9 then
                        sense_name, tier, rgb = "Horse", "tameable mount", 0xFFC040   -- gold, same as the griffin/ox tier
                    end
                    -- a genuine WILD DOE stays unmarked (tier nil -> the return below). She is the
                    -- wolf rite's PREY, not a tame, and a "tameable" label would promise something
                    -- every rite refuses. This is also the graceful-degrade path: no IrisWildHorses
                    -- loaded means no registry, means no markers, means exactly today's behaviour.
                elseif name_in_csv(nm, tostring(C.sense_mount_bands or "ch253,ch299003")) then tier, rgb = "tameable mount", 0xFFC040   -- griffin = passive tame + RIDE, gold
                elseif name_in_csv(nm, C.sense_boss_bands) then tier, rgb = "combat tame", 0x5050FF
                end
                if not tier then return end
                local gpp = upos(go)
                local dd = (gpp and pp) and dist(gpp, pp) or 1e9
                if dd > rng then return end
                local rp = nil
                pcall(function() rp = go:call("get_Transform"):call("get_Position") end)
                if not rp then return end
                rp.y = rp.y + 1.0
                local sp = draw.world_to_screen(rp)
                if sp then
                    local col = afull + rgb
                    draw.filled_circle(sp.x, sp.y, 7, col, 16)
                    iris_screen_text(string.format("%s  -  %s (%.0fm)", companion_name or sense_name or creature_label(go), tier, dd), sp.x + 11, sp.y - 8, col, 17)
                end
            end)
        end
        -- ── HARVESTABLE TIMBER (Wayfarer's Sense grows past creatures, 2026-07-21) ──
        -- breakable tree gimmicks join the pulse. Cached ONCE per pulse (trees don't move;
        -- census proved findComponents(app.GimmickBase) walks the subclasses).
        pcall(function()
            if S.sense_tree_pulse ~= S.sense_until then
                S.sense_tree_pulse = S.sense_until
                S.sense_trees = {}
                local tset = { ["app.Gm80_002"] = true, ["app.Gm80_109"] = true, ["app.Gm80_110"] = true }
                -- minable stone (2026-07-22, Aurora's rock list): same pipeline, its own tier
                local rset = { ["app.Gm80_009"] = true, ["app.Gm80_010"] = true, ["app.Gm80_140"] = true,
                               ["app.Gm81_059"] = true, ["app.Gm81_064"] = true, ["app.Gm81_143"] = true,
                               ["app.Gm81_145"] = true, ["app.Gm81_146"] = true }
                local gcomps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.GimmickBase"))
                local gn = 0
                pcall(function() gn = gcomps:call("get_Length") or 0 end)
                if gn == 0 then pcall(function() gn = gcomps:get_size() or 0 end) end
                for i = 0, (tonumber(gn) or 0) - 1 do
                    pcall(function()
                        local c
                        pcall(function() c = gcomps:call("get_Item", i) end)
                        if not c then pcall(function() c = gcomps:get_element(i) end) end
                        if not c then return end
                        local tn2 = c:get_type_definition():get_full_name()
                        local kind = tset[tn2] and "timber" or (rset[tn2] and "stone" or nil)
                        if not kind then return end
                        if c:call("get_IsBroken") == true then return end
                        local tgo = c:call("get_GameObject")
                        if tgo then S.sense_trees[#S.sense_trees + 1] = { go = tgo, kind = kind } end
                    end)
                end
            end
            for _, te in ipairs(S.sense_trees or {}) do
                pcall(function()
                    local tgo = te.go or te   -- tolerate the older bare-GO cache shape
                    local gpp = upos(tgo)
                    local dd = (gpp and pp) and dist(gpp, pp) or 1e9
                    if dd > rng then return end
                    local rp2 = tgo:call("get_Transform"):call("get_Position")
                    rp2.y = rp2.y + 2.0
                    local sp2 = draw.world_to_screen(rp2)
                    if sp2 then
                        local stone = (te.kind == "stone")
                        local col2 = afull + (stone and 0xC0B8A0 or 0x30C060)
                        draw.filled_circle(sp2.x, sp2.y, 7, col2, 16)
                        iris_screen_text(stone and string.format("minable stone (%.0fm)", dd)
                            or string.format("harvestable timber (%.0fm)", dd), sp2.x + 11, sp2.y - 8, col2, 17)
                    end
                end)
            end
        end)
    end)
    -- the naming of a new companion: the world holds its breath, you type straight
    -- onto the card (the baby card's proven pattern -- no overlay needed)
    pcall(function()
        if S.name_pending then
            -- 08-12 (typing opened the Stable Screen / customisation): while the card is
            -- up, EVERY gated IRIS hotkey is dead -- re-asserted each frame, the gate
            -- clears it, so an abandoned card can never deadlock the stack
            _G.IrisTypingActive = true
            if not S.name_paused then name_pause(true) end
            -- lazy-register the pretty D2D card (reframework-d2d loads AFTER us)
            if not S.name_d2d_reg and _G.d2d and type(d2d.register) == "function" then
                pcall(function()
                    d2d.register(function() iris_name_make_fonts(1080) end, function() iris_name_draw_card() end)
                    S.name_d2d_reg = true
                end)
            end
            local pad_accept, pad_cancel = iris_name_pad_edges()
            local sealed = name_capture() or pad_accept
            local esc = false; pcall(function() esc = (rawget(_G, "iris_kb_raw") or iris_kb)(0x1B) end)
            if esc or pad_cancel then
                name_pause(false); S.name_pending = nil; S.name_buf = ""; S.name_pad_prev = nil; return
            end
            -- imgui FALLBACK card only when the D2D card isn't drawing
            if not S.name_d2d_reg then
                local ds = nil
                pcall(function() ds = imgui.get_display_size() end)
                local w = (ds and ds.x) or 1920
                imgui.set_next_window_pos(Vector2f.new(w * 0.5, ((ds and ds.y) or 1080) * 0.30), 0, Vector2f.new(0.5, 0.0))
                local opened = false
                pcall(function() opened = imgui.begin_window("Name the one who chose you##tame_name", nil, 2 | 8 | 32 | 64) end)
                if opened then
                    if S.font_big then pcall(imgui.push_font, S.font_big) end
                    pcall(imgui.text_colored, tostring(S.name_buf or "") .. "_", 0xFF80D0FF)
                    if S.font_big then pcall(imgui.pop_font) end
                    imgui.text("type the name -- Enter / A seals, Esc / B cancels")
                    if imgui.button("Seal the name (Enter)##tame_name_ok") then sealed = true end
                    pcall(imgui.end_window)
                end
            end
            if sealed and S.name_pending then
                local nm9 = tostring(S.name_buf or "")
                if nm9 ~= "" then
                    if S.name_pending.kind == "stable" then
                        pcall(function()
                            local b = _G.IrisGriffinBridge
                            if b and b.rename_active then b.rename_active(nm9) end
                        end)
                    elseif S.name_pending.kind == "stable_id" and S.name_pending.stable_id then
                        pcall(function()
                            local b = _G.IrisGriffinBridge
                            if b and b.rename_companion then b.rename_companion(S.name_pending.stable_id, nm9) end
                        end)
                    elseif S.name_pending.ch and S.tamed[S.name_pending.ch] then
                        S.tamed[S.name_pending.ch].name = nm9
                    end
                    set_prompt("NAMED", nm9 .. " walks with you.", 4.0, 0xFF80FFB0)
                end
                name_pause(false)
                S.name_pending = nil
                S.name_buf = ""
                S.name_pad_prev = nil
            end
        elseif S.name_paused then
            name_pause(false)   -- safety: never leave our pause behind
            S.name_pad_prev = nil
        end
    end)
    -- markers: never lose the wolf or the quarry again
    pcall(function()
        if C.enabled ~= true then return end
        if C.marker_wolf ~= false and S.armed and S.target then
            local wgo = char_go(S.target)
            if wgo then
                local glbl = creature_label(wgo)
                if S.trial and S.trial.gender then
                    -- 08-08 BELT (Aurora: flipped ♂→♀ AGAIN even with
                    -- the try_finish stash): mirror the gender every
                    -- frame the symbol is SHOWN -- whatever she courts
                    -- on screen is what do_commit seals, no matter
                    -- which path clears S.trial first.
                    S.pact_gender = S.trial.gender
                    glbl = glbl .. " " .. (S.trial.gender == "female" and "\u{2640}" or "\u{2642}")
                end
                draw_marker(wgo, glbl, 0xFF80D0FF)
            end
        end
        if C.marker_quarry ~= false and S.trial and S.trial.hunt_ch then
            local qgo = char_go(S.trial.hunt_ch)
            if qgo then draw_marker(qgo, creature_label(qgo) .. " (quarry)", 0xFF80FF80) end
        end
        -- 08-08 TRUCE BUBBLE (Aurora: "guards carried on attacking it
        -- while I was taming"): while a trial runs, every ~2s any
        -- combatant near our wolf lets its hate go. Party members were
        -- already stripped at commit; this covers town guards DURING
        -- the courtship. (Also calms the wolf's own pack vs the guards
        -- inside the bubble -- acceptable in ritual space.)
        if S.trial and S.target
            and os.clock() >= (tonumber(S.truce_at) or 0.0) then
            S.truce_at = os.clock() + 2.0
            pcall(function()
                local wgo = char_go(S.target)
                local wp = wgo and upos(wgo)
                if not wp then return end
                local sm = sdk.get_native_singleton("via.SceneManager")
                local smt = sdk.find_type_definition("via.SceneManager")
                local scene = sm
                    and sdk.call_native_func(sm, smt, "get_CurrentScene")
                local comps = scene and scene:call(
                    "findComponents(System.Type)",
                    sdk.typeof("app.Character"))
                -- ⛔ 08-14: THIS SWEEP NEVER GOT truce_bubble's PARTY SKIP, and clear_targets nulls
                -- app.LockOnTarget.TargetData - so for the whole trial it was wiping the PLAYER's
                -- own lock-on every two seconds. That is the exact bug truce_bubble was already
                -- fixed for; this copy was simply missed. Party pawns are handled surgically by
                -- shield_party_off (wolf-only strips, so they still fight goblins mid-rite).
                local skip3 = {}
                pcall(function()
                    for _, m3 in ipairs(party_characters()) do
                        pcall(function() skip3[m3:get_address()] = true end)
                    end
                end)
                for _, c in ipairs(comps and comps:get_elements() or {}) do
                    pcall(function()
                        if c == S.target then return end
                        local ca3 = c:get_address()
                        if ca3 and skip3[ca3] then return end
                        -- ⛔ 08-14 THE THIRD SWEEP. truce_bubble and pacify_pack both learned to
                        -- leave the hunt's quarry alone; this one is a separate 25m bubble around
                        -- the WOLF and it was still reaching it. clear_targets nulls
                        -- app.LockOnTarget.TargetData, which is the same lever the homestead box
                        -- uses to make a body un-aimable - so this quietly kept de-targeting the
                        -- one creature the errand exists to kill.
                        if S.is_quarry and S.is_quarry(c) then return end
                        local g = char_go(c)
                        local p = g and upos(g)
                        if p and dist(p, wp) < 25.0 then
                            strip_hate(c); clear_targets(c)
                        end
                    end)
                end
            end)
        end
    end)
    -- 08-08 WYRMFEEDING CONTEXT LABEL (its OWN pcall so an earlier
    -- marker error can never skip it -- Aurora: "no context label").
    -- The wyrm block (UpdateBehavior) sets S.wyrm_offer_go when at a
    -- DEPLOYED camp, near the companion, with 3 crystals.
    -- 08-11: pad button is B now (the native interact button) -- B is
    -- not Jump, so the jump gate is permanently off (the
    -- requestActionCore hook stays installed but never fires on nil).
    pcall(function()
        -- ⛔ 08-08 THE valid() BUG: valid() is a GriffinRideProbe fn, NOT
        -- defined here -- calling it threw, the pcall ate it, and the
        -- label + jump gate silently never ran ("nothing changed").
        -- Plain truthy check instead (matches the quarry marker above).
        S.wyrm_jump_gate = nil
        -- Wyrm's Rite now uses ui020701 exclusively. The old marker could outlive the native
        -- guide by a frame/scan interval and advertise an action after eligibility had ended.
        -- 08-12 round 11 (Aurora: "the ox isn't being marked like it normally does"):
        -- the courted ox wears the same marker every other tame wears -- species + gender
        -- glyph, the gender being the individual's own roll (the one the seal will lock)
        local R9 = S.ox_rite
        if R9 and R9.go then
            local lbl9 = "Ox"
            pcall(function() lbl9 = tostring(creature_label(R9.go)) end)
            pcall(function()
                local sp9 = rawget(_G, "IrisSpecies")
                local g9 = sp9 and sp9.gender and sp9.gender(R9.go) or nil
                if g9 == "female" then lbl9 = lbl9 .. " \u{2640}"
                elseif g9 == "male" then lbl9 = lbl9 .. " \u{2642}" end
            end)
            draw_marker(R9.go, lbl9, 0xFFFFC040)
        end
    end)
    pcall(function()
        -- MUSIC SAFETY (runs even when the mod is toggled off): never leave a theme stuck playing.
        -- The main music edge lives past several early-returns (disabled/pause/player-loss), so
        -- reconcile the stop here where it always runs. S.armed clears the moment a tame ends/loses.
        -- 08-12 round 3 (the silent yoke): the ox rite never sets S.armed -- this edge was
        -- KILLING the theme the same frame the want-edge started it. It must know every
        -- state the want-edge knows.
        if S.music_playing and (C.enabled ~= true or C.music_enabled ~= true
            or (S.armed ~= true and S.ox_rite == nil)) then
            bgm_stop(S.music_playing.g, S.music_playing.p); S.music_playing = nil
        end
        if C.enabled ~= true then return end
        if not _G.IrisTamingStrikeHookInstalled then install_strike_hook() end   -- retry until the HitController hook lands
        if not _G.IrisTamingHoldHookInstalled then install_hold_hook() end       -- retry until the target-list hook lands
        if not _G.IrisTamingRelHookInstalled then install_rel_hook() end         -- retry until the relationship hook lands
        if not _G.IrisTamingGuardHookInstalled then install_guard_hook() end     -- retry until the damage-clamp hook lands
        if not _G.IrisTamingTryCatchHookInstalled then install_trycatch_hook() end -- retry until the grab-detect hook lands
        if not _G.IrisTamingHateDoorInstalled then install_hate_door_hook() end   -- retry until the acquisition door lands
        if IPPS then IPPS("player_base") end
        local now = os.clock()
        local dt = math.max(0.001, math.min(0.1, now - (S.last_tick or now)))
        S.last_tick = now
        local player = get_player()
        local pgo = player and char_go(player)
        if not pgo then
            S.tame_gone = true
            if S.music_playing then bgm_stop(S.music_playing.g, S.music_playing.p); S.music_playing = nil end
            return
        end
        if S.tame_gone then S.tame_gone = nil; S.familiar = {} end   -- fresh on every (re)load
        local pp = upos(pgo)

        -- CAMP LEARNING: on the edge of "the player made camp", remember the spot (feeds the
        -- "carry it somewhere safe" marker). Throttled poll; edge-detected.
        if now >= (tonumber(S.camp_poll_at) or 0.0) then
            S.camp_poll_at = now + 1.0
            local camping = camp_active()
            if camping and not S.was_camping then learn_camp(pp) end
            S.was_camping = camping
        end

        -- THE FLEE (failed critter courtship): we still own the body for ~3s -- drive it
        -- AWAY (bird climbs out on the wing, ground critter bolts), then the brain goes back.
        -- Before this it just stood there "remembering" (Aurora), which read as nothing.
        if S.critter_flee then
            pcall(function()
                local F9 = S.critter_flee
                local ok9, ep9 = pcall(function() return upos(F9.go) end)
                if not ok9 or not ep9 or now > (tonumber(F9.until_t) or 0.0) then
                    pcall(function() set_ground_glue(F9.go, true) end)
                    pcall(function() release_creature(F9.ch) end)   -- shield off, brain back, immunity cleared
                    S.critter_flee = nil
                    return
                end
                if not F9.started then
                    F9.started = true
                    pcall(function() set_think_stop(F9.ch, true) end)
                    pcall(function() set_ground_glue(F9.go, false) end)
                    pcall(function() play_motion(F9.ch, 0, tonumber(F9.clip) or 200) end)
                end
                local sp9 = F9.fly and 6.5 or 5.5
                local dt9 = 0.016
                local v9 = ValueType.new(sdk.find_type_definition("via.Position"))
                v9.x = ep9.x + F9.dx * sp9 * dt9
                v9.z = ep9.z + F9.dz * sp9 * dt9
                if F9.fly then
                    v9.y = ep9.y + 2.4 * dt9   -- up and away
                else
                    local hb9 = ground_probe(ep9.x, ep9.y + 1.0, ep9.z)
                    v9.y = (hb9 and tonumber(hb9.y)) or ep9.y   -- hug the terrain at a dead run
                end
                set_upos(F9.go, v9)
                pcall(function()
                    -- face the escape (yaw from the flee direction)
                    local yaw9 = math.atan(F9.dx, F9.dz)
                    local qv9 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                    qv9.x = 0.0; qv9.y = math.sin(yaw9 * 0.5); qv9.z = 0.0; qv9.w = math.cos(yaw9 * 0.5)
                    F9.go:call("get_Transform"):call("set_Rotation", qv9)
                end)
            end)
        end

        -- player think-stop watchdog: the stance re-leases it every frame; ANY exit (fail,
        -- tame, key release, script error) lets the lease lapse and control restores itself
        if S.pstop_tick and now - (tonumber(S.pstop_tick) or 0.0) > 0.4 then
            set_think_stop(player, false)
            set_player_fsm(pgo, true)
            set_player_speed(player, 1.0)
            S.pstop_tick = nil
            S.pclip = nil
        end

        -- PAUSE RESPECT: while paused the ritual stands perfectly still; on resume every live
        -- timestamp shifts by the pause length -- nothing decays, nothing fails behind a menu
        if is_game_paused() then
            S.pause_t0 = S.pause_t0 or now
            return
        elseif S.pause_t0 then
            local shift = now - S.pause_t0
            S.pause_t0 = nil
            local T0 = S.trial
            if T0 then
                for _, k in ipairs({ "t0", "pact_at", "snarl_at", "flinch_until", "pat_until", "rush_p0" }) do
                    if tonumber(T0[k]) then T0[k] = T0[k] + shift end
                end
            end
            for _, k in ipairs({ "yield_until", "lie_at", "pclip_t0", "camp_tend" }) do
                if tonumber(S[k]) then S[k] = S[k] + shift end   -- camp_tend's "true" sentinel is skipped by tonumber
            end
            if S.lockouts then for k2, v2 in pairs(S.lockouts) do S.lockouts[k2] = v2 + shift end end
        end

        -- The house-cat spawner owns only the birth; once adopted, ordinary
        -- S.tamed upkeep below owns the body like every other ground critter.
        pcall(HC.queued_spawn_tick)
        pcall(HC.spawn_tick)

        -- pump the conjuror ONLY while a birth is pending: pumping stale instances
        -- forever is a native-crash roulette (suspect in the N-press CTD)
        if S.spawner and S.spawn_pump_until and now < (tonumber(S.spawn_pump_until) or 0.0) then
            pcall(function() S.spawner:requestSpawnOutstanding() end)
        end
        if S.oxtame_decoy_spawner and S.oxtame_decoy_pump_until
            and now < (tonumber(S.oxtame_decoy_pump_until) or 0.0) then
            pcall(function() S.oxtame_decoy_spawner:requestSpawnOutstanding() end)
        end
        -- Scene-owned decoy teardown. Clear the Griffin's managed target first, wait a full second
        -- for its target lists to rebuild, then destroy the spawner instance. Destroying a live target
        -- in the same frame as clearing it is another stale-pointer risk in LockOnTargetManager.
        if S.oxtame_decoy_spawner and not S.oxtame then
            if not S.oxtame_decoy_cleanup_at then
                oxtame_decoy_disarm(nil, S.oxtame_decoy_griffin, nil)
                S.oxtame_decoy_cleanup_at = now + 1.25
            elseif now >= S.oxtame_decoy_cleanup_at then
                pcall(function() S.oxtame_decoy_spawner:deleteAll() end)
                S.oxtame_decoy_spawner = nil; S.oxtame_decoy_ch = nil
                S.oxtame_decoy_griffin = nil; S.oxtame_decoy_pump_until = nil
                S.oxtame_decoy_pos = nil; S.oxtame_decoy_cleanup_at = nil
                pcall(function() log.info("[OxTame] live-bait decoy retired") end)
            end
        end

        -- DID THE DOE ACTUALLY GET BORN? "spawn requested" only means the conjuror accepted
        -- the request -- it says nothing about a body existing. Without this, a silent birth
        -- failure and a doe standing 35m behind you look identical from the log.
        if S.doe_spawn_pt and S.doe_verify_until then
            if now >= (tonumber(S.doe_verify_until) or 0.0) then
                S.doe_verify_until = nil
                local found, nearest = 0, nil
                pcall(function()
                    local sm = sdk.get_native_singleton("via.SceneManager")
                    local smt = sdk.find_type_definition("via.SceneManager")
                    local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
                    local comps = scene and scene:call("findComponents(System.Type)",
                        sdk.typeof("app.Character"))
                    local n = 0
                    pcall(function() n = comps:call("get_Length") or 0 end)
                    if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
                    for i = 0, (tonumber(n) or 0) - 1 do
                        pcall(function()
                            local c = comps:call("get_Item", i) or comps[i]
                            local nm = go_name(char_go(c))
                            -- the quarry band follows the config now (it is a STAG since 08-14)
                            if nm:find(tostring(C.hunt_spawn_cid or "ch299010_A_00"):sub(1, 8), 1, true) then
                                found = found + 1
                                local p = upos(char_go(c))
                                if p then
                                    -- ⛔ S.doe_spawn_pt is the RENDER-converted request point and `p`
                                    -- is UNIVERSAL - comparing them printed a distance wrong by the
                                    -- origin offset. Measure against the berth we actually vetted.
                                    local d = dist(p, S.doe_spawn_uni or S.doe_spawn_pt)
                                    if not nearest or d < nearest then nearest = d end
                                end
                            end
                        end)
                    end
                end)
                pcall(function() log.info(string.format(
                    "[IrisTaming] quarry VERIFY: %d in scene, nearest %s from the vetted berth",
                    found, nearest and string.format("%.1fm", nearest) or "n/a")) end)
            end
        end

        -- landing-spot tuning aid: the flight's target drawn where it truly is (raise the arm
        -- via a live call, then drag the sliders until the dot sits on the glove).
        -- Drawn EXACT: draw_marker_at_universal floats its dot +1.6m for overhead labels, which
        -- made every alignment land 1.6m low (the bird at the feet with Y tuned to 0).
        if C.call_land_marker == true and pgo then
            pcall(function()
                local tfp = pgo:call("get_Transform")
                local prot = tfp:call("get_Rotation")
                local ox, oy, oz = qrot(prot,
                    tonumber(C.call_land_x) or 0.45, tonumber(C.call_land_y) or 1.30, tonumber(C.call_land_z) or 0.35)
                local rp = tfp:call("get_Position")
                rp.x = rp.x + ox; rp.y = rp.y + oy; rp.z = rp.z + oz
                local sp2 = draw.world_to_screen(rp)
                if sp2 then
                    draw.filled_circle(sp2.x, sp2.y, 7, 0xFF80FFB0, 12)
                    iris_screen_text("landing", sp2.x + 10, sp2.y - 8, 0xFF80FFB0, 17)
                end
            end)
        end

        -- deferred non-donor whistle (fires at the gesture's hand-to-mouth moment)
        if S.wlate and now >= (tonumber(S.wlate.at) or 0.0) then
            local WL = S.wlate
            S.wlate = nil
            if WL.mode == "critter" and WL.ch then
                pcall(function()
                    local wcc = WL.ch:get_field("<WwiseContainer>k__BackingField")
                    if not wcc then wcc = WL.ch:call("get_WwiseContainer") end
                    local cgo9 = char_go(WL.ch)
                    if wcc and cgo9 then
                        wcc:call("triggerLogLess(System.UInt32, via.GameObject, via.GameObject)", WL.id, cgo9, cgo9)
                    end
                end)
            elseif WL.mode == "player" then
                play_player_wwise(player, WL.id)
            end
        end

        -- THE WHISTLE DONOR: an invisible ghost of the sound's species, spawned purely to carry
        -- the whistle's bank. The spawner births it in ITS OWN coordinate dialect (a prior build
        -- found it 34,000km out and gave up) -- so take the new body WHEREVER it lands, WARP it
        -- to the player, let the transform settle a beat, then fire and destroy.
        if S.wdonor then
            local W9 = S.wdonor
            if W9.go and not W9.fired and now >= (tonumber(W9.fire_at) or 0.0) then
                -- warped and settled: the whistle, from a body standing right beside the player
                pcall(function()
                    local wcc = W9.chr and W9.chr:get_field("<WwiseContainer>k__BackingField")
                    if not wcc and W9.chr then wcc = W9.chr:call("get_WwiseContainer") end
                    if wcc then wcc:call("triggerLogLess(System.UInt32, via.GameObject, via.GameObject)", W9.id, W9.go, W9.go) end
                end)
                W9.fired = true
                W9.kill_at = now + 3.5
                pcall(function() log.info("[IrisTaming] whistle donor fired id=" .. tostring(W9.id)) end)
            elseif W9.go and W9.fired and now >= (tonumber(W9.kill_at) or 0.0) then
                pcall(function() W9.go:call("destroy", W9.go) end)
                S.wdonor = nil
            elseif not W9.go and now >= (tonumber(W9.until_t) or 0.0) then
                S.wdonor = nil   -- never materialised: let it go and log it
                pcall(function() log.info("[IrisTaming] whistle donor never born") end)
            elseif not W9.go then
                pcall(function()
                    local sm9 = sdk.get_native_singleton("via.SceneManager")
                    local smt9 = sdk.find_type_definition("via.SceneManager")
                    local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
                    local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("app.Character"))
                    local n9 = 0
                    pcall(function() n9 = comps9:call("get_Length") or 0 end)
                    if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
                    for i9 = 0, (tonumber(n9) or 0) - 1 do
                        pcall(function()
                            local c9b = comps9:call("get_Item", i9) or comps9[i9]
                            local g9 = char_go(c9b)
                            local nm9b = g9 and go_name(g9) or ""
                            if (not W9.go) and nm9b:find(W9.band, 1, true) == 1 and not W9.seen[c9b:get_address()] then
                                -- the ghost is born: unseen, untouchable, silent in body
                                pcall(function() g9:call("set_DrawSelf", false) end)
                                set_think_stop(c9b, true)
                                set_immunity(c9b, true)
                                set_ground_glue(g9, false)
                                pcall(function() c9b:call("setCharacterControllerEnable", false) end)
                                -- warp to the player: wwise is positional, and the spawner may have
                                -- birthed it a continent away
                                local dd9 = 0.0
                                pcall(function()
                                    local bu9 = upos(g9)
                                    if bu9 and pp then dd9 = dist(bu9, pp) end
                                end)
                                if pp then
                                    local pv9 = ValueType.new(sdk.find_type_definition("via.Position"))
                                    pv9.x = pp.x; pv9.y = pp.y + 1.5; pv9.z = pp.z
                                    set_upos(g9, pv9)
                                end
                                W9.go = g9
                                W9.chr = c9b
                                -- one breath for the warp to take, AND the gesture's hand-to-mouth
                                -- moment (the sound fired too early against the animation)
                                W9.fire_at = math.max(now + 0.2, tonumber(W9.not_before) or 0.0)
                                pcall(function() log.info(string.format("[IrisTaming] donor born %.0fm out, warped to player", dd9)) end)
                            end
                        end)
                    end
                end)
            end
        end

        -- GENDER BACKFILL: companions tamed before the gender system roll theirs, so breeding
        -- finds a full roster (Aurora: "give the current tames genders"). RETRIES until the
        -- stable answers -- the first attempt fired before the stable file had loaded, got
        -- nothing, and marked itself done (the symbol-less old tames)
        -- IV BACKFILL (08-11, the gender-backfill pattern but NEVER latched: it re-sweeps
        -- every 30s so any register route that misses the tame-time roll still gets genes)
        if now >= (tonumber(S.iv_backfill_at) or 0.0) then
            S.iv_backfill_at = now + 30.0
            pcall(function()
                local b = _G.IrisGriffinBridge
                if b and b.companion_ivs then
                    local n0 = b.companion_ivs()
                    if n0 and tonumber(n0) and tonumber(n0) > 0 then
                        log.info("[IrisTaming] IV backfill: " .. tostring(n0) .. " companion(s) rolled their genes")
                    end
                end
            end)
        end
        if not S.gender_backfilled and now >= (tonumber(S.gender_backfill_at) or 0.0) then
            S.gender_backfill_at = now + 3.0
            pcall(function()
                local b = _G.IrisGriffinBridge
                if b and b.companion_genders then
                    local n0 = b.companion_genders()
                    if n0 ~= nil then   -- nil = stable not loaded yet; keep asking
                        S.gender_backfilled = true
                        if (tonumber(n0) or 0) > 0 then
                            log.info("[IrisTaming] gender backfill: " .. tostring(n0) .. " companion(s) assigned")
                        end
                    end
                end
            end)
        end

        -- NEST SURVEY markers: every logged nest drawn in-world (the egg hunt's map aid),
        -- with the distance from the player ("could be miles away" -- now it says so)
        if IPPS then IPPS("markers") end
        if C.nest_markers == true and pgo then
            local pu8 = upos(pgo)
            local function dist_tag8(x8, y8, z8)
                if not pu8 then return "" end
                local dx8, dy8, dz8 = (tonumber(x8) or 0) - pu8.x, (tonumber(y8) or 0) - pu8.y, (tonumber(z8) or 0) - pu8.z
                local d8 = math.sqrt(dx8 * dx8 + dy8 * dy8 + dz8 * dz8)
                if d8 >= 1000.0 then return string.format("  %.1fkm", d8 / 1000.0) end
                return string.format("  %dm", math.floor(d8))
            end
            for _, n9 in ipairs(nests_load()) do
                pcall(function()
                    draw_marker_at_universal(pgo, tonumber(n9.x) or 0.0, tonumber(n9.y) or 0.0, tonumber(n9.z) or 0.0,
                        "NEST " .. tostring(n9.label or "") .. dist_tag8(n9.x, n9.y, n9.z), 0xFF40C0FF)
                end)
            end
            -- learned griffin REST NODES (the cartographer's roost candidates): fly to one,
            -- check for a nest prop, LOG it if real
            pcall(function()
                for id9, nd9 in pairs(groutes_load().nodes or {}) do
                    if nd9.rest then
                        local tag9 = nd9.air and " (aerial: roost BELOW?)" or ""
                        draw_marker_at_universal(pgo, tonumber(nd9.x) or 0.0, tonumber(nd9.y) or 0.0, tonumber(nd9.z) or 0.0,
                            tostring(nd9.name or ("REST NODE " .. tostring(id9))) .. tag9 .. dist_tag8(nd9.x, nd9.y, nd9.z), 0xFFFF60E0)
                    end
                end
            end)
        end
        -- THE HEIST WAY-HOME marker (⛔ MUST draw here in the FRAME callback -- draw.* renders
        -- ONLY on_frame, never in UpdateBehavior; that's why the camp beacon was invisible).
        -- The egg-heist tick SETS S.heist_marker; we PAINT it, clamped to 120m so a far camp
        -- shows as a compass beacon instead of falling off the far clip. Always shows while
        -- carrying a stolen egg, like the wolf-tame camp marker.
        if S.heist_marker and pgo then
            pcall(function()
                local pu7 = upos(pgo)
                if not pu7 then return end
                local mx7, my7, mz7 = S.heist_marker.x, S.heist_marker.y, S.heist_marker.z
                local dx7, dy7, dz7 = mx7 - pu7.x, my7 - pu7.y, mz7 - pu7.z
                local d7 = math.sqrt(dx7 * dx7 + dy7 * dy7 + dz7 * dz7)
                if d7 > 120.0 then
                    local s7 = 120.0 / d7
                    mx7 = pu7.x + dx7 * s7
                    my7 = pu7.y + dy7 * s7 + 2.0
                    mz7 = pu7.z + dz7 * s7
                end
                draw_marker_at_universal(pgo, mx7, my7, mz7, S.heist_marker.label, 0xFF60E0FF)
            end)
        end
        -- THE OX-TAME SCENE MARKER (same draw law: the tick SETS S.oxtame_mark, we PAINT).
        -- Clamped like the heist beacon so a distant circling griffin still shows as a compass.
        if S.oxtame_mark and pgo and os.clock() < (tonumber(S.oxtame_mark.until_t) or 0.0) then
            pcall(function()
                local pu7 = upos(pgo)
                if not pu7 then return end
                local mx7, my7, mz7 = S.oxtame_mark.x, S.oxtame_mark.y, S.oxtame_mark.z
                local dx7, dy7, dz7 = mx7 - pu7.x, my7 - pu7.y, mz7 - pu7.z
                local d7 = math.sqrt(dx7 * dx7 + dy7 * dy7 + dz7 * dz7)
                if d7 > 140.0 then
                    local s7 = 140.0 / d7
                    mx7 = pu7.x + dx7 * s7
                    my7 = pu7.y + dy7 * s7 + 2.0
                    mz7 = pu7.z + dz7 * s7
                end
                draw_marker_at_universal(pgo, mx7, my7, mz7, S.oxtame_mark.label, 0xFFFFD080)
            end)
        end

        -- WILD GRIFFIN TRACKER (the nest hunt, Aurora): every streamed-in ch253 that is NOT the
        -- companion gets a live marker + a breadcrumb flight trail; when it streams out (the world
        -- loads around the PLAYER -- a 2km griffin does not exist to track), its LAST-SEEN marker
        -- and trail stay up so you can chase the heading until it streams back in.
        -- GHOST MODE rides the same sweep: it feeds the rel-hook's address sets (wild griffins +
        -- party) so griffins classify the observers as FRIEND and never engage.
        -- the ghost shield = the PERSISTENT config (manual nest-observation tool) OR the
        -- VOLATILE court-mode shield (S.oxtame_shield -- never saved, never sticky; Aurora
        -- caught the old config-write leaving ghost silently ON between sessions)
        local ghost_on9 = (C.griffin_ghost == true) or (S.oxtame_shield ~= nil)
        if _G.IrisTamingGhost then
            _G.IrisTamingGhost.on = ghost_on9
            if not ghost_on9 then
                -- belt + braces (Aurora's RiftSpeak pacifist scar): OFF also EMPTIES the sets,
                -- so even a stale hook closure has nothing to match
                _G.IrisTamingGhost.griffins = {}
                _G.IrisTamingGhost.party = {}
            end
        end
        if IPPS then IPPS("ghost_tracker") end
        if (C.griffin_tracker == true or ghost_on9) and pgo then
            S.gtrack = S.gtrack or {}
            if now >= (tonumber(S.gtrack_scan_at) or 0.0) then
                S.gtrack_scan_at = now + 1.0
                pcall(function()
                    local comp_addr = nil
                    pcall(function()
                        local B = _G.IrisGriffinBridge
                        local g = B and B.griffin and B.griffin()
                        if g then comp_addr = tostring(g:get_address()) end
                    end)
                    local gset, pset = {}, {}
                    local sm = sdk.get_native_singleton("via.SceneManager")
                    local smt = sdk.find_type_definition("via.SceneManager")
                    local scene = sm and sdk.call_native_func(sm, smt, "get_CurrentScene")
                    local comps = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.Character"))
                    local n = 0; pcall(function() n = comps:call("get_Length") or 0 end)
                    if n == 0 then pcall(function() n = comps:get_size() or 0 end) end
                    for i = 0, (tonumber(n) or 0) - 1 do
                        pcall(function()
                            local ch = comps:call("get_Item", i) or comps[i]
                            local go = ch and char_go(ch)
                            if not go or is_dead(ch) then return end
                            if not tostring(go_name(go)):find("ch253", 1, true) then return end
                            local addr_n = ch:get_address()
                            local ach = tostring(addr_n)
                            if comp_addr and ach == comp_addr then return end   -- the tamed one is not wild
                            if S.tamed_addrs and S.tamed_addrs[ach] then return end
                            gset[addr_n] = true
                            local up = upos(go)
                            if not up then return end
                            local e = S.gtrack[ach] or { trail = {} }
                            S.gtrack[ach] = e
                            e.x = tonumber(up.x); e.y = tonumber(up.y); e.z = tonumber(up.z); e.t = now
                            -- what is it DOING? current FSM motion (bank:clip) on the label --
                            -- roost idles vs sleep vs nest behaviors, read off layer 0 (Aurora's ask)
                            pcall(function()
                                local ly9 = ch:call("get_Motion"):call("getLayer", 0)
                                local mb9, mi9 = nil, nil
                                pcall(function() mb9 = ly9:call("get_MotionBankID") end)
                                pcall(function() mi9 = ly9:call("get_MotionID") end)
                                if tonumber(mi9) then
                                    e.clip = tostring(tonumber(mb9) and math.floor(tonumber(mb9)) or "?")
                                        .. ":" .. tostring(math.floor(tonumber(mi9)))
                                end
                            end)
                            -- THE CARTOGRAPHER: the griffin commutes an AI-map NODE GRAPH (waypoint
                            -- dump v2: CurrentNodeId/NextNodeId/LastRestPoint on Ch253000's
                            -- _Ch253AirWayPointMoveCtrl). Node coords are in AI-MAP LOCAL space --
                            -- but at the MOMENT CurrentNodeId changes, the body stands at that node,
                            -- so its own universal position IS the node's world position. Every
                            -- transition we witness fills in the route map; REST nodes = roost/nest
                            -- candidates, drawn with the nest markers.
                            pcall(function()
                                local c253 = comp(go, "app.Ch253000")
                                local wp9 = c253 and c253:get_field("_Ch253AirWayPointMoveCtrl")
                                if not wp9 then return end
                                local cur9 = tonumber(wp9:get_field("<CurrentNodeId>k__BackingField"))
                                local rest9 = tonumber(wp9:get_field("<LastRestPoint>k__BackingField"))
                                if not cur9 then return end
                                if cur9 == 4294967295 then return end   -- UInt32 -1: off the graph, not a node
                                e.node = math.floor(cur9)
                                if e.node_prev == nil then
                                    -- first sighting: it may be MID-LEG between nodes -- its position
                                    -- would lie about where this node is. Only witnessed CHANGES stamp.
                                    e.node_prev = e.node
                                elseif e.node_prev ~= e.node then
                                    e.node_prev = e.node
                                    local gr9 = groutes_load()
                                    local key9 = tostring(e.node)
                                    local prev9 = gr9.nodes[key9]
                                    gr9.nodes[key9] = {
                                        x = e.x, y = e.y, z = e.z,
                                        rest = (rest9 == e.node) or (prev9 and prev9.rest) or nil,
                                        -- stamped while FLYING = an aerial lane node (its roost sits
                                        -- below it); stamped while parked = ground truth. Self-corrects
                                        -- if a later visit catches it sitting here.
                                        air = ((e.still or 0.0) < 2.0) or nil,
                                        seen = os.date("%Y-%m-%d %H:%M"),
                                    }
                                    json.dump_file("IrisGriffinRoutes.json", gr9)
                                end
                            end)
                            -- REST detection that needs NO graph at all: a wild griffin holding one
                            -- spot for 20s+ is roosting -- stamp a coord-keyed rest spot (this also
                            -- catches roosts the sentinel/graph weirdness would hide)
                            pcall(function()
                                local mv9 = 1e9
                                if e.px then
                                    local dx9, dy9, dz9 = e.x - e.px, e.y - e.py, e.z - e.pz
                                    mv9 = math.sqrt(dx9 * dx9 + dy9 * dy9 + dz9 * dz9)
                                end
                                e.px, e.py, e.pz = e.x, e.y, e.z
                                if mv9 < 1.0 then
                                    e.still = (e.still or 0.0) + 1.0
                                else
                                    e.still = 0.0
                                    e.rest_stamped = nil   -- moved on: re-arm for the next distinct sit
                                end
                                if (e.still or 0.0) >= 20.0 and not e.rest_stamped then
                                    e.rest_stamped = true
                                    local gr9 = groutes_load()
                                    local key9 = string.format("r_%d_%d", math.floor((e.x or 0) / 10), math.floor((e.z or 0) / 10))
                                    if not gr9.nodes[key9] then
                                        gr9.nodes[key9] = { x = e.x, y = e.y, z = e.z, rest = true, seen = os.date("%Y-%m-%d %H:%M") }
                                        json.dump_file("IrisGriffinRoutes.json", gr9)
                                    end
                                end
                            end)
                            local tr = e.trail
                            local lastp = tr[#tr]
                            local far9 = true
                            if lastp then
                                local dx9, dz9 = e.x - lastp.x, e.z - lastp.z
                                far9 = (dx9 * dx9 + dz9 * dz9) > 225.0   -- a crumb every ~15m
                            end
                            if far9 then
                                tr[#tr + 1] = { x = e.x, y = e.y, z = e.z }
                                while #tr > 60 do table.remove(tr, 1) end
                            end
                        end)
                    end
                    for _, member in ipairs(party_characters()) do
                        pcall(function() pset[member:get_address()] = true end)
                    end
                    _G.IrisTamingGhost = { on = ghost_on9, griffins = gset, party = pset }
                end)
            end
            if C.griffin_tracker == true then   -- ghost-only mode watches silently, no markers
                local pu9 = upos(pgo)
                for ach, e in pairs(S.gtrack) do
                    pcall(function()
                        local age = now - (tonumber(e.t) or 0.0)
                        if age > 900.0 then S.gtrack[ach] = nil; return end   -- forget after 15 min
                        local d9 = 0.0
                        if pu9 then
                            local dx9, dy9, dz9 = e.x - pu9.x, e.y - pu9.y, e.z - pu9.z
                            d9 = math.sqrt(dx9 * dx9 + dy9 * dy9 + dz9 * dz9)
                        end
                        local live9 = age < 3.0
                        local lbl = live9 and string.format("WILD GRIFFIN %dm%s", math.floor(d9),
                                e.clip and ("  [" .. e.clip .. "]") or "")
                            or string.format("griffin last seen %ds ago (%dm)%s", math.floor(age), math.floor(d9),
                                e.clip and ("  [was " .. e.clip .. "]") or "")
                        draw_marker_at_universal(pgo, e.x, e.y, e.z, lbl, live9 and 0xFFFFC040 or 0x90FFC040)
                        for _, p9 in ipairs(e.trail or {}) do
                            draw_marker_at_universal(pgo, p9.x, p9.y, p9.z, "", 0x50FFC040)
                        end
                    end)
                end
            end
        end

        -- THE CAW ECHO: the caw id lives in the crow's species BANK, and a creature-bank trigger
        -- is audible only GO-to-GO from a body of that species (the whistle laws; the player-GO
        -- form is a tested FALSE SUCCESS). The scouting crow is far away and the wwise listener
        -- stays with the player -- so the FIRST caw ghost-spawns ONE invisible echo-crow beside
        -- the player (the whistle-donor recipe: adopt wherever born, silence, warp home); it
        -- carries every caw of the scout and dies with it.
        if IPPS then IPPS("cdonor") end
        if S.cdonor and not S.scout and (tonumber(S.cdonor_test) or 0.0) <= now then
            pcall(function() if S.cdonor.go then S.cdonor.go:call("destroy", S.cdonor.go) end end)
            S.cdonor = nil; S.cdonor_want = nil
        elseif S.cdonor_want and not S.cdonor and (S.scout or (tonumber(S.cdonor_test) or 0.0) > now) then
            local band0 = "ch299410"
            pcall(function()
                local g0 = char_go(S.scout.ch)
                local nm0 = g0 and go_name(g0) or ""
                band0 = nm0:match("ch%d+") or band0
            end)
            local cid0 = tostring(C.scout_caw_donor_cid or "")
            if cid0 == "" then cid0 = band0 .. "_A_00" end
            local want0 = S.cdonor_want
            S.cdonor_want = nil
            pcall(function()
                if not S.spawner then
                    local SR = require("EnemySpawner/spawnRequest")
                    S.spawner = SR:new()
                end
                -- snapshot the band so the ghost is identified as the NEW body, never a wild one
                local seen0 = {}
                local sm0 = sdk.get_native_singleton("via.SceneManager")
                local smt0 = sdk.find_type_definition("via.SceneManager")
                local scene0 = sm0 and sdk.call_native_func(sm0, smt0, "get_CurrentScene")
                local comps0 = scene0 and scene0:call("findComponents(System.Type)", sdk.typeof("app.Character"))
                local n0 = 0
                pcall(function() n0 = comps0:call("get_Length") or 0 end)
                if n0 == 0 then pcall(function() n0 = comps0:get_size() or 0 end) end
                for i0 = 0, (tonumber(n0) or 0) - 1 do
                    pcall(function()
                        local cb0 = comps0:call("get_Item", i0) or comps0[i0]
                        local nmb0 = go_name(char_go(cb0))
                        if nmb0:find(band0, 1, true) == 1 then seen0[cb0:get_address()] = true end
                    end)
                end
                local q0 = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                q0.x = 0; q0.y = 0; q0.z = 0; q0.w = 1
                local rp0 = pgo and pgo:call("get_Transform"):call("get_Position")
                if not rp0 then return end
                rp0.y = rp0.y + 1.5
                S.spawner:requestAddInstances(cid0, rp0, q0,
                    { spawnIdle = false, ovrScale = { enable = false, scale = 1.0, normalizeSpeed = false }, postProcScale = false }, 1)
                S.spawn_pump_until = os.clock() + 8.0
                S.cdonor = { band = band0, seen = seen0, id = want0.id, until_t = now + 8.0 }
                pcall(function() log.info("[IrisTaming] caw echo spawn requested (" .. cid0 .. ")") end)
            end)
        elseif S.cdonor then
            local E9 = S.cdonor
            if not E9.go and now >= (tonumber(E9.until_t) or 0.0) then
                S.cdonor = nil
                pcall(function() log.info("[IrisTaming] caw echo never born") end)
            elseif not E9.go then
                pcall(function()
                    local sm9 = sdk.get_native_singleton("via.SceneManager")
                    local smt9 = sdk.find_type_definition("via.SceneManager")
                    local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
                    local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("app.Character"))
                    local n9 = 0
                    pcall(function() n9 = comps9:call("get_Length") or 0 end)
                    if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
                    for i9 = 0, (tonumber(n9) or 0) - 1 do
                        pcall(function()
                            local c9b = comps9:call("get_Item", i9) or comps9[i9]
                            local g9 = char_go(c9b)
                            local nm9b = g9 and go_name(g9) or ""
                            if (not E9.go) and nm9b:find(E9.band, 1, true) == 1 and not E9.seen[c9b:get_address()] then
                                -- the echo is born: unseen, untouchable, still in body
                                pcall(function() g9:call("set_DrawSelf", false) end)
                                set_think_stop(c9b, true)
                                set_immunity(c9b, true)
                                set_ground_glue(g9, false)
                                pcall(function() c9b:call("setCharacterControllerEnable", false) end)
                                if pp then
                                    local pv9 = ValueType.new(sdk.find_type_definition("via.Position"))
                                    pv9.x = pp.x; pv9.y = pp.y + 1.5; pv9.z = pp.z
                                    set_upos(g9, pv9)
                                end
                                E9.go = g9
                                E9.chr = c9b
                                -- 0.8s first beat: the warp needs a breath AND a fresh spawn's
                                -- cold wwise bank needs a moment to bind (cold resources lie)
                                E9.stages = scout_caw_stages(now + 0.8)
                                pcall(function() log.info("[IrisTaming] caw echo born, warped to player") end)
                            end
                        end)
                    end
                end)
            else
                if S.cdonor_want then
                    -- another caw while the ghost lives: run a fresh probe sequence
                    E9.id = S.cdonor_want.id
                    S.cdonor_want = nil
                    E9.stages = scout_caw_stages(now + 0.15)
                end
                local st9 = E9.stages and E9.stages[1]
                if st9 then
                    if st9.mode == "crow" then
                        if now >= (tonumber(st9.at) or 0.0) then
                            table.remove(E9.stages, 1)
                            pcall(function()
                                local wc9 = _G.route3_wwise_container and _G.route3_wwise_container()
                                local b9 = _G.IrisGriffinBridge
                                local ch9 = b9 and b9.griffin and b9.griffin()
                                local g9c = ch9 and char_go(ch9)
                                if wc9 and g9c then
                                    wc9:call("triggerLogLess(System.UInt32, via.GameObject, via.GameObject)",
                                        math.floor(tonumber(E9.id) or 0), g9c, g9c)
                                end
                            end)
                            pcall(function() log.info("[IrisTaming] caw probe fired @crow-container id=" .. tostring(E9.id)) end)
                        end
                    elseif not st9.warped then
                        if now >= (tonumber(st9.at) or 0.0) then
                            st9.warped = true
                            st9.fire_at = now + 0.25   -- one breath for the warp to take
                            pcall(function()
                                local anchor = nil
                                if st9.mode == "bird" and S.scout then
                                    local bg9 = char_go(S.scout.ch)
                                    anchor = bg9 and upos(bg9)
                                end
                                if not anchor then anchor = pp end
                                if anchor and E9.go then
                                    local pv9 = ValueType.new(sdk.find_type_definition("via.Position"))
                                    pv9.x = anchor.x; pv9.y = anchor.y + 1.5; pv9.z = anchor.z
                                    set_upos(E9.go, pv9)
                                end
                            end)
                        end
                    elseif now >= (tonumber(st9.fire_at) or 0.0) then
                        table.remove(E9.stages, 1)
                        pcall(function()
                            local wcc = E9.chr and E9.chr:get_field("<WwiseContainer>k__BackingField")
                            if not wcc and E9.chr then wcc = E9.chr:call("get_WwiseContainer") end
                            if wcc then wcc:call("triggerLogLess(System.UInt32, via.GameObject, via.GameObject)",
                                math.floor(tonumber(E9.id) or 0), E9.go, E9.go) end
                        end)
                        pcall(function() log.info("[IrisTaming] caw probe fired @" .. tostring(st9.mode) .. " (echo-ghost) id=" .. tostring(E9.id)) end)
                    end
                end
            end
        end

        -- delayed player one-shots (fired a breath after the FSM is seized, or they get stomped)
        -- player one-shot HOLD: a lone play_player_motion doesn't render (the FSM reclaims layer 0);
        -- keep the FSM OFF and pin the last frame for a window so the clip is actually SEEN
        if S.phold then
            if now < (tonumber(S.phold.until_t) or 0.0) then
                -- ⭐ UPPER-BODY MODE (Aurora 07-26: "make it top half only so I can walk during
                -- it"). The FSM keeps layer 0 = locomotion, the gesture rides layer 1 = upper body
                -- (the carry-walk law). So NO think-stop and NO FSM seize - that's what pinned you.
                if not S.phold.upper then
                    set_think_stop(player, true)
                    set_player_fsm(pgo, false)
                end
                local li = S.phold.upper and 1 or 0
                if not S.phold.played then
                    S.phold.played = true
                    pcall(function() log.info("[IrisTaming] player HOLD clip=" .. tostring(S.phold.clip)
                        .. (S.phold.upper and " (UPPER BODY, layer 1)" or "")) end)
                    play_player_motion(player, tonumber(S.phold.clip) or 830, nil, nil, li)
                    local mid = nil
                    pcall(function()
                        mid = tonumber(player:call("get_Motion"):call("getLayer", li):call("get_MotionID"))
                        log.info("[IrisTaming] phold clip=" .. tostring(S.phold.clip) .. " readback=" .. tostring(mid))
                    end)
                    -- SELF-HEAL: if layer 1 refused the clip we'd show NOTHING, which is worse
                    -- than the truncation we set out to fix. Detect the refusal and immediately
                    -- redo it the old full-body way.
                    if S.phold.upper and mid ~= (tonumber(S.phold.clip) or -2) then
                        pcall(function() log.info("[IrisTaming] layer 1 refused the clip - falling back to full body") end)
                        S.phold.upper = false
                        set_think_stop(player, true)
                        set_player_fsm(pgo, false)
                        play_player_motion(player, tonumber(S.phold.clip) or 830, nil, nil, 0)
                    end
                    -- 08-12: play the held gesture FASTER when asked (Aurora:
                    -- the sense search "takes a while... frustrating")
                    if S.phold.speed then
                        pcall(function()
                            player:call("get_Motion")
                                :call("getLayer", S.phold.upper and 1 or 0)
                                :call("set_Speed", S.phold.speed)
                        end)
                    end
                else
                    -- ⭐ FOLLOW THE CLIP: hold exactly as long as it actually RUNS. A fixed timeout
                    -- is what truncated the search gesture; reading the live layer needs no
                    -- frame-rate assumption and cannot cut out early.
                    if S.phold.follow then
                        pcall(function()
                            local layer = player:call("get_Motion"):call("getLayer", li)
                            if not layer then return end
                            local f = tonumber(layer:call("get_Frame")) or 0
                            local ef = tonumber(layer:call("get_EndFrame")) or 0
                            local mid = tonumber(layer:call("get_MotionID")) or -1
                            local want = tonumber(S.phold.clip) or -2
                            if mid == want then
                                if ef > 1.0 and f < ef - 1.0 then
                                    S.phold.until_t = now + 0.30      -- still running: keep it alive
                                    S.phold.at_frame = f              -- remember how far it got
                                end
                            elseif (S.phold.at_frame or 0) > 0.0 and not S.phold.gave_up then
                                -- ⭐ SOMETHING STOLE THE LAYER MID-CLIP. Aurora 07-26: "it was
                                -- mostly cutting out if I moved the right stick (camera)" - camera
                                -- input evidently pushes its own motion even with the FSM held off.
                                -- Rather than diagnose every thief, just put our clip BACK where it
                                -- was and carry on. Capped so a clip the game truly refuses can't
                                -- become an infinite fight.
                                S.phold.retries = (S.phold.retries or 0) + 1
                                if S.phold.retries > 12 then
                                    S.phold.gave_up = true
                                    pcall(function() log.info("[IrisTaming] phold: layer kept being stolen, letting go") end)
                                else
                                    play_player_motion(player, want, nil, S.phold.at_frame, li)
                                    S.phold.until_t = now + 0.30
                                    if S.phold.speed then
                                        pcall(function()
                                            player:call("get_Motion")
                                                :call("getLayer", li)
                                                :call("set_Speed", S.phold.speed)
                                        end)
                                    end
                                end
                            end
                        end)
                    end
                    -- 08-12 [B] EARLY-OUT (Aurora: "press B to cancel"):
                    -- bottom-right hint while a cancelable gesture holds;
                    -- B (pad, enum-resolved -- never guess masks) or the B
                    -- key ends it now via the normal cleanup path.
                    if S.phold.cancel then
                        -- 08-12 (Aurora: "use the native UI, not a fake label
                        -- over the button"): publish into the game's own key
                        -- guide via the shared IrisPromptBar service -- B slot
                        -- = PNL_R02, fire-and-forget with a 1s TTL, so this
                        -- per-tick republish is the whole contract.
                        pcall(function()
                            local P9 = rawget(_G, "IrisPrompt")
                            if P9 and P9.set_slot then
                                P9.set_slot("iris_sense", "PNL_R02",
                                    "End Search")
                            end
                        end)
                        local cb9 = false
                        pcall(function() cb9 = iris_kb(0x42) end)
                        if not cb9 then
                            pcall(function()
                                if S.sense_cancel_mask == nil then
                                    S.sense_cancel_mask = 0
                                    local bt9 = sdk.find_type_definition(
                                        "via.hid.GamePadButton")
                                    local f9 = bt9 and bt9:get_field("RRight")
                                    S.sense_cancel_mask =
                                        tonumber(f9:get_data(nil)) or 0
                                end
                                local hid9 = sdk.get_native_singleton(
                                    "via.hid.GamePad")
                                local ht9 = sdk.find_type_definition(
                                    "via.hid.GamePad")
                                local dev9 = sdk.call_native_func(hid9, ht9,
                                    "get_MergedDevice")
                                local mask9 = dev9
                                    and tonumber(dev9:call("get_Button")) or 0
                                cb9 = S.sense_cancel_mask ~= 0
                                    and (mask9 & S.sense_cancel_mask) ~= 0
                            end)
                        end
                        if cb9 then
                            pcall(function() log.info(
                                "[IrisTaming] sense gesture cancelled ([B])") end)
                            S.phold.until_t = 0.0
                            S.phold.next = nil
                            pcall(function()
                                local P9 = rawget(_G, "IrisPrompt")
                                if P9 and P9.clear_slot then
                                    P9.clear_slot("iris_sense")
                                end
                            end)
                        end
                    end
                    if not S.phold.no_pin then
                        pcall(function()
                            local layer = player:call("get_Motion"):call("getLayer", li)
                            local ef = layer and layer:call("get_EndFrame")
                            if ef and ef > 4.0 and layer:call("get_Frame") >= ef - 2.0 then layer:call("set_Frame", ef - 2.0) end
                        end)
                    end
                end
            elseif S.phold.next then
                -- 08-12 (Aurora: "she can run really fast" after the sense):
                -- set_Speed lives on the LAYER, not the clip -- the FSM
                -- inherits a 1.6x locomotion layer unless it is handed back
                -- at 1.0. Reset at EVERY exit, chained or final.
                if S.phold.speed then
                    pcall(function()
                        local mo9 = player:call("get_Motion")
                        mo9:call("getLayer", 0):call("set_Speed", 1.0)
                        mo9:call("getLayer", 1):call("set_Speed", 1.0)
                    end)
                end
                S.phold = S.phold.next   -- chained clip: keep the freeze, play the follow-up
            else
                if S.phold.speed then
                    pcall(function()
                        local mo9 = player:call("get_Motion")
                        mo9:call("getLayer", 0):call("set_Speed", 1.0)
                        mo9:call("getLayer", 1):call("set_Speed", 1.0)
                    end)
                end
                if S.phold.cancel then
                    pcall(function()
                        local P9 = rawget(_G, "IrisPrompt")
                        if P9 and P9.clear_slot then
                            P9.clear_slot("iris_sense")
                        end
                    end)
                end
                -- only hand the body back if we actually took it (upper-body never seized it)
                if not S.phold.upper then
                    set_think_stop(player, false)
                    set_player_fsm(pgo, true)
                end
                S.phold = nil
            end
        end

        -- post-tame peace: the ally switch lands async -- until it does, the old brain
        -- stays muzzled (it bit a pawn in the gap once)
        if S.posttame then
            if now < (tonumber(S.posttame.at) or 0.0) then
                pcall(function()
                    full_pacify(S.posttame.ch)
                    _G.IrisTamingRitualUntil = now + 0.5
                    _G.IrisTamingTargetAddr = S.posttame.ch:get_address()
                    -- keep the FRIEND SHIELD leased through the settle: the ally-switch lands async,
                    -- and in the gap the fresh companion's waking AI can wind up a threat at a pawn
                    -- (field report: "looked like it was about to attack"). Friend-classified both
                    -- ways, nobody -- including IT -- picks a fight until the stable owns it.
                    local ptgo = char_go(S.posttame.ch)
                    _G.IrisTamingHoldWolf = {
                        addr = ptgo and ptgo:get_address(),
                        ch_addr = S.posttame.ch:get_address(),
                        until_t = now + 0.5,
                    }
                end)
            else
                _G.IrisTamingTargetAddr = nil
                S.posttame = nil
            end
        end

        -- THE PACT HOWL, in three breaths. The body is still think-stopped with its FSM off here
        -- (the clip-visibility recipe), so nothing else is touching layer 0 - the seal is the last
        -- thing this creature does as a wild animal.
        if S.seal_howl and not char_go(S.seal_howl.ch) then
            S.seal_howl = nil   -- the body went away mid-seal; do_handover's early return would
                                -- otherwise leave this machine talking to a dead handle forever
        end
        if S.seal_howl then
            -- ⛔ THE SEAL MUST KEEP THE BODY (review round 3). The trials path runs
            -- release_creature the instant try_finish returns - which restores the creature's
            -- motion FSM, its brain and its nav, and drops immunity. So the comment that used to
            -- sit here ("still think-stopped, nothing else is touching layer 0") was simply wrong
            -- for the path that actually runs, and 4611/4612 would have been stomped by the body's
            -- own FSM exactly the way the single 4610 was. Hold it ourselves for the few seconds
            -- the howl needs, and keep the shield lease fresh so nothing swings at it mid-pact;
            -- do_handover does the real, careful hand-back the moment the chain ends.
            pcall(function()
                local sgo = char_go(S.seal_howl.ch)
                if sgo then
                    set_think_stop(S.seal_howl.ch, true)
                    set_player_fsm(sgo, false)
                    set_immunity(S.seal_howl.ch, true)
                    _G.IrisTamingHoldWolf = { addr = sgo:get_address(),
                        ch_addr = S.seal_howl.ch:get_address(), until_t = os.clock() + 0.5 }
                end
            end)
            local H9 = S.seal_howl
            if H9.stage == "end" and now >= (tonumber(H9.end_at) or 0.0)
                + (tonumber(C.seal_howl_end_secs) or 1.8) + 1.0 then
                S.seal_howl = nil   -- self-retire: the handover normally clears this first
            elseif H9.stage == "start" and now >= (tonumber(H9.loop_at) or 0.0) then
                H9.stage = "loop"
                pcall(function() play_motion(H9.ch, 0, tonumber(C.cue_howl_loop) or 4611) end)
            elseif H9.stage == "loop" and now >= (tonumber(H9.end_at) or 0.0) then
                H9.stage = "end"
                pcall(function() play_motion(H9.ch, 0, tonumber(C.cue_howl_end) or 4612) end)
            end
        end
        -- phase 2 of a settling pact
        if S.finish_pending and now >= (tonumber(S.finish_pending.at) or 0.0) then
            local fpd = S.finish_pending
            S.finish_pending = nil
            do_handover(fpd.ch, fpd.why)
        end
        if S.finish_commit and now >= (tonumber(S.finish_commit.at) or 0.0) then
            local fcd = S.finish_commit
            S.finish_commit = nil
            do_commit(fcd.ch, fcd.why)
        end

        -- player movement speed (for the approach pressure)
        if IPPS then IPPS("input_perch") end
        local pspeed = 0.0
        if S.player_prev_pos and pp then pspeed = dist(pp, S.player_prev_pos) / dt end
        -- FACE HOLD: re-assert the release facing for a beat (until you move) so waking the FSM
        -- can't spin the character 180 to the camera when you let go of the hand
        -- 08-08 r3 (Aurora: "when you let go it tries to rotate you
        -- back... keeps rotating left and right"): DURING a trial the
        -- stages own facing, and a lingering hold FIGHTS them = the
        -- oscillation. In-trial, a hold may only mask the release snap
        -- for 0.35s, then it dies.
        if S.face_hold and S.trial then
            local left = (tonumber(S.face_hold.until_t) or 0.0) - now
            if left > 0.35 then S.face_hold.until_t = now + 0.35 end
        end
        if S.face_hold then
            if now < (tonumber(S.face_hold.until_t) or 0.0) and pspeed < 0.8 then
                pcall(function()
                    local q = ValueType.new(sdk.find_type_definition("via.Quaternion"))
                    q.x = S.face_hold.x; q.y = S.face_hold.y; q.z = S.face_hold.z; q.w = S.face_hold.w
                    pgo:call("get_Transform"):call("set_Rotation", q)
                end)
            else
                S.face_hold = nil
            end
        end
        pcall(function()
            -- published speed: TB's dash-vs-hand discriminator (pad B is also sprint)
            if S.player_prev_pos then S.player_spd = dist(pp, S.player_prev_pos) / math.max(0.016, dt) end
        end)
        S.player_prev_pos = pp

        -- tame key edge (08-12 slice A: keyboard N OR pad B -- one button, every rite)
        local down = TB.held()
        local pressed = down and not S.btn_prev
        S.btn_prev = down
        -- IrisHorseRodeo owns N while an aimed horse (or an active horse
        -- rite) is claimed.  Previously this module kept a cached rabbit,
        -- wolf or deer target and armed it from the same held key.
        local horse_claim_addr = tonumber(rawget(
            _G, "__iris_horse_taming_claim_addr"))

        -- ===== tamed companions upkeep (v1: pacified + warp-follow) =====
        -- RE-ADOPT across script resets: the local roster is runtime-only, but the STABLE's active
        -- companion survives -- a stable critter without a record here would lose its L3 shoulder
        -- forever, and a reset mid-perch leaves its motion FSM dark (the skating statue). Found
        -- one -> rebuild the record + hand the body back whole, once.
        if now >= (tonumber(S.stable_scan_at) or 0.0) then
            S.stable_scan_at = now + 2.0
            pcall(function()
                local b = _G.IrisGriffinBridge
                local ach = b and b.griffin and b.griffin()
                -- IDENTITY BY ADDRESS: userdata wrappers differ per call for the SAME body (the
                -- address-compare law) -- a plain table-key check re-adopted the perched crow as
                -- a stranger every 2s, detached it as "welded" and set a duplicate follow on it
                -- (the head-crow that floated away while walking)
                local known = ach == nil
                if ach then
                    local aaddr = nil
                    pcall(function() aaddr = ach:get_address() end)
                    if S.tamed[ach] then known = true end
                    if not known and aaddr then
                        for kch in pairs(S.tamed) do
                            pcall(function() if kch:get_address() == aaddr then known = true end end)
                        end
                    end
                end
                if ach and not known then
                    local ago = char_go(ach)
                    local anm = ago and go_name(ago) or ""
                    if name_in_csv(anm, C.critter_bands) then
                        -- local pet again (our follow, our shoulder). Its NAME lives in the stable
                        -- record, not the GameObject -- storing anm here floated "ch299400_A_00"
                        -- over Batty's head; stable_active makes the nameplate read the record live
                        S.tamed[ach] = { follow = true, stable_active = true }
                        set_think_stop(ach, false)
                        pcall(function() set_player_fsm(ago, true) end)
                        pcall(function() ach:call("setCharacterControllerEnable", true) end)
                        set_ground_glue(ago, true)
                        -- ⛔ 08-13: was a hard-coded 1.0 -- the SAME defect as the set-down write
                        -- (:14939). A re-adopt that "restores" 1.0 discards the size gene and the
                        -- easer then has to crawl the body back at 2%/frame. Ask the bridge, which
                        -- is now gene-aware, and only write if it answers.
                        pcall(function()
                            local bsr = nil
                            pcall(function()
                                local br = _G.IrisGriffinBridge
                                if br and br.body_scale then bsr = tonumber(br.body_scale()) end
                            end)
                            if bsr and bsr > 0.05 and bsr <= 3.0 then
                                ago:call("get_Transform"):call("set_LocalScale", Vector3f.new(bsr, bsr, bsr))
                            end
                        end)
                        pcall(function() ach:call("resetActionAndAI") end)
                        pcall(function() if b.companion_hold then b.companion_hold(true) end end)   -- the driver has no critter gaits
                        pcall(function()   -- welded to the player from before the orig-restore fix? best-effort free
                            local ctf9 = ago:call("get_Transform")
                            local par9 = ctf9:call("get_Parent")
                            local ptf9 = pgo:call("get_Transform")
                            if par9 and ptf9 and par9:get_address() == ptf9:get_address() then
                                pcall(function() ctf9:call("set_ParentJoint", "") end)
                                pcall(function() ctf9:call("setParent", nil, true) end)
                                pcall(function() ctf9:call("set_Parent", nil) end)
                                log.info("[IrisTaming] re-adopt: body was WELDED to the player -> detach attempted")
                            end
                        end)
                        pcall(function() log.info("[IrisTaming] stable critter re-adopted (L3 shoulder restored): " .. anm) end)
                    end
                end
            end)
        end
        -- L3 (the mount button family) shoulders a tamed critter / sets it down again
        -- L3 on the pad, and ⭐ 08-18 a KEYBOARD equivalent too ('G' by default). DD2 binds
        -- nothing to a stick click on keyboard, so unlike Ping/Soar/Collect there is no native
        -- key to mirror -- this is a new bind, which is exactly why the drawn prompt shows it.
        local perch_dn = (gp_mask() & math.floor(tonumber(C.perch_button_bit) or 0x1000)) ~= 0
            or iris_kb(math.floor(tonumber(C.perch_key) or 0x47))
        local perch_edge = perch_dn and not S.perch_btn_prev
        S.perch_btn_prev = perch_dn
        -- a shoulder transition that lost its body (record gone mid-arc) must never jam L3 --
        -- and the body it strands must come back WHOLE (controller re-enabled, puppet resumed)
        if S.perch_trans and now - (tonumber(S.perch_trans.t0) or 0.0) > 3.0 then
            pcall(function()
                local ch0 = S.perch_trans.ch
                local go0 = ch0 and char_go(ch0)
                local rec0 = ch0 and S.tamed[ch0]
                if go0 then
                    iris_body_solid(ch0, go0, true)
                    set_ground_glue(go0, true)
                    -- WHOLE means whole (08-05): the old recovery left the strand think-stopped,
                    -- FSM-off and perch-scaled -- a frozen floater. Restore everything.
                    set_think_stop(ch0, false)
                    pcall(function() set_player_fsm(go0, true) end)
                    pcall(function() ch0:call("resetActionAndAI") end)
                    pcall(function()
                        local bs0 = 1.0
                        pcall(function() local b = _G.IrisGriffinBridge; if b and b.body_scale then bs0 = tonumber(b.body_scale()) or 1.0 end end)
                        go0:call("get_Transform"):call("set_LocalScale", Vector3f.new(bs0, bs0, bs0))
                    end)
                    pcall(function()
                        local cu0 = upos(go0)
                        local hit0 = cu0 and ground_probe(cu0.x, cu0.y + 1.0, cu0.z)
                        if cu0 and hit0 and tonumber(hit0.y) and math.abs(cu0.y - tonumber(hit0.y)) > 0.05 then
                            local pv0 = ValueType.new(sdk.find_type_definition("via.Position"))
                            pv0.x = cu0.x; pv0.y = tonumber(hit0.y) + 0.02; pv0.z = cu0.z
                            set_upos(go0, pv0)
                        end
                    end)
                    pcall(function() log.info("[IrisTaming] shoulder transition TIMED OUT -- body restored whole") end)
                end
                if rec0 then rec0.follow = true; rec0.perch = nil; rec0.perch_ground_scale = nil end
                rawset(_G, "IrisTamingPerchScaleHold", nil)
            end)
            S.perch_trans = nil
        end

        -- PET GRAB v2 (the passive unfreeze window alone didn't take -- Aurora 07-15: a
        -- FRIENDLY-faction body fails native TARGET-SELECTION even unfrozen, the child-carry
        -- lesson) -- on the grab key near a ground pet, release the puppet and call the
        -- player's carry API DIRECTLY (llm_freetalk's proven small-animal recipe)
        -- ⛔ THE MISSING SETTER for the rabbit native-catch SKIP (08-08).
        -- The consumer lives in install_trycatch_hook (~line 2044) and its comment states
        -- the intent exactly: "native catch on a woken standing critter flings the player,
        -- so rabbits skip it and use startBridalCarry instead". That guard was being READ
        -- and never WRITTEN, so the skip never happened and the rabbit kept walking into
        -- the native catch -- which is the launch.
        --
        -- Aurora's pointer to the combat tame is what named the mechanism: there the
        -- creature is PRONE + think-stopped when you press grab, and the native catch
        -- resolves cleanly. The pet path WAKES the body first (think-stop off, FSM on,
        -- controller on) and then grabs a live, standing critter -- the one body state
        -- that flings you.
        --
        -- PROXIMITY-armed, not edge-armed: the PRE-hook has to see the guard already live
        -- on the press frame. Scoped to GROUND CRITTERS only (species_clips().ground =
        -- rabbit/rat), so the ch223 WOLF path is untouched -- it deliberately WANTS the
        -- native catch to run (r3, Aurora's un-freeze recipe).
        pcall(function()
            if not pp then return end
            for ch2, rec2 in pairs(S.tamed) do
                if rec2.follow or rec2.carried or rec2.carried_script then
                    local g2 = char_go(ch2)
                    if g2 and (species_clips(g2) or {}).ground then
                        local cp2 = upos(g2)
                        if cp2 and dist(cp2, pp) <= (tonumber(C.grab_range) or 2.5) then
                            S.critter_catch_skip = now + 0.3   -- ⛔ NOT wolf_grab_guard: see the hook
                            break
                        end
                    end
                end
            end
            -- Do not arm critter_catch_skip for ch223. A tamed wolf uses the same
            -- native requestTryCatch route as a wild wolf; suppressing that request
            -- was the stale transform-pin experiment that made pickup impossible.
        end)
        local pg_dn9 = grab_button_down()
        local pg_edge9 = pg_dn9 and not S.pet_grab_prev
        S.pet_grab_prev = pg_dn9
        -- 08-08 PICKUP DIAG (Aurora: "still can't pick the wolf up"): on
        -- the grab edge, log why we bail, so the next press names it.
        if pg_edge9 then
            local why9 = (not player and "no player")
                or (S.perch_trans and "perch transition busy")
                or (S.scout and "scout active")
                or (S.pet_carry_try and "pet_carry_try still set (prior attempt stuck)")
                or "proceeding"
            pcall(function() log.info("[IrisTaming] pet-grab edge: " .. why9) end)
            -- open the pickup forensics window on EVERY grab edge (see below): 3s of
            -- action + altitude trace, and arm the climb tracer for the same window
            S.pickup_diag_until = now + 3.0
            S.pickup_diag_t0 = now
            S.pickup_diag_last = nil
            S.pickup_diag_y = pp and tonumber(pp.y) or nil
        end
        if pg_edge9 and player and not S.perch_trans and not S.scout and not S.pet_carry_try then
            pcall(function()
                local relch9 = nil
                for ch2, rec2 in pairs(S.tamed) do
                    if rec2.carried_script then relch9 = ch2; break end
                end
                if relch9 and S.tamed[relch9].carry_native then
                    -- SCHEDULE the end, don't run it: the same RT press reaches the NATIVE
                    -- carry input, and unlocking the keep while the button is down let its
                    -- CarryCancel stomp our BridalCarryEnd 34ms in (the log named it) = the
                    -- wall-shove. The keep stays LOCKED until the button has been up a beat.
                    S.tamed[relch9].carry_end_at = now + 0.35
                    S.grab_edge_used = now   -- this press is OURS (see the wolf-block edge gate)
                    return
                end
                if relch9 then
                    -- SECOND press (scripted pin) = set it down at your feet, whole
                    local rec9 = S.tamed[relch9]
                    local g9 = char_go(relch9)
                    rec9.carried_script = nil
                    if g9 then
                        -- place BEFORE re-solidifying, in front + on the floor (same fix as
                        -- the native set-down: a fixed pp+0.6/+0.6 at the player's y drops it
                        -- under her boots, and she ends up standing on / climbing it)
                        pcall(function()
                            local set_d9 = tonumber(C.carry_setdown_dist) or 1.4
                            local fx9, fz9 = 0.0, 1.0
                            pcall(function()
                                local prot9 = pgo:call("get_Transform"):call("get_Rotation")
                                fx9 = 2.0 * (prot9.x * prot9.z + prot9.w * prot9.y)
                                fz9 = 1.0 - 2.0 * (prot9.x * prot9.x + prot9.y * prot9.y)
                                local fl9 = math.sqrt(fx9 * fx9 + fz9 * fz9)
                                if fl9 > 0.01 then fx9 = fx9 / fl9; fz9 = fz9 / fl9 else fx9, fz9 = 0.0, 1.0 end
                            end)
                            local tx9 = pp.x + fx9 * set_d9
                            local tz9 = pp.z + fz9 * set_d9
                            local ty9 = pp.y
                            local hit9 = ground_probe(tx9, pp.y + 1.0, tz9)
                            if hit9 and tonumber(hit9.y) then ty9 = tonumber(hit9.y) + 0.02 end
                            local pv9 = ValueType.new(sdk.find_type_definition("via.Position"))
                            pv9.x = tx9; pv9.y = ty9; pv9.z = tz9
                            set_upos(g9, pv9)
                        end)
                        iris_body_solid(relch9, g9, true)
                        set_ground_glue(g9, true)
                    end
                    S.critter_no_climb = now + 2.0   -- across the settle
                    rec9.follow = true; rec9.fmode = nil
                    S.grab_edge_used = now   -- this press is OURS
                    return
                end
                if catch_active(player) then return end
                local bch9, bgo9, bd9 = nil, nil, 2.0
                for ch2, rec2 in pairs(S.tamed) do
                    if rec2.follow and not rec2.carried then
                        local g2 = char_go(ch2)
                        if g2 and (species_clips(g2) or {}).ground then
                            local cp2 = upos(g2)
                            local d2 = (cp2 and pp) and dist(cp2, pp) or 99.0
                            if d2 < bd9 then bd9 = d2; bch9 = ch2; bgo9 = g2 end
                        end
                    end
                end
                -- (08-08: bridged wolf/cat carry moved to its OWN
                -- self-contained block below -- the native bridal carry
                -- REJECTS a wolf-sized body, so it needs a pin, not this
                -- rabbit-sized native path.)
                if not bch9 then return end
                -- v4: NATIVE SUSTAINED carry first (startCarry = the over-shoulder hold with
                -- CarryWait; walks while holding -- the arms the screenshot was missing).
                -- Release the puppet FIRST (CarrySpike law), then touch NOTHING for ~0.9s:
                -- keeping mid-start interrupts CarryStart and it never establishes
                -- (llm_freetalk's hard-won note -- v2's instant action request did exactly that).
                set_think_stop(bch9, false)
                pcall(function() set_player_fsm(bgo9, true) end)
                pcall(function() bch9:call("setCharacterControllerEnable", true) end)
                pcall(function()
                    local b = _G.IrisGriffinBridge
                    if b and b.companion_hold then b.companion_hold(true) end
                end)
                local hum9, hcp9 = nil, nil
                pcall(function() hum9 = player:call("get_Human") end)
                pcall(function() hcp9 = hum9 and hum9:call("get_CatchProcessor") end)
                if not hcp9 then pcall(function() hcp9 = hum9 and hum9["<CatchProcessor>k__BackingField"] end) end
                local okc9 = false
                if hcp9 then
                    -- BRIDAL first (Aurora: "the cute bridal carry with the upside down
                    -- rabbit") -- the couple-carry precedent runs it SUSTAINED with the keep;
                    -- the over-shoulder startCarry is stage 2 if bridal never binds
                    for _, f9 in ipairs({
                        function() hcp9:call("startBridalCarry(app.Character)", bch9) end,
                        function() hcp9:call("startBridalCarry", bch9) end,
                    }) do if pcall(f9) then okc9 = true; break end end
                end
                S.grab_edge_used = now   -- this press is OURS (claim stamp: any later block in
                                         -- the same tick must not also act on it -- the 08-08
                                         -- start-and-throw-in-one-frame bug)
                S.pet_carry_try = { ch = bch9, t0 = now, api = okc9, stage = 1 }
            end)
        end
        -- ============================================================================
        -- WOLF / CAT PICKUP -- NATIVE CARRY (08-08 rebuild #2).
        --
        -- Aurora's evidence ended the argument: she can carry a WILD wolf right now,
        -- perfectly -- full fur, tail and ragdoll, same ch223 chassis -- and the combat
        -- tame carries one too. So the engine has no problem with this body. Every
        -- explanation that blamed the CREATURE (size, secondary motion, ragdoll) was
        -- wrong. The only case that fails is OUR pet wolf, and the only thing that
        -- makes it special is that we interfere with it.
        --
        -- ⛔ WHAT WE WERE DOING TO OURSELVES: the pet path set S.critter_catch_skip,
        -- which SKIPS app.Human.requestTryCatch -- the native grab itself. So the pet
        -- wolf was never allowed to be picked up the way the wild one is; we blocked
        -- the working path and substituted a transform pin, and the pin is what
        -- thrashes (root DRIFT measured 0.000m, so the pin held perfectly and the mesh
        -- tore itself apart around it -- a body dragged by transform instead of being
        -- carried by the engine).
        --
        -- SO: no skip, no pin, no transform writes. Do the minimum a COMPANION needs
        -- that a wild wolf does not, and let the game carry it:
        --   1. un-freeze the body -- the bridge think-stops companions, and a frozen
        --      body fails the native grab's eligibility check (dd2-native-grab-catch);
        --   2. hold the griffin mod's drivers down while it is being carried, so
        --      nothing yanks the body out of the engine's hands mid-carry.
        -- If it still refuses to bind, the state dump below says exactly which field
        -- differs from the wild wolf that works.
        pcall(function()
            if not pp then return end
            local b9 = _G.IrisGriffinBridge
            local g9 = b9 and b9.griffin and b9.griffin()
            local go9 = g9 and char_go(g9)
            -- pet tier only: a wyrm-grown wolf is a MOUNT, not something you carry
            local is_wolf9 = go9 and tostring(go_name(go9) or ""):find("ch223", 1, true)
                and not (b9.active_wyrm_grown and b9.active_wyrm_grown() == true)
            if not is_wolf9 then return end
            local carried9 = catch_active(player)
            -- Remember ownership at entry. If the vanilla requestTryCatch binds the
            -- wolf on this very grab edge, it is a pickup to adopt, not a set-down.
            local owned_before9 = S.wolf_native_carry == true
            local near9 = false
            pcall(function()
                local cp9 = upos(go9)
                near9 = cp9 and dist(cp9, pp) <= (tonumber(C.grab_range) or 2.5)
            end)
            local wolf_addr9 = nil
            pcall(function() wolf_addr9 = go9:get_address() end)

            -- FIRST-USE NATIVE-CONTROLLER PRIME (trace-driven, 08-10).
            -- On a freshly spawned ch223 the first startCarry makes both catch
            -- controllers active but never starts the victim interpolation. After
            -- one completed carry cycle, the same API moves it into the shoulder
            -- constraint within ~23ms. Automate that otherwise-manual first cycle:
            -- hold the initial bind for three frames, end it natively, wait for the
            -- controller to close, then rebind from the same button press.
            local prime9 = S.wolf_pose_prime
            if prime9 and prime9.addr ~= wolf_addr9 then
                S.wolf_pose_prime = nil
                S.wolf_native_carry = nil
                pcall(function() if b9 and b9.companion_hold then b9.companion_hold(false) end end)
                pcall(function() set_nav_stop(g9, false) end)
                prime9 = nil
            end
            if prime9 then
                if prime9.stage == "hold" then
                    if carried9 then
                        S.wolf_native_carry = true
                        wolf_carry_keep(player, g9)
                        pcall(function() if b9 and b9.companion_hold then b9.companion_hold(true) end end)
                        pcall(function() if b9 and b9.carry_hold then b9.carry_hold(0.5, go9) end end)
                        pcall(function() set_nav_stop(g9, true) end)
                    end
                    if now >= (tonumber(prime9.at) or math.huge) then
                        S.wolf_native_carry = nil
                        S.wolf_pickup_pending_until = nil
                        wolf_native_end(player)
                        prime9.stage = "wait_end"
                        prime9.at = now + 0.05
                        pcall(function() log.info("[IrisTaming] WOLF first-pick prime: warm bind ended") end)
                    end
                    return
                elseif prime9.stage == "wait_end" then
                    if carried9 or now < (tonumber(prime9.at) or math.huge) then return end
                    set_think_stop(g9, false)
                    pcall(function() set_player_fsm(go9, true) end)
                    local tookp9 = "none"
                    pcall(function() tookp9 = try_native_carry(player, g9) or "none" end)
                    if tookp9 ~= "none" and tookp9 ~= "no-hcp" then
                        S.wolf_native_carry = true
                        wolf_carry_keep(player, g9)
                        pcall(function() if b9 and b9.companion_hold then b9.companion_hold(true) end end)
                        pcall(function() if b9 and b9.carry_hold then b9.carry_hold(0.5, go9) end end)
                        pcall(function() set_nav_stop(g9, true) end)
                        S.wolf_pose_primed = S.wolf_pose_primed or {}
                        if wolf_addr9 then S.wolf_pose_primed[wolf_addr9] = true end
                        S.wolf_pose_prime = nil
                        S.wolf_native_verdict_at = now + 0.6
                        pcall(function() log.info("[IrisTaming] WOLF first-pick prime: rebound into initialised caught pose via " .. tostring(tookp9)) end)
                    elseif now < (tonumber(prime9.deadline) or 0.0) then
                        prime9.at = now + 0.05
                    else
                        S.wolf_pose_prime = nil
                        pcall(function() if b9 and b9.companion_hold then b9.companion_hold(false) end end)
                        pcall(function() set_nav_stop(g9, false) end)
                        pcall(function() log.info("[IrisTaming] WOLF first-pick prime: rebind timed out") end)
                    end
                    return
                end
            end

            -- ===== KEEP IT GRABBABLE: un-freeze while you are close enough to grab =====
            -- (the rabbit's PICKUP WINDOW, same reasoning -- think-stop is the documented
            -- grab blocker. Step away and the bridge's follow resumes on its own.)
            if near9 and not carried9 then
                set_think_stop(g9, false)
                pcall(function() set_player_fsm(go9, true) end)
            end

            -- ===== WHILE THE ENGINE CARRIES IT: stand our drivers down, touch nothing =====
            if carried9 and S.wolf_native_carry then
                -- the griffin mod would otherwise keep ground-snapping / re-driving this
                -- body mid-carry. companion_hold parks the order; carry_hold takes the
                -- transform. Both time-boxed, so a dropped carry cannot strand the follower.
                pcall(function() if b9 and b9.companion_hold then b9.companion_hold(true) end end)
                pcall(function() if b9 and b9.carry_hold then b9.carry_hold(0.5, go9) end end)
                -- ⛔ NO pin, NO set_upos, NO set_Rotation, NO think-stop, NO component
                -- disabling. The engine owns the body completely -- exactly as it does for
                -- a wild wolf. Every previous attempt failed by taking some of it back.
                --
                -- THE KEEP -- the combat tame's exact flags (the yielded branch further down
                -- uses these and holds a live wolf indefinitely). A caught LIVE creature
                -- struggles free after ~10s on the escape/gacha timer, and the carry also
                -- falls through to its own end if these are not re-asserted. Every frame.
                wolf_carry_keep(player, g9)
                -- ⛔⛔ STOP IT WALKING OUT OF THE CARRY (08-08 -- the glitch catcher named it).
                -- The catcher fired with tamedFlags=(NOT in S.tamed), perchArmed=false,
                -- pinArmed=false, no griffin claim block, and stillCaught=TRUE: nothing WE own
                -- moved the body, and the engine still believed it was carrying it. 1.94m in a
                -- frame landing 1.70m away is a STRIDE, not a teleport -- the wolf walked off
                -- under its own navigation and the catch yanked it back, which is exactly
                -- "teleports away and glides back", on repeat.
                -- WHY only the companion does this: to let the native grab take an ALLY body we
                -- un-freeze it (think_stop false + FSM live). A wild wolf gets its AI parked in
                -- a caught state; ours keeps a live NavigationAI issuing moves. So park the
                -- navigation for the duration -- every frame, because anything that resets the
                -- companion's orders re-arms it.
                -- ⛔ set_IsStopCalled ONLY. Disabling the NavigationAI component is the
                -- documented crash (MoveBase.updateImpl null-AV under CommandExecutor) -- the
                -- r10 lesson from the old code: "nav-stop reassert, NOT component disable".
                pcall(function() set_nav_stop(g9, true) end)
                pcall(function()
                    local nav7 = comp(go9, "app.NavigationAI")
                    if nav7 then pcall(function() nav7:call("set_IsStopCalled", true) end) end
                end)
                -- ⭐ GLITCH CATCHER (08-08). Aurora: during an otherwise healthy carry the wolf
                -- "suddenly teleports away and glides back to the shoulder position", over and
                -- over. Catch the exact frame it jumps and name every system that could have
                -- done it, instead of me theorising a fourth time. Silent unless it really
                -- jumps (>0.8m in a single frame).
                pcall(function()
                    local cu7 = upos(go9)
                    if not cu7 then return end
                    local pv7 = S.wolf_watch_pos
                    S.wolf_watch_pos = { x = tonumber(cu7.x), y = tonumber(cu7.y), z = tonumber(cu7.z) }
                    if not pv7 then return end
                    local jx7 = S.wolf_watch_pos.x - pv7.x
                    local jy7 = S.wolf_watch_pos.y - pv7.y
                    local jz7 = S.wolf_watch_pos.z - pv7.z
                    local jump7 = math.sqrt(jx7 * jx7 + jy7 * jy7 + jz7 * jz7)
                    if jump7 < 0.8 then return end
                    if now - (tonumber(S.wolf_watch_log_at) or 0.0) < 0.4 then return end
                    S.wolf_watch_log_at = now
                    local rec7 = S.tamed[g9]
                    local flags7 = rec7 and table.concat({
                        rec7.perch and "perch" or "-", rec7.follow and "follow" or "-",
                        rec7.carried and "carried" or "-", rec7.carried_script and "pinned" or "-",
                        rec7.stable_active and "stable" or "-" }, "/") or "(NOT in S.tamed)"
                    local dp7 = dist(cu7, pp) or -1
                    pcall(function()
                        log.info(string.format(
                            "[IrisTaming] ⚠ WOLF JUMPED %.2fm in ONE frame -- distFromPlayer=%.2f tamedFlags=[%s] perchArmed=%s pinArmed=%s stillCaught=%s",
                            jump7, dp7, flags7,
                            tostring(S.perch_active ~= nil), tostring(S.wolf_pin_active ~= nil),
                            tostring(catch_active(player))))
                    end)
                end)
            elseif S.wolf_native_carry and not carried9 then
                -- carry ended (native set-down, escape, or it was never bound): hand the
                -- body back to the follow driver
                S.wolf_native_carry = nil
                S.wolf_pickup_pending_until = nil
                S.wolf_native_verdict_at = nil
                S.wolf_watch_pos = nil
                -- the carry ended some other way (escape, despawn, reload): release the nav
                -- park too, or the wolf is left standing rooted to the spot
                pcall(function() set_nav_stop(g9, false) end)
                pcall(function()
                    local nav7 = comp(go9, "app.NavigationAI")
                    if nav7 then pcall(function() nav7:call("set_IsStopCalled", false) end) end
                end)
                pcall(function() if b9 and b9.companion_hold then b9.companion_hold(false) end end)
                pcall(function() g9:call("resetActionAndAI") end)
                pcall(function() log.info("[IrisTaming] wolf native carry: ended -- follow + nav restored") end)
            end

            -- ===== THE GRAB EDGE: get out of the way, then report what happened =====
            if pg_edge9 and not S.perch_trans and carried9 and owned_before9 then
                -- ===== SET DOWN: unlock the keep and let the engine run its own end =====
                -- The keep above is what stops it wriggling free, so it must come OFF first
                -- or the release fights it. No admin kill, no forced action, no placement --
                -- the native carry has a real set-down; let it play.
                S.wolf_native_carry = nil
                -- A native release remains active for another frame or two. Without
                -- clearing/fencing this, that tail was being re-adopted as a fresh
                -- pickup roughly 50ms after set-down.
                S.wolf_pickup_pending_until = nil
                S.wolf_native_verdict_at = nil
                S.grab_edge_used = now
                pcall(function()
                    local cc9 = player:call("get_CatchController")
                    if not cc9 then return end
                    pcall(function() cc9:call("set_IsContinue(System.Boolean)", false) end)
                    pcall(function() cc9:call("set_IsRejectAbortOnDefault(System.Boolean)", false) end)
                    pcall(function() cc9:call("set_IsDisableEscape(System.Boolean)", false) end)
                    local ca9 = cc9:get_field("CaughtCtrl")
                    if ca9 then
                        pcall(function() ca9:call("set_IsContinue(System.Boolean)", false) end)
                        pcall(function() ca9:call("set_IsRejectAbortOnDefault(System.Boolean)", false) end)
                        pcall(function() ca9:set_field("IsDisableEscapeInternal", false) end)
                        pcall(function() ca9:set_field("IsTempDisableEscape", false) end)
                    end
                end)
                pcall(function()
                    local hum9 = player:call("get_Human")
                    local hcp9 = hum9 and hum9:call("get_CatchProcessor")
                    if not hcp9 then hcp9 = hum9 and hum9["<CatchProcessor>k__BackingField"] end
                    if hcp9 then
                        -- ⛔ endCarry / requestEndCarry ONLY. NEVER throwCatch -- that is a
                        -- throw, and it is what launched the player on the rabbit path.
                        for _, f9 in ipairs({
                            function() hcp9:call("endCarry") end,
                            function() hcp9:call("requestEndCarry") end,
                        }) do if pcall(f9) then break end end
                    end
                end)
                -- give the wolf its legs back -- the carry parked its navigation, and a pet
                -- that cannot path is worse than one that wriggles
                pcall(function() set_nav_stop(g9, false) end)
                pcall(function()
                    local nav7 = comp(go9, "app.NavigationAI")
                    if nav7 then pcall(function() nav7:call("set_IsStopCalled", false) end) end
                end)
                pcall(function() if b9 and b9.companion_hold then b9.companion_hold(false) end end)
                pcall(function() log.info("[IrisTaming] WOLF: set-down requested (keep unlocked, nav released)") end)
            elseif pg_edge9 and near9 and not S.perch_trans then
                if not carried9 then
                    -- Marks this edge as a PICKUP transaction. A native bind may
                    -- appear one frame after requestTryCatch, so adoption needs a
                    -- short window; an ending carry must never qualify.
                    S.wolf_pickup_pending_until = now + 0.8
                    -- ⭐ DO NOT set S.critter_catch_skip here. That is the rabbit's guard and
                    -- it blocks the very grab we want. The wolf WANTS the native catch.
                    set_think_stop(g9, false)
                    pcall(function() set_player_fsm(go9, true) end)
                    pcall(function() strip_hate(g9) end)
                    -- STATE DUMP: the A/B that answers "why does the wild one work". Grab a
                    -- wild wolf, then the pet wolf, and diff these two lines.
                    pcall(function()
                        local vct9, rej9, rejt9, kind9, thk9 = "?", "?", "?", "?", "?"
                        pcall(function() vct9 = tostring(g9:call("get_ValidCaughtTypes")) end)
                        pcall(function() rej9 = tostring(g9:call("isRejectCaughtBecauseOfOwnStatus")) end)
                        pcall(function() rejt9 = tostring(g9:call("isRejectCaughtBecauseOfOwnStatusWithoutTempStatus")) end)
                        pcall(function() thk9 = tostring(g9:call("get_IsThinkStop")) end)
                        pcall(function()
                            local ctx9 = g9:get_field("<Context>k__BackingField") or g9:call("get_Context")
                            if ctx9 then kind9 = tostring(ctx9:get_field("CharacterKind")) end
                        end)
                        log.info(string.format(
                            "[IrisTaming] WOLF GRAB (companion) validCaught=%s reject=%s rejectNoTemp=%s kind=%s thinkStop=%s",
                            vct9, rej9, rejt9, kind9, thk9))
                    end)
                    -- ⭐ CALL THE CARRY DIRECTLY (08-08 -- the dump proved why R does nothing).
                    -- validCaught=52 and reject=false: the body says it CAN be caught and does
                    -- not refuse. The only difference from the wild wolf that works is kind=2
                    -- (ally) vs kind=8 (wild) -- and an ally is never OFFERED by the native
                    -- grab's target selection. Same wall the rabbit hit ("a FRIENDLY-faction
                    -- body fails native TARGET-SELECTION even unfrozen -- the child-carry
                    -- lesson"), same cure: skip target selection and call the API on the body.
                    -- This is still the ENGINE carrying it -- real carry animation on both
                    -- sides, no pin, no transform writes. try_native_carry puts startCarry
                    -- (the over-shoulder carry vanilla uses on a wolf) FIRST, then bridal,
                    -- then smallAnimal, and stops at the first one that binds.
                    -- ⭐ ONE-SHOT API DUMP (08-08): startCarry binds but gives the WRONG POSE --
                    -- held overhead like an object, where the wild wolf grab drapes it across
                    -- her. ValidCaughtTypes=52 is a BITMASK (bits 2/4/5), so this body accepts
                    -- THREE catch types and startCarry is just picking type 2. We need the call
                    -- that lets us NAME the type. Dump the whole catch API once so we can see
                    -- what is actually available instead of guessing method names.
                    if not _G.IrisCatchApiDumped then
                        _G.IrisCatchApiDumped = true
                        pcall(function()
                            local out = { valid_caught_types = 52, methods = {} }
                            for _, tn in ipairs({ "app.HumanCatchProcessor", "app.CatchController", "app.CaughtController" }) do
                                local td = sdk.find_type_definition(tn)
                                if td then
                                    -- ⚠ get_params() is NOT the REFramework API and threw
                                    -- inside the pcall, which is why no file ever appeared.
                                    -- Method NAMES alone are enough to spot a call that takes
                                    -- an explicit catch type.
                                    local list = {}
                                    for _, m in ipairs(td:get_methods() or {}) do
                                        pcall(function() list[#list + 1] = tostring(m:get_name()) end)
                                    end
                                    table.sort(list)
                                    out.methods[tn] = list
                                end
                            end
                            json.dump_file(MOD .. "_catch_api.json", out)
                            log.info("[IrisTaming] catch API dumped -> " .. MOD .. "_catch_api.json")
                        end)
                    end
                    local took9 = "none"
                    pcall(function() took9 = try_native_carry(player, g9) or "none" end)
                    S.grab_edge_used = now
                    -- ⛔⛔ ARM THE KEEP THE INSTANT IT BINDS, NOT AT THE VERDICT (08-08).
                    -- try_native_carry only returns an API name when catch_active() has gone
                    -- TRUE, so "carry" means the engine really took the body. The log then
                    -- showed it gone 600ms later -- because the keep was gated on
                    -- S.wolf_native_carry, which was only set by the verdict 0.6s afterwards.
                    -- So the carry ran completely UNPROTECTED through the exact window where
                    -- CarryStart falls through to CarryCancel, and the keep never once ran.
                    -- The cancel is also the knockback ("it tries to pick her up then gets
                    -- knocked back"). Set the flag here so the keep arms on the very next frame.
                    if took9 ~= "none" and took9 ~= "no-hcp" then
                        S.wolf_native_carry = true
                        wolf_carry_keep(player, g9)   -- SAME FRAME as the bind, not next tick
                        -- First-pick pose repair. On a newly spawned companion the
                        -- follow/navigation owner is still live on the bind frame and
                        -- can repaint locomotion over the victim-side caught action.
                        -- Park every competing owner immediately, not one frame later
                        -- in ordinary carry upkeep.
                        pcall(function() if b9 and b9.companion_hold then b9.companion_hold(true) end end)
                        pcall(function() if b9 and b9.carry_hold then b9.carry_hold(0.5, go9) end end)
                        pcall(function() set_nav_stop(g9, true) end)
                        pcall(function()
                            local nav9 = comp(go9, "app.NavigationAI")
                            if nav9 then nav9:call("set_IsStopCalled", true) end
                        end)
                        S.wolf_pickup_pending_until = nil
                        if wolf_addr9 and not ((S.wolf_pose_primed or {})[wolf_addr9]) then
                            S.wolf_pose_prime = {
                                addr = wolf_addr9, stage = "hold",
                                at = now + 0.06, deadline = now + 1.2,
                            }
                            pcall(function() log.info("[IrisTaming] WOLF first-pick prime: warm bind started") end)
                        end
                    end
                    pcall(function() log.info("[IrisTaming] WOLF GRAB: try_native_carry -> " .. tostring(took9)) end)
                    -- verdict a beat later: did the ENGINE take it? The first-use
                    -- prime owns its own verdict after the internal rebind.
                    if not S.wolf_pose_prime then
                        S.wolf_native_verdict_at = now + 0.6
                    else
                        S.wolf_native_verdict_at = nil
                    end
                end
            end
            -- CharacterKind 8 lets the normal target selector bind the companion just
            -- like a wild wolf. Adopt that native bind immediately so the companion
            -- drivers stand down and the live-creature abort flags are held from this
            -- frame onward. The direct carry call above remains the fallback when the
            -- normal selector has not taken the body.
            if carried9 and near9 and not owned_before9 and not S.wolf_native_carry
                and (tonumber(S.wolf_pickup_pending_until) or 0.0) > now then
                S.wolf_native_carry = true
                S.wolf_pickup_pending_until = nil
                wolf_carry_keep(player, g9)
                pcall(function() if b9 and b9.companion_hold then b9.companion_hold(true) end end)
                pcall(function() if b9 and b9.carry_hold then b9.carry_hold(0.5, go9) end end)
                pcall(function() set_nav_stop(g9, true) end)
                S.grab_edge_used = now
                pcall(function() log.info("[IrisTaming] WOLF GRAB: adopted native requestTryCatch bind") end)
            end
            if S.wolf_native_verdict_at and now >= S.wolf_native_verdict_at then
                S.wolf_native_verdict_at = nil
                local took9 = catch_active(player)
                if took9 then S.wolf_native_carry = true end
                pcall(function() log.info("[IrisTaming] WOLF GRAB verdict: native catch "
                    .. (took9 and "BOUND -- engine owns the body" or "REFUSED -- compare the dump above with a WILD wolf's")) end)
            end
        end)
        -- deferred solidity restore (a body re-solidified inside the player's capsule = a shove)
        -- ⛔ RESTORE SOLIDITY ONLY WHEN THE PLAYER IS CLEAR (08-08, trace-driven).
        -- This used to be a blind 0.6s timer, and the trace showed exactly why that fails:
        -- the +0.46m single-tick pops after a set-down all land AFTER the timer expires --
        -- the body goes solid while she is still standing on top of it, and a ~0.5m step
        -- (about rabbit height) shoves her up. Same family as the bassinet auto-step
        -- (dd2-climb-suppression): you cannot undo the mount, you have to prevent it.
        -- So gate on DISTANCE, not time: stay ghosted until she is a clear body-width away.
        -- Timeout is a backstop only -- if she just stands on it forever, solidity has to
        -- come back eventually or the pet is permanently walk-through.
        if S.solid_restore then
            local sr = S.solid_restore
            local clear = false
            pcall(function()
                local bu = sr.go and upos(sr.go)
                if bu and pp then
                    local ddx = tonumber(bu.x) - pp.x
                    local ddz = tonumber(bu.z) - pp.z
                    clear = math.sqrt(ddx * ddx + ddz * ddz) >= (tonumber(C.carry_setdown_clear) or 1.1)
                end
            end)
            local timed_out = now >= (tonumber(sr.deadline) or (tonumber(sr.at) or 0.0) + 5.0)
            if (clear and now >= (tonumber(sr.at) or 0.0)) or timed_out then
                pcall(function() iris_body_solid(sr.ch, sr.go, true) end)
                if timed_out and not clear then
                    pcall(function() log.info("[IrisTaming] set-down: solidity restored on TIMEOUT (player still on top of it)") end)
                end
                S.solid_restore = nil
            end
        end
        -- set-down forensics: log every player action change in the window (the "hit" anim
        -- names itself -- Dmg* = the catch aborted; *CarryEnd = the end ran but looks rough)
        if S.carry_diag_until and now < S.carry_diag_until then
            pcall(function()
                local am9 = nil
                pcall(function() am9 = player["<ActionManager>k__BackingField"] end)
                if not am9 then pcall(function() am9 = player:call("get_ActionManager") end) end
                if not am9 then return end
                local l09, l19 = "-", "-"
                pcall(function() local it9 = am9.CurrentActionList[0]; l09 = tostring(it9.Name or it9:call("get_Name")) end)
                pcall(function() local it9 = am9.CurrentActionList[1]; l19 = tostring(it9.Name or it9:call("get_Name")) end)
                local line9 = "L0:" .. l09 .. "  L1:" .. l19
                if S.carry_diag_last ~= line9 then
                    S.carry_diag_last = line9
                    pcall(function() log.info("[IrisTaming] set-down action " .. line9) end)
                end
            end)
        elseif S.carry_diag_until then
            S.carry_diag_until = nil; S.carry_diag_last = nil
        end
        -- ===== PICKUP FORENSICS (08-08 R&D -- Aurora: "picking up the rabbit still knocks
        -- me up") =====
        -- Two wrong guesses (capsule depenetration, then the double-consumed grab press --
        -- the latter WAS a real bug and is fixed) cost two test rounds, because the ONLY
        -- action log we had opened on SET-DOWN. So we were reading the wrong 2 seconds.
        -- This opens the same forensics on the PICKUP edge and adds the one number that
        -- discriminates every remaining hypothesis: the player's ALTITUDE per tick.
        --   * Y climbs BEFORE "NATIVE hold bound"  -> the grab INPUT did it (climb/vault
        --     path), and the carry is an innocent bystander.
        --   * Y climbs AFTER the bind             -> the carry/collision did it.
        -- Also names any climb entry point that fires in the window (the trace pattern from
        -- dd2-climb-suppression: hook the candidates, let the game say which one it uses --
        -- for the bassinet it turned out to be ClimbWallAction.startClimbing, NOT the
        -- obvious Character.startClimb).
        -- ⛔ RETIRED 08-08 (kept, inert): this trace is what finally cracked the launch --
        -- the altitude column showed the player snapping to rabbit+0.29 with no Climb action,
        -- which is what pointed outside this file to the griffin mod's RT mount. Re-arm by
        -- deleting the `false and` if a positional mystery ever needs the same treatment.
        if false and S.pickup_diag_until and now < S.pickup_diag_until then
            pcall(function()
                local am9 = nil
                pcall(function() am9 = player["<ActionManager>k__BackingField"] end)
                if not am9 then pcall(function() am9 = player:call("get_ActionManager") end) end
                local l09, l19 = "-", "-"
                if am9 then
                    pcall(function() local it9 = am9.CurrentActionList[0]; l09 = tostring(it9.Name or it9:call("get_Name")) end)
                    pcall(function() local it9 = am9.CurrentActionList[1]; l19 = tostring(it9.Name or it9:call("get_Name")) end)
                end
                local py9 = pp and tonumber(pp.y)
                local dy9 = (py9 and tonumber(S.pickup_diag_y)) and (py9 - tonumber(S.pickup_diag_y)) or 0.0
                local line9 = "L0:" .. l09 .. "  L1:" .. l19
                -- log on ACTION CHANGE, or on any real vertical movement (>5cm/tick), so a
                -- silent launch inside one action still shows up
                -- the CRITTER's altitude too (08-08): +1.4m in one 25ms tick is a position
                -- write, not physics. If both bodies rise together, it is the feedback loop
                -- (player attached to the critter while the carry pins the critter to the
                -- player); if only the player rises, the critter is innocent.
                local ry9, rgap9 = nil, nil
                pcall(function()
                    for ch3, rec3 in pairs(S.tamed) do
                        if rec3.carried or rec3.carried_script then
                            local g3 = char_go(ch3)
                            local u3 = g3 and upos(g3)
                            if u3 then ry9 = tonumber(u3.y); if py9 and ry9 then rgap9 = ry9 - py9 end end
                            break
                        end
                    end
                end)
                if S.pickup_diag_last ~= line9 or math.abs(dy9) > 0.05 then
                    S.pickup_diag_last = line9
                    pcall(function()
                        -- glue_dbg carries set_ground_glue's own hit count. Its comment warns
                        -- "0 = the disable silently failed: diagnose" -- and every call here is
                        -- pcall'd, so a failing ghost would be completely invisible otherwise.
                        log.info(string.format("[IrisTaming] PICKUP +%.2fs  y=%.2f  dy=%+.2f  rab=%s gap=%s  [%s]  %s",
                            now - (tonumber(S.pickup_diag_t0) or now), py9 or -1.0, dy9,
                            ry9 and string.format("%.2f", ry9) or "-",
                            rgap9 and string.format("%+.2f", rgap9) or "-",
                            tostring(S.glue_dbg or "glue ?"), line9))
                    end)
                end
                if py9 then S.pickup_diag_y = py9 end
            end)
        elseif S.pickup_diag_until then
            S.pickup_diag_until = nil; S.pickup_diag_last = nil
            S.pickup_diag_y = nil; S.pickup_diag_t0 = nil
            pcall(function() log.info("[IrisTaming] PICKUP window closed") end)
        end
        -- ===== LAUNCH WATCHDOG (08-08) -- always on, near-silent =====
        -- Two holes in the pickup forensics made the last three traces unreadable:
        --   (1) it only logged the CARRIED critter, so the instant the pet was set down the
        --       column went "rab=-" -- blind at exactly the moment the +0.5m pops happen;
        --   (2) it only opened for 3s off a grab press, so a launch at any other time was
        --       invisible, and the ~30m flight in Aurora's first screenshot is nothing like
        --       the 0.5m oscillations the window did catch. We may never have logged the
        --       real event at all.
        -- So: watch the player's altitude EVERY tick, log ONLY on a real jolt, and always
        -- name the NEAREST tamed critter (whatever state it is in) with its distance.
        -- Near-zero spam, catches the event whenever it happens.
        pcall(function()
            if true then return end   -- ⛔ RETIRED 08-08 (kept, inert): the launch is fixed in
                                      -- GriffinRideProbe. This watchdog earned its keep -- it
                                      -- proved the launches happened in FOLLOW state with no
                                      -- carry, which killed three carry-based theories at once.
                                      -- Delete the `if true then return end` to re-arm.
            if not pp then return end
            local py8 = tonumber(pp.y)
            local prev8 = tonumber(S.launch_watch_y)
            S.launch_watch_y = py8
            if not (py8 and prev8) then return end
            local dy8 = py8 - prev8
            if dy8 < (tonumber(C.launch_watch_dy) or 0.35) then return end
            if now - (tonumber(S.launch_watch_at) or 0.0) < 0.15 then return end
            S.launch_watch_at = now
            local nm8, nd8, ny8, st8, nga8 = "-", 99.0, nil, "-", 0
            for ch8, rec8 in pairs(S.tamed) do
                local g8 = char_go(ch8)
                local u8 = g8 and upos(g8)
                if u8 then
                    local ex8 = tonumber(u8.x) - pp.x
                    local ez8 = tonumber(u8.z) - pp.z
                    local ed8 = math.sqrt(ex8 * ex8 + ez8 * ez8)
                    if ed8 < nd8 then
                        nd8 = ed8; ny8 = tonumber(u8.y); nm8 = tostring(go_name(g8) or "?")
                        pcall(function() nga8 = g8:get_address() end)
                        st8 = (rec8.carried and "carried") or (rec8.carried_script and "pinned")
                            or (rec8.perch and "perch") or (rec8.follow and "follow") or "?"
                    end
                end
            end
            local l08 = "-"
            pcall(function()
                local am8 = player and (player["<ActionManager>k__BackingField"] or player:call("get_ActionManager"))
                if am8 then local it8 = am8.CurrentActionList[0]; l08 = tostring(it8.Name or it8:call("get_Name")) end
            end)
            -- ⭐ IS THE BODY UNDER HER THE ONE WE ARE HOLDING? (08-08)
            -- The follow driver stops at 3.0m and set-down places at 1.4m, so NEITHER can
            -- produce the measured d=0.15. That means the body underfoot may not be the pet
            -- we think we're tracking -- and the log has been showing "stable critter
            -- re-adopted: ch299200_A_00" on a timer, which is a second claim on a rabbit.
            -- So count every ch299200 body near her and report the CARRIED one separately
            -- from the NEAREST one. If those two are different addresses, there are two
            -- rabbits and every fix so far has been aimed at the wrong body.
            local nbody8, carr8 = 0, "-"
            pcall(function()
                for ch7, rec7 in pairs(S.tamed) do
                    if rec7.carried or rec7.carried_script then
                        local g7 = char_go(ch7)
                        local u7 = g7 and upos(g7)
                        if u7 then
                            local ex7 = tonumber(u7.x) - pp.x
                            local ez7 = tonumber(u7.z) - pp.z
                            carr8 = string.format("d=%.2f gap=%+.2f @%x", math.sqrt(ex7 * ex7 + ez7 * ez7),
                                tonumber(u7.y) - py8, g7:get_address())
                        end
                    end
                end
                local sm7 = sdk.get_native_singleton("via.SceneManager")
                local smt7 = sdk.find_type_definition("via.SceneManager")
                local sc7 = sm7 and sdk.call_native_func(sm7, smt7, "get_CurrentScene")
                local cs7 = sc7 and sc7:call("findComponents(System.Type)", sdk.typeof("app.Character"))
                local n7 = 0
                pcall(function() n7 = tonumber(cs7:call("get_Length")) or 0 end)
                if n7 == 0 then pcall(function() n7 = cs7:get_size() or 0 end) end
                for i7 = 0, (tonumber(n7) or 0) - 1 do
                    pcall(function()
                        local c7 = cs7:call("get_Item", i7) or cs7[i7]
                        local g7 = c7 and char_go(c7)
                        local u7 = g7 and upos(g7)
                        if g7 and u7 and tostring(go_name(g7) or ""):find("ch299200", 1, true) then
                            local ex7 = tonumber(u7.x) - pp.x
                            local ez7 = tonumber(u7.z) - pp.z
                            if math.sqrt(ex7 * ex7 + ez7 * ez7) < 6.0 then nbody8 = nbody8 + 1 end
                        end
                    end)
                end
            end)
            pcall(function()
                log.info(string.format("[IrisTaming] ⚠ LAUNCH dy=%+.2f  y=%.2f  nearest=%s(%s) d=%.2f dy_gap=%s @%x  carried[%s]  rabbits_near=%d  L0:%s",
                    dy8, py8, nm8, st8, nd8,
                    ny8 and string.format("%+.2f", ny8 - py8) or "-",
                    (nga8 or 0), carr8, nbody8, l08))
            end)
        end)
        -- the carry-try poll: 0.9s of silence, then the verdict -- native bound (full anims)
        -- or the scripted chest pin (the proven fallback)
        if S.pet_carry_try then
            local T9 = S.pet_carry_try
            local rec9 = S.tamed[T9.ch]
            local act9 = false
            pcall(function()
                local cc9 = player and player:call("get_CatchController")
                act9 = cc9 and cc9:call("get_IsActive") == true
            end)
            if act9 and rec9 then
                S.pet_carry_try = nil
                rec9.carried_script = true; rec9.carry_native = true
                -- ⛔ GHOST THE CARRIED BODY THE INSTANT THE HOLD BINDS (08-08, Aurora:
                -- "pick the rabbit up and I go flying into the air"). The grab path
                -- re-enables the pet's CharacterController just before startBridalCarry
                -- (it must, or the catch won't take), and the carry then warps that LIVE
                -- capsule into the middle of the player's. Two co-located capsules have no
                -- horizontal separating axis, so depenetration dumps the whole correction
                -- into +Y -- every frame, because the carry re-pins it every frame. That
                -- accumulates into a launch. Same lesson the set-down already learned
                -- ("solidity returns DEFERRED ... inside the player's capsule was its own
                -- shove"); the native path just never got it. Ghosting here is safe: the
                -- catch attaches by ACTION/joint, not by physics -- the scripted pin carry
                -- has always run fully ghosted. We wait for the BIND (act9) rather than
                -- ghosting at fire time because touching the body mid-CarryStart
                -- interrupts it (the llm_freetalk law at the grab site above).
                pcall(function()
                    local cg9 = char_go(T9.ch)
                    if cg9 then
                        iris_body_solid(T9.ch, cg9, false)
                        set_ground_glue(cg9, false)   -- GroundFixer would fight the hold too
                    end
                end)
                rec9.carry_bridal = (tonumber(T9.stage) or 1) == 1   -- picks the GENTLE end action
                rec9.follow = nil; rec9.perch = nil; rec9.fmode = nil; rec9.carry_idle_at = nil
                set_prompt("IN YOUR ARMS", "You scoop it up. (Grab again: down.)", 2.5, 0xFF80FFB0)
                pcall(function() log.info("[IrisTaming] pet carry: NATIVE hold bound (stage " .. tostring(T9.stage) .. ")") end)
            elseif (tonumber(T9.stage) or 1) == 1 and now > (tonumber(T9.t0) or 0.0) + 0.9 then
                -- bridal never bound: stage 2 = the over-shoulder sustained carry
                T9.stage = 2; T9.t0 = now
                pcall(function()
                    local hum9 = player:call("get_Human")
                    local hcp9 = hum9 and hum9:call("get_CatchProcessor")
                    if not hcp9 then hcp9 = hum9 and hum9["<CatchProcessor>k__BackingField"] end
                    if hcp9 then
                        for _, f9 in ipairs({
                            function() hcp9:call("startCarry(app.Character, System.Boolean)", T9.ch, true) end,
                            function() hcp9:call("startCarry(app.Character, System.Boolean)", T9.ch, false) end,
                            function() hcp9:call("startCarrySmallAnimal(app.Character, System.Boolean)", T9.ch, false) end,
                        }) do if pcall(f9) then break end end
                    end
                end)
            elseif now > (tonumber(T9.t0) or 0.0) + 0.9 then
                S.pet_carry_try = nil
                if rec9 then
                    rec9.carried_script = true; rec9.carry_native = nil
                    rec9.follow = nil; rec9.perch = nil; rec9.fmode = nil; rec9.carry_idle_at = nil
                    pcall(function()
                        local pam9 = nil
                        pcall(function() pam9 = player["<ActionManager>k__BackingField"] end)
                        if not pam9 then pcall(function() pam9 = player:call("get_ActionManager") end) end
                        if pam9 then pam9:call("requestActionCore(app.ActionManager.Priority, System.String, System.UInt32)", 10, "CarrySmallAnimalStart", 0) end
                    end)
                    set_prompt("IN YOUR ARMS", "It settles against your chest. (Grab again: down. L3: shoulder.)", 2.5, 0xFF80FFB0)
                    pcall(function() log.info("[IrisTaming] pet carry: native refused -- scripted pin") end)
                end
            end
        end

        -- ===== SCOUT DRONE (bird only): launch / pilot / recall / panic =====
        -- The heavy flight/suppress machinery lives in the griffin bridge; here is the state
        -- machine + the failsafes. SAFETY LAW: the 60s cap and the panic key depend on NOTHING
        -- and route through scout_force_restore -- flying the bird can never strand the player.
        if IPPS then IPPS("scout") end
        if S.scout then S.scout_heartbeat = now end   -- the UNGATED failsafe watches this for a stall
        local sc_mask = gp_mask()
        local sc_launch = iris_kb(math.floor(tonumber(C.scout_key) or 0x4A))
            or (sc_mask & math.floor(tonumber(C.scout_button_bit) or 0x2000)) ~= 0
        local sc_launch_edge = sc_launch and not S.scout_launch_prev
        S.scout_launch_prev = sc_launch
        local sc_panic_combo = math.floor(tonumber(C.scout_panic_combo) or 0x3000)
        local sc_panic = iris_kb(math.floor(tonumber(C.scout_panic_key) or 0x08))
            or (sc_mask & sc_panic_combo) == sc_panic_combo
        if sc_panic and S.scout then
            scout_force_restore("panic")   -- FIRST, unconditional: the never-soft-locked button
        elseif S.scout then
            local sc = S.scout
            -- speak about the creature actually out there (crow-speak over a rabbit -- Aurora)
            local sgo0 = char_go(sc.ch)
            local sc_lbl = "companion"
            pcall(function() sc_lbl = tostring(creature_label(sgo0) or "companion"):lower() end)
            local sc_ground = (species_clips(sgo0) or {}).ground == true
            local bad = (not (sc.ch and char_go(sc.ch))) or is_dead(sc.ch)   -- bird gone/dead
            if not bad and player and is_dead(player) then bad = true end     -- Arisen died mid-scout
            if bad then
                scout_force_restore("lost")
            elseif sc.phase == "scouting" then
                -- a scout is a REMOTE DRONE: it can never die to a fall/jank while you drive it
                -- (a stable-adopted rat plummeted home off a cliff and DIED -- 07-15; the pet
                -- immunity at the loop top only covers non-stable records)
                set_immunity(sc.ch, true)
                -- SCOUT SOUNDS (ids Aurora hunted 07-15): the digging loop rides the burrow
                -- state (started at dig-in, STOPPED at dig-out -- it's continuous), the thump
                -- fires on both edges, the hop on hop-start, the pickup on any pouch growth
                pcall(function()
                    local stS = nil
                    local b0 = _G.IrisGriffinBridge
                    if b0 and b0.scout_status then stS = b0.scout_status() end
                    if not (stS and sgo0) then return end
                    -- the ids came from NICK'S PLAYER = they live in the PLAYER's banks; resolve
                    -- there, ring AT the rabbit (rabbit-own banks = the fallback)
                    local pgo0 = player and char_go(player)
                    local ring0 = function(id0)
                        id0 = math.floor(tonumber(id0) or 0)
                        if id0 <= 0 then return end
                        if not iris_play_trigger_on(sgo0, id0, pgo0) then iris_play_trigger_on(sgo0, id0) end
                    end
                    local bw = stS.burrowed == true
                    if bw ~= (S.snd_burrow_was == true) then
                        S.snd_burrow_was = bw
                        ring0(C.burrow_snd_edge)
                        local lid = math.floor(tonumber(C.burrow_snd_loop) or 0)
                        if lid > 0 then
                            if bw then
                                ring0(lid)
                            else
                                pcall(function()   -- stop via BOTH containers (whichever fired it)
                                    for _, bg0 in ipairs({ pgo0, sgo0 }) do
                                        local sc0 = bg0 and comp(bg0, "soundlib.SoundContainer")
                                        if sc0 then pcall(function() sc0:call("stopTriggered(System.UInt32, via.GameObject, System.UInt32)", lid, sgo0, 1) end) end
                                    end
                                end)
                            end
                        end
                    end
                    local hw = stS.hopping == true
                    if hw and not S.snd_hop_was then ring0(C.hop_snd_id) end
                    S.snd_hop_was = hw
                    local p0 = S.scout_pouch
                    local pn0 = p0 and (#(p0.items or {}) + (tonumber(p0.gathered) or 0) + (tonumber(p0.looted) or 0)) or 0
                    if pn0 > (tonumber(S.snd_pouch_n) or pn0) then ring0(C.collect_snd_id) end
                    S.snd_pouch_n = pn0
                end)
                if now >= (tonumber(sc.deadline) or 0.0) or sc_launch_edge then
                    -- the digging loop must not outlive the scurry (stop via BOTH containers)
                    if S.snd_burrow_was then
                        S.snd_burrow_was = nil
                        pcall(function()
                            local lid = math.floor(tonumber(C.burrow_snd_loop) or 0)
                            if lid <= 0 then return end
                            for _, bg0 in ipairs({ player and char_go(player), sgo0 }) do
                                local sc0 = bg0 and comp(bg0, "soundlib.SoundContainer")
                                if sc0 then pcall(function() sc0:call("stopTriggered(System.UInt32, via.GameObject, System.UInt32)", lid, sgo0, 1) end) end
                            end
                        end)
                    end
                    S.snd_hop_was = nil; S.snd_pouch_n = nil
                    -- END scouting: control back to the player NOW; the bird flies home cosmetically
                    pcall(function() local cam = _G.IrisCreatureCam
                        if cam then if cam.set_on then cam.set_on(false) end; if cam.clear_target then cam.clear_target() end end end)
                    pcall(function() local b = _G.IrisGriffinBridge; if b and b.scout_to_flyback then b.scout_to_flyback() end end)
                    pcall(function() scout_ears_restore() end)   -- control is hers again: ears home
                    sc.phase = "flyback"; sc.fb0 = now
                    S.scout_ping_prev = nil   -- a held ping button shouldn't swallow the next session's first ping
                    pcall(function() log.info("[IrisTaming] scout end requested (edge/deadline)") end)
                    if sc_ground then
                        set_prompt("IT SCURRIES BACK", "Control is yours. Your " .. sc_lbl .. " races back to you.", 2.5, 0xFF80FFB0)
                    else
                        set_prompt("IT FLIES BACK", "Control is yours. Your " .. sc_lbl .. " returns to your shoulder.", 2.5, 0xFF80FFB0)
                    end
                else
                    local sc_ping = iris_kb(math.floor(tonumber(C.scout_ping_key) or 0x50))
                        or (sc_mask & math.floor(tonumber(C.scout_ping_button_bit) or 0x10)) ~= 0
                    local sc_ping_edge = sc_ping and not S.scout_ping_prev
                    S.scout_ping_prev = sc_ping
                    if sc_ping_edge and now >= (tonumber(S.scout_ping_cd) or 0.0) then
                        S.scout_ping_cd = now + 3.0
                        pcall(function() local b = _G.IrisGriffinBridge; if b and b.scout_ping then b.scout_ping() end end)
                        -- the ping chime rings from HERE (the id lives in the player's COMMON/
                        -- ABILITY bank, not the scout's -- Nick's source/target split)
                        pcall(function()
                            local sid9 = math.floor(tonumber(C.scout_ping_sound_id) or 0)
                            if sid9 > 0 then
                                local pg9 = player and char_go(player)
                                if not iris_play_trigger_on(sgo0, sid9, pg9) then iris_play_trigger_on(sgo0, sid9) end
                            end
                        end)
                        set_prompt("PING", "It scans the area.", 1.6, 0xFF80D0FF)
                    end
                    -- A / F: peck & collect a nearby item (edge + short cooldown)
                    local sc_grab = iris_kb(math.floor(tonumber(C.scout_collect_key) or 0x46))
                        or (sc_mask & math.floor(tonumber(C.scout_collect_button) or 0x20020)) == math.floor(tonumber(C.scout_collect_button) or 0x20020)
                    local sc_grab_edge = sc_grab and not S.scout_grab_prev
                    S.scout_grab_prev = sc_grab
                    if sc_grab_edge and now >= (tonumber(S.scout_grab_cd) or 0.0) then
                        S.scout_grab_cd = now + 0.6
                        pcall(function() scout_collect() end)
                    end
                    -- X / C: CAW to distract a nearby enemy toward the crow (edge + cooldown)
                    local sc_caw = iris_kb(math.floor(tonumber(C.scout_caw_key) or 0x43))
                        or (sc_mask & math.floor(tonumber(C.scout_caw_button) or 0x40)) ~= 0
                    local sc_caw_edge = sc_caw and not S.scout_caw_prev
                    S.scout_caw_prev = sc_caw
                    if sc_caw_edge and now >= (tonumber(S.scout_caw_cd) or 0.0) then
                        S.scout_caw_cd = now + 2.0
                        -- X = DIVE-STEAL: a screech, then the bird auto-pilots onto the nearest
                        -- enemy, pecks 1 HP, steals for the pouch, and leaves the MARK on it
                        if sc_ground and not (species_clips(sgo0) or {}).burrow then
                            -- non-burrow ground critter (the rat) X = THE PICKPOCKET: dart to
                            -- the mark, rear up, rummage, LIFT -- no damage, no aggro
                            local pkr = 0
                            pcall(function() local bb = _G.IrisGriffinBridge
                                if bb and bb.scout_pickpocket then pkr = bb.scout_pickpocket() or 0 end end)
                            if pkr == 1 then
                                set_prompt("THE FILCH", "It darts toward its mark, paws itching...", 2.0, 0xFF80D0FF)
                            else
                                set_prompt("PICKPOCKET", "No pockets worth picking nearby.", 1.6, 0xFF80D0FF)
                            end
                        elseif sc_ground then
                            -- ground critter X = THE BURROW AMBUSH (Aurora's option B): stalk
                            -- beneath the earth, erupt under the prey
                            local amb = 0
                            pcall(function() local bb = _G.IrisGriffinBridge
                                if bb and bb.scout_ambush then amb = bb.scout_ambush() or 0 end end)
                            if amb == 1 then
                                set_prompt("THE STALK", "It slips through the earth toward its prey...", 2.0, 0xFF80D0FF)
                            elseif amb == -1 then
                                set_prompt("BURROW FIRST", "The ambush strikes from BELOW -- press B to burrow, then X.", 2.2, 0xFFFFD080)
                            else
                                set_prompt("AMBUSH", "Nothing near worth ambushing.", 1.6, 0xFF80D0FF)
                            end
                        else
                            local drew = 0
                            pcall(function() local bb = _G.IrisGriffinBridge
                                if bb and bb.scout_caw then drew = bb.scout_caw(math.floor(tonumber(C.scout_caw_sound_id) or 0)) or 0 end end)
                            set_prompt("DIVE", (tonumber(drew) or 0) > 0 and ("Your " .. sc_lbl .. " folds its wings and DIVES.") or "Nothing below worth diving.", 1.6, 0xFF80D0FF)
                        end
                    end
                    -- the STRIKE landed (bridge flag, once per dive): roll the steal into the pouch
                    local dive_hit = false
                    pcall(function() local bb = _G.IrisGriffinBridge
                        if bb and bb.scout_dive_result then dive_hit = bb.scout_dive_result() == true end end)
                    if dive_hit then
                        S.scout_pouch = S.scout_pouch or { items = {}, gathered = 0, looted = 0 }
                        local pool = {}
                        for id2 in tostring(C.scout_steal_items or ""):gmatch("%d+") do pool[#pool + 1] = tonumber(id2) end
                        -- species flavor: the rabbit ERUPTS, the rat LIFTS (a professional --
                        -- higher steal odds), the birds STRIKE
                        local spd9 = species_clips(sgo0) or {}
                        local chance9 = tonumber(spd9.steal_chance) or tonumber(C.scout_steal_chance) or 0.65
                        local t_hit9, t_win9, t_dry9
                        if sc_ground and spd9.burrow then
                            t_hit9 = "IT ERUPTS FROM BELOW"; t_win9 = "The earth bursts open - and it STEALS something!"
                            t_dry9 = "The earth bursts open - but nothing worth taking."
                        elseif sc_ground then
                            t_hit9 = "NIMBLE PAWS"; t_win9 = "It slips back with something LIFTED!"
                            t_dry9 = "Its paws come up empty - the mark carried nothing loose."
                        else
                            t_hit9 = "THE TALONS STRIKE"; t_win9 = "A peck of blood - and it STEALS something!"
                            t_dry9 = "A peck of blood - but nothing worth taking."
                        end
                        -- ⭐⭐⭐ 08-18: roll the VICTIM'S OWN TABLE first (app.Character.ItemDropInfo
                        -- -> getJob04SnatchItem, DD2's Thief PLUNDER roll). The fixed herb pool
                        -- survives only as the fallback for a body that carries no drop param --
                        -- so a goblin now yields goblin things, and Aurora stops being handed
                        -- Greenwarish by a crow that just robbed an ogre.
                        local nat9 = nil
                        pcall(function() local bb = _G.IrisGriffinBridge
                            if bb and bb.scout_snatch_roll then nat9 = bb.scout_snatch_roll(0) end end)
                        if nat9 and tonumber(nat9.id) then
                            S.scout_pouch.items[#S.scout_pouch.items + 1] =
                                { id = math.floor(nat9.id), count = math.max(1, math.floor(tonumber(nat9.num) or 1)),
                                  name = item_name_from_id(math.floor(nat9.id)) }
                            set_prompt(t_hit9, t_win9, 2.2, 0xFF80FFB0)
                            pcall(function() local bb = _G.IrisGriffinBridge
                                if bb and bb.scout_dive_robbed then bb.scout_dive_robbed() end end)
                        elseif #pool > 0 and math.random() <= chance9 then
                            local sid2 = pool[math.random(#pool)]
                            S.scout_pouch.items[#S.scout_pouch.items + 1] = { id = sid2, count = 1, name = item_name_from_id(sid2) }
                            set_prompt(t_hit9, t_win9, 2.2, 0xFF80FFB0)
                            -- ⭐ 08-17 (Aurora: "4 dives on one goblin, 3 items"): a body that has
                            -- actually been ROBBED is retired from the dive list for good. Only on
                            -- a successful lift -- a failed ~65% roll costs the mark nothing but
                            -- the short re-target cooldown, so the dice never lock her out.
                            pcall(function() local bb = _G.IrisGriffinBridge
                                if bb and bb.scout_dive_robbed then bb.scout_dive_robbed() end end)
                        else
                            set_prompt(t_hit9, t_dry9, 1.8, 0xFF80D0FF)
                        end
                    end
                    S.status = string.format("SCOUT: guide your %s (%.0fs left) - A collect, J/R3 return", sc_lbl, math.max(0, (tonumber(sc.deadline) or now) - now))
                end
            elseif sc.phase == "flyback" then
                -- the return leg is as protected as the scout itself (08-05, Aurora: a bird
                -- DIED on the way home and its soul went with it -- the per-frame immunity
                -- above only covered phase=="scouting", so the flyback flew mortal)
                set_immunity(sc.ch, true)
                local done = false
                pcall(function() local b = _G.IrisGriffinBridge; if b and b.scout_flyback_done then done = b.scout_flyback_done() end end)
                if done or now >= (tonumber(sc.fb0) or now) + 22.0 then
                    pcall(function() local b = _G.IrisGriffinBridge; if b and b.scout_settle then b.scout_settle() end end)
                    local rec = S.tamed[sc.ch]
                    if rec then rec.scouting = nil; rec.perch = true; rec.follow = nil end   -- the loop re-arms the pin
                    -- launch_prev stays TRUE while the button is held (nilling it here made the
                    -- rabbit's instant return re-read the held R3 as a fresh launch edge: the
                    -- end->relaunch loop in the 07-15 log). The per-tick tracker clears it on release.
                    S.scout = nil; S.scout_ping_prev = nil; S.scout_heartbeat = nil
                    S.scout_relaunch_at = now + 0.6
                    pcall(function() scout_vision_apply(false) end)   -- restore the screen grade
                    pcall(function() scout_deposit() end)   -- the crow empties its pouch into your bag
                    set_prompt("BACK ON YOUR SHOULDER", "Your " .. sc_lbl .. " settles.", 2.0, 0xFF80FFB0)
                end
            end
        elseif sc_launch_edge and now >= (tonumber(S.scout_relaunch_at) or 0.0)
            and not (S.armed or S.trial or S.feed_drop or S.camp_rite) then
            -- LAUNCH: a perched BIRD that is the active companion, and no tame/exclusive state
            local bch, bgo = nil, nil
            for ch2, rec2 in pairs(S.tamed) do
                local g2 = char_go(ch2)
                if rec2.perch and g2 and (name_in_csv(go_name(g2), C.bird_bands or "ch299410,ch299430")
                    or (species_clips(g2) or {}).ground) then   -- ground critters scout ON FOOT (rabbit: burrow)
                    bch = ch2; bgo = g2; break
                end
            end
            if bch and bgo then
                local ag = nil; pcall(function() local b = _G.IrisGriffinBridge; if b and b.griffin then ag = b.griffin() end end)
                local aa, ba = nil, nil
                pcall(function() aa = ag and ag:get_address() end)
                pcall(function() ba = bch:get_address() end)
                if aa and ba and aa == ba then
                    local ok = false
                    pcall(function() local b = _G.IrisGriffinBridge; if b and b.scout_start then ok = b.scout_start(bch) end end)
                    if ok then
                        local rec = S.tamed[bch]
                        if rec then rec.scouting = true; rec.perch = nil; rec.follow = nil end
                        S.scout_pouch = nil; S.scout_grab_prev = nil   -- a fresh, empty pouch each scout
                        S.snd_listener = nil   -- fresh listener find each scout (scene may have changed)
                        pcall(function() local cam = _G.IrisCreatureCam
                            if cam then if cam.set_target then cam.set_target(bgo) end; if cam.set_on then cam.set_on(true) end end end)
                        S.scout = { ch = bch, phase = "scouting", t0 = now, deadline = now + (tonumber(C.scout_secs) or 60.0) }
                        -- ⭐ 08-18 (Aurora: "the notification says it can burrow, which isn't true
                        -- -- and we don't need the controls on the notifications now we have the
                        -- native UI"). Both right, and the second explains the first: this card
                        -- listed controls from memory, so it drifted out of step with the code and
                        -- started lying (only the RABBIT burrows; the rat dashes). The panel is
                        -- now generated from the real slot table and cannot drift, so the card
                        -- goes back to being a card -- it says what happened, not how to fly.
                        local sp7 = species_clips(bgo) or {}
                        if sp7.ground then
                            set_prompt("SCURRY AWAY", "You slip into its skin. Off it goes.", 3.0, 0xFF80FFB0)
                        else
                            set_prompt("SCOUT AWAY", "You take to the air on borrowed wings.", 3.0, 0xFF80FFB0)
                        end
                    else
                        set_prompt("SCOUT", "Not now - dismount or finish the current action first.", 2.0, 0xFF5050FF)
                    end
                else
                    set_prompt("SCOUT", "That bird isn't your active companion.", 2.0, 0xFF5050FF)
                end
            end
        end

        S.perch_active = nil   -- re-armed below only while a crow is actually perched (self-healing)
        -- the one global shoulder dial, republished every frame so the slider tunes live and the
        -- easer in IrisGriffin/stable.lua (another file, another hook) reads the same number we do
        pcall(function() rawset(_G, "IrisTamingPerchShrink", iris_perch_shrink()) end)
        if IPPS then IPPS("TAMED_LOOP") end
        for ch, rec in pairs(S.tamed) do
            local go = char_go(ch)
            if not go or is_dead(ch) then
                S.tamed[ch] = nil
            elseif (function()
                    -- ⭐ THE BRINE SHIELD, asserted on a throttle for EVERY tamed body (including
                    -- one that is scouting or downed -- hence its place above every other branch).
                    -- The brine system is a live writer and streaming rebuilds re-enable it, so a
                    -- set-once would quietly lapse; 2s is cheap and has never lost the race.
                    if C.companion_brine_shield == false then return false end
                    if now >= (tonumber(rec.brine_at) or 0.0) then
                        rec.brine_at = now + 2.0
                        pcall(function()
                            local b = _G.IrisGriffinBridge
                            if b and b.brine_shield then b.brine_shield(ch, true) end
                        end)
                    end
                    return false   -- never claims the frame; the real branches below still run
                end)() then
            elseif iris_body_downed(go) then
                -- ⛔⛔⛔ 08-17 -- DOWNED = TOTAL HANDS OFF. THIS IS THE DIVEBOMB CTD.
                -- Aurora's crow dive-stole at something over the sea, hit the water, and the brine
                -- put it DOWN. downed.lua then owns that body absolutely: AI off, HP pinned at 1,
                -- parked in DmgDownLoop and re-asserted every frame. But a downed body reads ALIVE
                -- (hp 1, IsDead false), so nothing above stopped this loop -- the shoulder pin, the
                -- leap arcs and the puppet follow all kept writing its transform while the scout
                -- drive flew it. Two owners on an action-claimed body = the actinter move crash.
                -- ⇒ hand the body back the instant it goes down, and release any hold we had on it.
                local was_held = rec.perch or rec.carried or rec.perch_ground_scale
                    or rec.solid_state == false
                    or (S.perch_trans and S.perch_trans.ch == ch) or false
                if rec.perch or rec.carried or rec.perch_ground_scale then
                    rec.perch = nil; rec.carried = nil; rec.perch_ground_scale = nil
                    pcall(function() rawset(_G, "IrisTamingPerchScaleHold", nil) end)
                end
                if S.perch_trans and S.perch_trans.ch == ch then S.perch_trans = nil end
                -- HAND THE BODY BACK WHOLE, ONCE (the same contract as the set-down). The perch
                -- and the leap arcs ghost a critter completely -- controller off, AdjustPress,
                -- colliders and HitController off, ground glue off -- and the arc's landing code
                -- is what normally undoes all that. Going down mid-perch skips that code, so
                -- without this the body would collapse as an unglued, non-solid floater and
                -- REVIVE as one. Edge-triggered off rec.downed_hold: re-asserting collision
                -- toggles every frame at 60Hz on a body downed.lua is re-asserting is precisely
                -- the two-writers pattern this whole guard exists to stop.
                -- ⛔ collision + glue ONLY. AIDecisionMaker/NavigationAI are downed.lua's to
                -- restore (it records which ones IT disabled); waking either from here is the
                -- stale native MoveBase executor behind the revive CTD.
                if was_held and not rec.downed_hold then
                    pcall(function() iris_body_solid(ch, go, true) end)
                    pcall(function() set_ground_glue(go, true) end)
                    pcall(function() log.info("[IrisTaming] companion went DOWN while held -- body handed back whole") end)
                end
                rec.solid_state = nil
                -- ⛔ and NOT rec.follow either: the follow branch teleports and puppet-steps the
                -- body, which is the same fatal write by another name. downed.lua drives it now.
                rec.follow = nil; rec.fmode = nil
                rec.downed_hold = true
            elseif rec.scouting then
                -- the scout drone owns this body (griffin-side flight drive); IrisTaming stays hands-off
            else
                -- REVIVED (or it was never down): re-arm the follow the downed gate stood down.
                -- Without this a revived companion would stand where it fell forever -- nothing
                -- else in this loop ever sets rec.follow back on for a body it did not just tame.
                if rec.downed_hold then
                    rec.downed_hold = nil
                    if not (rec.carried or rec.perch or rec.carry_native) then
                        rec.follow = true; rec.fmode = nil
                    end
                    -- ⚠ "RELEASED", not "revived" -- 08-17, and the distinction cost Aurora a
                    -- wrong conclusion from the log. This latch clears when the body leaves
                    -- _G.IrisDownedAddrs, and EVERY downed exit does that: a real player revive,
                    -- the 30s window expiring (griffin_downed_to_stable -> dismissed to the
                    -- stable, soul kept), an invalid body, or the feature being switched off.
                    -- Her water test was the SECOND of those, not a revive.
                    pcall(function() log.info("[IrisTaming] companion released from DOWN (revived, or the window expired) -> follow re-armed") end)
                end
                -- floating nameplate: name + gender symbol over every companion (Aurora's ask);
                -- the ACTIVE stable companion reads its record via the bridge EVERY frame, so
                -- renames and the gender backfill land instantly (rec.stable was never set --
                -- the old lookup was dead code and the plate showed the GameObject name)
                if C.companion_nameplate ~= false then
                    pcall(function()
                        local nm2, g2 = rec.name, rec.gender
                        if rec.stable_active then
                            local b2 = _G.IrisGriffinBridge
                            local inf = b2 and b2.companion_info and b2.companion_info()
                            if inf then nm2 = inf.name or nm2; g2 = inf.gender or g2 end
                        end
                        -- "ch299400_A_00" is a body, not a name
                        if nm2 and tostring(nm2):find("^ch%d") then nm2 = nil end
                        local sym = (g2 == "female" and " \u{2640}") or (g2 == "male" and " \u{2642}") or ""
                        draw_marker(go, tostring(nm2 or creature_label(go)) .. sym, 0xFFB0FFC0)
                    end)
                end
                -- ⭐⭐⭐ 08-10 r95 -- THIS IS THE ONE. THE ENGINE WAS APPLYING ZERO.
                -- The clamp proved damage was reaching the pipeline and being
                -- ALLOWED: "clampHits=12  clamp=dmg 116 (hp 250, budget 249)" --
                -- twelve hits, 116 damage permitted each time, and HP reading a
                -- flat 250 at every single one. We were never blocking the hit;
                -- the engine was applying nothing.
                -- set_immunity(ch, true) sets IsDamageZero, which does not stop
                -- the damage PIPELINE -- calcDamageReaction still runs, so our
                -- clamp still sees a healthy 116 -- it zeroes the HP APPLICATION
                -- at the end. Every measurement we took was downstream of the
                -- decision and upstream of the effect.
                -- ⛔ And it is re-asserted EVERY FRAME, which is why the r85
                -- mortality enforcer could not win: the two writes fought each
                -- tick, and my "immunity reads 00" diag was simply sampling on a
                -- frame where the enforcer happened to go last. A tick-war, not
                -- a state.
                -- full_pacify(ch) beside it is the aggro half of the same story:
                -- hate, targets and hate-rate toward the party, wiped per frame.
                -- ⭐ The comment below says "mortality = design TBD". The downed
                -- system IS that design now -- so a mount you are RIDING is
                -- mortal and hateable, and everything else keeps the shield.
                local iris_ridden_now = false
                pcall(function()
                    local hm = rawget(_G, "IrisHorseMount")
                    iris_ridden_now = hm and hm.is_mounted
                        and hm.is_mounted(go) == true
                end)
                if not rec.stable and not iris_ridden_now then   -- stable-owned bodies keep their own driver; only the L3 shoulder is ours
                    full_pacify(ch)   -- permanently at peace: hate + targets + zero-rate toward party
                    set_immunity(ch, true)   -- v1: companions immune to friendly fire (mortality = design TBD)
                    local dm = comp(go, "app.AIDecisionMaker")
                    if dm then pcall(function() dm:call("set_Enabled", false) end) end   -- the terms hold
                elseif iris_ridden_now and not rec.stable then
                    -- ⭐ r95: mortal while ridden. Clear the flags this block set
                    -- on previous frames -- leaving them latched would keep the
                    -- mount invincible for the whole ride after a single frame
                    -- of the shield.
                    -- Wolf/cat rides use scripted contact while the native
                    -- decision/FSM stack is parked.  Letting hostile hit
                    -- reactions wake that stack created a relationship/hate
                    -- storm and left the whole game at 15 fps.  Keep ridden
                    -- wyrms shielded; horse/griffin mortality remains unchanged.
                    if rawget(_G, "IrisWyrmMounted") == true then
                        set_immunity(ch, true)
                    else
                        set_immunity(ch, false)
                    end
                end
                -- HorseRodeo owns every transform/action write while this exact
                -- companion is mounted.  The old code only used iris_ridden_now
                -- for immunity above, then allowed rec.follow to keep steering,
                -- teleporting and repainting layer 0 later in this same tick.
                -- That gave the body two drivers and could invalidate a native
                -- takeover before its first locomotion request.
                if iris_ridden_now then
                    rec.fmode = nil
                    rec.follow_last = nil
                elseif perch_edge and not S.perch_trans and name_in_csv(go_name(go), C.critter_bands) then
                    local cp0 = upos(go)
                    local d0 = (cp0 and pp) and dist(cp0, pp) or 1e9
                    if rec.perch then
                        -- SET IT DOWN: unparent + true size back NOW, then a driven hop-down ARC
                        -- (Aurora: "they still just teleport") -- the body is handed back WHOLE
                        -- (FSM live, action reset) only when the arc lands
                        rec.perch = nil; rec.follow = nil; rec.perch_idle_at = nil; rec.fmode = nil
                        S.perch_active = nil   -- the late pin stops
                        if rec.perch_parented then
                            pcall(function()
                                local ctf = go:call("get_Transform")
                                pcall(function() ctf:call("set_ParentJoint", "") end)
                                pcall(function() ctf:call("setParentJoint", "") end)
                                -- restore the ORIGINAL parent -- setParent(nil) is silently refused
                                -- on scene bodies (the invisible-stick law)
                                local orig = rec.perch_orig
                                if orig ~= nil then
                                    pcall(function() ctf:call("setParent", orig, true) end)
                                    pcall(function() ctf:call("set_Parent", orig) end)
                                else
                                    pcall(function() ctf:call("setParent", nil, true) end)
                                    pcall(function() ctf:call("set_Parent", nil) end)
                                end
                                local still = nil
                                pcall(function() still = ctf:call("get_Parent") end)
                                pcall(function() log.info("[IrisTaming] shoulder set-down: orig=" .. tostring(orig ~= nil) .. " parent_now=" .. tostring(still ~= nil)) end)
                            end)
                            rec.perch_parented = nil
                            rec.perch_orig = nil
                        end
                        pcall(function()
                            -- "true size" = the PROBE's body scale (species base 0.75 for the
                            -- rat / wyrm growth), NEVER a hard-coded 1.0 -- that clobber made
                            -- every set-down rat huge (Aurora's three-scale stack find)
                            local bs9 = 1.0
                            pcall(function() local b = _G.IrisGriffinBridge; if b and b.body_scale then bs9 = tonumber(b.body_scale()) or 1.0 end end)
                            go:call("get_Transform"):call("set_LocalScale", Vector3f.new(bs9, bs9, bs9))
                        end)
                        pcall(function()
                            local b = _G.IrisGriffinBridge
                            if b and b.companion_hold then b.companion_hold(true) end   -- the driver stays down: OUR follow owns critters
                        end)
                        -- the arc starts from the shoulder point it's leaving; the puppet state
                        -- (think-stop, FSM off) rides through it -- restored when it lands
                        local cs0 = upos(go)
                        local climb0 = (species_clips(go) or {}).climb_on == true
                        S.perch_trans = { ch = ch, dir = "down", t0 = now, scale = rec.perch_ground_scale,
                            style = climb0 and "climb" or nil, dur = climb0 and 1.3 or 0.5,
                            fx = (cs0 and cs0.x) or pp.x, fy = (cs0 and cs0.y) or (pp.y + 1.3), fz = (cs0 and cs0.z) or pp.z }
                    elseif (not rec.carry_native) and (d0 <= 2.5 or catch_active(player)) then
                        -- TO THE SHOULDER (works from the ground or straight out of an RT carry)
                        -- Capture BEFORE disabling FSM/controller/ragdoll: this is the
                        -- rendered ground size the player has asked us to preserve.
                        rec.perch_ground_scale = nil
                        pcall(function()
                            local s0 = go:call("get_Transform"):call("get_LocalScale")
                            local x0 = tonumber(s0 and s0.x)
                            local obs = rawget(_G, "IrisGroundObservedScale")
                            if type(obs) == "table"
                                and tostring(obs.addr) == tostring(go:get_address())
                                and now - (tonumber(obs.at) or 0.0) < 0.25 then
                                x0 = tonumber(obs.scale) or x0
                            end
                            if x0 and x0 > 0.05 and x0 <= 3.0 then
                                rec.perch_ground_scale = x0
                                rawset(_G, "IrisTamingPerchScaleHold", {
                                    addr = tostring(go:get_address()), scale = x0,
                                })
                                log.info(string.format("[IrisTaming] shoulder scale captured from ground: %.3f", x0))
                            end
                        end)
                        if catch_active(player) then
                            pcall(function()   -- end the native carry cleanly before the perch takes the body
                                local cc = player:call("get_CatchController")
                                if cc then
                                    pcall(function() cc:call("set_IsContinue(System.Boolean)", false) end)
                                    pcall(function() cc:call("set_IsDisableEscape(System.Boolean)", false) end)
                                end
                            end)
                        end
                        -- the LEAP UP: a driven arc from the grass to the shoulder line; the
                        -- perch pin only takes the body once the arc arrives (works straight
                        -- out of the scripted arm-carry too)
                        rec.follow = nil; rec.fmode = nil; rec.carried_script = nil
                        pcall(function()
                            local b = _G.IrisGriffinBridge
                            if b and b.companion_hold then b.companion_hold(true) end   -- the follow driver stands down
                        end)
                        local climb0 = (species_clips(go) or {}).climb_on == true
                        S.perch_trans = { ch = ch, dir = "up", t0 = now,
                            style = climb0 and "climb" or nil, dur = climb0 and 1.4 or 0.5,
                            fx = (cp0 and cp0.x) or pp.x, fy = (cp0 and cp0.y) or pp.y, fz = (cp0 and cp0.z) or pp.z }
                    end
                end
                -- IN THE PLAYER'S ARMS? (the native small-animal carry -- Aurora: "make
                -- rabbits and rats pickupable"): while caught, the game owns the body
                local caught9 = false
                pcall(function()
                    local cc9 = ch:call("get_CaughtController")
                    caught9 = cc9 and cc9:call("get_IsCaught") == true
                end)
                if caught9 then
                    rec.carried = true
                    -- ⛔ NO-CLIMB while a critter is in your arms (08-08, trace-confirmed):
                    -- ObjectClimber offers the held body as a climbable monster, and the
                    -- player climbs it -> pops up -> falls -> climbs again. Refreshed every
                    -- frame so the window can never outlive the hold by more than 0.5s.
                    S.critter_no_climb = now + 0.5
                    -- hands off entirely (L3 from the carry still shoulders it -- the
                    -- catch_active branch above) -- EXCEPT the collision assert: the game
                    -- owns the pose, but it must NOT own a live capsule inside the player
                    -- (the 08-08 pickup launch). The FSM re-enables the controller on its
                    -- own, so this is re-asserted on a throttle while the hold lasts.
                    -- ⛔ DO NOT make this every-frame (tried 08-08, REVERTED): disabling the
                    -- collision components on every single frame stomps the native carry and
                    -- the bridal pose stops asserting. The 0.25s cadence is the known-good
                    -- value -- and the trace has since shown the ghost is NOT the problem
                    -- anyway ("glue OFF: 4 comps" = it is working, and the pops happen with
                    -- the body already ghosted).
                    if now >= (tonumber(rec.carry_ghost_at) or 0.0) then
                        rec.carry_ghost_at = now + 0.25
                        iris_body_solid(ch, go, false)
                        set_ground_glue(go, false)
                    end
                elseif rec.carried then
                    -- put down: back to the puppet follow
                    rec.carried = nil
                    rec.follow = true; rec.perch = nil; rec.fmode = nil
                    set_think_stop(ch, true)
                elseif S.perch_trans and S.perch_trans.ch == ch then
                    -- THE SHOULDER TRANSITION (Aurora: "they still just teleport"): a short
                    -- driven arc on/off the shoulder -- the rabbit leaps, birds fly. The body
                    -- stays a puppet (think-stop, FSM off) for the whole arc.
                    local tr9 = S.perch_trans
                    local k9 = (now - (tonumber(tr9.t0) or now)) / (tonumber(tr9.dur) or 0.5)
                    local spT = species_clips(go)
                    local grd9 = spT and spT.ground
                    -- Keep the same captured scale through both arcs. Without this the
                    -- body visibly expands during the last half-second before rec.perch.
                    local hs9 = tonumber(rec.perch_ground_scale or tr9.scale)
                    if hs9 and hs9 > 0.05 and hs9 <= 3.0 then
                        -- 08-17: the global shoulder dial rides the UP arc so the body arrives at
                        -- its shoulder size instead of popping to it on the landing frame. The
                        -- DOWN arc keeps the raw ground scale -- it is on its way back to being a
                        -- ground creature, and the set-down already restores the true size.
                        if tr9.dir == "up" then hs9 = hs9 * iris_perch_shrink() end
