            c9, C.scout_steal_chance = imgui.drag_float("Steal chance (0-1)##scout_stealchance", tonumber(C.scout_steal_chance) or 0.65, 0.02, 0.0, 1.0); chg = chg or c9
            if imgui.tree_node("ITEM CATALOG search (find ids: 'egg', 'milk', steal-pool loot...)##tame_itemsearch") then
                imgui.text("Searches every item id 1-36000 by name. One click may hitch a second.")
                local cq9, q9 = imgui.input_text("name contains##tame_isq", tostring(S.item_search_q or ""))
                if cq9 then S.item_search_q = q9 end
                if imgui.button("DUMP FULL CATALOG to file (Ctrl+F heaven)##tame_isdump") then
                    pcall(function()
                        local mgr = item_mgr()
                        if not mgr then S.status = "catalog dump: no ItemManager"; return end
                        local getter = nil
                        for _, gn in ipairs({ "getItemParam(System.Int32)", "getItemData(System.Int32)" }) do
                            pcall(function()
                                local p0 = mgr:call(gn, 184)
                                if p0 and tostring(p0:call("get_Name") or "") ~= "" then getter = gn end
                            end)
                            if getter then break end
                        end
                        if not getter then S.status = "catalog dump: no working getter"; return end
                        local rows = {}
                        for id9 = 1, 36000 do
                            pcall(function()
                                local p9 = mgr:call(getter, id9)
                                local nm9 = p9 and tostring(p9:call("get_Name") or "") or ""
                                if nm9 ~= "" then rows[#rows + 1] = string.format("%d  %s", id9, nm9) end
                            end)
                        end
                        json.dump_file("IrisTaming_item_catalog.json", { count = #rows, items = rows })
                        S.status = string.format("catalog: %d items -> data/IrisTaming_item_catalog.json", #rows)
                    end)
                end
                if imgui.button("SEARCH##tame_isgo") and tostring(S.item_search_q or "") ~= "" then
                    S.item_search_res = {}
                    pcall(function()
                        local mgr = item_mgr()
                        if not mgr then S.item_search_res = { { id = 0, name = "(no ItemManager)" } }; return end
                        -- resolve the working param-lookup ONCE (probe with greenwarish 184)
                        local getter = nil
                        for _, gn in ipairs({ "getItemParam(System.Int32)", "getItemData(System.Int32)" }) do
                            pcall(function()
                                local p0 = mgr:call(gn, 184)
                                if p0 and tostring(p0:call("get_Name") or "") ~= "" then getter = gn end
                            end)
                            if getter then break end
                        end
                        if not getter then S.item_search_res = { { id = 0, name = "(no working item-param getter -- tell Iris)" } }; return end
                        local ql = tostring(S.item_search_q):lower()
                        -- a PURE NUMBER query = direct id lookup (check neighbours of a find, e.g. 301 next to 302)
                        local qid = ql:match("^%s*(%d+)%s*$")
                        if qid then
                            local p9 = mgr:call(getter, tonumber(qid))
                            local nm9 = p9 and tostring(p9:call("get_Name") or "") or ""
                            S.item_search_res = { { id = tonumber(qid), name = nm9 ~= "" and nm9 or "(no item at this id)" } }
                            -- and the FULL param dump: exact field values to clone into CE bundle
                            -- items (the wedding-ring recipe -- never guess a consumable's shape)
                            if p9 then
                                pcall(function()
                                    local out9 = { id = tonumber(qid), name = nm9 }
                                    local td9 = p9:get_type_definition()
                                    while td9 do
                                        for _, f9 in ipairs(td9:get_fields()) do
                                            pcall(function()
                                                local v9 = f9:get_data(p9)
                                                local tv9 = type(v9)
                                                if tv9 == "number" or tv9 == "boolean" or tv9 == "string" then
                                                    out9[f9:get_name()] = v9
                                                end
                                            end)
                                        end
                                        td9 = td9:get_parent_type()
                                    end
                                    json.dump_file("IrisTaming_item_params.json", out9)
                                    S.status = "item " .. tostring(qid) .. " full params -> data/IrisTaming_item_params.json"
                                end)
                            end
                            return
                        end
                        for id9 = 1, 36000 do
                            pcall(function()
                                local p9 = mgr:call(getter, id9)
                                local nm9 = p9 and tostring(p9:call("get_Name") or "") or ""
                                if nm9 ~= "" and nm9:lower():find(ql, 1, true) then
                                    S.item_search_res[#S.item_search_res + 1] = { id = id9, name = nm9 }
                                end
                            end)
                            if #S.item_search_res >= 60 then break end
                        end
                        if #S.item_search_res == 0 then S.item_search_res = { { id = 0, name = "(no matches)" } } end
                    end)
                end
                for _, r9 in ipairs(S.item_search_res or {}) do
