            if imgui.tree_node("IRIS SOUND BROWSER (named banks, reliable play -- Nick's recipe)##tame_sndbrowse") then
                S.snd = S.snd or { src_mode = 1, udata_idx = 1, sub_idx = 1, page = 0, played = {} }
                local SB = S.snd
                imgui.text("Pick WHOSE sounds: every object carries NAMED sound banks. Egg crack -> source = spawned egg chassis.")
                local c8
                c8, SB.src_mode = imgui.combo("source##snd_src", SB.src_mode,
                    { "Player", "Courtship/deep-scan target", "Active companion", "Spawned egg chassis",
                      "NEAREST sound-carrying object (stand AT it)" })
                if c8 then SB.go = nil; SB.udata = nil; SB.subs = nil end
                if imgui.button("Recheck / load banks##snd_re") then SB.go = nil; SB.udata = nil; SB.subs = nil end
                pcall(function()
                    if not SB.go then
                        local go8
                        if SB.src_mode == 1 then
                            local p8 = get_player(); go8 = p8 and char_go(p8)
                        elseif SB.src_mode == 2 then
                            local t8 = S.target or S.lab_play_ch; go8 = t8 and char_go(t8)
                        elseif SB.src_mode == 3 then
                            local b8 = _G.IrisGriffinBridge
                            local g8 = b8 and b8.griffin and b8.griffin()
                            go8 = g8 and char_go(g8)
                        elseif SB.src_mode == 4 then
                            go8 = S.egg_break and S.egg_break.go
                        elseif SB.src_mode == 5 then
                            -- ANY world object with a voice: nearest WwiseContainerApp to the player
                            -- (stand at the pot/door/chest whose sound you want to steal)
                            local p8 = get_player()
                            local pg8 = p8 and char_go(p8)
                            local prp8 = pg8 and pg8:call("get_Transform"):call("get_Position")
                            if prp8 then
                                local paddr8 = pg8:get_address()
                                local sm8 = sdk.get_native_singleton("via.SceneManager")
                                local smt8 = sdk.find_type_definition("via.SceneManager")
                                local scene8 = sm8 and sdk.call_native_func(sm8, smt8, "get_CurrentScene")
                                local comps8 = scene8 and scene8:call("findComponents(System.Type)", sdk.typeof("app.WwiseContainerApp"))
                                local n8b = 0
                                pcall(function() n8b = comps8:call("get_Length") or 0 end)
                                if n8b == 0 then pcall(function() n8b = comps8:get_size() or 0 end) end
                                local bd8 = 8.0
                                for i8 = 0, (tonumber(n8b) or 0) - 1 do
                                    pcall(function()
                                        local cx8 = comps8:call("get_Item", i8) or comps8[i8]
                                        local g8b = cx8 and cx8:call("get_GameObject")
                                        if not g8b or g8b:get_address() == paddr8 then return end
                                        local rp8 = g8b:call("get_Transform"):call("get_Position")
                                        local dx8, dy8, dz8 = rp8.x - prp8.x, rp8.y - prp8.y, rp8.z - prp8.z
                                        local d8 = math.sqrt(dx8 * dx8 + dy8 * dy8 + dz8 * dz8)
                                        if d8 < bd8 then bd8 = d8; go8 = g8b end
                                    end)
                                end
                            end
                        end
                        if not go8 then imgui.text("(no source body -- court/scan/spawn one, or stand nearer the object)"); return end
                        SB.go = go8
                        SB.wwise = comp(go8, "app.WwiseContainerApp")
                        SB.cont = comp(go8, "soundlib.SoundContainer")
                        SB.udata = {}
                        local lst8 = SB.wwise and SB.wwise._UserDataList
                        for i8 = 0, (lst8 and lst8:get_Count() or 0) - 1 do
                            pcall(function()
                                SB.udata[#SB.udata + 1] = tostring(lst8[i8]:get_Path()):gsub("^Sound/Resource/", "")
                            end)
                        end
                        SB.udata_idx = 1; SB.subs = nil
                    end
                    if not SB.wwise or #SB.udata == 0 then imgui.text("(no WwiseContainerApp / no banks on this body)"); return end
                    imgui.text("source: " .. tostring(go_name(SB.go)) .. "  (" .. tostring(#SB.udata) .. " bank files)")
                    c8, SB.udata_idx = imgui.combo("bank file##snd_udata", SB.udata_idx, SB.udata)
                    if c8 then SB.subs = nil end
                    if not SB.subs then
                        SB.subs, SB.sub_nums = {}, {}
                        pcall(function()
                            local ud8 = SB.wwise._UserDataList[SB.udata_idx - 1]._UserDataList
                            for i8 = 0, ud8:get_Count() - 1 do
                                pcall(function()
                                    if ud8[i8]._TriggerInfoList then
                                        SB.subs[#SB.subs + 1] = tostring(ud8[i8]:get_Path()):gsub("^Sound/Resource/", "")
                                        SB.sub_nums[#SB.subs] = i8
                                    end
                                end)
                            end
                        end)
                        SB.sub_idx = 1; SB.page = 0
                    end
                    if #SB.subs == 0 then imgui.text("(no trigger lists in this bank file)"); return end
                    c8, SB.sub_idx = imgui.combo("sub file##snd_sub", SB.sub_idx, SB.subs)
                    if c8 then SB.page = 0 end
                    local tl8 = SB.wwise._UserDataList[SB.udata_idx - 1]._UserDataList[SB.sub_nums[SB.sub_idx]]._TriggerInfoList
                    local n8 = tl8:get_Count()
                    imgui.text(string.format("%d triggers. Click = PLAY on the source (reliable: createRequestInfo).", n8))
                    if imgui.button("stop all played##snd_stop") then
                        pcall(function()
                            for id8 in pairs(SB.played) do
                                SB.cont:call("stopTriggered(System.UInt32, via.GameObject, System.UInt32)", id8, SB.go, 1)
                            end
                        end)
                        SB.played = {}
                    end
                    local per8 = 60
                    if n8 > per8 then
                        c8, SB.page = imgui.drag_int("page##snd_page", SB.page, 1, 0, math.floor((n8 - 1) / per8))
                    end
                    local seen8, col8 = {}, 0
                    for i8 = SB.page * per8, math.min(n8 - 1, SB.page * per8 + per8 - 1) do
                        pcall(function()
                            local trig8 = tl8[i8]
                            local id8 = trig8._TriggerId
                            if not seen8[id8] then
                                seen8[id8] = true
