                                if not eu8 then return end
                                local dx8, dy8, dz8 = eu8.x - pu8.x, eu8.y - pu8.y, eu8.z - pu8.z
                                local d8 = math.sqrt(dx8 * dx8 + dy8 * dy8 + dz8 * dz8)
                                if d8 > 25.0 then return end
                                local res8 = mc8:call("getMesh") or mc8:call("get_Mesh")
