                                    t8 = { path = pth8, count = 0, nearest = 9999.0, go = gn8 }
                                    tally8[pth8] = t8
                                end
                                t8.count = t8.count + 1
                                if d8 < t8.nearest then t8.nearest = d8; t8.go = gn8 end
                            end)
                        end
