                                local okr8 = pcall(function() gen8:call(sig8, G8.ctrl, G8.container, 740000 + S.gmtest_seq, G8.inst, nil, nil) end)
                                G8.msg = okr8 and "spawn requested -- look 5m ahead" or "requestCreateInstance failed"
