                        if n8 == 0 then pcall(function() n8 = comps8:get_size() or 0 end) end
                        for i8 = 0, (tonumber(n8) or 0) - 1 do
                            pcall(function()
                                local tf8 = comps8:call("get_Item", i8) or comps8[i8]
                                local go8 = tf8 and tf8:call("get_GameObject")
                                if not go8 then return end
                                local eu8 = upos(go8)
                                if not eu8 then return end
                                local dx8, dy8, dz8 = eu8.x - pu8.x, eu8.y - pu8.y, eu8.z - pu8.z
                                local d8 = dx8 * dx8 + dy8 * dy8 + dz8 * dz8
                                if d8 > 225.0 then return end
                                local kinds8 = {}
                                pcall(function()
                                    local arr8 = go8:call("get_Components")
                                    local m8 = 0
                                    pcall(function() m8 = arr8:call("get_Length") or 0 end)
                                    if m8 == 0 then pcall(function() m8 = arr8:get_size() or 0 end) end
                                    for j8 = 0, (tonumber(m8) or 0) - 1 do
                                        pcall(function()
