                if ct9 and S.efx_tape_on then S.efx_tape = { t0 = os.clock(), seen = {}, rows = {}, sweeps = 0, ep_seen = 0, kid_eps = 0 } end
                if S.efx_tape_on and S.efx_tape then
                    local T9 = S.efx_tape
                    local grab8 = function(ep8, src8, pu8)
                        -- one EffectPlayer -> a tape row (path via ToString, tostring fallback)
                        local res8 = nil
                        pcall(function() res8 = ep8:call("get_Resource") end)
                        if not res8 then return end
                        local path8 = nil
                        pcall(function() path8 = tostring(res8:call("ToString")) end)
                        if (not path8 or path8 == "" or path8 == "nil") then pcall(function() path8 = tostring(res8) end) end
                        if not path8 or path8 == "" or T9.seen[path8] then return end
                        local go8 = nil
                        pcall(function() go8 = ep8:call("get_GameObject") end)
                        local eu8 = go8 and upos(go8)
                        local d8 = -1.0
                        if eu8 and pu8 then
                            local ax8, ay8, az8 = eu8.x - pu8.x, eu8.y - pu8.y, eu8.z - pu8.z
                            d8 = math.sqrt(ax8 * ax8 + ay8 * ay8 + az8 * az8)
                        end
                        if d8 > 60.0 then return end   -- far world efx = noise
                        T9.seen[path8] = true
                        T9.rows[#T9.rows + 1] = { efx = path8, owner = tostring(go_name(go8)), via = src8,
                            d = math.floor(d8 * 10.0 + 0.5) / 10.0,
                            t = math.floor((os.clock() - T9.t0) * 10.0 + 0.5) / 10.0 }
                    end
                    local dump8 = function()
                        json.dump_file("IrisTaming_efx_tape.json", { meta = {
                            sweeps = T9.sweeps, scene_eps = T9.ep_seen, child_eps = T9.kid_eps,
                            note = (T9.ep_seen == 0 and T9.kid_eps == 0)
                                and "ZERO EffectPlayers seen by EITHER route -- findComponents blind AND no effect children; next resort = hook route"
                                or nil }, rows = T9.rows })
                    end
                    if os.clock() - (tonumber(T9.t0) or 0.0) > 45.0 then
                        S.efx_tape_on = false
                        pcall(dump8)   -- ALWAYS writes, even empty -- silence was ambiguous (07-15)
                        S.status = string.format("efx tape: done, %d unique -> IrisTaming_efx_tape.json", #(T9.rows or {}))
                    elseif os.clock() >= (tonumber(T9.next) or 0.0) then
                        T9.next = os.clock() + 0.4
                        T9.sweeps = (tonumber(T9.sweeps) or 0) + 1
                        pcall(function()
                            local pgo8 = char_go(get_player())
                            local pu8 = pgo8 and upos(pgo8)
                            if not pu8 then return end
                            -- ROUTE 1: scene-wide findComponents (may be BLIND to this type --
                            -- the corpse-controller precedent; meta.scene_eps tells the truth)
                            local sm8 = sdk.get_native_singleton("via.SceneManager")
                            local smt8 = sdk.find_type_definition("via.SceneManager")
                            local scene8 = sm8 and sdk.call_native_func(sm8, smt8, "get_CurrentScene")
                            local comps8 = scene8 and scene8:call("findComponents(System.Type)", sdk.typeof("via.effect.EffectPlayer"))
                            local n8 = 0
                            pcall(function() n8 = comps8:call("get_Length") or 0 end)
                            if n8 == 0 then pcall(function() n8 = comps8:get_size() or 0 end) end
                            T9.ep_seen = (tonumber(T9.ep_seen) or 0) + (tonumber(n8) or 0)
                            for i8 = 0, (tonumber(n8) or 0) - 1 do
                                pcall(function() grab8(comps8:call("get_Item", i8) or comps8[i8], "scene", pu8) end)
                            end
                            -- ROUTE 2 (SkillMaker's truth): live action VFX ride CHILD GOs of
                            -- their owner -- walk the transform children of every nearby
                            -- character (the diving griffin!) + the player, two levels deep
                            local chars8 = scene8 and scene8:call("findComponents(System.Type)", sdk.typeof("app.Character"))
                            local cn8 = 0
                            pcall(function() cn8 = chars8:call("get_Length") or 0 end)
                            if cn8 == 0 then pcall(function() cn8 = chars8:get_size() or 0 end) end
                            local walk8
                            walk8 = function(tf8, depth8)
                                if not tf8 or depth8 > 2 then return end
                                local kid8 = nil
                                pcall(function() kid8 = tf8:call("get_Child") end)
                                while kid8 do
                                    pcall(function()
                                        local kgo8 = kid8:call("get_GameObject")
                                        local kep8 = kgo8 and comp(kgo8, "via.effect.EffectPlayer")
                                        if kep8 then
                                            T9.kid_eps = (tonumber(T9.kid_eps) or 0) + 1
                                            grab8(kep8, "child", pu8)
                                        end
                                        walk8(kid8, depth8 + 1)
                                    end)
                                    local nx8 = nil
                                    pcall(function() nx8 = kid8:call("get_Next") end)
                                    kid8 = nx8
                                end
                            end
                            for i8 = 0, (tonumber(cn8) or 0) - 1 do
                                pcall(function()
                                    local cgo8 = (chars8:call("get_Item", i8) or chars8[i8]):call("get_GameObject")
                                    local cu8 = cgo8 and upos(cgo8)
                                    if not cu8 then return end
                                    local ax8, az8 = cu8.x - pu8.x, cu8.z - pu8.z
                                    if (ax8 * ax8 + az8 * az8) > 3600.0 then return end   -- 60m
                                    walk8(cgo8:call("get_Transform"), 0)
                                end)
                            end
                            pcall(dump8)   -- rolling write: a crash mid-tape still leaves the file
                        end)
                    end
