                c9, C.egg_hold_rot = imgui.drag_float("held: YAW deg (tip direction)##tame_eholdr", tonumber(C.egg_hold_rot) or 0.0, 1.0, -180.0, 180.0); chg = chg or c9
                c9, C.egg_hold_pitch = imgui.drag_float("held: PITCH deg (nose up/down)##tame_eholdp", tonumber(C.egg_hold_pitch) or 0.0, 1.0, -180.0, 180.0); chg = chg or c9
                c9, C.egg_hold_roll = imgui.drag_float("held: ROLL deg (lean across the arms)##tame_eholdl", tonumber(C.egg_hold_roll) or 0.0, 1.0, -180.0, 180.0); chg = chg or c9
                c9, C.egg_burst_power = imgui.drag_float("shatter power##tame_eggpow", tonumber(C.egg_burst_power) or 3.9, 0.1, 0.5, 6.0); chg = chg or c9
                c9, C.egg_shard_life = imgui.drag_float("shard rest seconds##tame_egglife", tonumber(C.egg_shard_life) or 6.0, 0.5, 2.0, 20.0); chg = chg or c9
                local cid8
                c9, cid8 = imgui.input_text("crack sound wwise id (0 = silent; tape-hunt one)##tame_eggsnd", tostring(math.floor(tonumber(C.egg_crack_sound_id) or 2805824897)))
                if c9 then C.egg_crack_sound_id = math.floor(tonumber(cid8) or 0); chg = true end
