                        pcall(function() out9.hit_controller_enabled = hc9 and hc9:call("get_Enabled") end)
                        -- the BREAKABLE brain: find the gmBreakableBase-derived component and dump its
                        -- METHODS -- the force-break call (for drop/throw fragility) names itself here
                        pcall(function()
                            local cl9 = go9:call("get_Components")
                            local m9 = 0
                            pcall(function() m9 = cl9:call("get_Length") or 0 end)
