                        S.status = string.format("chassis diag: %s, HitController %s (enabled=%s) -> data/IrisTaming_egg_chassis_diag.json",
                            out9.go, tostring(out9.hit_controller), tostring(out9.hit_controller_enabled))
                    end)
                end
                -- THE POT HUNT: every breakable gimmick inherits app.gmBreakableBase (RSZ dump) --
                -- one press in town = the full nearby BREAKABLES census with mesh paths (what it
                -- looks like) + class names (the chassis id). No per-pot pilgrimage needed.
                if imgui.button("DUMP nearby BREAKABLES (stand in town)##tame_pothunt") then
                    pcall(function()
                        local player9 = get_player()
                        local pgo9 = player9 and char_go(player9)
                        local prp9 = pgo9 and pgo9:call("get_Transform"):call("get_Position")
                        if not prp9 then S.status = "pot hunt: no player"; return end
                        local out9 = { time = os.date("%Y-%m-%d %H:%M:%S"), breakables = {} }
                        local okE9, errE9 = pcall(function()
                            local sm9 = sdk.get_native_singleton("via.SceneManager")
                            local smt9 = sdk.find_type_definition("via.SceneManager")
                            local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
                            local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("app.gmBreakableBase"))
                            local n9 = 0
                            pcall(function() n9 = comps9:call("get_Length") or 0 end)
                            if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
                            out9.found_total = tonumber(n9) or 0
                            for i9 = 0, (tonumber(n9) or 0) - 1 do
                                pcall(function()
                                    local g9 = comps9:call("get_Item", i9) or comps9[i9]
                                    local go9 = g9 and g9:call("get_GameObject")
                                    local rp9 = go9 and go9:call("get_Transform"):call("get_Position")
                                    if not rp9 then return end
                                    local dx9, dy9, dz9 = rp9.x - prp9.x, rp9.y - prp9.y, rp9.z - prp9.z
                                    local dd9 = math.sqrt(dx9 * dx9 + dy9 * dy9 + dz9 * dz9)
                                    if dd9 > 1000.0 then return end   -- ~everything streamed-in
                                    local mpath9 = nil
                                    pcall(function()
                                        local mc9 = comp(go9, "via.render.Mesh")
                                        local res9 = mc9 and (mc9:call("getMesh") or mc9:call("get_Mesh"))
                                        for _, gtr9 in ipairs({ "get_ResourcePath", "get_Path", "get_ResourceName" }) do
                                            if not mpath9 then pcall(function() local v9 = res9:call(gtr9); if v9 then mpath9 = tostring(v9) end end) end
                                        end
                                    end)
                                    out9.breakables[#out9.breakables + 1] = {
                                        d = tonumber(string.format("%.1f", dd9)),
                                        go = tostring(go_name(go9)),
                                        class = tostring(g9:get_type_definition():get_full_name()),
                                        mesh = mpath9,
                                    }
                                end)
                            end
                        end)
                        if not okE9 then out9.err = tostring(errE9) end
                        table.sort(out9.breakables, function(a, b) return (a.d or 99) < (b.d or 99) end)
