            c, C.music_free_roam = imgui.checkbox("Play anywhere (ignore boss-arena gate)##tame_music_roam", C.music_free_roam ~= false); chg = chg or c
            c, C.music_group = imgui.drag_int("BGM group id##tame_music_g", math.floor(tonumber(C.music_group) or 23), 1, 0, 200); chg = chg or c
            c, C.music_phase = imgui.drag_int("BGM phase id##tame_music_p", math.floor(tonumber(C.music_phase) or 10), 1, 0, 200); chg = chg or c
            c, C.music_state = imgui.drag_int("BGM state (-1 = skip)##tame_music_s", math.floor(tonumber(C.music_state) or 20200), 1, -1, 2000000); chg = chg or c
