        imgui.same_line()
        if imgui.button("Dump CampManager API##tame_campdump") then
            -- one-shot reflection dump: if the game keeps a real campsite registry, its field/method
            -- names land in the json and the learned-camps list can be replaced with the real map
            pcall(function()
                local cm = singleton("app.CampManager")
                local out = { fields = {}, methods = {} }
                local td = cm and cm:get_type_definition()
                for _, f in ipairs((td and td:get_fields()) or {}) do
                    out.fields[#out.fields + 1] = tostring(f:get_name())
                end
                for _, m2 in ipairs((td and td:get_methods()) or {}) do
                    out.methods[#out.methods + 1] = tostring(m2:get_name())
                end
                table.sort(out.fields); table.sort(out.methods)
                -- walk the promising leads for a real campsite registry: the set catalog + save context
                local function describe(obj, depth)
                    local o = {}
                    if not obj or depth > 2 then return o end
                    pcall(function() o.type = tostring(obj:get_type_definition():get_full_name()) end)
                    pcall(function() o.count = tonumber(obj:call("get_Count")) end)
                    pcall(function()
                        local rows = {}
                        for _, f in ipairs(obj:get_type_definition():get_fields() or {}) do
                            if not f:is_static() then
                                local fn = tostring(f:get_name())
                                local v = nil
                                pcall(function() v = obj:get_field(fn) end)
                                rows[fn] = tostring(v)
                            end
                        end
                        o.field_values = rows
                    end)
                    if o.count and o.count > 0 then
                        pcall(function() o.first_item = describe(obj:call("get_Item", 0), depth + 1) end)
                    end
                    return o
                end
                pcall(function() out.camp_set_catalog = describe(cm:get_field("<CampSetCatalog>k__BackingField"), 0) end)
                pcall(function() out.camp_save_context = describe(cm:get_field("<CampSaveContext>k__BackingField"), 0) end)
                pcall(function() out.camp_controller = describe(cm:call("get_CampController"), 0) end)
                json.dump_file(MOD .. "_campmanager_api.json", out)
                S.status = string.format("CampManager dumped: %d fields, %d methods (+catalog walk)", #out.fields, #out.methods)
            end)
        end
        imgui.text(string.format("backup camps learned: %d (marker uses the MAP's campsite icons; this list only covers undiscovered ones)", S.camps and #S.camps or 0))
        if imgui.button("Dump nearby mesh paths (stand at the meat)##tame_meshdump") then
            -- tap-record a REAL mesh path off a live object (the safe way to find the meat prop:
            -- an unproven path fed to the loader crashes, a read-off-a-live-mesh path is proven)
            pcall(function()
                local player9 = get_player()
                local pgo9 = player9 and char_go(player9)
                local prp = pgo9 and pgo9:call("get_Transform"):call("get_Position")
                if not prp then S.status = "mesh dump: no player"; return end
                local out = {}
                local sm9 = sdk.get_native_singleton("via.SceneManager")
                local smt9 = sdk.find_type_definition("via.SceneManager")
                local scene9 = sm9 and sdk.call_native_func(sm9, smt9, "get_CurrentScene")
                local comps9 = scene9 and scene9:call("findComponents(System.Type)", sdk.typeof("via.render.Mesh"))
                local n9 = 0
                pcall(function() n9 = comps9:call("get_Length") or 0 end)
                if n9 == 0 then pcall(function() n9 = comps9:get_size() or 0 end) end
                for i9 = 0, (tonumber(n9) or 0) - 1 do
                    pcall(function()
                        local mc9 = comps9:call("get_Item", i9) or comps9[i9]
                        local go9 = mc9 and mc9:call("get_GameObject")
                        local rp9 = go9 and go9:call("get_Transform"):call("get_Position")
                        if rp9 then
                            local dx9, dy9, dz9 = rp9.x - prp.x, rp9.y - prp.y, rp9.z - prp.z
                            local dd9 = math.sqrt(dx9 * dx9 + dy9 * dy9 + dz9 * dz9)
                            if dd9 < 12.0 then   -- wide enough to catch the whole nest RING
                                local function respath(r9)
                                    if not r9 then return nil end
                                    local p9 = nil
                                    for _, gtr in ipairs({ "get_ResourcePath", "get_Path", "get_ResourceName" }) do
                                        if not p9 then pcall(function() local v9 = r9:call(gtr); if v9 then p9 = tostring(v9) end end) end
                                    end
                                    if not p9 then pcall(function() p9 = tostring(r9) end) end
                                    return p9
                                end
                                local res9 = nil
                                pcall(function() res9 = mc9:call("getMesh") end)
                                if not res9 then pcall(function() res9 = mc9:call("get_Mesh") end) end
                                -- the MATERIAL path too: a guessed .mdf2 fed to the loader crashes,
                                -- a read-off-the-live-component path is proven
                                local mres9 = nil
                                for _, gm9 in ipairs({ "get_Material", "getMaterial", "get_MaterialResource" }) do
                                    if not mres9 then pcall(function() mres9 = mc9:call(gm9) end) end
                                end
                                out[#out + 1] = { d = tonumber(string.format("%.2f", dd9)), go = tostring(go_name(go9)),
                                    mesh = tostring(respath(res9)), mat = tostring(respath(mres9)) }
                            end
                        end
                    end)
                end
                table.sort(out, function(a, b) return (a.d or 99) < (b.d or 99) end)
                json.dump_file(MOD .. "_nearby_meshes.json", out)
                for i9 = 1, math.min(#out, 15) do
                    pcall(function() log.info(string.format("[IrisTaming] mesh %.2fm %s -> %s", out[i9].d, out[i9].go, out[i9].mesh)) end)
                end
                S.status = string.format("nearby meshes dumped: %d within 4m (json + log)", #out)
            end)
        end
        c, C.yield_hp_pct = imgui.drag_float("Context below HP %##tame_ctx", tonumber(C.yield_hp_pct) or 0.25, 0.01, 0.05, 0.9); chg = chg or c
        c, C.yield_at_pct = imgui.drag_float("Yield at HP %##tame_yield", tonumber(C.yield_at_pct) or 0.05, 0.01, 0.01, 0.5); chg = chg or c
        c, C.yield_window_secs = imgui.drag_float("Yield window secs##tame_window", tonumber(C.yield_window_secs) or 120.0, 5.0, 15.0, 600.0); chg = chg or c
        c, C.familiar_need = imgui.drag_float("Familiarity needed##tame_famneed", tonumber(C.familiar_need) or 100.0, 5.0, 20.0, 500.0); chg = chg or c
        imgui.text("-- pace (tune live, saves automatically) --")
        c, C.circle_speed = imgui.drag_float("Circle speed rad/s##tame_cspd", tonumber(C.circle_speed) or 0.35, 0.02, 0.1, 1.5); chg = chg or c
        c, C.circle_radius = imgui.drag_float("Circle radius m##tame_crad", tonumber(C.circle_radius) or 4.2, 0.1, 2.0, 10.0); chg = chg or c
        c, C.circle_secs = imgui.drag_float("Circle duration s##tame_csec", tonumber(C.circle_secs) or 10.0, 0.5, 4.0, 30.0); chg = chg or c
        c, C.rush_speed = imgui.drag_float("Charge speed m/s##tame_rspd", tonumber(C.rush_speed) or 25.0, 0.5, 5.0, 50.0); chg = chg or c
        c, C.rush_stop_d = imgui.drag_float("Charge stops at m##tame_rstop", tonumber(C.rush_stop_d) or 5.0, 0.25, 2.0, 30.0); chg = chg or c
        c, C.rush_back_dist = imgui.drag_float("Coil back-up m##tame_rback", tonumber(C.rush_back_dist) or 55.0, 1.0, 5.0, 90.0); chg = chg or c
        c, C.crossing_speed = imgui.drag_float("Last-steps walk m/s##tame_xspd", tonumber(C.crossing_speed) or 1.6, 0.1, 0.5, 4.0); chg = chg or c
        imgui.tree_pop()
        end
        if imgui.tree_node("wolf CLIP LAB (find stop/pounce/growl ids)##tame_lab") then
            imgui.text("plays any bank:clip on the current target (think-stopped, like the studio)")
            local c2
            c2, C.lab_bank = imgui.drag_int("bank##tame_lab_b", math.floor(tonumber(C.lab_bank) or 0), 1, 0, 200); chg = chg or c2
            c2, C.lab_clip = imgui.drag_int("clip##tame_lab_c", math.floor(tonumber(C.lab_clip) or 0), 1, 0, 20000); chg = chg or c2
            local function lab_play()
                -- ⛔ was S.target-only: a WILD creature browsed via "DEEP SCAN nearest" never
                -- becomes the courtship target, so play silently no-op'd ("can't force it to
                -- play" -- Aurora, bat + seabird). The deep scan now remembers its body.
                local tgt = S.target or S.lab_play_ch
                if not tgt then S.status = "LAB: no body to play on (court one or DEEP SCAN it)"; return end
                set_think_stop(tgt, true)   -- hold it still or the live FSM stomps the clip
                S.wolf_clip = nil
                play_motion(tgt, math.floor(tonumber(C.lab_bank) or 0), math.floor(tonumber(C.lab_clip) or 0))
                S.status = string.format("LAB: playing %d:%d", math.floor(tonumber(C.lab_bank) or 0), math.floor(tonumber(C.lab_clip) or 0))
            end
            if imgui.button("scan target's clips##tame_lab_scan") then
                S.lab_catalog = {}
                S.lab_i = 1
                pcall(function()
                    local lgo = char_go(S.target)
                    local motion = comp(lgo, "via.motion.Motion")
                    if not motion then return end
                    local minfo = ValueType.new(sdk.find_type_definition("via.motion.MotionInfo"))
                    local seen = {}
                    local function scan_bank(bank_id, bank_name)
                        bank_id = tonumber(bank_id)
                        if bank_id == nil or bank_id < 0 or seen[bank_id] then return end
                        seen[bank_id] = true
                        S.lab_bankname = tostring(bank_name or "")
                        local count = 0
                        pcall(function() count = motion:call("getMotionCount", bank_id) end)
                        for i = 0, (tonumber(count) or 0) - 1 do
                            local okm = pcall(function()
                                motion:call("getMotionInfoByIndex(System.UInt32, System.UInt32, via.motion.MotionInfo)", bank_id, i, minfo)
                            end)
                            if okm then
                                local mid, mname = nil, nil
                                pcall(function() mid = minfo:get_MotionID() end)
                                pcall(function() mname = minfo:get_MotionName() end)
                                if tonumber(mid) then
                                    S.lab_catalog[#S.lab_catalog + 1] = { bank = bank_id, id = tonumber(mid), name = tostring(mname or "?"), bank_name = S.lab_bankname or "" }
                                end
                            end
                        end
                    end
                    -- evidence first: dump the REAL bank API of via.motion.Motion once
                    if not S.lab_bankdump then
                        S.lab_bankdump = true
                        pcall(function()
                            local names = {}
                            local td = sdk.find_type_definition("via.motion.Motion")
                            for _, m in ipairs(td:get_methods() or {}) do
                                local mn2 = tostring(m:get_name() or "")
                                if mn2:find("Bank") then names[#names + 1] = mn2 end
                            end
                            log.info("[IrisTaming] Motion bank API: " .. table.concat(names, " "))
                        end)
                    end
                    -- direct enumeration: holder arrays hide lazily-loaded banks
                    pcall(function()
                        local bc = motion:call("getMotionBankCount")
                        for i = 0, (tonumber(bc) or 0) - 1 do
                            pcall(function()
                                local bank = motion:call("getMotionBank", i)
                                local bid, bname = nil, nil
                                pcall(function() bid = bank:call("get_BankID") end)
                                if bid == nil then pcall(function() bid = bank:get_field("BankID") end) end
                                pcall(function()
                                    local list = bank:call("get_MotionList")
                                    bname = list and list:call("ToString()"):match("^.+%[.+/(.+)%.motlist%]")
                                end)
                                scan_bank(bid, bname)
                            end)
                        end
                    end)
                    for _, holder in ipairs({ "ActiveMotionBank", "DynamicMotionBank" }) do
                        local banks = nil
                        pcall(function() banks = motion:call("get_" .. holder) end)
                        if banks then
                            local nb = 0
                            pcall(function() nb = banks:call("get_Length") or 0 end)
                            for i = 0, (tonumber(nb) or 0) - 1 do
                                pcall(function()
                                    local bank = banks:call("get_Item", i) or banks[i]
                                    local bid, bname = nil, nil
                                    pcall(function() bid = bank:call("get_BankID") end)
                                    if bid == nil then pcall(function() bid = bank:get_field("BankID") end) end
                                    pcall(function()
                                        local list = bank:call("get_MotionList")
                                        bname = list and list:call("ToString()"):match("^.+%[.+/(.+)%.motlist%]")
                                    end)
                                    scan_bank(bid, bname)
                                end)
                            end
                        end
                    end
                    scan_bank(0, "base")
                end)
                S.status = string.format("LAB: %d clips catalogued", #(S.lab_catalog or {}))
            end
            if S.lab_catalog and #S.lab_catalog > 0 then
                -- banks are first-class: list them, filter by one, step within the view
                local bset, blist = {}, {}
                for _, e0 in ipairs(S.lab_catalog) do
                    if not bset[e0.bank] then
                        bset[e0.bank] = (e0.bank_name or "")
                        blist[#blist + 1] = e0.bank
                    end
                end
                table.sort(blist)
                local bdesc = {}
                for _, b in ipairs(blist) do
                    bdesc[#bdesc + 1] = tostring(b) .. (bset[b] ~= "" and (" (" .. bset[b] .. ")") or "")
                end
                imgui.text("banks: " .. table.concat(bdesc, ", "))
                local c3
                c3, C.lab_filter_bank = imgui.drag_int("bank filter (-1 = all)##tame_lab_bf", math.floor(tonumber(C.lab_filter_bank) or -1), 1, -1, 500); chg = chg or c3
                if imgui.button("< bank##tame_lab_bp") then
                    -- step through DISCOVERED banks only (-1 = all sits before the first)
                    local cur = math.floor(tonumber(C.lab_filter_bank) or -1)
                    local prev = -1
                    if cur == -1 then
                        prev = blist[#blist]
                    else
                        for i = #blist, 1, -1 do
                            if blist[i] < cur then prev = blist[i]; break end
                        end
                    end
                    C.lab_filter_bank = prev
                    S.lab_vi = 1
                end
                imgui.same_line()
                if imgui.button("bank >##tame_lab_bn") then
                    local cur = math.floor(tonumber(C.lab_filter_bank) or -1)
                    local nxt = -1
                    for i = 1, #blist do
                        if blist[i] > cur then nxt = blist[i]; break end
                    end
                    C.lab_filter_bank = nxt   -- past the last bank wraps to -1 (all)
                    S.lab_vi = 1
                end
                local view = {}
                local fb = math.floor(tonumber(C.lab_filter_bank) or -1)
                for idx, e0 in ipairs(S.lab_catalog) do
                    if fb < 0 or e0.bank == fb then view[#view + 1] = idx end
                end
                if #view > 0 then
                    S.lab_vi = math.max(1, math.min(tonumber(S.lab_vi) or 1, #view))
                    local e = S.lab_catalog[view[S.lab_vi]]
                    imgui.text(string.format("[%d/%d]  %d:%d  %s", S.lab_vi, #view, e.bank, e.id, e.name))
                    if imgui.button("<< prev##tame_lab_cprev") then
                        S.lab_vi = (S.lab_vi - 2) % #view + 1
                        local e2 = S.lab_catalog[view[S.lab_vi]]
