                        C.lab_bank = e.bank; C.lab_clip = e.id; lab_play()
                    end
                    imgui.same_line()
                    if imgui.button("next >>##tame_lab_cnext") then
                        S.lab_vi = S.lab_vi % #view + 1
                        local e2 = S.lab_catalog[view[S.lab_vi]]
                        C.lab_bank = e2.bank; C.lab_clip = e2.id; lab_play()
                    end
                    imgui.same_line()
                    if imgui.button("wake it##tame_lab_wake") then
                        -- release the audition hold on a wild body (it wanders off; scan again to re-hold)
                        pcall(function() set_think_stop(S.target or S.lab_play_ch, false) end)
