                    end
                else
                    imgui.text("(no clips in that bank)")
                end
            end
            if imgui.button("list mounted banks (click DURING a maul)##tame_lab_banks") then
                pcall(function()
                    -- pause-proof: while paused the frame logic sleeps, so grab the wolf directly
                    local tgt = S.target or find_candidate(char_go(get_player()))
                    local motion = tgt and comp(char_go(tgt), "via.motion.Motion")
                    if not motion then S.status = "no creature in range"; return end
                    local found = {}
                    for b = 0, 300 do
                        local cnt = 0
                        pcall(function() cnt = tonumber(motion:call("getMotionCount", b)) or 0 end)
                        if cnt > 0 then found[#found + 1] = string.format("%d(%d)", b, cnt) end
                    end
                    S.status = "mounted banks: " .. table.concat(found, "  ")
                    pcall(function() log.info("[IrisTaming] mounted banks: " .. table.concat(found, "  ")) end)
                end)
            end
            if imgui.button("request BITE action on target##tame_lab_bite") and S.target then
                -- the eating experiment: Ch223_Bite (from the action spy) fired as an action --
                -- needs a live FSM, so think is restored first
                set_think_stop(S.target, false)
                pcall(function()
                    local am = S.target:get_field("<ActionManager>k__BackingField") or S.target:call("get_ActionManager")
                    if am then
                        am:call("requestActionCore(app.ActionManager.Priority, System.String, System.UInt32)", 10, tostring(C.feast_bite_action or "Ch223_Bite"), 0)
                        S.status = "LAB: bite action requested"
                    end
                end)
            end
            if imgui.button("dump motion API to file##tame_lab_api") then
                pcall(function()
                    local out = {}
                    for _, tn in ipairs({ "via.motion.Motion", "via.motion.Layer", "via.motion.MotionBank", "via.motion.MotionInfo" }) do
                        local rows = {}
                        local td = sdk.find_type_definition(tn)
                        if td then
                            for _, m in ipairs(td:get_methods() or {}) do
                                local sig = tostring(m:get_name() or "?")
                                pcall(function()
                                    local np = m:get_num_params()
                                    sig = sig .. "(" .. tostring(np) .. " params) -> " .. tostring(m:get_return_type():get_full_name())
                                end)
                                rows[#rows + 1] = sig
                            end
                        end
                        out[tn] = rows
                    end
                    json.dump_file("IrisTaming_motion_api.json", out)
                    S.status = "LAB: motion API dumped to data/IrisTaming_motion_api.json"
                end)
            end
            -- DEEP SCAN: brute-force every id, verify by reading the layer's MotionID back --
            -- the enumeration under-reports (0:100 was seen in the tester; the catalogue denies it exists)
            imgui.text("Catalogue ANY creature (no tame needed): stand near it, then:")
            if imgui.button("DEEP SCAN nearest creature (any species)##tame_lab_deepany") then
                -- point the scan at the nearest body of any band -> its own atlas file, so we can
                -- build the motion library for every creature (sheep/ox/boar/bird/bat/...)
                local tgt = find_nearest_creature(char_go(get_player()))
                local motion = tgt and comp(char_go(tgt), "via.motion.Motion")
                if motion then
                    local banks = {}
                    for b = 0, 300 do
                        local cnt = 0
                        pcall(function() cnt = tonumber(motion:call("getMotionCount", b)) or 0 end)
                        if cnt > 0 then banks[#banks + 1] = b end
                    end
                    if #banks > 0 then
                        S.deep = { ch = tgt, multi = banks, bi = 1, bank = banks[1], i = 0, max = 8000, found = {},
                            minfo = ValueType.new(sdk.find_type_definition("via.motion.MotionInfo")) }
                        S.lab_play_ch = tgt   -- the browser's play buttons drive THIS body (wild = no S.target)
                        S.status = string.format("DEEP SCAN %s: %d banks queued", tostring(go_name(char_go(tgt))), #banks)
                    else
                        S.status = "that body has no readable motion banks"
                    end
                else
                    S.status = "no creature within 40m"
                end
            end
            if imgui.button("DEEP SCAN ALL MOUNTED BANKS##tame_lab_deepall") then
                local tgt = S.target or find_candidate(char_go(get_player()))
                local motion = tgt and comp(char_go(tgt), "via.motion.Motion")
                if motion then
                    local banks = {}
                    for b = 0, 300 do
                        local cnt = 0
                        pcall(function() cnt = tonumber(motion:call("getMotionCount", b)) or 0 end)
                        if cnt > 0 then banks[#banks + 1] = b end
                    end
                    if #banks > 0 then
                        S.deep = { ch = tgt, multi = banks, bi = 1, bank = banks[1], i = 0, max = 8000, found = {},
                            minfo = ValueType.new(sdk.find_type_definition("via.motion.MotionInfo")) }
                        S.status = string.format("DEEP SCAN ALL: %d banks queued", #banks)
                    end
                else
                    S.status = "no creature in range"
                end
            end
            if imgui.button("DEEP SCAN this bank (ids 0-8000)##tame_lab_deep") then
                -- v2 oracle: getMotionInfo(bank, id, out) returns TRUE only for REAL clips --
                -- pure queries, no changeMotion, the wolf does not even blink (pause-proof)
                local tgt = S.target or find_candidate(char_go(get_player()))
                if tgt then
                    S.deep = { ch = tgt, bank = math.floor(tonumber(C.lab_bank) or 0), i = 0, max = 8000, found = {},
                        minfo = ValueType.new(sdk.find_type_definition("via.motion.MotionInfo")) }
                    S.status = "DEEP SCAN running..."
                else
                    S.status = "no creature in range"
                end
            end
            if S.deep then
                pcall(function()
                    local dgo = char_go(S.deep.ch)
                    local motion = comp(dgo, "via.motion.Motion")
                    if not motion then S.deep = nil; return end
                    S.deep.enumed = S.deep.enumed or {}
                    S.deep.seen = S.deep.seen or {}
                    local function enum_bank(bank)
                        -- index enumeration: safe on EVERY bank (no invalid-param hammering)
                        local cnt = tonumber(motion:call("getMotionCount", bank)) or 0
                        local added, failed = 0, 0
                        for idx = 0, cnt - 1 do
                            local okx = pcall(function()
                                motion:call("getMotionInfoByIndex(System.UInt32, System.UInt32, via.motion.MotionInfo)", bank, idx, S.deep.minfo)
                            end)
                            local mid3, mn3, ef3 = nil, nil, nil
                            if okx then
                                pcall(function() mid3 = S.deep.minfo:get_MotionID() end)
                                pcall(function() mn3 = S.deep.minfo:get_MotionName() end)
                                pcall(function() ef3 = S.deep.minfo:call("get_MotionEndFrame") end)
                            end
                            if okx and tonumber(mid3) then
                                local key = tostring(bank) .. ":" .. tostring(mid3)
                                if not S.deep.seen[key] then
                                    S.deep.seen[key] = true
                                    added = added + 1
                                    S.deep.found[#S.deep.found + 1] = { bank = bank, id = tonumber(mid3), name = tostring(mn3 or "?"), endframe = tonumber(ef3) or 0 }
                                end
                            else
                                failed = failed + 1
                            end
                        end
                        pcall(function() log.info(string.format("[IrisTaming] deep bank %d: count=%d added=%d fail=%d", bank, cnt, added, failed)) end)
                    end
                    local n = 0
                    while S.deep and n < 400 do
                        n = n + 1
                        -- BANK START: enumerate once, the moment the bank becomes current
                        -- (the old chunk-top check missed banks that lived and died mid-chunk)
                        if not S.deep.enumed[S.deep.bank] then
                            S.deep.enumed[S.deep.bank] = true
                            pcall(function() enum_bank(S.deep.bank) end)
                        end
                        -- only bank 0 earns the id sweep (invalid-bank hammering = sol poison)
                        local done = (S.deep.bank ~= 0) or (S.deep.i > S.deep.max)
                        if done then
                            if S.deep.multi and S.deep.bi < #S.deep.multi then
                                S.deep.bi = S.deep.bi + 1
                                S.deep.bank = S.deep.multi[S.deep.bi]
                                S.deep.i = 0
                            else
                                pcall(function()
                                    local payload = { target = go_name(dgo), banks = S.deep.multi, clips = S.deep.found }
                                    json.dump_file("IrisTaming_deepscan.json", payload)
                                    -- the SPECIES LIBRARY: every creature keeps its own atlas
                                    local sp = tostring(go_name(dgo) or ""):match("ch%d+") or "unknown"
                                    json.dump_file("IrisTaming_atlas_" .. sp .. ".json", payload)
                                end)
                                S.lab_catalog = S.deep.found   -- feed the browser
                                S.lab_vi = 1
                                S.status = string.format("DEEP SCAN done: %d real clips -> browser + data/IrisTaming_deepscan.json", #S.deep.found)
                                S.deep = nil
                                break
                            end
                        else
                            local id = S.deep.i
                            pcall(function()
                                local okid = motion:call("getMotionInfo(System.UInt32, System.UInt32, via.motion.MotionInfo)", 0, id, S.deep.minfo)
                                if okid == true then
                                    local key = "0:" .. tostring(id)
                                    if not S.deep.seen[key] then
                                        S.deep.seen[key] = true
                                        local mn2, ef2 = nil, nil
                                        pcall(function() mn2 = S.deep.minfo:get_MotionName() end)
                                        pcall(function() ef2 = S.deep.minfo:call("get_MotionEndFrame") end)
                                        S.deep.found[#S.deep.found + 1] = { bank = 0, id = id, name = tostring(mn2 or "?"), endframe = tonumber(ef2) or 0 }
                                    end
                                end
                            end)
                            S.deep.i = id + 1
                        end
                    end
                end)
                imgui.text(string.format("DEEP SCAN: bank %s  id %d  (found %d)", tostring(S.deep and S.deep.bank or "-"), math.floor(tonumber(S.deep and S.deep.i or 0)), #(S.deep and S.deep.found or {})))
            end
            if imgui.button("load atlas from file##tame_lab_loadatlas") then
                -- the 303-clip atlas, restored instantly after any reset -- no rescan needed
                pcall(function()
                    -- prefer the atlas of whatever is standing in front of you
                    local dd = nil
                    pcall(function()
                        local tgt = S.target or find_candidate(char_go(get_player()))
                        local sp = tgt and tostring(go_name(char_go(tgt)) or ""):match("ch%d+") or nil
                        if sp then dd = json.load_file("IrisTaming_atlas_" .. sp .. ".json") end
                    end)
                    if not (dd and dd.clips) then dd = json.load_file("IrisTaming_deepscan.json") end
                    if dd and dd.clips and #dd.clips > 0 then
                        S.lab_catalog = dd.clips
                        S.lab_vi = 1
                        S.status = string.format("LAB: atlas loaded - %d clips in the browser", #dd.clips)
                    else
                        S.status = "LAB: no deep-scan file found (run DEEP SCAN ALL once)"
                    end
                end)
            end
            if imgui.button("dump catalogue to file##tame_lab_dump") and S.lab_catalog then
                pcall(function() json.dump_file("IrisTaming_clips.json", { scanned = go_name(char_go(S.target)), clips = S.lab_catalog }) end)
                S.status = string.format("LAB: %d clips dumped to data/IrisTaming_clips.json", #(S.lab_catalog or {}))
            end
            if imgui.button("play##tame_lab_play") then lab_play() end
            imgui.separator()
            imgui.text("APPEARANCE (color customization recon):")
            if imgui.button("dump materials + colors to file##tame_appear_dump") and S.target then
                pcall(function()
                    local ag = char_go(S.target)
                    local mc = comp(ag, "via.render.Mesh")
                    if not mc then S.status = "no via.render.Mesh on target"; return end
                    local out = { creature = go_name(ag), materials = {} }
                    local nmat = 0
                    pcall(function() nmat = mc:call("get_MaterialNum") or 0 end)
                    for mi = 0, (tonumber(nmat) or 0) - 1 do
                        local m = { name = tostring(mc:call("getMaterialName", mi) or "?"), vars = {} }
                        local nv = 0
                        pcall(function() nv = mc:call("getMaterialVariableNum", mi) or 0 end)
                        for vi = 0, (tonumber(nv) or 0) - 1 do
                            local vn = tostring(mc:call("getMaterialVariableName", mi, vi) or "?")
                            local f4 = nil
                            pcall(function()
                                local v = mc:call("getMaterialFloat4", mi, vi)
                                if v then f4 = { v.x, v.y, v.z, v.w } end
                            end)
                            m.vars[#m.vars + 1] = { i = vi, name = vn, value = f4 }
                        end
                        out.materials[#out.materials + 1] = m
                    end
                    json.dump_file("IrisTaming_appearance.json", out)
                    S.status = string.format("APPEARANCE: %d materials -> data/IrisTaming_appearance.json", #out.materials)
                end)
            end
            imgui.same_line()
            do
                local c4
                c4, C.appear_tint_r = imgui.drag_float("R##tame_tint_r", tonumber(C.appear_tint_r) or 1.0, 0.02, 0.0, 3.0); chg = chg or c4
                c4, C.appear_tint_g = imgui.drag_float("G##tame_tint_g", tonumber(C.appear_tint_g) or 0.3, 0.02, 0.0, 3.0); chg = chg or c4
                c4, C.appear_tint_b = imgui.drag_float("B##tame_tint_b", tonumber(C.appear_tint_b) or 0.3, 0.02, 0.0, 3.0); chg = chg or c4
                c4, C.appear_var_match = imgui.input_text("base-color var name contains##tame_tint_var", tostring(C.appear_var_match or "BaseColor"))
            end
            if imgui.button("TINT all base-color mats (test)##tame_tint_go") and S.target then
                pcall(function()
                    local ag = char_go(S.target)
                    local mc = comp(ag, "via.render.Mesh")
                    if not mc then return end
                    local nmat = mc:call("get_MaterialNum") or 0
                    local hits = 0
                    local needle = tostring(C.appear_var_match or "BaseColor"):lower()
                    for mi = 0, (tonumber(nmat) or 0) - 1 do
                        local nv = mc:call("getMaterialVariableNum", mi) or 0
                        for vi = 0, (tonumber(nv) or 0) - 1 do
                            local vn = tostring(mc:call("getMaterialVariableName", mi, vi) or ""):lower()
                            if vn:find(needle, 1, true) then
                                pcall(function()
                                    local v = ValueType.new(sdk.find_type_definition("via.vec4"))
                                    v.x = tonumber(C.appear_tint_r) or 1.0
                                    v.y = tonumber(C.appear_tint_g) or 0.3
                                    v.z = tonumber(C.appear_tint_b) or 0.3
                                    v.w = 1.0
                                    mc:call("setMaterialFloat4", mi, vi, v)
                                    hits = hits + 1
                                end)
                            end
                        end
                    end
                    S.status = string.format("TINT: wrote %d '%s' vars (dump first to see real names)", hits, tostring(C.appear_var_match or "BaseColor"))
                end)
            end
            imgui.text("(dump first, read the var names, then tint the right one)")
            imgui.same_line()
            if imgui.button("prev##tame_lab_prev") then C.lab_clip = math.max(0, math.floor(tonumber(C.lab_clip) or 0) - 1); lab_play() end
            imgui.same_line()
            if imgui.button("next##tame_lab_next") then C.lab_clip = math.floor(tonumber(C.lab_clip) or 0) + 1; lab_play() end
            imgui.same_line()
            if imgui.button("free the wolf##tame_lab_free") then
                if S.target then pcall(function() release_creature(S.target) end) end
            end
            imgui.text("tip: do NOT hold N / B while using the lab (the ritual would fight it)")
            imgui.tree_pop()
        end
        c, C.target_bands = imgui.input_text("Tameable name prefixes##tame_bands", tostring(C.target_bands or "")); chg = chg or c
        c, C.exclude_bands = imgui.input_text("Excluded prefixes##tame_excl", tostring(C.exclude_bands or "")); chg = chg or c
        if chg then save_state() end
        imgui.tree_pop()
    end
end)

re.on_script_reset(function()
    -- a reload while the crossing had the creature ghosted would otherwise orphan a body with no
    -- ground snap and no collision: S is rebuilt empty, so nobody would ever restore it
    pcall(function()
        local g9 = S.ghost_ch and char_go(S.ghost_ch)
        if g9 then set_ground_glue(g9, true) end
    end)
    S.ghost_ch = nil; S.ghost_lease = nil
    S.familiar = {}   -- every reset scripts starts fresh
    rawset(_G, "IrisTamingPerchScaleHold", nil)
    rawset(_G, "IrisTamingPerchGoAddr", nil)
    rawset(_G, "IrisGroundObservedScale", nil)
end)


-- ===================== HAND-OUT WALKABILITY PROBE (R&D) =====================
-- READ-ONLY. To play the hand-out WHILE walking we need the carry recipe: requestActionCore a real
-- ACTION NODE on layer 1 with the FSM LIVE (a raw clip on L1 only flashes then falls back). That
-- needs the gesture's action-node name. This logs the PLAYER's action node + motion bank:id on
-- layers 0 & 1 whenever they change. Turn it ON, do the hand-up gesture in-game (e.g. activate a
-- riftstone), then read re2_framework_log.txt for the "[IrisProbe]" lines to find the node name.
local iris_probe_on = false
local iris_probe_last = nil
local iris_walk_test = false        -- TEST: paint the hand-out on the UPPER-BODY layer (L1) while you walk
local iris_walk_mode = "motion"     -- "motion" = clip 60:6200 on L1 ; "action" = requestActionCore InteractRimStone on L1
local function iris_cur_action(am, layer)
    local nm = nil
    pcall(function()
        local list = am:get_field("CurrentActionList")
        local item = list and (list[layer] or list:call("get_Item", layer))
        nm = item and (item:get_field("Name") or item:call("get_Name"))
    end)
    return (nm and tostring(nm)) or "-"
end
re.on_frame(function()
    if not iris_probe_on then return end
    pcall(function()
        local pc = get_player()
        if not pc then return end
        local am = pc:get_field("<ActionManager>k__BackingField") or pc:call("get_ActionManager")
        local mo = pc:call("get_Motion")
        local function layline(n)
            local a = am and iris_cur_action(am, n) or "-"
            local l = mo and mo:call("getLayer", n)
            local m = l and (tostring(l:call("get_MotionBankID")) .. ":" .. tostring(l:call("get_MotionID"))) or "?"
            return a .. "[" .. m .. "]"
        end
        local line = "L0:" .. layline(0) .. "  L1:" .. layline(1)
        if line ~= iris_probe_last then
            iris_probe_last = line
            log.info("[IrisProbe] " .. line)
        end
    end)
    -- WALKABLE HAND-OUT TEST (RiftSpeak carry recipe): FSM stays LIVE so the legs walk on L0;
    -- the offer is painted on L1 (the UpperBodyDefault layer). Hold N / B in the open + move.
    if iris_walk_test and iris_kb(math.floor(tonumber(C.tame_key) or 0x4E)) then
        pcall(function()
            local pc = get_player()
            if not pc then return end
            if iris_walk_mode == "action" then
                local am = pc:get_field("<ActionManager>k__BackingField") or pc:call("get_ActionManager")
                if am then am:call("requestActionCore(app.ActionManager.Priority, System.String, System.UInt32)", 10, "InteractRimStone", 1) end
            else
                local l1 = pc:call("get_Motion"):call("getLayer", 1)
                local mid = l1 and l1:call("get_MotionID")
                if l1 and mid ~= 6200 and mid ~= 6201 then
                    l1:call("changeMotion(System.UInt32, System.UInt32, System.Single, System.Single, via.motion.InterpolationMode, via.motion.InterpolationCurve)", 60, 6200, 0.0, 6.0, 1, 1)
                end
            end
        end)
    end
end)
re.on_draw_ui(function()
    if imgui.tree_node("Iris HAND-OUT probe (R&D)") then
        local ch, v = imgui.checkbox("log player action/motion layers on change", iris_probe_on)
        if ch then iris_probe_on = v; iris_probe_last = nil end
        imgui.text("ON -> do the hand-up gesture (activate a riftstone) -> read log for [IrisProbe]")
        imgui.separator()
        imgui.text("WALK TEST: away from any wolf, hold N / B and move. Does the raised arm stay up?")
        local cw, wv = imgui.checkbox("TEST walk-with-hand-out (L1 paint)", iris_walk_test)
        if cw then iris_walk_test = wv end
        if imgui.button("mode: " .. iris_walk_mode .. "  (click to swap motion/action)") then
            iris_walk_mode = (iris_walk_mode == "motion") and "action" or "motion"
        end
        imgui.tree_pop()
    end
end)

-- ── MUSIC BRIDGE (2026-07-25) ────────────────────────────────────────────────
-- S is file-local, so IrisRitualMusic cannot see the ritual state. Publish it and let that
-- module WATCH the value. Deliberately additive and read-only: one watcher over there beats
-- patching the ten separate sites in here that reset S.mode to "idle", and every abort,
-- death and reload path then tears the music down for free.
re.on_frame(function()
    local music_mode = tostring(S.mode or "idle")
    -- Griffin courtship begins with the ox lure, but the ritual music begins only once the
    -- player climbs onto the griffin. Approach, feeding and landing stay in the world's score.
    if S.oxtame and tostring(S.oxtame.stage or "idle") == "rodeo" then
        music_mode = "context"
    end
    -- 08-12 (the silent yoke, round 4): the YOKE RITE is also a parallel machine that never
    -- touches S.mode -- the watcher heard "idle" through the whole tame. "trusting" is
    -- accepted by the watcher under EVERY start_mode config (context is not).
    if S.ox_rite then music_mode = "trusting" end
    -- Weapon state is a condition, never something the rite mutates for the player.
    -- Never force the player's weapon state. Passive rites now refuse a drawn-weapon start and
    -- spook through their own restore/flee paths if steel appears later; combat rites deliberately
    -- keep the weapon. Retain only the edge diagnostic for compatibility with the debug panel.
    S.sheathe_edge = music_mode
    rawset(_G, "IrisTamingMode", music_mode)
end)

-- ⭐ 08-13: the taming-mode indicator paints from a frame hook, not on_draw_ui -- on_draw_ui is
-- REFramework's own imgui window, which the player does not have open while playing. iris_screen_text
-- routes to IrisFont's d2d layer when it is up and falls back to draw.text's background drawlist.
re.on_frame(function()
    pcall(iris_tame_mode_hud)
end)
